(window.GIM_TP=window.GIM_TP||{})["Z.ChayeiSara.0"]={"from":0,"a":[[["וַיִּהְיוּ חַיִּי שָׂרָה מֵאָה שָׁנָה ועֶשְׂרִים שָׁנָה ושֶׁבַע שָׁנִים, רַבִּי יוֹסֵי פָּתַח וְאָמַר, (יונה א׳:ט״ו) ויִּשְׂאוּ אֶת יוֹנָה ויְטִלֻהוּ אֶל הַיָּם ויַּעֲמֹד הַיָּם מִזַּעְפּוֹ. הָכָא אִית לְאִסְתַּכָּלָא, מַאי טַעְמָא אַרְעִישַׁת יַמָּא עֲלֵיהּ דְּיוֹנָה, ולָא אַרְעִישַׁת עֲלֵיהּ אַרְעָא, כֵּיוָן דְּהֲוָה אָזִיל בְּגִין דְּלָא תִשְׁרֵי עֲלֵיהּ שְׁכִינְתָּא, יַמָּא (עלאה) אַמַּאי אָחִיד בֵּיהּ כַּד הֲוָה אָזִיל.","אֶלָא וַדַּאי מִלָּה בְּאַתְרֵיהּ הֲוָה. יַם, תְּנַן יַם דַּמְיָא לְרָקִיעַ וְרָקִיעַ לְכִסֵּא הַכָּבוֹד, וּבְגִין כָּךְ יַמָּא אָחִיד בֵּיהּ וְנְטַל לֵיהּ (בגין דהוה עריק) מִקַּמֵּי יַמָא עָרַק (נ\"א ומקמי ימא ביה שרא יראה בדוכתיה), שָׁדֵי יַמָּא יְדָא בֵּיהּ בְּדוּכְתָּהָא (נ\"א תשרי ידא בדוכתהא).","וַיִּשְׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם. אוֹלִיפְנָא כַּד הֲווּ נָטְלֵי לֵיהּ וְטָבְעֵי יַרְכוֹי בְּיַמָּא, הֲוָה יַמָּא שָׁכִיךְ, זָקְפִין לֵיהּ, אִתְרְעִישׁ יַמָּא, כָּל מַה דְּטָבְעֵי לֵיהּ הָכִי אִשְׁתְּכִיךְ יַמָּא, עַד דְּאִיהוּ אָמַר שָׂאוּנִי וַהֲטִילוּנִי אֶל הַיָּם, מִיָּד וַיִּשְׂאוּ אֶת יוֹנָה וַיְּטִלוּהוּ אֶל הַיָּם.","כֵּיוָן דְּאִתְרַמֵּי בַּיָּם פָּרְחָה מִנֵּיהּ נִשְׁמָתֵיהּ, וְסָלְקָא עַד כֻּרְסְיָיא דְמַלְכָּא, וְאִתְדָּנַת קַמֵּיהּ, וְאַהֲדָרַת לֵיהּ נִשְׁמָתֵיהּ, וְעָאל בְּפוּמָא דְהַהוּא נוּנָא, וּמִית נוּנָא, לְבָתַר אִתְקְיַּים הַהוּא נוּנָא, וְאוּקְמוּהָ."],[[0,"ויהיו חיי שרה מאה שנה:","ר' יוסי פתח ואמר. וישאו את יונה ויטילוהו אל הים ויעמוד הים מזעפו. כאן יש להסתכל. מהו הטעם, שהים הרעיש על יונה ולא הרעיש עליו הארץ דהיינו הנוקבא הנקראת ארץ, כיון שהיה הולך לחוץ לארץ כדי שלא תשרה עליו השכינה, ונמצא שברח מארץ ישראל, שה\"ס הנוקבא, א\"כ, הים למה נאחז בו כשהלך. ולא הארץ שממנה ברח."],[1,"אלא ודאי מלה וכו':","ומשיב, אלא ודאי, הדבר במקומו היה. ים, למדנו, שהים דומה לרקיע, ורקיע לכסא הכבוד, פירוש. כי אומר לעיל (פרשת לך דף ע\"ז אות רי\"א ולהלאה) שז' רקיעים הם, דהיינו חג\"ת נה\"י דז\"א, ורקיע עליון למעלה מהם, הנקרא \u0003מ\"י,\u0004 שהוא ישסו\"ת. ורקיע התחתון שלמטה מכולם, שה\"ס מלכות דז\"א, שממנה נבנית הנוקבא, מקבל ב' האותיות \u0003מ\"י\u0004 מרקיע העליון, שנעשים אצלה אותיות \u0003ים.\u0004 וע\"ש בהסולם, שפירוש הדברים הוא, אשר רקיע העליון שה\"ס ישסו\"ת הנקרא \u0003מ\"י,\u0004 אינו משפיע החכמה שבו לשום מדרגה, אלא להנוקבא. וע\"כ קבלה הנוקבא אותיות \u0003מ\"י\u0004 שבו ונעשו בה \u0003ים.\u0004 באופן שהשם \u0003ים\u0004 של הנוקבא, יורה במיוחד רק על מדרגת החכמה שבהנוקבא. עש\"ה."],[1,"","וזה אמרו \u0003הים,\u0004 שהוא הנוקבא \u0003דומה לרקיע,\u0004 דהיינו לרקיע התחתון דז\"א, כי מרקיע הזה כל בנינה, \u0003ורקיע זה דומה לכסא הכבוד\u0004 דהיינו ישסו\"ת, שהם כסא לאו\"א עלאין, שע\"כ קבל הרקיע התחתון אותיות מ\"י שבכסא הכבוד, ונעשה י\"ם. ונמצינו למדים בזה ההפרש מהשם \u0003ארץ\u0004 להשם \u0003ים.\u0004 כי השם ארץ של הנוקבא, אינו מיוחד על הארת חכמה שבה, אלא רק על הברכה שבה, בסוד מה דהות יבשה, אתעבידת \u0003ארץ\u0004 למעבד פירין ואיבין (כנ\"ל בהקדמת הזהר דף קצ\"ו אות ר\"ו ע\"ש) אבל השם ים של הנוקבא מיוחד רק על הארת חכמה שבה, שמשם נמשך הנבואה."],[1,"","וז\"ש, \u0003ובגין כך ימא אחיד ביה ונטיל ליה,\u0004 ומשום זה הים נאחז בו וקבל אותו לתוכו, \u0003בגין דהוה עריק מקמא ימא.\u0004 משום שהיה בורח מפני הים. דהיינו שהיה בורח מפני הנבואה הנמשכת מהמוחין דנוקבא, שהם בבחינת \u0003ים\u0004 כנ\"ל. וע\"כ הרעיש עליו הים ולא הארץ, וכן השליכוהו אל הים, שזה היה כדי להשיבו אל הנבואה שממנה ברח."],[2,"וישאו את יונה ויטילוהו אל הים:","כשהיו מטילים אותו אל הים, והטביעו אותו עד ברכיו, היה הים שכך. הרימו אותו זעף הים, כל כמה שהטביעוהו כן שכך הים, עד שהוא אמר בעצמו שאוני והטילוני אל הים. מיד וישאו את יונה ויטילוהו אל הים."],[3,"כיון דאתרמי בים וכו':","כיון שנשלך אל הים פרחה ממנו נשמתו, ועלתה עד כסא המלך ונדונה לפניו, והוחזרה לו הנשמה, ונכנס בפיו של אותו הדג, והדג מת. ואח\"כ חזר הדג לתחיה. וכבר בארוהו."]],[[0,"","וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים. רַבִּי יוֹסֵי פָּתַח וְאָמַר, (יונה א) וַיִּשְׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. כָּאן יֵשׁ לְהִסְתַּכֵּל מָה הַטַּעַם הִרְעִישׁ הַיָּם עַל יוֹנָה וְלֹא הִרְעִישָׁה הָאָרֶץ עָלָיו, כֵּיוָן שֶׁהָיָה הוֹלֵךְ כְּדֵי שֶׁלֹּא תִשְׁרֶה עָלָיו הַשְּׁכִינָה? לָמָּה הַיָּם (העליון) הָיָה אוֹחֵז בּוֹ כְּשֶׁהָיָה הוֹלֵךְ?"],[1,"","אֶלָּא וַדַּאי הָיָה הַדָּבָר בִּמְקמוֹ. יָם שָׁנִינוּ, הַיָּם דּוֹמֶה לָרָקִיעַ, וְהָרָקִיעַ לְכִסֵּא הַכָּבוֹד, וּמִשּׁוּם כָּךְ הַיָּם אָחַז בּוֹ וְנָטַל אוֹתוֹ (משום שהיה בורח) בָּרַח מִלִּפְנֵי הַיָּם (נ\"א: ומלפני הים בו שרתה יראה במקומו), זָרַק הַיָּם בּוֹ יָד בִּמְקוֹמוֹ (נ\"א תשרה היד במקומה)."],[2,"","וַיִּשְׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם. לָמַדְנוּ, כְּשֶׁהָיוּ נוֹטְלִים אוֹתוֹ וּמְטַבְּעִים אֶת יְרֵכָיו בַּיָּם - הַיָּם הָיָה שׁוֹכֵךְ. מְרִימִים אוֹתוֹ - וְהַיָּם רוֹעֵשׁ. כָּל מַה שֶּׁמְּטַבְּעִים אוֹתוֹ - כָּךְ הָיָה הַיָּם שׁוֹכֵךְ. עַד שֶׁהוּא אָמַר שָׂאוּנִי וַהֲטִילֻנִי אֶל הַיָּם. מִיָּד וַיִּשִׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם."],[3,"","כֵּיוָן שֶׁנִּזְרַק בַּיָּם, פָּרְחָה מִמֶּנּוּ נִשְׁמָתוֹ, וְעָלְתָה עַד כִּסֵּא הַמֶּלֶךְ וְנִדּוֹנָה לְפָנָיו, וְחָזְרָה לוֹ נִשְׁמָתוֹ, וְנִכְנַס בְּפִי הַדָּג הַהוּא וּמֵת הַדָּג. לְאַחַר מִכֵּן הִתְקַיֵּם אוֹתוֹ הַדָּג, וּפֵרְשׁוּהָ."]]],[["תָּא חֲזֵי, בְּשַׁעְתָּא דְּבַר נָשׁ סָלִיק בְּעַרְסֵיהּ כָּל לֵילְיָא וְלֵילְיָא, נִשְׁמָתֵיהּ נָפְקַת מִנֵּיהּ וְאִתְדָּנַת קַמֵּי בֵּי דִינָא דְמַלְכָּא, אִי זַכָּאָה לְאִתְקָיְימָא, אִתְהַדָּרַת לְהַאי עַלְמָא.","וְדִינָא הוּא בִּתְרֵין גְּוָונִין, דְּהָא לָא דָיְינִין לֵיהּ לְבַר נָשׁ עַל בִּישִׁין דְּאִיהוּ עָתִיד וְזַמִּין לְמֶעְבַּד דִּכְתִיב (בראשית כ״א:י״ז) כִּי שָׁמַע אֱלהִים וְגו' בַּאֲשֶׁר הוּא שָׁם. וְלָא תֵימָא דְּדָנִין לֵיהּ עַל טָבִין דְּעָבִיד לְחוּד, אֶלָּא לְאוֹטָבָא לֵיהּ עַל אִינוּן טָבִין דְּהַשְׁתָּא כְּמָה דְאִתְּמָר, וְדָנִין לֵיהּ עַל זָכְיָין דְּאִיהוּ זַמִּין לְמֶעְבַּד, וּבְגִינַיְיהוּ אִשְׁתְּזִיב אַף עַל גַּב דְּאִיהוּ הַשְׁתָּא חַיָּיבָא. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד טִיבוּ עִם כָּל בִּרְיָין וְכָל אָרְחוֹי דְאִיהוּ עָבִיד לְאוֹטָבָא לְכֹלָּא, וְלָא דָאִין לְבַר נָשׁ עַל בִּישִׁין דְּאִיהוּ זַמִּין לְמֶעְבַּד, וּבְגִין כָּךְ אִתְדָּן בַּר נָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזֵי, כֵּיוָן דְּאַטִּילוּ לֵיהּ לְיוֹנָה בְּיַמָּא, מַה כְּתִיב, וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. הַיָּם עִלָּאָה, מַאי וַיַּעֲמֹד, דְּקָאִים בְּקִיּוּמֵיהּ כְּדְקָא יְאוּת, בַּעֲמִידָה אִיהוּ כַּד רוּגְזָא שָׁכִיךְ, בְּשַׁעְתָּא דְּדִינָא שַׁרְיָא בְּעַלְמָא, הַהוּא בֵּי דִינָא אִיהוּ כְּאִתְּתָא דְּמִתְעַבְּרָא, וְקַשְׁיָא לְאוֹלָדָא, וְכַד אוֹלִידַת שְׁכִיךְ רוּגְזָא. הָכִי נָמֵי כַּד דִּינָא שַׁרְיָא בְּעַלְמָא, לָא שָׁכִיךְ וְלָא נָח עַד דְּאִתְעֲבִיד דִּינָא בְּחַיָּיבַיָא, כְּדֵין הוּא נַיְיחָא דִילֵיהּ, לְמֵיקַם בְּדוּכְתָּא שְׁלִים, וּלְמֵיקַם בְּקִיּוּמֵיהּ, הֲדָא הוּא דִכְתִיב, (משלי י״א:י׳) וּבַאֲבֹד רְשָׁעִים רִנָּה. וְהָא אוֹקִימְנָא.","בַּאֲבֹד רְשָׁעִים רִנָּה. וְהָכְתִיב (יחזקאל י״ח:כ״ג) הֶחָפֹץ אֶחְפֹּץ מוֹת רָשָׁע וְהָא לֵית נַיְיחָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כַּד אִתְעֲבִיד דִּינָא בְּרַשִּׁיעַיָּיא. אֶלָּא כָּאן קוֹדֶם דְּאִשְׁתְּלִים קִיסְטָא, כָּאן לְבָתַר דְּאִשְׁתְּלִים קִיסְטָא (אית ליה נייחא):","\u0003תוספתא\u0004 וְיִהְיוּ חַיֵּי שָׂרָה, גּוּפָא דְּמַתְנִיתִין אֲנַן קְרֵיבִין הֲוֵינָא שְׁמַעְנָא קָלָא מִתְהַפֵּךְ מִלְּעִילָּא לְתַתָּא אֶתְפַּשְּׁטַת בְּעָלְמָא קַל מִתְּבַר טוּרֵין וּמְתַבַּר טִנָּרִין תַּקִּיפִין עִלְעוּלִין רַבְרְבִין סָלְקִין אוּדְנַנָא פְּתִיחָן","הֲוָה אָמַר בִּמְטַלְּנוֹי קוֹץ קוֹצִיתָא דְּמִיכָן דְּמִיְּמִין שִׁינְתָּא בְּחוּרֵיהוֹן קַיָּימִין בִּקְיוֹמֵיהוּן מַלְכָּא דְּמִמְּלָל (וְלָא אִעַבַּרוּ אִשְׁתְּכַחוּ) נָטְרֵי תַּרְעִין שֶׁלִּיטָא דְּחִילִין סַגִּיאִין קָם בְּקִיּוּמֶיהָ","כֻּלְּהוּ לָא מַרְגְּשָׁן וְלָא יָדְעִי דְּסָפְרָא פָּתִיחַ וּבִשְׁמָא אֶכְתּוֹב וְדוֹמֶה קָאֵים וְנָטֵיל בְּחוּשְׁבָּנָא וְדָיְירִי עַפְרָא תַּיְיבִין לְבַר וְקָרִיב טָב לְאִתְמְנְאָה בְּהוּ לָא תְּאֵיבִין גִּלְגּוֹלָא וַהֲפוֹךְ","נָפְלִין וְלָא קָיְימִין אִתְמְחוּן חַיָּיבִין מִסִּפְרָא דְּדוֹמֶה מַאן יִתְבַּע לוֹן וּמַאן יָתֵיב בְּחוּשְׁבָּנְהוֹן וָוֵי לוֹן וָוֵי לִחְיָיְהוֹן וַוי לרגשׁיהון (ס\"א לְנַפְשִׁיהוֹן) בְּגִינְהוּן אִתַּקַּרִי (תהילים ס״ט:כ״ט) יִמְחוּ מִסְפַּר חַיִּים וְגוֹ':","וַיִּהְיוּ חַיֵּי שָׂרָה. מַאי שְׁנָא הָכָא שָׂרָה דִּכְתִיב מִיתָתָה בְּאוֹרַיְיתָא מִכָּל נְשֵׁי דְעַלְמָא דְּלָא כְּתִיב הָכִי מִיתַתְהוֹן בְּאוֹרַיְיתָא. אָמַר רַבִּי חִיָיא וְלָאו, וְהָכְתִיב (בראשית ל״ה:י״ט) וַתָּמָת רָחֵל וַתִּקָּבֵר בְּדֶרֶךְ אֶפְרָתָה. וּכְּתִיב, (במדבר כ׳:א׳) וַתָּמָת שָׁם מִרְיָם וְגו'. וּכְתִיב, (בראשית ל״ה:י״ט) וַתָּמָת דְּבוֹרָה מֵינֶקֶת רִבְקָה. וּכְתִיב, (בראשית ל״ח:י״ב) וַתָּמָת בַּת שׁוּעַ אֵשֶׁת יְהוּדָה."],[[0,"תא חזי בשעתא וכו':","בוא וראה, בשעה שאדם עולה על המטה וישן, כל לילה ולילה יוצאת נשמתו ממנו, ונדונת לפני בית דינו של המלך. אם זוכה להשאר בחיים, הוחזרה הנשמה לעולם הזה."],[1,"ודינא הוא וכו':","והדין הוא בשני דרכים. כי לא דנים האדם על הרע שהוא עתיד ונועד לעשות, שכתוב כי שמע אלקים אל קול הנער באשר הוא שם. ולא על העתיד. ואל תאמר, שכן דנים האדם רק על הטוב שכבר עשה, בלבד, אלא שמטיבים לאדם על הטוב של עתה כמו שאמרו, ודנים אותו על הזכיות שהוא עתיד לעשות שהוא נצל בשבילם אע\"פ שהוא עתה רשע, כמו שאמרו. משום שהקב\"ה עושה טוב עם כל הבריות, וכל דבריו שעושה הוא רק להטיב לכל, וע\"כ, אינו דן האדם על הרע שעתיד לעשות. וע\"כ נדון האדם לפני הקב\"ה שיודע העתידות. פירוש. כי הביא המאמר הזה אשר האדם נדון בכל לילה, כדי לבאר מה שאמר לעיל על יונה שיצאה נשמתו ונדון לפני הקב\"ה, ולפיכך מסיים המאמר \u0003ובגין כך אתדן בר נש קמי קב\"ה.\u0004 שסובב על מה שאמר על יונה, כמבואר."],[2,"תא חזי כיון וכו':","בוא וראה כיון שהטילו את יונה אל הים, מה כתוב, ויעמוד הים מזעפו, היינו ים העליון שהוא הנוקבא כנ\"ל, מהו ויעמוד. הוא שעמד על עמדו כראוי. כי כשהכעס נשקט הוא בעמידה."],[2,"בשעתא דדינא וכו':","בשעה שהדין שורה בעולם, בית דין ההוא, דהיינו הנוקבא, הוא, כאשה מעוברת המקשה לילד, וכאשר ילדה, הבהלה שככה. כן כשהדין שורה בעולם, אינו נשקט ואינו נח, עד שנעשה הדין ברשעים, ואז הוא המנוחה שלו לעמוד במקומו בשלמות ולהמצא בקיומו. וזהו שכתוב, ובאבוד רשעים רנה. וכבר נתבאר."],[3,"באבוד רשעים וכו':","מקשה, על הכתוב באבוד רשעים רנה, והרי כתוב, החפוץ אחפוץ מות רשע, הרי שאין נחת לפני הקב\"ה כשנעשה דין ברשעים. ומשיב, אלא כאן קודם שנשלמה הסאה, אז אינו חפץ במות רשע, כאן לאחר שנשלמה הסאה, שאז באבוד רשעים רנה."],[4,"ויהיו חיי שרה: גופא דמתניתין,","עיקר המשנה הוא. כלומר תמצית המשנה. כי ארוכה היתה וקצרוה. \u0003אנן קריבין הוינא,\u0004 אנחנו היינו בעלי המשנה, קרובים היינו לפנימיות המדרגה \u0003שמענא, קלא מתהפך מלעילא לתתא, אתפשפת בעלמא,\u0004 שמענו \u0003קול\u0004 מתהפך להשפיע ממעלה למטה ומתפשט בעולם."],[4,"","פירוש. מאחר שז\"א, שה\"ס \u0003קול\u0004 עלה והכריע והשלים ב' קוין ימין ושמאל דבינה בהארתו שם ממטה למעלה, הוא מתהפך. ומתפשט משם לעולם, ומאיר ממעלה למטה \u0003קל מתבר טורין ומתבר טנרין תקיפין, הקול,\u0004 עוקר הרים, ומשבר סלעים תקיפים. כלומר שהארתו עוקר ומשבר כל הקליפות. \u0003עלעולין רברבין סלקין, אודננא פתיחן,\u0004 רוחות גדולות עולות, האזנים פתוחות. פירוש. כי מבאר מאין כח השפעתו של \u0003הקול,\u0004 שהוא ז\"א, ואומר, שרוחות גדולות, שהם ספירות הז\"א שנקרא \u0003רוח,\u0004 עולות לאזנים שה\"ס בינה בסוד מ\"ן, ונעשה שם קול, והוא מכריע שם בין ב' קוין דבינה, ומתלבש החכמה שבשמאל בחסדים שבימין, ואז \u0003אודננא פתיחן,\u0004 שנפתחו האזנים להאיר (כמ\"ש לעיל בפרשת לך בס\"ת דף ד' אות ו' ד\"ה וכרוזא קרי) ובשיעור \u0003שהקול\u0004 פתח האזנים להאיר, כן מתפשט ומאיר גם הוא, כמ\"ש לעיל (בראשית א' דף פ\"ז אות שס\"ג) תלת נפקי מחד חד בתלת קיימא, עש\"ה."],[5,"הוה אמר במטלנוי:","הקול היה אומר בנסיעותיו, דהיינו בהשפעתו, שנקרא נסיעה, משום שהולך \u0003בתלת דוכתי,\u0004 (כנ\"ל וירא יוד אות כ\"ח ד\"ה אמר ריב\"ז, ובראשית א' דף כ' אות י\"ב) \u0003קוץ קוציתא,\u0004 קצץ חלק, \u0003דמיכן דמימין שינתא בחוריהון, קמיימין בקיומייהו,\u0004 וישנים הדוממים, שהשינה בחורי עיניהם, חוזרים ועומדים על מעמדם."],[5,"","פירוש. כי נתבאר לעיל (פרשת לך דף י\"ג אות כ\"ב ד\"ה ונתבאר) שאין קו אמצעי יכול להכריע בין ב' הקוין ולכלול אותם זה בזה, מטרם שממעט את קו השמאל מג\"ר לו\"ק דג\"ר ע\"ש. וכן נתבאר (לעיל לך דף ו' אות ח' ד\"ה ווי) שבעת הארת השמאל בלי התכללות בחסדי הימין נסתמים כל האורות ונחשך הלילה ובני אדם ישנים, דהיינו שנסתלקו מהם המוחין. וז\"ש כאן, \u0003שהקול,\u0004 שה\"ס קו אמצעי, אומר \u0003קוץ קוציתא\u0004, קצץ חלק, כלומר שמצוה בכחו למעט חלק הג\"ר דג\"ר מהארת קו השמאל, ואז \u0003דמיכן דמימין שינתא בחוריהון.\u0004 ואז ישנים הדוממים שהשינה בחורי עיניהם, מחמת הארת השמאל בלי התכללות בימין, שסתם להם האורות, נמצאים עתה, שהם \u0003קיימין בקיומיהון,\u0004 שחוזרים ועומדים על מעמדם, כי עתה אחר שנתמעטו הג\"ר דשמאל, נכללו השמאל וימין זה בזה והאורות נפתחים (כנ\"ל לך דף ז' אות ט' ד\"ה ולית) וע\"כ נתעוררו הישנים והשיגו המוחין שלהם. שהם קיומם."],[5,"מלכא דממלל, נטרי תרעין:","מלך, היינו הנוקבא, שמקבלת מז\"א שנקרא \u0003קול,\u0004 שמדבר: שמרו השערים. \u0003שליטא דחילין סגיאין קם בקיומיה\u0004 השליט על צבאות רבות, עמד על מעמדו."],[5,"","פירוש. אחר שהמלך, דהיינו הנוקבא, קבלה המוחין מקול, שה\"ס קו אמצעי, אמרה, שמרו השערים, והיינו משום שהקול אמר \u0003קוץ קוציתא,\u0004 ומיעט הג\"ר, המשפיעים מלמעלה למטה, לפיכך אמרה גם הנוקבא, שמרו השערים, שלא ימשיכו ממעלה למטה. ואז השליט על צבאות רבות, שהוא מטטרון, עמד על מעמדו דהיינו שקבל המוחין ההם מן הנוקבא."],[6,"כלהו לא מרגשן ולא ידעי:","כולם אינם מרגישים ואינם יודעים, \u0003דספרא פתיח, ובשמא אכתוב, ודומה קאים ונטיל בחשבון\u0004 שהספר פתוח, ובשם כתוב, ודומה קם ומקבל בחשבון."],[6,"","פירוש. כי ג' הללו, \u0003ספר שם וחשבון\u0004 הם בהנוקבא, כי הנוקבא עצמה נקראת \u0003ספר,\u0004 שבה כל הנשמות, וממנה יוצאות. וכל נשמה ונשמה יש לה בהספר, שהוא הנוקבא, שיעור קומה, והוא נקרא \u0003שם.\u0004 ושיעור קומה ההיא יוצאת בזווג על מסך, כנודע, ומסך הזה נק' \u0003חשבון,\u0004 משום שקומת הזווג מחושב ומשוער בעוביות המסך, (כמ\"ש בפתיחה לחכמת הקבלה לעיל חלק א' דף ה' אות י\"ח עש\"ה). וז\"ש \u0003דספרא פתיח,\u0004 שהנוקבא פתוחה לקבל נשמות מז\"א. \u0003ובשמא אכתוב,\u0004 שכל נשמה יש לה שיעור קומה מיוחדת שם בהספר. שהיא יוצאת על חשבון, שה\"ס המסך. \u0003ודומה,\u0004 שהוא מלאך הממונה על המתים, לדונם בקברותיהם, ולהכשירם לתחית המתים, ועל נפשות הרשעים לדונם בגיהנם. \u0003קאים ונטיל בחושבנא, קם\u0004 בהתמנות שלו, \u0003ומקבל,\u0004 כח לדון הגופות \u0003בחשבון,\u0004 שה\"ס המסך דקו אמצעי."],[6,"","פירוש. יש ב' מיני דינים ועונשים א) הנמשכים משליטת קו שמאל מטרם שבא קו אמצעי (כנ\"ל וירא דף ע\"ב אות ר\"נ ד\"ה וה'). ב) הנמשכים מקו אמצעי עצמו אחר שהכליל ב' הקוין ימין ושמאל זה בזה. והוא מחמת שקו אמצעי, אומר \u0003במטלנוי קוץ קוציתא,\u0004 כנ\"ל, שפירושו שממעט הג\"ר דקו שמאל המשפיעות ממעלה למטה. ומכח זה, כל אלו הכלים, שבלעו פעם הארה זו ממעלה למטה מחויבים להתבטל ולהתחדש פעם שנית. ונודע שסוד אכילת עץ הדעת, ה\"ס המשכת השפע ממעלה למטה (כנ\"ל ב\"ב דף ק\"ע אות רפ\"ה ד\"ה ועל) שמטעם זה נגזר המיתה על הגופות. ומכח הארת קו האמצעי מחויבות הגופות להתבטל לגמרי, דהיינו להרקב בקבר, עד שלא ישאר מהם כי אם תרווד רקב, כי לא יצא מהם הזוהמא שקבלו, בפחות מזה, ואח\"ז בזמן התחיה חוזרים ומתחדשים, והממונה על הדין הזה, הוא \u0003המלאך דומה,\u0004 ועל כן מדייק \u0003ודומה קאים ונטיל בחושבנא,\u0004 שהוא קם להתמנות שלו, לדון הגופות בקברותיהם, שמקבל מכח \u0003החשבון,\u0004 דהיינו מהמסך דחירק שבקו אמצעי, הנקרא חשבון, דהיינו מין הב' דדינים ועונשים, הנמשכים מקו אמצעי, מהמסך שלו כנ\"ל."],[6,"","ולפיכך, רק אלו שזכו בחייהם לקבל המוחין מקו אמצעי, הנה אחר מיתתם, ידונו גופותיהם ביד \u0003דומה,\u0004 מכח קו אמצעי כנ\"ל. אבל אלו שבחייהם לא זכו לקבל המוחין דקו אמצעי האמורים, אלא שהיו דבוקים בקו שמאל, הרי הדינים ועונשים הבאים עליהם הם ממין הא' הנ\"ל, ולא מקו אמצעי, ועל כן אחר מיתתם לא יקבל \u0003דומה\u0004 את הגופות שלהם, מכח שדיניו רק מקו אמצעי הם, ואלו, שלא זכו בו בחייהם, איך יזכה בו לאחר מיתה, כמו שהתוספתא מבארת לפנינו."],[6,"","וההפרש אם הגופות ידונו תחת יד דומה, או לא, הוא גדול מאד. כי סוד תחית המתים נמשך מזווג הכולל הגדול שיהיה בגמר התקון, שענינו, שכל הזווגים, והקומות שיצאו מהם, בזה אחר זה, במשך שתא אלפי שני, יתקבצו כולם בזווג הכולל בבת אחת, שסיבת קיבוצם בבת אחת, מביא אור גדול מאד, המביא את גמר התקון (כמ\"ש זה לעיל בהקדמת הזהר דף ק' אות צ\"א ד\"ה וז\"ש בן איש חי ע\"ש) ולפיכך אלו הגופות שנדונו תחת יד \u0003דומה,\u0004 דהיינו מבחינת הזווגים שבקו אמצעי, מכח החשבון שבכל זווג כנ\"ל, נעשו בזה מוכנים לקבל גם כן, קבוץ כל הזווגים בבת אחת שבגמר התקון, ויעמדו לתחית המתים. שז\"ס שהמלאך דומה מקבל המתים \u0003בחשבון,\u0004 דהיינו במדת הזווג, ואח\"כ לעת תחית המתים מוציאם \u0003בחשבון,\u0004 כי אז, יתקבצו כל החשבונות לחשבון אחד, ויחיו המתים כנ\"ל. אבל הנדונים ממין הא' של העונשים, דהיינו מקו השמאל, אשר גופותיהם לא נכללו בחשבון שמקו אמצעי, שדומה אינו מקבלם מחמת זה בחשבון, הם לא יקומו לתחית המתים, כי אין להם חלק באור גדול הזה שנתקבץ מכל הזווגים שבקו אמצעי."],[6,"ודיירי עפרא תייבין לבר:","ושוכני עפר, דהיינו הרשעים, אינם בכלל הזווג דקול ודבור הנ\"ל, אלא שחוזרים לחוץ. כלומר אף על פי שכבר באו בפנימיות כדי לקבל מקו אמצעי, יחזרו לחוץ ולא ירצו לקבל ממנו, כי \u0003וקריב טב לאתמנאה בהו, לא תאיבין גלגולא והפוך\u0004 וקרב טוב, היינו קו אמצעי, שהוא יסוד הנקרא טוב, להיות מחושב בהם, דהיינו להשפיע להם בסוד חשבון, אינם רוצים בגלגול והיפוך. פירוש. כי המוחין הנמשכים בסוד חשבון מקו אמצעי נמשכים בסוד \u0003גלגולא\u0004 שפירושו, שמתגלגלים ובאים בזה אחר זה בסדר ג' נקודות חולם שורק חירק, כמ\"ש לעיל (בפרשת וירא י\"ז אות מ\"ח ד\"ה וזה אמרו ע\"ש) וכן נתקן סוד היפוך המדרגות בהארת השמאל, שמה שהיה בו מקודם לכן ג\"ר למעלה ואחריהן ו\"ק, ואחריהן גזירת דינא, נתהפכו, והגזירת דינא נעשה עליון ואחריה ו\"ק ולבסוף כולם הג\"ר, (כנ\"ל פרשת וירא דף פ\"ג אות רפ\"ו ד\"ה פנימיות עש\"ה) וזהו שאלו הרשעים הדבקים בקו שמאל אינם רוצים בהמוחין מקו האמצעי, משום שבאים בגלגול על ג' נקודות, ובהיפוך המדרגות בקו שמאל. וז\"ש, \u0003לא תאיבין בגלגולא והפוך.\u0004 להיותם חפצים רק בג\"ר דשמאל הנמשכים להם ממעלה למטה."],[7,"נפלין ולא קיימין:","משום שאינם חפצים במוחין הבאים בגלגול והפוך, כנ\"ל, נופלים ואינם עומדים לתחיה, \u0003אתמחון חייבין מספרא דדומה,\u0004 ועל כן, הרשעים נמחים מספרו של דומה, כי הוא מקבל רק בחשבון מקו אמצעי, שהרשעים אינם כלולים ממנו כנ\"ל. וע\"כ, \u0003מאן יתבע לון,\u0004 מי ידרוש אותם בעת תחית המתים, כי אומר להלן (ד\"י דף קכ\"ד ע\"ב ובסולם דף כ' אות ס' במדרש הנעלם) שבעת תחית המתים, \u0003יקבל המלאך מטטרון חושבן פתקא, בבתי קברי מן דומה,\u0004 כמו שיתבאר שם, אבל אותם הרשעים שאינם בחשבון של דומה מי ידרוש אותם לתחית המתים. \u0003ומאן יתיב בחושבנהון.\u0004 ומי יושב בחשבון שלהם, רומז בזה לקליפה הקשה הנקראת סיחון, היושב בחשבון. שהוא הלעומת כנגד דומה, כי דומה פירושו דממה, וסיחון הוא שיחה ודיבור. \u0003ווי לון ווי לחייהון ווי לרגשיהון, בגינהון אתקרי ימחו מספר חיים וגו':\u0004 ווי להם ווי לחייהם ווי למכאוביהם. בשבילם נאמר, ימחו מספר חיים וגו', כי אינם עומדים לתחיית המתים."],[8,"ויהיו חיי שרה:","שואל, מה השינוי כאן בשרה, שנאמר מיתתה בתורה, מכל נשי העולם, שלא נאמר מיתתן בתורה. אמר רבי חייא, ולא, והרי כתוב, ותמת רחל וגו', וכתוב ותמת שם מרים וגו', וכתוב ותמת דבורה מינקת רבקה. וכתוב ותמת בת שוע אשת יהודה. הרי שכמה נשים כתובה מיתתן בתורה."]],[[0,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם עוֹלֶה עַל מִטָּתוֹ בְּכָל לַיְלָה וְלַיְלָה, נִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ וְנִדּוֹנֵית לִפְנֵי בֵּית הַדִּין שֶׁל הַמֶּלֶךְ. אִם זַכַּאי לְהִתְקַיֵּם - חוֹזֶרֶת לָעוֹלָם הַזֶּה."],[1,"","וְהַדִּין הוּא בִּשְׁנֵי גְוָנִים, שֶׁהֲרֵי אֵין דָּנִים אֶת הָאִישׁ עַל הָרָעוֹת שֶׁהוּא עָתִיד וּמְזֻמָּן לַעֲשׂוֹת, שֶׁכָּתוּב (בראשית כא) כִּי שָׁמַע אֱלֹהִים וְגוֹ' בַּאֲשֶׁר הוּא שָׁם. וְלֹא תֹאמַר שֶׁדָּנִים אוֹתוֹ עַל הַטּוֹבוֹת שֶׁעָשָׂה לְחוּד, אֶלָּא לְהֵיטִיב לוֹ עַל אוֹתָם טוֹבוֹת שֶׁל עַכְשָׁו, כְּמוֹ שֶׁנִּתְבָּאֵר. וְדָנִים אוֹתוֹ עַל זְכֻיּוֹת שֶׁעָתִיד לַעֲשׂוֹת, וּבִשְׁבִילָם הוּא נִצּוֹל, אַף עַל גַּב שֶׁהוּא כָּעֵת רָשָׁע. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם כָּל הַבְּרִיּוֹת, וְכָל דַּרְכּוֹ שֶׁהוּא עוֹשֶׂה - לְהֵיטִיב לַכֹּל, וְלֹא דָן אֶת הָאָדָם עַל הָרָעוֹת שֶׁהוּא עָתִיד לַעֲשׂוֹת, וּמִשּׁוּם כָּךְ נִדּוֹן הָאָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","בֹּא רְאֵה, כֵּיוָן שֶׁהִטִּילוּ אֶת יוֹנָה לַיָּם מַה כָּתוּב? וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. הַיָּם הָעֶלְיוֹן. מַה זֶּה וַיַּעֲמֹד? שֶׁעָמַד בְּקִיּוּמוֹ כָּרָאוּי. הוּא בַּעֲמִידָה כְּשֶׁהָרֹגֶז שׁוֹכֵךְ. בְּשָׁעָה שֶׁהַדִּין שָׁרוּי בָּעוֹלָם, אוֹתוֹ בֵּית הַדִּין הוּא כְּמוֹ אִשָּׁה שֶׁמִּתְעַבֶּרֶת וּמַקְשָׁה לָלֶדֶת, וּכְשֶׁמּוֹלִידָה, שׁוֹכֵךְ הָרֹגֶז. כָּךְ גַּם כְּשֶׁהַדִּין שׁוֹרֶה בָּעוֹלָם, לֹא שׁוֹכֵךְ וְלֹא נָח עַד שֶׁנַּעֲשֶׂה הַדִּין בָּרְשָׁעִים, וְאָז הוּא הַמְּנוּחָה שֶׁלּוֹ, לַעֲמֹד בְּמָקוֹם שָׁלֵם וְלַעֲמֹד בְּקִיּוּמוֹ. זֶהוּ שֶׁכָּתוּב (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה. וְזֶה בֵּאַרְנוּ."],[3,"","בַּאֲבֹד רְשָׁעִים רִנָּה. וַהֲרֵי כָּתוּב (יחזקאל יח) הֶחָפֹץ אֶחְפֹּץ מוֹת רָשָׁע? וַהֲרֵי אֵין נַחַת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנַּעֲשֶׂה דִין בָּרְשָׁעִים? ! אֶלָּא כָּאן קֹדֶם שֶׁנִּשְׁלְמָה הַסְּאָה - וְכָאן אַחַר שֶׁנִּשְׁלְמָה הַסְּאָה (יש לו נחת)."],[4,"","וַיִּהְיוּ חַיֵּי שָׂרָה. גּוּף הַמִּשְׁנָה, אָנוּ קְרוֹבִים הָיִינוּ, שָׁמַעְנוּ קוֹל מִתְהַפֵּךְ מִמַּעְלָה לְמַטָּה מִתְפַּשֵּׁט בָּעוֹלָם, קוֹל מְשַׁבֵּר הָרִים וּמְשַׁבֵּר סְלָעִים חֲזָקִים, רוּחוֹת חֲזָקוֹת עוֹלוֹת. אָזְנֵינוּ פְתוּחוֹת."],[5,"","הָיָה אוֹמֵר בְּמַסָּעָיו, אָקִיץ בְּקוֹץ הַיְשֵׁנִים הַדּוֹמְמִים. שֵׁנָה בְּחוֹרֵיהֶם (בעיניהם), עוֹמְדִים עַל עָמְדָּם. הַמֶּלֶךְ שֶׁמְּדַבֵּר, (ולא עברו, נמצאו) שׁוֹמְרֵי הַשְּׁעָרִים, שִׁלְטוֹן שֶׁל חֲיָלוֹת רַבִּים עוֹמֵד עַל עָמְדּוֹ."],[6,"","כֻּלָּם לֹא מַרְגִּישִׁים וְלֹא יוֹדְעִים שֶׁהַסֵּפֶר פָּתוּחַ וּבַשֵּׁם נִכְתָּבִים, וְדוּמָה עוֹמֵד וְנוֹטֵל בְּחֶשְׁבּוֹן, וְשׁוֹכְנֵי עָפָר שָׁבִים לַחוּץ, וְקָרֵב טוב לְהִמָּנוֹת בָּהֶם, אֵינָם חוֹשְׁקִים בְּגִּלְגּוּל וְהִפּוּךְ."],[7,"","נוֹפְלִים וְלֹא עוֹמְדִים, נִמְחִים הַחַיָּבִים מִסִּפְרוֹ שֶׁל דּוּמָה, מִי יְבַקֵּשׁ אוֹתָם וּמִי יֵשֵׁב בְּחֶשְׁבּוֹנוֹתֵיהֶם. אוֹי לָהֶם! אוֹי לְחַיֵּיהֶם! אוֹי לָרְגָשׁוֹת שֶׁלָּהֶם (לנפשותם) ! בִּשְׁבִילָם נֶאֱמַר (תהלים סט) יִמָּחוּ מִסֵּפֶר חַיִּים וְגוֹ'."],[8,"","וַיִּהְיוּ חַיֵּי שָׂרָה. מַה שּׁוֹנֶה כָּאן שֶׁכְּתוּבָה מִיתָתָהּ בַּתּוֹרָה מִכָּל נְשׁוֹת הָעוֹלָם שֶׁלֹּא כְתוּבָה כָּךְ מִיתָתָן בַּתּוֹרָה? אָמַר רַבִּי חִיָּיא, וְלֹא!? וְהִנֵּה כָּתוּב (בראשית לה) וַתָּמָת רָחֵל וַתִּקָּבֵר בְּדֶרֶךְ אֶפְרָתָה, וְכָתוּב (במדבר כ) וַתָּמָת שָׁם מִרְיָם וְגוֹ', וְכָתוּב (בראשית לה) וַתָּמָת דְּבוֹרָה מֵינֶקֶת רִבְקָה, וְכָתוּב (בראשית לח) וַתָּמָת בַּת שׁוּעַ אֵשֶׁת יְהוּדָה."]]],[["אָמַר רַבִּי יוֹסֵי בְּכֻלְּהוּ לָא כְּתִיב כְּמָה דִכְתִיב בְּשָׂרָה דְּאִתְּמָר וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים שְׁנֵי חַיֵּי שָׂרָה. דְּהָא בְּכֻלְּהוּ לָא אִתְמָנוּן יוֹמִין וּשְׁנִין כְּמוֹ לְשָׂרָה. בְּכֻלְּהוּ לָא כְּתִיב פָּרְשָׁתָא חָדָא בִּלְחוּדָהָא כְּמוֹ לְשָׂרָה. אֶלָּא רָזָא אִיהוּ בְּגִין הַהוּא דַרְגָּא דְּכָל יוֹמִין וּשְׁנִין דְּבַר נָשׁ בֵּיהּ תַּלְיָין (דדא היא ה\"א בתראה).","פָּתַח וְאָמַר, (קהלת ה׳:ח׳) וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא מֶלֶךְ לְשָׂדֶה נֶעֱבָד. וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא וַדַּאי דְּהָא מִתַּמָּן נָפְקִין רוּחִין וְנִשְׁמָתִין וְתוֹעַלְתָּא לְעַלְמָא. מֶלֶךְ לְשָׂדֶה נֶעֱבָד, מַאן מֶלֶךְ דָּא קוּדְשָׁא בְּרִיךְ הוּא. לְשָׂדֶה נֶעֱבָד כַּד אִיהוּ (עז ב אתתקן כדקא יאות. ומלך, דא, מלך עלאה דאתחבר לשדה כד איהו נעבד. מאן שדה, דא שדה אשר ברכו יי. דכתיב, (בראשית כ״ז:כ״ז)) כְּרִיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ. דְּכַד אִיהוּ (אתעבד) נֶעֱבַד וְאִתְתַּקַּן בְּכָל מַה דְּאִצְטְרִיךְ לֵיהּ כְּדְקָא יָאוֹת, כְּדֵין מֶלֶךְ עִלָּאָה אִתְחַבַּר עִמֵּיהּ.","רַבִּי אֶלְעָזָר אָמַר, מֶלֶךְ לְשָׂדֶה נֶעֱבָד. כַּמָּה גַוְונֵי רָזִין עִלָּאִין הָכָא. מֶלֶךְ. דָּא (עזב) שְׁכִינְתָּא דְּלָא שַׁרְיָא בְּבֵיתָא לְאִתְתַּקָּנָא בָהּ אֶלָּא בְּזִמְנָא דְּאִתְנָסִיב בַּר נָשׁ וְאִזְדַּוַּוג בְּאִנְתְּתֵיהּ לְאוֹלָדָא וּלְמֶעְבַּד אִיבִּין, וְאִיהִי אֲפִיקַת נִשְׁמָתִין לְאַשְׁרָאָה בָהּ, וּבְגִין כָּךְ לְשָׂדֶה נֶעֱבָד וְלָא לְאָחֳרָא.","דָּבָר אַחֵר מֶלֶךְ דָּא אִשָּׁה יִרְאַת יְיָ כְּמָא דְאַתְּ אָמֵר, (משלי ל״א:ל׳) אִשָּׁה יִרְאַת יְיָ הִיא תִתְהַלָּל. לְשָׂדֶה נֶעֱבָד דָּא אִשָּׁה זָרָה כְּמָא דְאַתְּ אָמֵר, (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָּׁה זָרָה. בְּגִין דְּאִית שָׂדֶה וְאִית שָׂדֶה. אִית שָׂדֶה דְּכָל בִּרְכָאָן וְקִדּוּשִׁין בֵּיהּ שַׁרְיָין כְּמָה דְאַתְּ אָמֵר כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ. וְאִית שָׂדֶה דְּכָל חִירוּב וּמְסָאֲבוּ וְשֵׁיצָאָה וְקָטוֹלִין וּקְרָבִין בֵּיהּ שָׁרְיָין. וְהַאי מֶלֶךְ זִמְנִין דְּאִיהוּ נֶעֱבַד לְהַאי שָׂדֶה דִּכְתִיב, (משלי ל׳:כ״ב) תַּחַת שָׁלשׁ רָגְזָה אֶרֶץ וְגו', תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגו' וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. וְהַאי מֶלֶךְ אִתְכַּסְּיָא נְהוֹרֵיהּ וְאִתְחַשָּׁךְ עַד דְּאִתְדַּכֵּי וְאִתְחַבַּר לְעֵילָא."],[[0,"אמר ר' יוסי וכו':","ומשיב ר' יוסי, בכולן לא כתוב כמו שכתוב בשרה, שנאמר בה, ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים שני חיי שרה, שהרי בכולן לא נמנו ימים ושנים כמו לשרה. בכולן לא כתוב פרשה מיוחדת כמו לשרה. אלא שהוא סוד, מ\"ש בשרה ימים ושנים ופרשה מיוחדת, משום שהיא המדרגה, שכל הימים והשנים של אדם בה תלוים. כלומר, מאלו המוחין שה\"ס חיי שרה, המרומזים בהמספרים מאה שנה ועשרים שנה ושבע שנים, נמשכים החיים של האדם כמו שיתבאר לפנינו."],[1,"פתח ואמר ויתרון ארץ בכל הוא מלך לשדה נעבד:","ויתרון ארץ, שהוא הנוקבא, \u0003בכל,\u0004 הוא ודאי, שהוא יסוד דז\"א הנק' \u0003כל,\u0004 כי משם, מן היסוד, יוצאים רוחות ונשמות. ותועלת העולם."],[1,"מלך לשדה נעבד:","ושואל, מי הוא המלך ואומר שזהו הקב\"ה, \u0003לשדה נעבד,\u0004 כשהוא נתקן כראוי, ומלך זהו מלך עליון, דהיינו ז\"א, שנתחבר לשדה, כשהוא נעבד. ושואל, מי הוא שדה. ואומר זהו שדה אשר ברכו ה'. דהיינו, הנוקבא, שכתוב כריח שדה אשר ברכו ה'. כי כשנעבד ונתתקן בכל הצורך כראוי, אז מלך העליון, ז\"א, מתחבר עמו."],[2,"ר' אלעזר אמר:","רא\"א, \u0003מלך לשדה נעבד,\u0004 כמה פנים של סודות עליונים מרומזים כאן, \u0003מלך,\u0004 זה השכינה, שאינה שורה בביתו של אדם להתתקן בה, אלא בזמן שהאדם נשוי, ומזדווג באשתו כדי להוליד ולעשות פירות, והיא היינו השכינה מוציאה נשמות לשכן אותן בה, ומשום זה היא מתחברת רק לשדה נעבד, ולא לאחר."],[3,"ד\"א מלך דא אשה וכו':","פירוש אחר. \u0003מלך\u0004 זה היא אשה יראת ה', כמו שאתה אומר אשה יראת ה' היא תתהלל. דהיינו השכינה. \u0003לשדה נעבד,\u0004 זה היא אשה זרה דהיינו הס\"א, כמו שאתה אומר לשמרך מאשה זרה. משום שיש שדה ויש שדה. יש שדה שכל הברכות והקדושות שורות בו, כמו שאתה אומר כריח שדה אשר ברכו ה'. דהיינו השכינה. ויש שדה, שכל חורבן וטומאה, וכליה, והריגות ומלחמות, שורות בו. דהיינו הסטרא אחרא."],[3,"והאי מלך וכו':","ומלך הזה. דהיינו השכינה, לפעמים שהוא נעבד לשדה ההוא, להס\"א, שכתוב תחת שלש רגזה ארץ וגו', ושפחה כי תירש גבירתה. שהשדה דס\"א תירש השכינה ח\"ו, ואז מלך הזה, שהוא השכינה, נתכסה אורה ונחשכה, עד שתטהר ותתחבר למעלה לז\"א."]],[[0,"","אָמַר רַבִּי יוֹסֵי, בְּכֻלָּם לֹא כָתוּב כְּמוֹ שֶׁכָּתוּב בְּשָׂרָה, שֶׁנֶּאֱמַר וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים שְׁנֵי חַיֵּי שָׂרָה. שֶׁהֲרֵי בְּכֻלָּם לֹא נִמְנוּ יָמִים וְשָׁנִים כְּמוֹ לְשָׂרָה, וּבְכֻלָּם לֹא כָתוּב פָּרָשָׁה אַחַת לְבַדָּהּ כְּמוֹ לְשָׂרָה. אֶלָּא סוֹד הוּא, מִשּׁוּם אוֹתָהּ הַדַּרְגָּה שֶׁכָּל הַיָּמִים וְהַשָּׁנִים שֶׁל אָדָם תְּלוּיִים בָּהּ (שזו היא ה\"א האחרונה)."],[1,"","פָּתַח וְאָמַר, (קהלת ה) וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא מֶלֶךְ לְשָׂדֶה נֶעֱבָד. וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא וַדַּאי, שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת הָרוּחוֹת וְהַנְּשָׁמוֹת וְתוֹעֶלֶת לָעוֹלָם. מֶלֶךְ לְשָׂדֶה נֶעֱבָד, מִי הַמֶּלֶךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. לְשָׂדֶה נֶעֱבָד, כְּשֶׁהוּא נִתְקָן כָּרָאוּי. וּמֶלֶךְ זֶה הַמֶּלֶךְ הָעֶלְיוֹן שֶׁמִּתְחַבֵּר לַשָּׂדֶה כְּשֶׁהוּא נֶעֱבָד. מִי הַשָּׂדֶה? זֶה הַשָּׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', שֶׁכָּתוּב (בראשית כז) כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. שֶׁכְּשֶׁהוּא (נעשה) נֶעֱבָד וְנִתְקָן בְּכָל מַה שֶּׁצָּרִיךְ לוֹ כָּרָאוּי, אָז הַמֶּלֶךְ הָעֶלְיוֹן מִתְחַבֵּר עִמּוֹ."],[2,"","רַבִּי אֶלְעָזָר אָמַר, מֶלֶךְ לְשָׂדֶה נֶעֱבָד - כַּמָּה גְוָנִים סוֹדוֹת עֶלְיוֹנִים כָּאן. מֶלֶךְ - זוֹ הַשְּׁכִינָה שֶׁאֵין שׁוֹרָה בַּבַּיִת לְהִתַּקֵּן בָּהּ אֶלָּא בִּזְמַן שֶׁנִּשָּׂא אָדָם וּמִזְדַּוֵּג עִם אִשְׁתּוֹ לְהוֹלִיד וְלַעֲשׂוֹת פֵּרוֹת, וְהִיא מוֹצִיאָה נְשָׁמוֹת לְהַשְׁרוֹת בָּהּ, וּמִשּׁוּם כָּךְ לְשָׂדֶה נֶעֱבָד וְלֹא לְאַחֵר."],[3,"","דָּבָר אַחֵר, מֶלֶךְ - זוֹ אִשָּׁה יִרְאַת ה', כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) אִשָּׁה יִרְאַת ה' הִיא תִתְהַלָּל. לְשָׂדֶה נֶעֱבָד - זוֹ אִשָּׁה זָרָה, כְּמוֹ שֶׁנֶּאֱמַר (שם ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה. מִשּׁוּם שֶׁיֵּשׁ שָׂדֶה וְיֵשׁ שָׂדֶה. יֵשׁ שָׂדֶה שֶׁכָּל הַבְּרָכוֹת וְהַקְּדֻשּׁוֹת בּוֹ שׁוֹרוֹת, כְּמוֹ שֶׁנֶּאֱמַר כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', וְיֵשׁ שָׂדֶה שֶׁכָּל חֻרְבָּן וְטֻמְאָה וְכִלָּיוֹן וְהֶרֶג וּקְרָבוֹת שְׁרוּיִים בּוֹ, וְהַמֶּלֶךְ הַזֶּה לִפְעָמִים שֶׁהוּא נֶעֱבָד לַשָּׂדֶה הַזּוֹ, שֶׁכָּתוּב (שם ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ' תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגוֹ' וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. וְהַמֶּלֶךְ הַזֶּה מִתְכַּסֶּה אוֹרוֹ וְנֶחְשָׁךְ עַד שֶׁנִּטְהָר וּמִתְחַבֵּר לְמַעְלָה."]]],[["וּבְגִין כָּךְ שָׂעִיר דְּרֹאשׁ חוֹדֶשׁ, בְּגִין דְּאִתְפְּרַשׁ הַהוּא שָׂדֶה מִמַּלְכָּא קַדִּישָׁא וְלָא שַׁרְיָין בְּהַאי שָׂדֶה בִּרְכָאָן מֵהַאי מֶלֶךְ. וְכַד אִיהוּ נֶעֱבַד לְהַאי שָׂדֶה כְּדֵין כְּתִיב, (דברים כ״ב:כ״ז) כִּי בַשָּׂדֶה מְצָאָהּ וְגו'. כִּי בַּשָּׂדֶה כְּמָה דְאִתְּמָר.","תָּא חֲזֵי, אָתַת חַוָּה לְעַלְמָא אִתְדַּבְּקַת בְּהַאי חִוְּיָא וְאַטִּיל בָהּ זוּהֲמָא. וְגָרְמָא מוֹתָא לְעַלְמָא וּלְבַעֲלָהּ. אָתַת שָׂרָה וְנָחֲתַת וְסָלְקַת וְלָא אִתְדַּבְּקַת בֵּיהּ כְּמָא דְאַתְּ אָמֵר, (בראשית י״ג:א׳) וַיַּעַל אַבְרָם מִמִּצְרַיִם הוּא וְאִשְׁתּוֹ וְכָל אֲשֶׁר לוֹ. אֲתָא נֹחַ לְעַלְמָא מַה כְּתִיב (בראשית ט׳:כ״א) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל וְגו'.","וּבְגִין דְּאַבְרָהָם וְשָׂרָה לָא אִתְדַּבָּקוּ בֵּיהּ, בְגִין כָּךְ שָׂרָה זָכְתָה לְחַיִּין עִלָּאִין לָהּ וּלְבַעֲלָהּ וְלִבְנָהָא בַּתְרָאָה הֲדָא הוּא דִכְתִיב (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חוּצַבְתֶּם וְאֶל מַקֶּבֶת בּוֹר נוּקַרְתֶּם. וְעַל דָּא וַיִּהְיוּ חַיֵּי שָׂרָה דְּזָכְתָה בְּהוּ בְּכֻלְּהוּ, וְלָא כְּתִיב בְּכֻלְּהוּ נַשֵּׁי וַיִּהְיוּ חַיֵּי חַוָּה, וְכֵן בְּכֹלָּא, הִיא אִתְדַּבְּקַת בַּחַיִּין, וְעַל דָּא דִילָהּ הֲווּ חַיִּין:","\u0003תּוֹסֶפְתָּא\u0004 זַכָּאָה אִיהוּ מַאן דְּאַזְעִיר גַּרְמֵיהּ בְּהַאי עַלְמָא. כַּמָּה אִיהוּ רַב וְעִלָּאָה בְּהַהוּא עַלְמָא. וְהָכִי פָּתַּח רַב מְתִּיבְתָּא מַאן דְּאִיהוּ זְעֵיר אִיהוּ רַב. מַאן דְּאִיהוּ רַב אִיהוּ זְעֵיר. דִּכְתִּיב וַיִּהְיוּ חַיֵּי שָׂרָה וְגו' מֵאָה דְּאִיהוּ חוּשְׁבַּן רַב כְּתִּיב בֵּיהּ שָׁנָה, זְעִירוּ דִשְׁנִין חַד אַזְעִיר לֵיהּ. שֶׁבַע דְּאִיהוּ חוּשְׁבַּן זָעִיר אַסְגֵּי לֵיהּ ורַבֵּי לֵיהּ דִּכְתִּיב שָׁנִים. תָּא חֲזֵי, דְּלָא רַבֵּי קוּדְשָׁא בְּרִיךָ הוּא אֶלָּא לִדְאַזְעִיר, ולָא אַזְעִיר אֶלָּא לִדְרַבֵּי. זַכָּאָה אִיהוּ מַאן דְּאַזְעִיר גַּרְמֵיהּ בְּהַאי עַלְמָא, כַּמָּה אִיהוּ רַב בְּעִלּוּיָא לְהַהוּא עַלְמָא. עַד כָּאן.","מַאן דְּפָּסַק יִתְּפַּסַק. מַאן דְּקָצַּר יִתְּקַצַּר. מַאן דְּקָצַּר יִתְּאָרַךָ. רְצּוֹנוֹ לוֹמַר מַאן דְּפָּסַק מִלִּין דְּאוֹרַיְיתָּא על מִלִּין בְּטֵלִין יִתְּפַּסְקוּן חַיּוֹהִי מֵהַאי עַלְמָא וְדִינִיהּ קָיְימָא בְּהַהוּא עָלְמָא. מַאן דְּקָצַּר אָמֵן ולָא מַאֲרִיךָ גּוֹ נַיְיחָא יִתְּקַצַּר מֵחַיִּין דְּהַאי עָלְמָא. מַאן דְּאָמַר אֶחָד אִצְּטְרִיךָ לְחָטְפָּא אָלֶ\"ף וּלְקַצֵּר קַרְנָא דִילֵיהּ ולָא יְעַכֵּב בְּהַאי אוֹתּ כְּלָל, וּמַאן דְּיַעֲבִיד דָּא יִתְּאָרְכוּן חַיָּיו. (אלו הם חדושים שהגידו לרבי שמעון בר יוחאי בישיבה של מעלה), (עד כאן התוספתא השייך לדף קכב ע\"ב)","וַיִּהְיוּ חַיֵּי שָׂרָה. אִינוּן חַיִּין כֻּלְּהוּ לְעֵילָא, מֵאָה שָׁנָה לְעֵילָא. וְעֶשְׂרִים שָׁנָה לְעֵילָא, וְשֶׁבַע שָׁנִים לְעֵילָא, כֻּלְּהוּ הֲווּ כְּדְקָא יְאוּת. אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי רָזָא דְמִלָּה, מַאי שְׁנָא בְּכֻלְּהוּ דְּאָמַר שָׁנָה שָׁנָה, וּבְאִינוּן שֶׁבַע דְּאָמַר שָׁנִים. דִּכְתִיב מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה, וּלְבָתַר שֶׁבַע שָׁנִים."],[[0,"ובגין כך וכו':","ומשום זה בא השעיר דראש החדש, שאז נפרד שדה ההוא, הס\"א, מן המלך הקדוש שהיא השכינה, וברכות אינן שורות בשדה ההוא, בס\"א. אבל כשהוא נעבד לשדה ההוא, לס\"א, אז כתוב, כי בשדה מצאה. את השכינה, צעקה הנערה המאורשה ואין מושיע לה, כי בשדה, היינו הס\"א, כמו שנתבאר."],[1,"ת\"ח אתת חוה וכו':","בוא וראה, באה חוה לעולם, נדבקה באותו הנחש, והטיל בה זוהמא, וגרמה מות לעולם, ולבעלה. באה שרה, וירדה, למקום הס\"א, ועלתה, ולא נדבקו בה הקליפות, כמש\"א ויעל אברם ממצרים הוא ואשתו וכל אשר לו. בא נח לעולם, מה כתוב, וישת מן היין וישכר ויתגל."],[2,"ובגין דאברהם וכו':","ומשום שאברהם ושרה לא נתדבקו בס\"א, זכתה שרה לחיים עליונים לה ולבעלה ולבניה אחריה, וזהו שכתוב הביטו אל צור חוצבתם, דהיינו אברהם, ומקבת בור נוקרתם דהיינו שרה. וע\"כ כתוב, ויהיו חיי שרה, שזכתה בהן בכולן, בכל השנים שלא כתוב כן בכל הנשים, שלא כתוב, ויהיו חיי חוה, וכן בכולן, כי היא נדבקה בחיים, ועל כן החיים, שלה הם."],[3,"זכאה איהו וכו':","אשרי הוא מי שממעט את עצמו בעולם הזה, כמה הוא גדול ועליון בעולם הנצחי. וכן פתח ראש הישיבה, מי שהוא קטן בעוה\"ז, הוא גדול בעולם הנצחי, ומי שהוא גדול בעוה\"ז הוא קטן בעולם הנצחי. שכתוב ויהיו חיי שרה וגו', \u0003מאה\u0004 שהוא חשבון גדול כתוב בו \u0003שנה,\u0004 למיעוט של שנה אחד המעיט אותו. \u0003שבע,\u0004 שהוא חשבון קטן, הגדיל אותו והרבה אותו, שכתוב בו \u0003שנים.\u0004"],[3,"ת\"ח דלא רבי וכו':","בוא וראה שאין הקב\"ה מגדיל אלא להמקטין עצמו, ואינו מקטין אלא להמגדיל עצמו. אשרי הוא מי שמקטין עצמו בעולם הזה, כמה הוא גדול במעלה לעולם הנצחי (עד כאן התוספתא) מכאן עד סוף התוספתא שבאות כ\"ב הוא גליון, ואין לו שום שייכות לכאן. והם מדברי הזהר פרשת שלח ח\"ג קס\"ב ע\"א ובסולם אות צ\"ד. ויתבאר במקומו בע\"ה."],[5,"ויהיו חיי שרה:","אלו החיים הם כולם למעלה, בבינה, מאה שנה, שהוא כתר, למעלה. ועשרים שנה, שהם חו\"ב, למעלה. ושבע שנים, שהם ז\"ת למעלה. שה\"ס ג\"ר וז\"ת דבינה, שמשם קבלה שרה החיים, שהם המוחין."],[5,"אמר ר' שמעון וכו':","אר\"ש, בוא וראה סוד הדבר. מהו השינוי, שבכולן נאמר שנה שנה, ובשבע, נאמר שנים. שכתוב, מאה \u0003שנה,\u0004 ועשרים \u0003שנה,\u0004 ואחר כך שבע \u0003שנים.\u0004"]],[[0,"","וּמִשּׁוּם כָּךְ הַשָּׂעִיר שֶׁל רֹאשׁ חֹדֶשׁ, מִשּׁוּם שֶׁנִּפְרָד הַשָּׂדֶה הַהוּא מִן הַמֶּלֶךְ הַקָּדוֹשׁ וְלֹא שׁוֹרוֹת בַּשָּׂדֶה הַזּוֹ בְּרָכוֹת מִן הַמֶּלֶךְ הַזֶּה. וּכְשֶׁהוּא נֶעֱבָד לַשָּׂדֶה הַזּוֹ, אָז כָּתוּב (דברים כב) כִּי בַשָּׂדֶה מְצָאָהּ וְגוֹ'. כִּי בַשָּׂדֶה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[1,"","בֹּא רְאֵה, בָּאָה חַוָּה לָעוֹלָם וְנִדְבְּקָה בַּנָּחָשׁ הַזֶּה, וְהִטִּיל בָּהּ זֻהֲמָה, וְגָרְמָה מָוֶת לָעוֹלָם וּלְבַעְלָהּ. בָּאָה שָׂרָה וְיָרְדָה וְעָלְתָה וְלֹא נִדְבְּקָה בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יג) וַיַּעַל אַבְרָם מִמִּצְרַיִם הוּא וְאִשְׁתּוֹ וְכָל אֲשֶׁר לוֹ. בָּא נֹחַ לָעוֹלָם, מַה כָּתוּב? (שם ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל וְגוֹ'."],[2,"","וּמִשּׁוּם שֶׁאַבְרָהָם וְשָׂרָה לֹא נִדְבְּקוּ בוֹ, מִשּׁוּם כָּךְ זָכְתָה לְחַיִּים עֶלְיוֹנִים לָהּ וּלְבַעְלָהּ וּלְבָנֶיהָ אַחֲרֶיהָ. זֶהוּ שֶׁכָּתוּב (ישעיה נא) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם וְאֶל מַקֶּבֶת בּוֹר נֻקַּרְתֶּם. וְעַל כֵּן וַיִּהְיוּ חַיֵּי שָׂרָה, שֶׁזָּכְתָה בָהֶם בְּכֻלָּם. וְלֹא כָתוּב בְּכָל הַנָּשִׁים וַיִּהְיוּ חַיֵּי חַוָּה, וְכֵן בְּכֻלָּם. הִיא נִדְבְּקָה בַּחַיִּים, וְעַל כֵּן שֶׁלָּהּ הָיוּ הַחַיִּים."],[3,"","אַשְׁרֵי מִי שֶׁמַּקְטִין אֶת עַצְמוֹ בָּעוֹלָם. כַּמָּה הוּא גָדוֹל וְעֶלְיוֹן בָּעוֹלָם הַהוּא. וְכָךְ פָּתַח רֹאשׁ הַיְשִׁיבָה: מִי שֶׁהוּא קָטָן - הוּא גָדוֹל. מִי שֶׁהוּא גָדוֹל - הוּא קָטָן. שֶׁכָּתוּב וַיִּהְיוּ חַיֵּי שָׂרָה וְגוֹ'. מֵאָה שֶׁהוּא חֶשְׁבּוֹן גָּדוֹל, כָּתוּב בּוֹ שָׁנָה. קֹטֶן הַשָּׁנִים אֶחָד הִקְטִין אוֹתוֹ. שֶׁבַע שֶׁהוּא חֶשְׁבּוֹן קָטָן, הִגְדִּיל אוֹתוֹ וְרִבָּה אוֹתוֹ, שֶׁכָּתוּב שָׁנִים. בֹּא רְאֵה שֶׁאֵינוֹ מְגַדֵל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְמִי שֶׁמַּקְטִין, וְלֹא מַקְטִין אֶלָּא לַמִּתְגַּדֵּל. אַשְׁרֵי הוּא מִי שֶׁמַּקְטִין אֶת עַצְמוֹ בָּעוֹלָם הַזֶּה, כָּה הוּא גָדוֹל בְּעִלּוּי לְאוֹתוֹ הָעוֹלָם. עַד כָּאן."],[4,"","מִי שֶׁפָּסַק יִפָּסֵק. מִי שֶׁקִּצֵּר יִתְקַצֵּר. מִי שֶׁקִּצֵּר יִתְאָרֵךְ. רְצוֹנוֹ לוֹמַר, מִי שֶׁפּוֹסֵק בְּדִבְרֵי תוֹרָה עַל דְּבָרִים בְּטֵלִים - יִפָּסְקוּ חַיָּיו מִן הָעוֹלָם הַזֶּה, וְדִינוֹ קַיָּם בָּעוֹלָם הַהוּא. מִי שֶׁמְּקַצֵּר בְּאָמֵן וְלֹא מַאֲרִיךְ תּוֹךְ מְנוּחָה - יִתְקַצֵּר מֵהַחַיִּים שֶׁל הָעוֹלָם הַזֶּה. מִי שֶׁאוֹמֵר אֶחָד, צָרִיךְ לַחְטֹף הָאָלֶ\"ף וּלְקַצֵּר אֶת הַקְּרִיאָה שֶׁלָּהּ, וְלֹא יִתְעַכֵּב בָּאוֹת הַזּוֹ כְּלָל, וּמִי שֶׁיַּעֲשֶׂה אֶת זֶה יִתְאָרְכוּ יָמָיו. (אלו החדושים שהגידו לרבי שמעון בר יוחאי בישיבה של מעלה,) ע\"כ התוספתא"],[5,"","וַיִּהְיוּ חַיֵּי שָׂרָה. אוֹתָם הַחַיִּים כֻּלָּם לְמַעְלָה. מֵאָה שָׁנָה לְמַעְלָה, וְעֶשְׂרִים שָׁנָה לְמַעְלָה, וְשֶׁבַע שָׁנִים לְמַעְלָה, כֻּלָּם הָיוּ כָּרָאוּי. אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה אֶת סוֹד הַדָּבָר, מַה שּׁוֹנֶה בְּכֻלָּם שֶׁאָמַר שָׁנָה שָׁנָה, וּבְאוֹתָם שֶׁבַע אָמַר שָׁנִים, שֶׁכָּתוּב מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה, וְאַחַר כָּךְ שֶׁבַע שָׁנִים?"]]],[["אֶלָּא כֹּלָּא חֲד. מֵאָה שָׁנָה כְּלָלָא דְכֹלָּא (נ\"א כלא כחדא ברזא דמאה ברכאן בכל יומא. וכן עשרים שנה דאתכליל עלאה סתימא דכל סתימין, ובגין כך כתיב שנה רזא דיחודא). קוּדְשָׁא בְּרִיךְ הוּא דְּאִתְכְּלִיל מֵאֲתַר עִלָּאָה סְתִימָא דְכָל סְתִימִין בְּמֵאָה בְּרָזָא דְמֵאָה בִּרְכָאָן דְּכָל יוֹמָא, וְכֵן עֶשְׂרִים שָׁנָה, וּבְגִין כָּךְ כְּתִיב שָׁנָה רָזָא דְּיִחוּדָא דְּלָא אִתְפְּרַשׁ (צא ב) מַחֲשָׁבָה וְיוֹבְלָא לְעָלְמִין.","שֶׁבַע שָׁנִים אִלֵּין אִתְפָּרְשָׁן וְנָפְקָאן מִכְּלָלָא סְתִימָאָה דִלְעֵילָא. וְאַף עַל גַּב דְּכֹלָּא יִחוּדָא חָדָא, אֲבָל מִתְפָּרְשָׁן בְּדִינָא וְרַחֲמֵי בְּכַמָּה סִטְרִין וְאוֹרְחִין מַה דְּלָא הֲוִי הָכִי לְעֵילָא. וּבְגִין כָּךְ כְּתִיב שָׁנָה רָזָא דְּיִחוּדָא דְּלָא אִתְפְּרַשׁ לְעָלְמִין. שֶׁבַע שָׁנִים אִלֵּין אִתְפָּרְשָׁאן בְּדִינָא וְרַחֲמֵי בְּכַמָּה סִטְרִין וְאוֹרְחִין מַה דְּלָא הֲוֵי הָכִי לְעֵילָא. וּבְגִין כָּךְ בְּאִלֵּין שֶׁבַע שָׁנִים כְּתִיב בְּהוּ שָׁנִים וְלָא שָׁנָה, וְכֻלְּהוּ אִקְרוּן חַיִּים. וַיִּהְיוּ חַיֵּי שָׂרָה, דְּהֲווּ מַמָּשׁ דְּאִתְבְּרִיאוּ וְאִתְקַיְּימוּ לְעֵילָא.","אָמַר רַבִּי חִיָּיא הָא אוּקְמוּהָ דְהָא כַּד אִתְעַקַּד יִצְחָק בַּר תְּלָתִין וְשֶׁבַע שָׁנִים הֲוָה, וְכֵיוָן דְּאִתְעַקַּד יִצְחָק מִיתַת שָׂרָה, דִּכְתִיב וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. מֵאַיִן בָּא, מֵהַר הַמּוֹרִיָּה בָּא מִלְּמֶעֱקַד לֵיהּ לְיִצְחָק, וְאִינוּן תְּלָתִין וְשֶׁבַע שְׁנִין מִיּוֹמָא דְּאִתְיְילִיד יִצְחָק עַד שַׁעְתָּא דְּאִתְעַקַּד אִינוּן הֲווּ חַיֵּי שָׂרָה וַדַּאי כְּחוּשְׁבַּן וַיִּהְי\"וּ בְּגִימַטְרִיָּ\"א תְּלָתִין וּשְׁבַע שְׁנִין הֲווּ כְּמָה דְּאִתְּמָר מִדְּאִתְיְלִיד יִצְחָק עַד דְּאִתְעַקַּד.","רַבִּי יוֹסֵי פָּתַח וְאֲמַר, (תהילים צ״ח:א׳) מִזְמוֹר שִׁירוּ לַיְיָ שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה הוֹשִׁיעָה לוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הַאי קְרָא אוּקְמוּהָ חַבְרַיָא, דְּפָרוֹת אֲמְרוּהָ. כְּמָה דִכְתִיב, (שמואל א ו׳:י״ב) וַיִּשַּׁרְנָה הַפָּרוֹת בַּדֶּרֶךְ. מַאי וַיִּשַּׁרְנָה, דְּהֲווּ אָמְרֵי שִׁירָתָא חַדְתָּא. וּמַאי שִׁירָה אָמְרוּ. מִזְמוֹר שִׁירוּ לַיְיָ שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה.","הָכָא אִית לְאִסְתַּכָּלָא, דְּכָל מַה דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא כֻּלְּהוּ אָמְרִי תּוּשְׁבְּחָן וְשִׁירָתָא קַמֵּיהּ בֵּין לְעֵילָא בֵּין לְתַתָּא, וְאִי תֵימָא דְּאִינְהוּ מִגַּרְמַיְיהוּ (ד\"א ל\"ג הוו) אָמְרֵי שִׁירָתָא דָא, הָכִי הוּא וַדַּאי דְּרָזָא עִלָּאָה אִיהוּ, אֲבָל הַנֵּי, אֲרוֹנָא הֲוָה עַל גַּבַּיְיהוּ, וְכֵיוָן דַּאֲרוֹנָא אִשְׁתְּקִיל עֲלַיְיהוּ וְשַׁוְיוּהָ לְעֵילָא אִינוּן שְׁרִירוּ (נ\"א לא שכיבו מ) שִׁירָתָא, דְּהָא כֵּיוָן דְּאִתְנְטִיל מִנַּיְיהוּ אֲרוֹנָא הֲווּ גָעָאן כְּאוֹרַח שְׁאָר פָּרוֹת דְּעַלְמָא וְלָא אָמְרוּ שִׁירָתָא. וַדַּאי אֲרוֹנָא דְּעַל גַּבַּיְיהוּ עָבִיד לוֹן לְזַמְּרָא."],[[0,"אלא מאה שנה כללא דכלא תמן וכו':","אלא מאה שנה, שם כלל הכל, דהיינו כתר, הכולל כל עשר הספירות שכל אחת כלולה מעשר והן מאה. כי נכלל שם מקום העליון הסתום מכל סתום, שהוא אריך אנפין, בסוד המאה ברכות שבכל יום. כלומר, שהוא משפיע מאה ברכות אל המלכות בכל יום ממאה ספירות שבו. ואריך אנפין ה\"ס הכתר דאצילות. וכן עשרים שנה, שהם חו\"ב, נכלל בהם א\"א, שהוא סתום מכל סתום. ומשום כך, כתוב בהם שנה, לשון יחיד שהוא סוד היחוד, כי מחשבה ויובל, שה\"ס חו\"ב, אינם נפרדים זה מזה לעולם. כי ג\"ר מקושרים זב\"ז כאחת."],[1,"שבע שנין אלין וכו':","אבל ז' שנים שהם ז' ספירות תחתונות דבינה, הן נפרדות זה מזה ויוצאות מכלל הסתום שלמעלה, שהוא א\"א, כי הן עומדות למטה מפרסא דא\"א שבחזה שלו, והפרסא מפסקת ביניהן לא\"א, ואף על פי שהכל הוא יחוד אחד בשוה, אבל הז\"ת נבחנים בדין ורחמים לכמה צדדים ודרכים, מה שאין כן למעלה בג\"ר דבינה, שא\"א מתלבש בהם מבחינת למעלה מחזה ואין שם דין כלל, ומשום זה באלו שבע שנים כתוב בהם \u0003שנים\u0004, ולא שנה כמו בג\"ר, וכולם, כל ע\"ס ג\"ר וז\"ת, נקראים חיים. וע\"כ כתוב, ויהיו חיי שרה, שהיו ממש, שנבראו ועמדו למעלה בע\"ס דבינה."],[2,"אמר ר' חייא וכו':","אר\"ח הנה בארוה, סובב על הקושיא הנ\"ל באות י\"ג למה כתוב מיתת שרה יותר משאר נשים. כי כשנעקד יצחק היה בן ל\"ז שנה, וכיון שנעקד מתה שרה. שכתוב ויבא אברהם וגו', מהיכן בא, הוא בא מהר המוריה, בא מעקדת יצחק, ואלו ל\"ז שנה מיום שנולד יצחק עד הזמן שנעקד, הם היו ודאי חיי שרה, כחשבון \u0003ויהיו\u0004 שהוא בגימטריא ל\"ז שנים. כמו שנתבאר שהם מיום שנולד יצחק עד שנעקד. ובכדי להשמיענו זה, כתוב מיתת שרה בתורה."],[3,"ר' יוסי פתח וכו':","ר\"י פתח ואמר, מזמור שירו לה' שיר וגו'. מקרא זה בארו החברים שהפרות אמרו אותו. כמו שכתוב וישרנה הפרות בדרך, מהו וישרנה, היינו שהיו אומרים שירה חדשה. ואיזה שירה אמרו, מזמור שירו לה' שיר חדש וגו'."],[4,"הכא אית לאסתכלא וכו':","כאן יש להסתכל, שכל מה שברא הקב\"ה בעולם, כולם אומרים תשבחות ושירים לפניו, בין למעלה ובין למטה. ואם תאמר, לפי זה, הפרות מעצמם אמרו שירה זו, כן הוא ודאי, כי סוד עליון יש כאן. אבל אלו הפרות הארון היה עליהם, וכיון שהארון נלקח מהם היו גועות כדרך שאר פרות העולם, ולא אמרו שירה. ודאי הארון שעליהם עשו אותם לזמר."]],[[0,"","אֶלָּא הַכֹּל אֶחָד. מֵאָה שָׁנָה - הַכְּלָל שֶׁל הַכֹּל (נ\"א: הכל כאחד בסוד של מאה ברכות בכל יום, וכן עשרים שנה, שנכלל העליון, הנסתר של כל הנסתרים, ומשום כך כתוב שנה, הסוד של היחוד). הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּכְלָל מִמָּקוֹם עֶלְיוֹן, הַנִּסְתָּר שֶׁל כָּל הַנִּסְתָּרִים בְּמֵאָה, בְּסוֹד שֶׁל מֵאָה בְרָכוֹת שֶׁל כָּל יוֹם, וְכֵן עֶשְׂרִים שָׁנָה. וּמִשּׁוּם כָּךְ כָּתוּב שָׁנָה, סוֹד הַיִּחוּד, שֶׁלֹּא נִפְרָדִים הַמַּחֲשָׁבָה וְהַיּוֹבֵל לְעוֹלָמִים."],[1,"","שֶׁבַע הַשָּׁנִים הַלָּלוּ הִתְפָּרְדוּ וְיָצְאוּ מִכְּלַל הַנִּסְתָּר שֶׁלְּמַעְלָה. וְאַף עַל גַּב שֶׁהַכֹּל יִחוּד אֶחָד, אֲבָל נִפְרָדִים בְּדִין וְרַחֲמִים בְּכַמָּה צְדָדִים וּדְרָכִים מַה שֶּׁלֹּא הָיָה כָּךְ לְמַעְלָה. וּמִשּׁוּם כָּךְ כָּתוּב שָׁנָה, סוֹד הַיִּחוּד שֶׁלֹּא נִפְרָד לְעוֹלָמִים. שֶׁבַע הַשָּׁנִים הַלָּלוּ נִפְרָדִים בְּדִין וְרַחֲמִים בְּכַמָּה צְדָדִים וּדְרָכִים מַה שֶּׁאֵין כֵּן לְמַעְלָה. וּמִשּׁוּם כָּךְ בְּשֶׁבַע הַשָּׁנִים הַלָּלוּ כָּתוּב בָּהֶם שָׁנִים וְלֹא שָׁנָה. וְכֻלָּם נִקְרָאִים חַיִּים. וַיִּהְיוּ חַיֵּי שָׂרָה, שֶׁהָיוּ מַמָּשׁ, שֶׁנִּבְרְאוּ וְהִתְקַיְּמוּ לְמַעְלָה."],[2,"","אָמַר רַבִּי חִיָּיא, הִנֵּה פֵּרְשׁוּהָ, שֶׁהֲרֵי כַּאֲשֶׁר נֶעֱקַד יִצְחָק, הוּא הָיָה בֶּן שְׁלֹשִׁים וְשֶׁבַע שָׁנִים, וְכֵיוָן שֶׁנֶּעֱקַד, מֵתָה שָׂרָה, שֶׁכָּתוּב וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. מֵאַיִן בָּא? מֵהַר הַמֹּרִיָּה בָּא, מִלַּעֲקֹד אֶת יִצְחָק. וְאוֹתָם שְׁלֹשִׁים וְשֶׁבַע שָׁנִים מִיּוֹם שֶׁנּוֹלַד יִצְחָק וְעַד הַשָּׁעָה שֶׁנֶּעֱקַד, הֵם הָיוּ חַיֵּי שָׂרָה. וַדַּאי כְּחֶשְׁבּוֹן וַיִּהְי\"וּ בְּגִימַטְרִיָּא שְׁלֹשִׁים וְשֶׁבַע שָׁנִים הָיוּ, כְּמוֹ שֶׁנִּתְבָּאֵר, מִשֶּׁנּוֹלַד יִצְחָק וְעַד שֶׁנֶּעֱקַד."],[3,"","רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים צח) מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ הַחֲבֵרִים שֶׁהַפָּרוֹת אָמְרוּ אוֹתוֹ, כַּכָּתוּב (שמואל א ו) וַיִּשַּׁרְנָה הַפָּרוֹת בַּדֶּרֶךְ, שֶׁהָיוּ אוֹמְרוֹת שִׁירָה חֲדָשָׁה. וְאֵיזוֹ שִׁירָה הֵן אָמְרוּ? מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה."],[4,"","כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁכָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, כֻּלָּם אוֹמְרִים שִׁירָה וְתִשְׁבָּחוֹת לְפָנָיו, בֵּין לְמַעְלָה בֵּין לְמַטָּה. וְאִם תֹּאמַר שֶׁהֵם מֵעַצְמָם (ד\"א היו) אוֹמְרִים אֶת הַשִּׁירָה הַזּוֹ - כָּךְ זֶה וַדַּאי! שֶׁזֶּהוּ סוֹד עֶלְיוֹן. אֲבָל אֵלּוּ, הָאָרוֹן הָיָה עַל גַּבָּן. וְכֵיוָן שֶׁהָאָרוֹן נִשְׁקַל עֲלֵיהֶם וְשָׂמוּהוּ לְמַעְלָה, הֵן שָׁרוּ (נ\"א: לא שכבו) שִׁירָה, שֶׁהֲרֵי כֵּיוָן שֶׁנִּנְטַל מֵהֶן הָאָרוֹן, הָיוּ גוֹעוֹת כְּדֶרֶךְ שְׁאָר הַפָּרוֹת שֶׁל הָעוֹלָם וְלֹא אָמְרוּ שִׁירָה. וַדַּאי שֶׁהָאָרוֹן שֶׁעַל גַּבָּן עָשָׂה אוֹתָן לְזַמֵּר."]]],[["מִזְמוֹר. הָא אוֹקִימְנָא, וְאִתְּמָר בְּכֹלָּא כְּתִיב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר. וְהָכָא לָא אָמַר דָּוִד כְּלָל. אֶלָּא מִזְמוֹר דְּרוּחַ קוּדְשָׁא זַמִּין לְזַמְּרָא לֵיהּ לְזִמְנָא דְיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל מֵעַפְרָא. וּכְדֵין שִׁירוּ לַיְיָ שִׁיר חָדָשׁ, כְּדֵין אִיהוּ חָדָשׁ, דְּהָא שִׁירָתָא כְּהַאי לָא אִתְּמָר מִיּוֹמָּא דְאִתְבְּרֵי עָלְמָא.","אָמַר רַבִּי חִיָּיא כְּתִיב, (קהלת א׳:ט׳) אֵין כָּל חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. וְהָכָא שִׁירָתָא דָא אִיהִי חָדָשׁ וְאִיהִי תַּחַת הַשֶּׁמֶשׁ, דְּהָא תְּחוֹת שִׁמְשָׁא לֶהוֵי. וּמַאי אִיהוּ דָּא סִיהֲרָא, וּכְדֵין הֲוִי חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. מַאי טַעְמָא בְּגִין כִּי נִפְלָאוֹת עָשָׂה. וּמַאן אִינוּן נִפְלָאוֹת, הַאי דִכְתִיב הוֹשִׁיעָה לוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הוֹשִׁיעָה לוֹ. לְמַאן לְהַהוּא דַרְגָּא דְּאָמַר שִׁירָתָא דָא, בְּגִין דְּבְּהוּ אִסְתַּמִּיךְ בִּימִינָא וּבִשְׂמָאלָא. הוֹשִׁיעָה לוֹ יְמִינוֹ, וַדַּאי לְהַהוּא דַרְגָּא דְּהַאי מִזְמוֹר, אֵימָתַי בְּזִמְנָא דִּיקוּמוּן מֵתֵי עַלְמָא וְיִתְעָרוּן מֵעַפְרָא, כְּדֵין יְהֵא חָדָשׁ מַה דְּלָא אִתְעֲבִיד בְּהַאי עָלְמָא."],[[0,"מזמור הא אוקימנא וכו':","כתוב מזמור כאן, ואמרו, בכל המקומות, כתוב מזמור לדוד או לדוד מזמור, וכאן לא נאמר \u0003דוד\u0004 לגמרי, אלא \u0003מזמור\u0004 בלבד. והוא משום שהרוח הקודש עתיד לזמר אותו, בזמן שיקום הקב\"ה את ישראל מעפר. ועל כן לא נאמר כאן לדוד. ואז שירו לה' שיר חדש, כי זה הוא חדש, כי שיר כזה, לא נאמר עוד מיום שנברא העולם."],[1,"א\"ר חייא וכו':","אר\"ח, כתוב אין כל חדש תחת השמש, וכאן שיר הזה הוא חדש, והוא תחת השמש, כי תחת השמש יהיה. ומי הוא השיר חדש. זהו הלבנה. שהיא הנוקבא כי אז תהיה הלבנה חדשה תחת השמש. דהיינו שתתחדש אורה להיות כאור החמה. שהוא ז\"א מהו הטעם, שיהיה חדש תחת השמש. זה שאומר הכתוב, כי נפלאות עשה. ומה המה הנפלאות. היינו שכתוב הושיעה לו ימינו וזרוע קדשו, שה\"ס ימינו ושמאלו. חו\"ג. \u0003הושיעה לו,\u0004 למי. הוא לאותה המדרגה שאמרה שיר הזה, שהיא רוח הקודש שהוא הנוקבא, משום שנסמכה בהם הנוקבא, בימין ובשמאל, כמ\"ש הושיעה לו ימינו, וזרוע קדשו, הוא שמאלו. וע\"כ הושיעה לו ימינו, ודאי פירושו, לאותה המדרגה שהיא נקראת \u0003מזמור\u0004, דהיינו רוח הקודש, שהיא הנוקבא. שתהיה אורה כאור החמה. מתי יהיה זה, בזמן שיקומו מתי עולם ויתעוררו מעפר. אז יהיה חדש, מה שעוד לא נעשה בעולם הזה."]],[[0,"","מִזְמוֹר, הֲרֵי בֵּאַרְנוּ, וְנִתְבָּאֵר, וּבַכֹּל כָּתוּב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר, וְכָאן לֹא אָמַר דָּוִד כְּלָל. אֶלָּא מִזְמוֹר, שֶׁעֲתִידָה רוּחַ הַקֹּדֶשׁ לְזַמֵּר אוֹתוֹ בִּזְמַן שֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל מִן הֶעָפָר, וְאָז שִׁירוּ לַה' שִׁיר חָדָשׁ. אָז הוּא חָדָשׁ. שֶׁהֲרֵי שִׁירָה כָּזוֹ לֹא נֶאֶמְרָה מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם."],[1,"","אָמַר רַבִּי חִיָּיא, כָּתוּב (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ, וְכָאן שִׁירָה זוֹ הִיא חָדָשׁ, וְהִיא תַּחַת הַשֶּׁמֶשׁ, שֶׁהֲרֵי תַּחַת הַשֶּׁמֶשׁ הִיא, וּמִי הִיא? זוֹ הַלְּבָנָה. וְאָז יֵשׁ חָדָשׁ תַּחַת הַשָּׁמֶשׁ. מָה הַטַּעַם? מִשּׁוּם כִּי נִפְלָאוֹת עָשָׂה. וּמִי הֵם הַנִּפְלָאוֹת? זֶה שֶׁכָּתוּב הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הוֹשִׁיעָה לּוֹ, אֶת מִי? אֶת אוֹתָהּ הַדַּרְגָּה שֶׁאָמְרָה אֶת הַשִּׁירָה הַזּוֹ, מִשּׁוּם שֶׁבָּהֶם נִסְמְכָה בְּיָמִין וּבִשְׂמֹאל. הוֹשִׁיעָה לּוֹ יְמִינוֹ, וַדַּאי לְאוֹתָהּ הַדַּרְגָּה שֶׁל הַמִּזְמוֹר הַזֶּה. מָתַי? בִּזְמַן שֶׁיָּקוּמוּ מֵתֵי עוֹלָם וְיִתְעוֹרְרוּ מִן הֶעָפָר, וְאָז יִהְיֶה חָדָשׁ מַה שֶּׁלֹּא נַעֲשָׂה בָּעוֹלָם הַזֶּה."]]],[["רַבִּי יוֹסֵי אָמַר בְּזִמְנָא דְּיַעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא נוּקְמִין בְּעָלְמָא בְּגִינַיְיהוּ דְיִשְׂרָאֵל, כְּדֵין יִתְאֲמַר שִׁירָתָא, דְּהָא לְבָתַר יִתְעָרוּן מֵעַפְרָא מֵתֵי עַלְמָא וְיִתְחַדֵּשׁ עַלְמָא בְּקִיּוּם שְׁלִים דְּלָא לֶיהוֵי (כקדמיתא דשליט מותא בעלמא בגין דחויא) (נ\"א כרת ומיתה בעלמא ויתעבר חויא מעלמא דגרים) גָּרִים מוֹתָא בְּעַלְמָא לְכֹלָּא וְאִסְתָּאַב עַלְמָא וְאִתְחֲשִׁיךְ אַנְפּוֹי.","תָּא חֲזֵי, כְּתִיב, (בראשית ג׳:ט״ו) וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה. מַאי וְאֵיבָה כְּדִכְתִיב (איוב ט׳:כ״ו) חָלְפוּ עִם אֳנִיּוֹת אֵבֶה. דְּהָא כַּמָּה אַרְבִין שָׁטָאן גּוֹ יַמָּא רַבָּא, וְאִית אַרְבִין וּסְפִינָן מִתְפָּרְשָׁן דָּא מִן דָּא. וְאִינוּן אַרְבִין דְּהַאי נָחָשׁ שָׁאט בְּגַוַּויְיהוּ אִקְרוּן אֳנִיּוֹת אֵבָה.","בֵּינְךָ וּבֵין הָאִשָּׁה. דָּא אִשָּׁה יִרְאַת יְיָ. וּבֵין זַרְעֶךָ, אִלֵּין שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבֵין זַרְעָהּ, אִלֵּין יִשְׂרָאֵל. הוּא יְשׁוּפְךָ רֹאשׁ, דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּזַמִּין לְבַעֲרָא לֵיהּ מֵעַלְמָא דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוְת לָנֶצַח. וּכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.","רֹאשׁ, דָּא לְזִמְנָא דְאָתֵי דְיִתְעָרוּן מֵתַיָא. דְּהָא כְּדֵין לֶהֱוֵי עַלְמָא רֹא\"שׁ, דְּיִתְקַיַּים בָּרֹא\"שׁ דְּאִיהוּ עַלְמָא עִלָּאָה. וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. דָּא בְּהַאי עַלְמָא הַשְׁתָּא דְאִיהוּ עָקֵב וְלָאו אִיהוּ בְּקִיּוּמָא וְהַהוּא חִוְיָא נָשִׁיךְ לְעַלְמָא וְאַחְשִׁיךְ אַנְפּוֹי בִּרְיָין.","תָּא חֲזֵי, יוֹמִין דְּבַר נָשׁ אִתְבְּרִיאוּ וְקָיְימוּ בְּאִינוּן דַּרְגִּין עִלָּאִין, כֵּיוָן דִּמְסַיְימוּ לְאִתְקַיְימָא בְּאִינוּן דַּרְגִּין דִּכְתִיב, (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה וְגו', מִכָּאן וּלְהָלְאָה לֵית דַּרְגָא לְאִתְקַיְּימָא. וּבְגִין כָּךְ וְרָהְבָּ\"ם עָמָל וָאָוֶן. וְאִינוּן כְּלָא הֲווּ."],[[0,"ר' יוסי אמר וכו':","רי\"א בזמן שיעשה הקב\"ה נקמות בעולם בשביל ישראל אז יאמר שיר חדש הנ\"ל, דהיינו בביאת המשיח. שאינו בזמן אחד עם תחית המתים. כי לאחר ביאת המשיח יתעוררו מתי העולם מעפר והעולם יתחדש בקיום שלם, שלא יהיה כבתחילה שהמות שלט בעולם, משום שהנחש גרם מות בעולם לכל, ונטמא העולם ונחשכו פניהם של הבריות."],[1,"ת\"ח כתיב ואיבה אשית בינך וגו':","שואל, מהו ואיבה. ואומר שהוא, כמ\"ש חלפו עם אניות אבה, כי כמה אניות שטות תוך ים הגדול, ויש ביניהם אניות וספינות נבדלות זו מזו, ואלו אניות של הנחש השטות ביניהם נקראות אניות איבה. פירוש. ים הגדול הוא הנוקבא, אניות השטות בים הן מדרגות הארתה לתחתונים. אניות הנחש הן אחיזות הנחש לינק ממנה, ואחיזות אלו מכונות אבה. ושיעור הכתוב, ואיבה אשית בינך ובין האשה, היינו שיתן לו אחיזה לינק מהנוקבא. שאחיזה זו נקראת איבה."],[2,"בינך ובין האשה:","היינו אשה יראת ה', שהיא המלכות. \u0003בין זרעך,\u0004 אלו הם שאר כל העמים עובדי ע\"ז. שהם זרעו של הנחש. \u0003ובין זרעה,\u0004 היינו ישראל, שהם זרעה של המלכות, \u0003הוא ישופך ראש\u0004 זה הקב\"ה, שעתיד לבער את הנחש מן העולם. שכתוב בלע המות לנצח, וכתוב ואת רוח הטומאה אעביר מן הארץ."],[3,"ראש:","זהו לעתיד לבא, שיחיו המתים, כי אז יהיה העולם, \u0003ראש,\u0004 משום שיתקיים \u0003בראש\u0004 דהיינו שיאירו בו ג\"ר, שהם עולם העליון. \u0003ואתה תשופנו עקב,\u0004 זהו בעולם הזה עתה, לפני גמר התקון, שהעולם הוא \u0003עקב,\u0004 ואינו בקיום שלם, ונחש ההוא נושך את העולם ומחשיך פני הבריות."],[4,"ת\"ח, יומין דבר נש וכו':","בוא וראה, ימיו של אדם נבראו ועמדו במדרגות העליונות, דהיינו בז' ספירות חג\"ת נהי\"מ, כיון שגמרו להתקיים באלו המדרגות, כמ\"ש ימי שנותינו בהם שבעים שנה, דהיינו כנגד ז\"ס שכל אחת מהן כוללת עשר, אין עוד מדרגה להתקיים בה, ומשום זה \u0003ורהבם עמל ואון,\u0004 והם כלא היו, \u0003ורהבם\u0004 פירושו יותר מזה, דהיינו אם חי יותר מע' שנים הם רק עמל ואון, כי אין עוד ספירה להמשיך החיים ממנה, וע\"כ שנים הללו, הם כלא היו כלל, שאין בהם חפץ."]],[[0,"","רַבִּי יוֹסֵי אָמַר, בִּזְמַן שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמוֹת בָּעוֹלָם בִּשְׁבִיל יִשְׂרָאֵל, אָז תֵּאָמֵר הַשִּׁירָה (הזו), שֶׁהֲרֵי אַחַר כָּךְ יִתְעוֹרְרוּ מִן הֶעָפָר הַמֵּתִים שֶׁל הָעוֹלָם וְיִתְחַדֵּשׁ הָעוֹלָם בְּקִיּוּם שָׁלֵם, שֶׁלֹּא יִהְיֶה (כבתחלה שהמות שולט בעולם, משום שהנחש) (נ\"א: כרת ומיתה בעולם, ויעבר הנחש מהעולם שהוא גרם) גָּרַם מָוֶת בָּעוֹלָם לַכֹּל, וְנִטְמָא הָעוֹלָם וְנֶחְשְׁכוּ פָנָיו."],[1,"","בֹּא רְאֵה, כָּתוּב (בראשית ג) וְאֵיבָה אָשִׁית בֵּינְךְ וּבֵין הָאִשָּׁה. מַה זֶּה וְאֵיבָה? כַּכָּתוּב (איוב ט) חָלְפוּ עִם אֳנִיּוֹת אֵבֶה. שֶׁהִנֵּה כַּמָּה אֳנִיּוֹת וּסְפִינוֹת מְשׁוֹטְטוֹת בְּתוֹךְ הַיָּם הַגָּדוֹל, וְיֵשׁ אֳנִיּוֹת וּסְפִינוֹת נִפְרָדוֹת זוֹ מִזּוֹ. וְאוֹתָן הָאֳנִיּוֹת שֶׁהַנָּחָשׁ הַזֶּה שָׁט בְּתוֹכָן, נִקְרָאוֹת אֳנִיּוֹת אֵבָה."],[2,"","בֵּינְךָ וּבֵין הָאִשָּׁה - זוֹ אִשָּׁה יִרְאַת ה'. וּבֵין זַרְעֲךְ - אֵלּוּ שְׁאָר עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבֵין זַרְעָהּ - אֵלּוּ יִשְׂרָאֵל. הוּא יְשׁוּפְךְ רֹאשׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעָתִיד לְבַעֵר אוֹתוֹ מִן הָעוֹלָם, שֶׁכָּתוּב (ישעיה כד) בִּלַּע הַמָּוֶת לָנֶצַח, וְכָתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ."],[3,"","רֹאשׁ - זֶה לֶעָתִיד לָבֹא כְּשֶׁיִּתְעוֹרְרוּ הַמֵּתִים, שֶׁהֲרֵי אָז הָעוֹלָם יִהְיֶה רֹא\"שׁ, שֶׁיִּתְקַיֵּם בָּרֹא\"שׁ, שֶׁהוּא הָעוֹלָם הָעֶלְיוֹן. וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב - זֶה בָּעוֹלָם הַזֶּה, כָּעֵת שֶׁהוּא עָקֵב וְאֵינוֹ בְּקִיּוּם, וְאוֹתוֹ הַנָּחָשׁ נוֹשֵׁךְ אֶת הָעוֹלָם וּמַחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת."],[4,"","בֹּא רְאֵה, הַיָּמִים שֶׁל אָדָם נִבְרְאוּ וְעָמְדוּ בְּאוֹתָם הַדְּרָגוֹת הָעֶלְיוֹנוֹת, כֵּיוָן שֶׁהִסְתַּיְּמוּ לְהִתְקַיֵּם בְּאוֹתָן הַדְּרָגוֹת, שֶׁכָּתוּב (תהלים צ) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה וְגוֹ'. מִכָּאן וָהָלְאָה אֵין דַּרְגָּה לְהִתְקַיֵּם, וּמִשּׁוּם כָּךְ וְרָהְבָּ\"ם עָמָל וָאָוֶן, וְהֵם כְּלֹא הָיוּ."]]],[["אֲבָל אִינוּן יוֹמִין דְּצַדִּיקַיָא הֲווּ וְאִתְקָיְימוּ כְּמָא דְאַתְּ אָמֵר וַיִּהְיוּ חַיֵּי שָׂרָה. וְכֵן וְאֵלֶּה יְמֵי שְׁנֵי חַיֵּי אַבְרָהָם. וְאִי תֵימָא הָכִי נָמֵי כְּתִיב בְּיִשְׁמָעֵאל דִּכְתִיב, (בראשית כ״ה:ז׳) שְׁנֵי חַיֵּי יִשְׁמָעֵאל. אֶלָּא בִּתְשׁוּבָה אַהֲדַר, וְעַל דָּא קָרֵי (ביומוי) וַיִּהְיוּ:","\u0003מִדְרָשׁ הַנֶּעֱלָם\u0004 וַיִּהְיוּ. רַבָּנָן פָּתְחֵי בְּהַאי קְרָא, (שיר השירים ז׳:י״ב) לְכָה דוֹדִי נֵצֵּא הַשָּׂדֶה נָלִינָה בַּכְּפָרִים. תָּנוּ רַבָּנָן הַיּוֹצֵּא לַדֶּרֶךְ יִתְפַּלֵּל שָׁלשׁ תְּפִלּוֹת, תְּפִלָּה שֶׁהִיא חוֹבָה שֶׁל יוֹם. וּתְפִלַּת הַדֶּרֶךְ עַל הַדֶּרֶךְ שֶׁהוּא עוֹשֶׂה. וּתְפִלָּה שֶׁיַּחְזוֹר לְבֵיתוֹ לְשָׁלוֹם. וְלֵימָא לְהוּ לְהַנֵּי שְׁלשָׁה, אֲפִילּוּ בְּאֶחָד יָכִיל לְמֶעְבְּדֵיהּ, דְּתָנִינָן כָּל שְׁאֵלוֹתָיו שֶׁל אָדָם יָכִיל לְמִכְלְלִינְהוּ בְּשׁוֹמֵעַ תְּפִלָּה.","אָמַר רַבִּי יְהוּדָה כָּל עוֹבָדוֹי דְּבַר נָשׁ כְּתִיבִין בְּסִפְרָא, הֵן טַב הֵן בִּישׁ, וְעַל כֻּלְּהוֹן עָתִיד לְמִיתַּן דִּינָא, דְּתָנִינָן אָמַר רַב יְהוּדָה אָמַר רַב, מַאי דִכְתִיב, (תהילים קל״ט:ט״ז) גָּלְמִי רָאוּ עֵינֶיךָ, אוֹתָם הַדְּבָרִים שֶׁעָשָׂה הַגּוֹלֶם שֶׁאֵינוֹ מַשְׁגִּיחַ בָּעוֹלָם הַבָּא, כּוּלָּם רָאוּ עֵינֶיךָ שֶׁעִיַּינְתָּ בָּהֶם. וְעַל סִפְרְךָ כּוּלָּם יִכָּתֵבוּ, לִיתֵּן עֲלֵיהֶם דִּין וחֶשְׁבּוֹן לָעוֹלָם הַבָּא, הִלְכָּךְ יַקְדִּים אָדָם תְּפִלָּתוֹ תָּמִיד וְיוֹעִיל לֵיהּ.","אָמַר רַבִּי יִצְּחָק אֵין אָדָם עוֹשֶׂה עֲבֵירוֹת אֶלָּא מִי שֶׁהוּא גּוֹלֶם ולֹא אָדָם, וְהַיְינוּ הַהוּא דְּלָא מִסְתַּכַּל בְּנִשְׁמָתָא קַדִּישָׁא, אֶלָּא כָּל עוֹבָדוֹי כְּהַאי בְּעִירָא דְּלָא מַשְׁגַּחַת וְלָא יָדְעַת. אָמַר רַבִּי בּוֹ, וְכִי גוֹלֶם מִתְקְרֵי דָוד דְּאָמַר הַאי פְּסוּקָא. אָמַר לוֹ רַבִּי יִצְּחָק אָדָם הָרִאשׁוֹן אֲמָרוֹ, גָּלְמִי רָאוּ עֵינֶיךָ, קוֹדֶם שֶׁזָּרַקְתָּ בִּי נְשָׁמָה, רָאוּ עֵינֶיךָ לְמֶעְבַּד בִּדְיוֹקְנִי בְּנֵי נָשָׁא דְדָמוּ לִי. וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ, מַאן אִינוּן. יָמִים יוּצָּרוּ, כְּהַאי צּוּרָה דִידִי. וְלֹא אֶחָד בָּהֶם דְּלָא אִשְׁתָּאַר חַד מִנְּהוֹן.","אָמַר רַבִּי בּוֹ, לָמָּה. אָמַר לֵיהּ תָּא חֲזֵי, כֻּלְּהוּ דְדָמוּ לֵיהּ אוֹ בִּרְמִיזָא דִילֵיהּ, לָא מֵתוּ בְּמִיתַת נַפְשְׁהוֹן, וְכֻלְּהוּ לָקוּ בְּהַהוּא עִנְיָינָא מַמָּשׁ. תָּא חֲזֵי, אָמַר רַבִּי יְהוּדָה דִּיוּקְנֵיהּ דְּאָדָם הָרִאשׁוֹן וְשַׁפִּירוּתֵיהּ הֲוָה כְּזָהֲרָא דִּרְקִיעָא עִלָּאָה דְּעַל גַּבֵּי שְׁאָר רְקִיעֵי, וּכְהַהוּא נְהוֹרָא דְּגָנִיז קוּדְשָׁא בְּרִיךְ הוּא לְצַּדִּיקַיָּיא לְעַלְמָא דְאָתֵי, וְכָל אִינוּן דְּהֲווּ רְמִיזָא בֵּיהּ מִדִיוּקְנֵיהּ דְּאָדָם הָרִאשׁוֹן בֵּיהּ לָקוּ וּמִיתוּ.","דְּכָךְ אוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, יָהִיב עוּתְרָא לְבַר אִינִישׁ, לָמָּה, לְמֵיזַן עֲנָיִין וּלְמֶעְבַּד פִּקּוּדוֹי. לָא עָבִיד הַאי ואִתְגָאֵי (ואי אתגליא ביה) בְּהַהוּא עוּתְרָא, בֵּיהּ יִלְקֵי דִּכְתִיב, (קהלת ה׳:י״ב) עשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. יָהִיב לֵיהּ בְּנִין, לָמָּה, לְמֵילַף לְהוּ אוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וּלְמִיטַר פִּקּוּדוֹי כִּדְאָמוּר בְּאַבְרָהָם (בראשית י״ח:י״ט) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַּוְּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶרֶךְ יְיָ לַעֲשׂוֹת צְּדָקָה וְגו'. לָא עָבִיד הַאי וּמִתְגָּאֶה בְּהוּ, בְּהוּ לָקֵי דִּכְתִיב, (איוב י״ח:י״ט) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ וְגו'. וְכֵן כְּהַאי גַוונָא כַּד יָהִיב קוּדְשָׁא בְּרִיךְ הוּא מִשַׁפִּירוּתָא טָבָא עִלָּאָה דְאָדָם הָרִאשׁוֹן לְהוּ, לָמָּה, בְּגִין לְמִיטַר פִּקּוּדוֹי וּלְמֶעְבַּד רְעוּתֵיהּ, לָא עָבְדוּ כְּדֵין אֶלָּא אִתְגָּאוּ בֵּיהּ. בֵּיהּ לָקוּ בְּהַאי שַׁפִּירוּתָא.","אָמַר רַב יְהוּדָה, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא אָדָם הָרִאשׁוֹן, הֲוָה גוֹלֶם עַד לָא זָרִיק בֵּיהּ נִשְׁמָתָא, וְקָרָא לְהַהוּא מַלְאָכָא דְּהוּא מְמוּנֶּה עַל דִּיוּקְנָא דִּבְנֵי נָשָׁא, וְאָמַר לוֹ עַיֵּין וְצֹּר בְּדִיוּקְנָא דְדֵין שִׁיתָּא בְּנִי נְשָׁא, הֲדָא הוּא דִכְתִיב, (בראשית ה׳:ג׳) וַיּוֹלֶּד בִּדְמוּתוֹ כְּצַּלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, כְּלוֹמַר שִׁיתָּא.","אָמַר רַבִּי יִצְּחָק מֵהַהוּא עַפְרָא מַמָּשׁ דְּאִתְבְּרֵי אָדָם הָרִאשׁוֹן נָסִיב קוּדְשָׁא בְּרִיךְ הוּא לְאִתְבְּרָאָה אִלֵּין שִׁיתָּא, וְקָרָא לֵיהּ שֵׁת, שִׁיתָּא, הֲדָא הוּא דִכְתִיב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַּלְּמוֹ מֵאוֹתָהּ הָעִיסָה שֶׁנִּבְרָא הַגּוֹלֶם שֶׁלּוֹ, וְעַל כָּךְ נֶאֱמַר גָּלְמִי רָאוּ עֵינְיךָ וְעִיַינְת בּוֹ לַעֲשׂוֹת (ד\"א ל\"ג בו) דְּדָאמוּ לֵיהּ. וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ, מַאן אִינוּן, כֻּלְּהוּ דְּלָא נָטְרוּ מַאי דְּיָהַב קוּדְשָׁא בְּרִיךְ הוּא לוֹן וְאִתְטָרְדוּ מִן עַלְמָא (ואתדנו בההוא דינא).","תְּנַן הָתָם אָמַר רַב יְהוּדָה אָמַר רַב אַשְׁכַּחְנָא דִּתְלַת מִטְרָן הֲוִי לֵילְיָא, וְכָל חַד וְחַד אִית עִנְיָינָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּבַר נָשׁ. כַּד נָפִיק נִשְׁמָתֵיהּ מִינֵּיהּ ואִשְׁתָּאַר הַהוּא גּוֹלְמָא נָאִים עַל עַרְסֵיהּ, וְנִשְׁמָתֵיהּ סָלְקָא בְּכָל לֵילְיָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אָמַר רַבִּי יִצְּחָק אִי זַכָּאָה הִיא חָדָאן עִמַּהּ, וְאִי לָא דַּחְיָין לָהּ לְבַר. אָמַר רַב יְהוּדָה אָמַר רַב מַאי דִכְתִיב, (שיר השירים ה׳:ח׳) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַםִ אִם תִּמְצְּאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי.","אָמַר רַבִּי פִּנְחָס אָמַר רַבִּי יְהוּדָה הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַם, הַנְּשָׁמָה אוֹמֶרֶת לְאוֹתָם הַנְּשָׁמוֹת הַזּוֹכוֹת לִיכָּנֵס לִירוּשָׁלַם שֶׁל מַעְלָה, והֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַםִ עַל שֶׁזּוֹכוֹת לִיכָּנֵס שָׁם, וּלְפִיכָךְ הַנְּשָׁמָה אוֹמֶרֶת לָהֶם הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַםִ אִם תִּמְצְּאוּ אֶת דּוֹדִי דָּא קוּדְשָׁא בְּרִיךְ הוּא. רַב אָמַר זֶה זִיו אַסְפַּקְלַרְיָאה שֶׁל מַעְלָה. מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי, לֵיהָנוֹת מִזִּיו שֶׁלּוֹ וּלְהִסְתּוֹפֵף בְּצִּלּוֹ. רַב הוּנָא אָמַר שֶׁחוֹלַת אַהֲבָה אָנִי, אוֹתָהּ הַתְּשׁוּקָה וְהַכִּסּוּף שֶׁכָּסַפְתִּי בָּעוֹלָם עַל הַכֹּל לְפִיכָךְ אֲנִי חוֹלָה. רַבִּי יְהוּדָה אָמַר זוֹ אַהֲבָה שֶׁאוֹהֶבֶת הַנְּשָׁמָה לַגּוּף, דְּכֵיון שֶׁנִּשְׁלַם קִצּוֹ שֶׁל גּוּף אוֹתָם הַיָּמִים שֶׁנִּגְזְרוּ עָלָיו כְּמָה דְאַתְּ אָמֵר וַיִּהְיוּ חַיֵּי שָׂרָה, מַה כְּתִיב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וְגו'.","אָמַר רַב יְהוּדָה אָמַר רַב מַה כְּתִיב בַּפָּסוּק קוֹדֶם זְה דִּכְתִיב וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאֶרֶץ כְּנַעַן.","רַבִּי יִצְּחָק אָמַר רַבִּי יוֹחָנָן בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לָאָדָם וְהִכְנִיס בּוֹ אַרְבָּעָה דְבָרִים הַנֶּחֱלָקִים בַּגּוּף. אָמַר רַבִּי יְהוּדָה הַמְחוּבָּרִים בַּגּוּף. רַבִּי יִצְּחָק אָמַר הַנֶּחלָקִים בַּגּוּף שֶׁהֵם חוֹלְקִים לְהִתְפָּרֵשׁ כָּל אֶחָד לִיסוֹדוֹ כְּשֶׁיּוֹצֵּא הָאָדָם מִן הָעוֹלָם הַזְּה. רַבִּי יְהוּדָה אָמַר הַמְחוּבָּרִים בַּגּוּף בְּחַיָּיו, מַשְׁמַע מִקְרָא דִכְתִיב וַתָּמָת שָׂרָה, זֶה הַגּוּף. בְּקִרְיַת אַרְבַּע, אֵלּוּ הָאַרְבַּע יְסוֹדוֹת. הִיא חֶבְרוֹן, שֶׁהָיוּ מְחוּבָּרִים בְּגוּפוֹ בְּחַיָּיו. בְּאֶרֶץ כְּנַעַן, בָּעוֹלָם הַזְּה הַבּוֹחֵר אָדָם בִּזְמַן מוּעָט:","וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה ולִבְכֹּתָהּ. הַיְינוּ (דכתיב) דִתְנַן כָּל שִׁבְעַת הַיָּמִים נַפְשׁוֹ שֶׁל אָדָם פּוֹקֶדֶת לְגוּפוֹ וּמִתְאַבֶּלֶת עָלָיו, הֲדָא הוּא דִכְתִיב, (איוב י״ד:כ״ב) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. כְּהַאי גַוְונָא וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. וַיָּבֹא אַבְרָהָם, זוֹ הִיא הַנְּשָׁמָה. לִסְפֹּד לְשָׂרָה, זְה הַגּוּף.","אָמַר רַבִּי יִצְּחָק בְּשָׁעָה שֶׁהַנְּשָׁמָה זוֹכָה וְעוֹלָה לִמְקוֹם מַעֲלָתָהּ, הַגּוּף שׁוֹכֵב בְּשָׁלוֹם וְיָנוּחַ עַל מִשְׁכָּבוֹ הֲדָא הוּא דִכְתִיב, (איוב נז) יָבֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם, הֹלֵךְ נְכֹחֹה. מַאי הוֹלֵךְ נְכֹחֹה. אָמַר רַבִּי יִצְּחָק הַנְּשָׁמָה הוֹלֵךְ נְכֹחֹה לִמְקוֹם הָעֵדֶן הַגָּנוּז לָהּ. מַאי מַשְׁמַע. אָמַר רַבִּי יְהוּדָה מֵהַאי מַשְׁמַע, נְכֹחֹה כְּתִיב, (לפנינו כ' בואו ועי' לעיל פג ב בדרך אמת אות ג) בְּה\"א. וּבְשָׁעָה שֶׁאֵינָהּ זוֹכָה וְהִיא רְאוּיָה לְקַבֵּל עוֹנְשָׁהּ הוֹלֶכֶת מְשׁוֹמֶמֶת וּמְבַקֶּרֶת בְּכָל יוֹם לַגּוּף וְלַקֶּבֶר.","אָמַר רַבִּי יוֹסֵי הַאי קוּלִיתָא דְקַרְדִינוּתָא, כַּד אָזִיל בִּסְרִיחוּתָא לְכָאן וּלְכָאן אָזַל וּמְבַקֵּר לָהּ לְאַתְרָהּ תְּרֵיסַר יַרְחֵי. כָּךְ נִשְׁמָתָא הַהִיא דְּאִתְחַזְּיָא לְקַבְּלָא עָנְשָׁא, אָזְלָה לְבַר בְּעַלְמָא וּמַפְקֶדֶת לָה לְאַתְרָהּ תְּרֵיסַר יַרְחֵי בְּבָתֵּי קִבְרֵי וּבְעַלְמָא.","אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, דִּכְתִיב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וגו', אָמַר רַבִּי אַבָּא וְהָא תְּנַן דְּכַד נִשְׁמָתָא הִיא בְּתַשְׁלוּמָא עִלָּאָה, נִיתּוֹסַף בָּהּ ה' וְנִקְרֵאת אַבְרָהָם בְּתַשְׁלוּמָא עִלָּאָה. וְהָכָא אַתְּ אָמֵר דְּכַד לֵיתָא זַכָּאָה כָּל כָּךְ דִּכְתִיב וַיָּקָם אַבְרָהָם. עָבְדַת מַאן דְּיָתִיב בְּכֻּרְסְיָיא נָחִית בְּגוֹ זוּטָר תַּתָּאָה.","אֶלָּא הָכִי גַּזַּרְנָא וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ, דְּאָמַר רַבִּי בּוֹ אָמַר רַבִּי זְרִיקָא כְּשֶׁהַנְּשָׁמָה רְאוּיָה לַעֲלוֹת לִמְקוֹם עִדְנָּה, קוֹדֶם מְגִינָה עַל הַגּוּף הַקָּדוֹשׁ שֶׁיּוֹצֵּאת מִשָּׁם וְאַחַר כָּךְ עוֹלָה לִמְקוֹם מַעֲלָתָהּ, הֲדָא הוּא דִכְתִיב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ זְהוּ הַגּוּף.","וַיְדַבֵּר אֶל בְּנֵי חֵת אֵלּוּ שְׁאָר גּוּפוֹת הַצַּדִּיקִים שֶׁהֵם (ד\"א ל\"ג בני) חַתְּחַתִּים וְנְהֱלָמִים בָּעוֹלָם לְמַעַן יִרְאַת קוֹנָם, חָתִּים עַל שֶׁהֵם שׁוֹכְנֵי עָפָר, וְאַמַּאי צְּרִיכָה לְהוּ אָמַר רַבִּי יְהוּדָה כֹּלָּא בְּמִנְיָינָא כְּתִיבִין, וְעַל (דהוי ד\"א דא הוי ההוא) גוּפָא בְּמִנְיָינָא עִמְּהוֹן.","וּמַה אָמַר לְהוּ בְּדֶרֶךְ פִּיּוּס וּבְדֶרֶךְ כָּבוֹד. גֵּר וְתוֹשָׁב אָנֹכִי עִמָּכֶם וְגו' דְּהַאי גּוּפָא יֶהֱוִי בְּמִנְיָינָא חַד עִמְּכוֹן בְּחִבּוּרָא דָא. אָמַר רַבִּי רְאֵה מַה כְּתִיב וַיַּעֲנוּ בְּנֵי חֵת אֶת אַבְרָהָם וְגו'. כְּמוֹ כֵן בְּדֶרֶךְ כָּבוֹד בְּדֶרֶךְ פִּיּוּס, הֲדָא הוּא דִכְתִיב שְׁמָעֵנוּ אֲדוֹנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ.","מַאי נְשִׂיא אֱלֹהִים אַתָּה. אָמַר רַבִּי פִּנְחָס קוֹדֶם שֶׁיִּצֵּא הַצַּדִּיק מִן הָעוֹלָם, בַּת קוֹל יוֹצֵּאת בְּכָל יוֹם עַל אוֹתָם הַצַּדִּיקִים בְּגַן עֵדֶן הָכִינוּ מָקוֹם לִפְלוֹנִי שֶׁיָּבֹא לְכָאן. וְעַל כֵּן הֵם אוֹמְרִים מֵאֵת אֱלהִים מִלְּמַעְלָה אַתָּה נָשִׂיא בְּכָל יוֹם בְּתוֹכֵנוּ, בְּמִבְחַר קְבָרֵינוּ בְּמִבְחַר הַצַּדִּיקִים הַצַּדִּיקִים בַּחֲבוּרַת הַמּוּבְחָרִים מְנֵה אוֹתוֹ הַכְנִיסֵהוּ בְּחֶשְׁבּוֹן עִמָּנוּ, וְאִישׁ מִמֶּנּוּ לֹא יִמְנַע אֶת הַמִּנְיָן כִּי כוּלָּנוּ שְׂמֵחִים בּוֹ וּמַקְדִּימִים לוֹ שָׁלוֹם.","אָמַר רַבִּי יוֹסֵי בֶּן פַּזִּי תָּא חֲזֵי, כֵּיוָן שֶׁהַנְּשָׁמָה פּוֹגַעַת בָּהֶם (ותדון), לְאַחַר כָּךְ פּוֹגַעַת לְאוֹתוֹ הַמַּלְאָךְ הַמְמוּנֶּה עֲלֵיהֶם דִּתְנַן מַלְאָךְ מְמוּנֶּה עַל בָּתֵּי קִבְרֵי וְדוּמָה שְׁמוֹ, והוּא מַכְרִיז בֵּינֵיהֶם בְּכָל יוֹם עַל הַצַּדִּיקִים הָעֲתִידִים לִיכָּנֵס בֵּינֵיהֶם, וּמִיָּד פּוֹגַעַת בּוֹ כְּדֵי לְשַׁכֵּן הַגּוּף בְּהַשְׁקֵט וּבְבִטְחָה וּבִמְנוּחָה וּבַהֲנָאָה, (עלאה) הֲדָא הוּא דִכְתִיב וַיְדַבֵּר אֶל עֶפְרוֹן.","אָמַר רַבִּי יִיסָא זֶה הַמַּלְאָךְ הַנִּקְרָא דּוּמָה, וְלָמָּה נִתְכַּנֶּה שְׁמוֹ עֶפְרוֹן, עַל שֶׁהוּא מְמוּנֶּה עַל שׁוֹכְנֵי עָפָר. וְהוּפְקְדוּ בְּיָדוֹ כָּל פִּנְקְסֵי הַצַּדִּיקִים וַחֲבוּרוֹת הַחֲסִידִים הַשּׁוֹכְנִים בֶּעָפָר, וְהוּא עָתִיד לְהוֹצִּיאָם בְּחֶשְׁבּוֹן.","וְתָאנָא אָמַר רַבִּי אֶלְעָזָר, לֶעָתִיד לָבֹא כְּשֶׁיִּפְקוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, יִקְרָא לַמַּלְאָךְ הַמְּמוּנֶּה עַל הַקְּבָרוֹת, וְדוּמָה שְׁמוֹ, וְיִתְּבַע מִמֶּנּוּ מִנְיַן כָּל הַמֵּתִים הַצַּדִּיקִים וְהַחֲסִידִים וְאוֹתָם גֵּרֵי הַצֶּדֶק וְשֶׁנֶּהֶרְגוּ עַל שְׁמוֹ, וְהוּא מוֹצִּיאָם בְּחֶשְׁבּוֹן כְּמוֹ שֶׁנְּטָלָם (שמות צז ב) בְּחֶשְׁבּוֹן, הֲדָא הוּא דִכְתִיב (ישעיהו מ׳:כ״ו) הַמּוֹצִּיא בְּמִסְפַּר צְּבָאָם וְגו' אִישׁ לא נֶעְדָר.","וְתָאנָא אָמַר רַבִּי שְׁמוּאֵל בְּרַבִּי יַעֲקֹב, נְפָשׁוֹת הָרְשָׁעִים נְתוּנוֹת בְּיָדוֹ שֶׁל מַלְאָךְ זֶה שֶׁשְּׁמוֹ דוּמָה, לְהַכְנִיסָם בַּגֵּיהִנָּם ולָדוּן שָׁם, וְכֵיוָן שֶׁנִּמְסָרוֹת בְּיָדוֹ, שׁוּב אֵינָן חוֹזְרוֹת עַד שֶׁיִּכָּנְסוּ לַגֵּיהִנֹּם, וְזְה יִרְאַת דָּוִד שֶׁנִּתְיָירֵא כְּשֶׁעָשָׂה אוֹתוֹ עָוֹן שֶׁנְּאֱמַר (תהילים צ״ד:י״ז) לוּלֵי יְיָ עֶזְרָתָה לִי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. אָמַר רַבִּי יִיסָא הַנְּשָׁמָה פּוֹגַעַת לוֹ לְהַכְנִיס אוֹתוֹ גּוּף עִם שְׁאָר גּוּפוֹת הַצַּדִּיקִים בְּחֶשְׁבּוֹנָם הֲדָא הוּא דִכְתִיב וַיְדַבֵּר אֶל עֶפְרוֹן וְגו'.","אָמַר רַבִּי תַּנְחוּם הַמַּלְאָךְ קוֹדֵם וְאוֹמֵר לוֹ. רְאֵה מַה כְּתִיב לְמַעְלָה וְעֶפְרוֹן יוֹשֵׁב בְּתוֹךְ בְּנֵי חֵת, שִׁחֲתוֹ לִשְׁכּוֹן בֶּעָפָר. והוּא מַקְדִּים וְאוֹמֵר לוֹ לְהַכְנִיס אוֹתוֹ הַגּוּף בְּחֶשְׁבּוֹן הַצַּדִּיקִים, הֲדָא הוּא דִכְתִיב וַיַּעַן עֶפְרוֹן הַחִתִּי אֶת אַבְרָהָם בְּאָזְנֵי בְנֵי חֵת לְכֹל בָּאֵי שַׁעַר עִירוֹ לֵאמֹר. מַאי לְכֹל בָּאֵי שַׁעַר עִירוֹ. רַב נַחְמָן אָמַר אִינוּן דְּעָאלוּ בִּכְתַב חוּשְׁבַּן פִּנְקָסֵיהּ, דְּאָמַר רַב נַחְמָן וְהָכִי אִתְגְּזַר (על) חֶשְׁבּוֹן, עַל יְדוֹי דְדוּמָה עָאלִין בְּבָתֵּי קִבְרֵי וּבְחוּשְׁבַּן פִּתְקָא זַמִּין לְאֲפָקָא לוֹן וְהוּא מְמוּנֶּה עַל דַּיְירֵי עַפְרָא.","מַהוּ הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ. אָמַר רַבִּי יוֹסֵי הַפְקָדָא דְּשַׁלְּוָה וּמְנוּחָה רַבָּה. אָמַר רַבִּי שָׁלוֹם בַּר מִנְיוּמֵי אֵין לְךָ כָּל צַּדִּיק וְצַּדִּיק מֵאוֹתָם הָעוֹסְקִים בַּתּוֹרָה שֶׁאֵין לוֹ מָאתַיִם עוֹלָמוֹת וְכִסּוּפִין בִּשְׁבִיל הַתּוֹרָה הֲדָא הוּא דִכְתִיב, (שיר השירים ח׳:י״ב) וּמָאתַיִם לַנּוֹטְרִים אֶת פִּרְיוֹ, וּמָאתַיִם עַל שֶׁמּוֹסְרִים עַצְּמָם בְּכָל יוֹם כְּאִילּוּ נֶהֶרְגוּ עַל קְדוּשַׁת שְׁמוֹ, נִצְּחוֹ כְּהַאי פְּסוּקָא (נ\"א וכך אמרו בהאי פסוקא) דִכְתִיב וְאָהַבְתָּ אֵת יְיָ וְגו'. וְתָאנָא כָּל הַמְכַוִין לִבּוֹ בְּהַאי פְּסוּקָא כְּדֵי לִמְסוֹר נַפְשׁוֹ עַל קְדוּשַׁת שְׁמוֹ מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ נֶהֱרַג בְּכָל יוֹם עָלָיו, הֲדָא הוּא דִכְתִיב, (תהלים מה) כִּי עָלֶיךָ הוֹרַגְנוּ כָּל הַיּוֹם. אָמַר רַב נַחְמָן כָּל הַמּוֹסֵר נַפְשׁוֹ בְּהַאי פְּסוּקָא נוֹחֵל אַרְבַּע מֵאוֹת עוֹלָמוֹת לָעוֹלָם הַבָּא. אָמַר רַב יוֹסֵף וְהָא תְּנַן מָאתַיִם. אָמַר רַב נַחְמָן מָאתַיִם עַל הַתּוֹרָה, וּמָאתַיִם עַל שֶׁמָּסַר עַצְּמוֹ בְּכָל יוֹם עַל קְדוּשַׁת שְׁמוֹ,","וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע. רַבִּי אַבָּא אָמַר כְּגַוְונָא דָא לָא הֲווּ בְּכָל נְשֵׁי עַלְמָא דְּהָא אִתְּמָר חוּשְׁבַּן יוֹמָהָא וּשְׁנָהָא וְקִיּוּמָהָא בְּעָלְמָא וְהַהוּא אֲתַר דְּאִתְקַבְרַת בֵּיהּ. אֶלָּא לְאַחֲזָאָה דְּלָא הֲוָה כְּשָׂרָה בְּכָל נְשֵׁי עָלְמָא.","וְאִי תֵימָא הָא מִרְיָם דִּכְתִיב (במדבר כ׳:א׳) וַתָּמָת שָׁם מִרְיָם וַתִּקָּבֵר שָׁם. בְּגִין לְאַחֲזָאָה סָרְחָנָא דְיִשְׂרָאֵל קָא אֲתָא, דְּהָא מַיָיא לָא אָזְלֵי לְהוּ בְּיִשְׂרָאֵל אֶלָּא בִּזְכוּתָא דְמִרְיָם. אֲבָל לָא אִתְּמָר בְּמִיתָתָהּ כְּמָה דְאִתְּמָר בְּשָׂרָה.","רַבִּי יְהוּדָה פָּתַח (קהלת י׳:י״ז) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין וְשָׂרַיִךְ בָּעֵת יאכֵלוּ. הַאי קְרָא (צה ב) אוּקְמוּהָ חַבְרַיָיא, אֲבָל אִית לָן לְאִסְתַּכָּלָא בֵּיהּ, דְּזַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא לְמִנְדַע כָּל אוֹרְחִין סְתִימִין וּלְאִתְגַּלְּיָיא לוֹן רָזִין עִלָּאִין וְהָא אִתְּמָר.","אַשְׁרֵיךָ אֶרֶץ, דָּא אֶרֶץ הַחַיִּים, בְּגִין דְּמַלְכָּא דִילָהּ אַזְמִין לָהּ כָּל בִּרְכָאן דְּאִתְבָּרְכָא מֵאֲבָהָן עִלָּאִין, רָזָא דְוא\"ו דְּאִיהוּ קַיְימָא לְאַרְקָא עֲלָהּ בִּרְכָאן תָּדִיר, וְאִיהוּ בֶּן חוֹרִין בֶּן יוֹבֵלָא דְּאַפִּיק עַבְדִּין לְחֵירוּ, בְּרָא דְּעַלְמָא עִלָּאָה דְּאַפִּיק תָּדִיר כָּל חַיִּין וְכָל נְהִירוּ וְכָל מְשַׁח רְבוּת, וְכֹלָּא אָעִיד (נ\"א אנגיד) הַאי בְּרָא בּוּכְרָא לְהַאי אֶרֶץ כְּמָא דְאַתְּ אָמֵר (שמות ד) בְּנִי בְּכֹרִי יִשְׂרָאֵל, וּבְגִין כָּךְ אַשְׁ\"רֵיךְ אֶרֶץ.","וּמַה דְּאִתְּמָר אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נַעַר כְּמָה דְאוּקְמוּהָ, דְּהַאי אֶרֶץ תַּתָּאָה וְעַלְמָא תַּתָּאָה לָא יָנְקָא אֶלָּא מִגּוֹ שָׁלְטָנוּתָא (דעילא) דְּעָרְלָה. וְכֹלָּא מֵהַהוּא מַלְכָּא דְּאִקְרֵי נַעַר כְּמָה דְאוּקְמוּהָ. וַוי לְאַרְעָא דְּאִצְטְרִיךְ לִינָקָא הָכִי."],[[0,"אבל אינון וכו':","אבל ימיהם של הצדיקים הווים ומתקיימים. כלומר, אפילו אם הם חיים יותר מע' שנה, כי הם מקבלים ממזל העליון, שהוא מוסיף חיים על ע' שנה, כמה שרוצה. (כמ\"ש להלן בהשמטות דפו\"י דף רנ\"ז ע\"ב אות קנ\"ח בהשמטות עם מראות הסולם ע\"ש) כמו שאתה אומר, \u0003ויהיו חיי שרה,\u0004 וכן \u0003ואלה ימי שני חיי אברהם.\u0004 ואם תאמר, הרי גם בישמעאל כתוב, ואלה שני חיי ישמעאל, ואע\"פ שלא היה צדיק, הוא משום שעשה תשובה, ועל כן נאמר \u0003אלה\u0004 בימיו, כמו באברהם."],[1,"ויהיו וגו':","רבנן פתחו במקרא הזה, לכה דודי נצא השדה נלינה בכפרים. תנו רבנן. היוצא לדרך יתפלל ג' תפילות וכו': ולומר לאלו השלשה, אינו צריך ג' ברכות, אלא אפילו בברכה אחת יכול לעשותו, כי למדנו, כל שאלותיו של אדם יכול לכלול אותם בברכת שומע תפלה."],[2,"אמר ר' יהודה וכו':","אר\"י, כל מעשיו של אדם כתובים בספר, בעולם העליון הן טוב והן רע ועל כולם הוא עתיד ליתן את הדין. כי למדנו אמר רב יהודה אמר רב מה שכתוב, גלמי ראו עיניך וגו', פירושו, אותם הדברים שעשה הגולם, דהיינו הגוף, שאינו משגיח מה שיהיה בעולם הבא, כולם \u0003ראו עיניך\u0004 כי עיינת בהם. \u0003ועל ספרך כולם יכתבו,\u0004 ליתן עליהם דין וחשבון לעולם הבא. לפיכך יקדים אדם תפלתו תמיד קודם למעשהו, ויועיל לו."],[3,"אמר ר' יצחק וכו':","אר\"י, אין אדם עושה עבירות אלא מי שהוא גולם ולא אדם, והיינו אותו אדם שאינו מסתכל בצרכיה של נשמה הקדושה, אלא כל מעשיו כבהמה זו שאינה משגחת ואינה יודעת. אמר רבי בו, לר' יצחק, וכי נקרא דוד גולם, דהיינו שאינו מסתכל בנשמה, שהוא אמר אותו הכתוב."],[3,"אמר לו ר' יצחק וכו':","א\"ל ר\"י, אדם הראשון אמר לאותו הפסוק. גלמי ראו עיניך, כי גולם פירושו חומר מטרם שנשלם צורתו, ואמר, קודם שזרקת בי נשמה שהיתי גולם, ראו עיניך לעשות בצורתי אנשים שיהיו דומים לי. \u0003ועל ספרך כולם יכתבו,\u0004 שיכתבו בשמותם מי הם. \u0003ימים יוצרו,\u0004 היינו שיוצרו כצורה זו שלו. \u0003ולא אחד בהם,\u0004 היינו שלא נשאר אחד מהם."],[4,"אמר רבי בא, למה:","שואל, למה לא נשאר מאותם הדומים לצורת אדה\"ר, אף אחד. אמר לו. בוא וראה, כל אלו שהיו דומים לאדה\"ר, או אפילו דומים לו רק ברמז, כלומר, לא בבירור, לא מתו מיתת עצמם. כמ\"ש בפרקי דר' אליעזר פרק נ\"ג ובסוטה דף יוד ע\"א. וכולם הוכו באותו ענין ממש שהיו דומים לאדם הראשון. שמשון לקה בכחו שאול בצוארו וכו' כמ\"ש שם."],[4,"תא חזי אר\"י וכו':","בוא וראה אמר ר' יהודה, צורתו של אדם הראשון ויפיו היתה כזהר הרקיע העליון על כל הרקיעים, וכאותו האור שגנז הקב\"ה לצדיקים לעולם הבא. ולפיכך, כל אלו שהיה בהם רמז משהו מצורתו של אדם הראשון, הוכו בו ומתו. כמ\"ש לפנינו."],[5,"דכך אורחוי דקב\"ה וכו':","כי כך דרכיו של הקב\"ה, אם נותן עושר לאדם, למה נותן לו, הוא, לזון את העולם, ולעשות מצותיו, לא עשה זה, אלא שמתגאה בעשרו, בו יוכה, שכתוב עושר שמור לבעליו לרעתו."],[5,"יהיב ליה בנין וכו':","אם נותן לו בנים, למה נותן לו, הוא כדי ללמדם דרכיו של הקב\"ה ולשמור מצותיו, כאמור באברהם, כי ידעתיו למען אשר יצוה וגו'. לא עשה זה, אלא שמתגאה בהם, בהם הוא מוכה, שכתוב לא נין לו ולא נכד וגו'."],[5,"וכן כהאי גוונא וכו':","וכך בדרך זה, כאשר נתן הקב\"ה להם, מיופי הטוב העליון של אדם הראשון, למה נתן להם זה, הוא כדי לשמור מצותיו ולעשות רצונו. לא עשו זה, אלא שנתגאו בו, באותו היופי שנתברכו בו הוכו."],[6,"אמר רב יהודה וכו':","אר\"י, כשברא הקב\"ה את אדם הראשון בעוד שהיה גולם, מטרם שזרק בו הנשמה, קרא לאותו המלאך שהוא ממונה על צורות בני אדם, ואמר לו, עיין וצר בצורתו של זה, ששה אנשים. והם: שמשון, שאול, עשהאל, יאשיהו, צדקיהו, אבשלום, כמ\"ש בפרקי דר\"א פרק נ\"ג. וזהו שכתוב, ויולד בדמותו כצלמו ויקרא את שמו שת, כלומר ששה. דהיינו ששה אנשים הנ\"ל."],[7,"אמר ר' יצחק וכו':","אר\"י מאותו העפר ממש שנברא אדם הראשון לקח הקב\"ה לברוא אלו ששה אנשים, וקרא לו שת שפירושו שתא. כלומר שקרא והזמין ששה אנשים, וזהו שכתוב ויולד בדמותו כצלמו, דהיינו מאותו הבצק שנברא הגולם שלו, ועל כך נאמר גלמי ראו עיניך, שפירושו, שעיינת לעשות דומים אליו. \u0003ועל ספרך כולם יכתבו,\u0004 מי הם כולם. היינו שלא שמרו מה שנתן להם הקב\"ה ונגרשו מן העולם."],[8,"תנן התם וכו':","למדנו שם: אמר רב יהודה אמר רב, מצאנו שג' משמורות מתחלק הלילה, דהיינו לג' פעמים ד' שעות, וכל משמורה ומשמורה, יש לו להקב\"ה ענין מיוחד עם האדם והוא כאשר הנשמה יצאה הימנו, ואותו הגולם, דהיינו הגוף, נשאר ישן על מטתו, ואז נשמתו עולה בכל לילה לפני הקב\"ה. ויש לו ענין מיוחד עמה בכל משמורה ומשמורה. אמר ר' יצחק, אם היא זוכה, שמחים עמה למעלה, ואם לא דוחין אותה לחוץ."],[9,"אמר רב יהודה אמר רב וכו':","מכאן עד אות נ' א\"צ פירוש."],[14,"אמר ר' יוסי וכו':","אר\"י, עצם קולית הקשה, דהיינו עצם הירך, שהוכה ומש ממקומו ומוסרח לכאן ולכאן, הוא הולך ומבקר את מקומו שנים עשר חודש. כך אותה הנשמה הראויה לקבל עונש, הולכת בחוץ בעולם ופוקדת את מקומה, בעולם ובבית הקברות שנים עשר חודש."],[15,"אמר ר' יהודה וכו':","אר\"י בוא וראה, שכתוב ויקם אברהם מעל פני מתו וגו' הקשה ר' אבא, והרי למדנו, כאשר הנשמה היא בשלמות העליון, דהיינו מבינה, ניתוסף בה \u0003ה'\u0004 ונקרא אברהם בשלמות העליון. וכאן אתה אומר, כמו שאינו צדיק כל כך, שכתוב, ויקם אברהם וגו', ואתה עושה את מי שיושב בכסא גדול, שירד לשבת בתוך כסא קטן תחתון. פירוש. כי סוד \u0003ה'\u0004 של אברהם שנתוסף לו, רומז שעלה והשיג המוחין הגדולים מבינה, כנ\"ל (בפרשת לך דף קמ\"ז אות תנ\"ה ד\"ה וזה ששואל, עש\"ה), וסוד הכתוב ויקם אברהם מעל פני מתו, יורה על המוחין דקטנות המאירים לגוף, כי \u0003ויקם,\u0004 פירושו קבלת מוחין, המעמידים אותו על רגליו, \u0003מעל פני מתו,\u0004 היינו מהפנים השייכים לגוף המת, שנקרא שרה, כנ\"ל, שהם מוחין דקטנות, ומקשה כיון שהנשמה נקראת בשם \u0003אברהם,\u0004 הרי זה יורה שכבר יש לה מוחין דגדלות מבינה עלאה, ואם כן איך אומר הכתוב ויקם אברהם מעל פני מתו. שיורה על מוחין דקטנות. וז\"ש \u0003עבדת מאן דיתיב בכרסיא, נחית בגו זוטר תתאה,\u0004 שאתה עושה את היושב בכסא גדול, לירד לשבת בכסא קטן תחתון."],[16,"אלא הכי גזרנא וכו':","אלא כך אני מחליט בביאור הכתוב, ויקם אברהם מעל פני מתו, כי אמר ר' בו אמר ר' זריקא, כשהנשמה ראויה לעלות למקום העדן שלה, היא מגינה קודם על הגוף הקדוש שיצאה משם, ואחר כך היא עולה למקום מעלתה, הה\"ד ויקם אברהם מעל פני מתו, פירוש. שמקודם שהנשמה מסתלקת מהגוף לעלות לגן עדן היא ממשיכה בשביל הגוף מוחין הראוים לו, כדי שיוכל להתחבר במנין עם שאר גופות הצדיקים, כמ\"ש לפנינו, ואלו המוחין מרומזים בהכתוב ויקם אברהם וגו'. ומיושב בזה הקושיא הנ\"ל, איך ירד ממוחין דגדלות למוחין דקטנות, כי לא המשיכם בשביל עצמו, אלא בשביל הגוף."],[17,"וידבר אל בני חת:","הם שאר גופות הצדיקים, הנפחדים ומוכים בעולם למען יראת קונם, ומפחדים וחתים על שהם שוכני עפר, ועל כן נקראים בני חת. ושואל ולמה צריכה הנשמה את גופות הצדיקים. אמר ר' יהודה, כולם כתובין במנין, היינו שמכניסם בחשבון ומוציאם לתחיית המתים בחשבון, ועל כן דברה עמהם הנשמה כדי שהגוף יהיה במנין עמהם וז\"ש וידבר אל בני חת. (וכבר נתבאר ענין זה לעיל בתוספתא דף ד' אות י\"א ד\"ה כלהו ע\"ש ועוד יתבאר לפנינו)."],[18,"ומה אמר להו וכו':","ומה אמרה להם הנשמה שנקראת אברהם. אמרה בדרך פיוס ובדרך כבוד, גר ותושב אנכי \u0003עמכם\u0004 וגו', שפירושו, שאמר להם: גוף הזה יהיה \u0003עמכם\u0004 במנין אחד בחבור הזה. אמר רבי, ראה מה כתיב, ויענו בני חת את אברהם וגו' שהם ענו לו כמו כן בדרך כבוד ובדרך פיוס. וז\"ש שמענו אדוני וגו'."],[19,"מאי נשיא אלקים אתה וכו':","מכאן עד אות נ\"ט א\"צ פירוש."],[22,"ותאנא אמר ר' אלעזר וכו':","כשיפקוד הקב\"ה להחיות המתים וכו', ויתבע ממנו מנין וכו' והוא מוציאם בחשבון. כבר נתבאר זה לעיל דף ה' אות י\"א ד\"ה וההפרש."],[25,"מהו השדה וכו' א\"ר יוסי הפקדא דשלוה וכו':","הפקדא, פירושו אוצר, בדומה להמלה הפתק (ע\"ז ל\"ט ע\"ב) (ע\"כ מדרש הנעלם)."],[26,"ותמת שרה בקרית ארבע:","ר' אבא אמר, כעין זה לא היה בכל נשי העולם. כי נאמר חשבון ימיה ושנותיה וחיים שלה בעולם, ומקום ההוא שנקברה בו. כדי להראות שלא היה בכל נשי העולם כמו שרה."],[27,"ואי תימא הא מרים:","ואם תאמר הרי מרים שכתוב בה, ותמת שם מרים ותקבר שם, כמו בשרה. ואומר, שהוא נכתב רק כדי להראות הטאם של ישראל, כמ\"ש לאחר זה, ולא היה מים לעדה ויקהלו וגו'. כי המים לא הלכו בישראל אלא בזכותה של מרים, אבל לא נאמר במיתתה מספר ימים ושנים כמו שנאמר בשרה."],[28,"ר' יהודה פתח וכו':","ר\"י פתח אשריך ארץ שמלכך בן חורין וגו', מקרא הזה בארוהו החברים. אבל יש לנו להסתכל בו, כי אשריהם ישראל שהקב\"ה נתן להם התורה לדעת כל דרכים הסתומים ולגלות להם סודות העליונים."],[29,"והא אתמר. אשריך ארץ:","זהו ארץ החיים. דהיינו הנוקבא המלבשת לאלקים חיים, שהוא אמא, משום שהמלך שלה שהוא ז\"א, הכין לה כל הברכות שהתברך מאבות העליונים, דהיינו או\"א עלאין, שהמלך הזה הוא סוד ה \u0003ו'\u0004, שהוא עומד להריק עליה תמיד ברכות. והוא נקרא בן חורין, להיותו בן יובלא שהיא בינה דהיינו ישסו\"ת, שהמוחין שלה מוציאים עבדים לחירות שהם המוחין דהארת חכמה, והוא בן לעולם העליון, שהוא או\"א עלאין, שמשפיע תמיד מזווגם התמידי, כל חיים וכל אור, וכל שמן של גדולה וכבוד, פירוש. כי המלך שהוא ז\"א הוא בן ליובלא שמשם מושפע מוחין \u0003דחירות\u0004 שהוא הארת חכמה והוא גם בן לאו\"א שזווגם תמידי ולא נפסק לעולם שמהם כל המוחין הנ\"ל. וע\"כ נק' בן חורין ולא בן חירות, (כמ\"ש לעיל לך קמ\"ה אות תמ\"ז ד\"ה הכי הוא עש\"ה) \u0003וכלא אנגיד האי ברא בוכרא להאי ארץ,\u0004 וכל המוחין הנ\"ל של יובל ושל או\"א עלאין משפיע בן הבכר שהוא ז\"א, לארץ הזו, שהיא הנוקבא, כמו שאתה אומר בני בכרי ישראל. שזה נאמר על ז\"א שנקרא ישראל, ונקרא בן בכור, בעת שיש לו כל אלו המוחין הנ\"ל. \u0003ובגין כך אשריך ארץ.\u0004 וע\"כ אומר הכתוב עליה, אשריך ארץ."],[30,"ומה דאתמר אי לך וגו':","ומה שנאמר, אי לך ארץ שמלכך נער הוא כמו שבארוהו, (ל עיל לך דף קמ\"ה אות תמ\"ט) שארץ זו התחתונה ועולם התחתון אינו יונק אז אלא מממשלת הערלה, והכל נמשך למטה רק ממלך ההוא שנקרא \u0003נער\u0004 דהיינו מטטרון, כמו שבארוהו. ווי לעולם הצריך לינק כך."]],[[0,"","אֲבָל אוֹתָם הַיָּמִים שֶׁל הַצַּדִּיקִים הָיוּ וְהִתְקַיְּמוּ, כְּמוֹ שֶׁנֶּאֱמַר וַיִּהְיוּ חַיֵּי שָׂרָה, וְכֵן וְאֵלֶּה יְמֵי שְׁנֵי חַיֵּי אַבְרָהָם. וְאִם תֹּאמַר, כָּךְ גַּם כָּתוּב בְּיִשְׁמָעֵאל, שֶׁכָּתוּב (בראשית כה) שְׁנֵי חַיֵּי יִשְׁמָעֵאל? אֶלָּא שֶׁחָזַר בִּתְשׁוּבָה, וְעַל כֵּן קָרָא בְּיָמָיו וַיִּהְיוּ."],[1,"","וַיִּהְיוּ, רַבּוֹתֵינוּ פָּתְחוּ בַּפָּסוּק הַזֶּה (שיר ז) לְכָה דוֹדִי נֵצֵא הַשָּׂדֶה נָלִינָה בַּכְּפָרִים. שָׁנוּ רַבּוֹתֵינוּ, הַיּוֹצֵא לַדֶּרֶךְ יִתְפַּלֵּל שָׁלֹשׁ תְּפִלּוֹת: תְּפִלָּה שֶׁהִיא חוֹבָה שֶׁל יוֹם, וּתְפִלַּת הַדֶּרֶךְ עַל הַדֶּרֶךְ שֶׁהוּא עוֹשֶׂה, וּתְפִלָּה שֶׁיַּחֲזר לְבֵיתוֹ לְשָׁלוֹם. וְיֹאמַר אֶת הַשְּׁלֹשָׁה הָאֵלּוּ, אֲפִלּוּ בְּאֶחָד יָכוֹל לַעֲשׂוֹתוֹ, שֶׁשָּׁנִינוּ, כָּל שְׁאֵלוֹתָיו שֶׁל אָדָם יָכוֹל לִכְלֹל אוֹתָן בְּשׁוֹמֵעַ תְּפִלָּה."],[2,"","אָמַר רַבִּי יְהוּדָה, כָּל מַעֲשָׂיו שֶׁל אָדָם כְּתוּבִים בְּסֵפֶר, הֵן טוֹב וְהֵן רַע, וְעַל כֻּלָּם עָתִיד לָתֵת אֶת הַדִּין. שֶׁשָּׁנִינוּ, אָמַר רַב יְהוּדָה אָמַר רַב, מַה שֶּׁכָּתוּב (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךְ - אוֹתָם הַדְּבָרִים שֶׁעָשָׂה הַגֹּלֶם, שֶׁאֵינוֹ מַשְׁגִּיחַ בָּעוֹלָם הַבָּא, כֻּלָּם רָאוּ עֵינֶיךְ שֶׁעִיַּנְתָּ בָּהֶם. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ - לִתֵּן עֲלֵיהֶם דִּין וְחֶשְׁבּוֹן לָעוֹלָם הַבָּא. הִלְכָּךְ יַקְדִּים אָדָם תְּפִלָּתוֹ תָּמִיד וְיוֹעִיל לוֹ."],[3,"","אָמַר רַבִּי יִצְחָק, אֵין אָדָם עוֹשֶׂה עֲבֵרוֹת אֶלָּא מִי שֶׁהוּא גֹלֶם וְלֹא אָדָם, וְהַיְנוּ אוֹתוֹ שֶׁלֹּא מִסְתַּכֵּל בַּנְּשָׁמָה הַקְּדוֹשָׁה, אֶלָּא כָּל מַעֲשָׂיו כַּבְּהֵמָה הַזּוֹ שֶׁאֵין מַשְׁגַּחַת וְאֵין יוֹדַעַת. אָמַר רַבִּי בּוֹ, וְכִי גֹלֶם נִקְרָא דָוִד שֶׁאָמַר אֶת הַפָּסוּק הַזֶּה? אָמַר לוֹ רַבִּי יִצְחָק, אָדָם הָרִאשׁוֹן אֲמָרוֹ, גָּלְמִי רָאוּ עֵינֶיךְ. קֹדֶם שֶׁזָּרַקְתָּ בִּי נְשָׁמָה, רָאוּ עֵינֶיךְ לַעֲשׂוֹת בִּדְמוּתִי בְּנֵי אָדָם שֶׁיִּדְמוּ לִי. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ, מִי הֵם? יָמִים יֻצָּרוּ, בַּצּוּרָה הַזּוֹ שֶׁלִּי. וְלֹא אֶחָד בָּהֶם, שֶׁלֹּא נִשְׁאָר אֶחָד מֵהֶם."],[4,"","אָמַר רַבִּי בּו, לָמָּה? אָמַר לוֹ, בֹּא רְאֵה, כֻּלָּם שֶׁדָּמוּ לוֹ אוֹ בְּרֶמֶז שֶׁלּוֹ, לֹא מֵתוּ בְּמִיתַת נַפְשָׁם, וְכֻלָּם לָקוּ בְּאוֹתוֹ עִנְיָן מַמָּשׁ. בֹּא רְאֵה, אָמַר רַבִּי יְהוּדָה, דְּמוּתוֹ שֶׁל אָדָם הָרִאשׁוֹן וְיָפְיוֹ הָיָה כְּזֹהַר הָרָקִיעַ הָעֶלְיוֹן שֶׁעַל גַּבֵּי שְׁאָר הָרְקִיעִים, וּכְאוֹתוֹ הָאוֹר שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים לָעוֹלָם הַבָּא. וְכָל אוֹתָם שֶׁהָיוּ רְמוּזִים בּוֹ מִדְּמוּתוֹ שֶׁל אָדָם הָרִאשׁוֹן, בּוֹ הֵם לָקוּ וּמֵתוּ."],[5,"","שֶׁכָּךָ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - נוֹתֵן עֹשֶׁר לָאָדָם, לָמָּה? לָזוּן אֶת הָעֲנִיִּים וְלַעֲשׂוֹת מִצְווֹתָיו. אֵינוֹ עוֹשֶׂה אֶת זֶה וּמִתְגָּאֶה (ואם נתגלה בו) בָּעֹשֶׁר הַהוּא - בּוֹ יִלְקֶה, שֶׁכָּתוּב (קהלת ה) עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. נוֹתֵן לוֹ בָּנִים, לָמָּה? לְלַמֵּד אוֹתָם דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר מִצְווֹתָיו, כְּמוֹ שֶׁאָמוּר בְּאַבְרָהָם (בראשית יח) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת כָּל בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶרֶךְ ה' לַעֲשׂוֹת צְדָקָה וְגוֹ'. הוּא לֹא עוֹשֶׂה אֶת זֶה וּמִתְגָּאֶה בָהֶם - בָּהֶם הוּא לוֹקֶה, שֶׁכָּתוּב (איוב יח) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ וְגוֹ'. וְכֵן כְּמוֹ זֶה, כְּשֶׁנּוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מִיפִי טוּב עֶלְיוֹן שֶׁל אָדָם הָרִאשׁוֹן לָהֶם, לָמָּה? כְּדֵי לִשְׁמֹר מִצְווֹתָיו וְלַעֲשׂוֹת רְצוֹנוֹ. לֹא עָשׂוּ כָּךְ אֶלָּא הִתְגָּאוּ בוֹ - בּוֹ לוֹקִים, בַּיֹּפִי הַזֶּה."],[6,"","אָמַר רַב יְהוּדָה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אָדָם הָרִאשׁוֹן, הָיָה גֹלֶם טֶרֶם שֶׁזָּרַק בּוֹ נְשָׁמָה, וְקָרָא לְאוֹתוֹ הַמַּלְאָךְ הַמְמֻנֶּה עַל צוּרוֹת בְּנֵי אָדָם, וְאָמַר לוֹ: עַיֵּן וְצֹר בַּדְּמוּת הַזּוֹ שִׁשָּׁה בְּנֵי אָדָם. זֶהוּ שֶׁכָּתוּב (בראשית ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, כְּלוֹמַר שִׁתָּא שֵׁשׁ."],[7,"","אָמַר רַבִּי יִצְחָק, מֵאוֹתוֹ עָפָר מַמָּשׁ שֶׁנִּבְרָא אָדָם הָרִאשׁוֹן, לָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת שֵׁשֶׁת אֵלֶּה, וְקָרָא לוֹ שֵׁת שֵׁשׁ. זֶהוּ שֶׁכָּתוּב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, מֵאוֹתָהּ הָעִסָּה שֶׁנִּבְרָא הַגֹּלֶם שֶׁלּוֹ. וְעַל כָּךְ נֶאֱמַר גָּלְמִי רָאוּ עֵינֶיךְ, וְעִיַּנְתָּ בּוֹ לַעֲשׂוֹת (בו) שֶׁדּוֹמִים לוֹ. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ, מִי הֵם? כֻּלָּם שֶׁלֹּא שָׁמְרוּ מַה שֶּׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לָהֶם וְנִטְרְדוּ מִן הָעוֹלָם (ונדונו באותו הדין)."],[8,"","שָׁנִינוּ שָׁם, אָמַר רַב יְהוּדָה אָמַר רַב, מָצָאנוּ שֶׁשָּׁלֹשׁ מִשְׁמָרוֹת הוּא הַלַּיְלָה, וּלְכָל אֶחָד וְאֶחָד יֵשׁ עִנְיָן לַקָּבָּ\"ה בָּאָדָם, כְּשֶׁיּוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ וְנִשְׁאָר אוֹתוֹ גֹלֶם יָשֵׁן עַל מִטָּתוֹ, וְנִשְׁמָתוֹ עוֹלָה בְּכָל לַיְלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר רַבִּי יִצְחָק, אִם הִיא צַדִּיקָה - שְׂמֵחִים עִמָּהּ, וְאִם לֹא - דּוֹחִים אוֹתָהּ הַחוּצָה. אָמַר רַב יְהוּדָה אָמַר רַב, מַה שֶּׁכָּתוּב (שיר ה) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי."],[9,"","אָמַר רַבִּי פִּנְחָס אָמַר רַבִּי יְהוּדָה, הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם - הַנְּשָׁמָה אוֹמֶרֶת לְאוֹתָם הַנְּשָׁמוֹת הַזּוֹכוֹת לְהִכָּנֵס לִירוּשָׁלַיִם שֶׁל מַעְלָה, וְהֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם עַל שֶׁזּוֹכוֹת לִכָּנֵס שָׁם, וּלְפִיכָךְ הַנְּשָׁמָה אוֹמֶרֶת לָהֶם הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁ לם, אִם תִּמְצְאוּ אֶת דּוֹדִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַב אָמַר, זֶה זִיו הָאַסְפַּקְלַרְיָה שֶׁל מַעְלָה. מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי, לֵהָנוֹת מֵהַזִּיו שֶׁלּוֹ וּלְהִסְתּוֹפֵף בְּצִלּוֹ. רַב הוּנָא אָמַר, שֶׁחוֹלַת אַהֲבָה אָנִי - אוֹתָהּ הַתְּשׁוּקָה וְהַכִּסּוּף שֶׁכָּסַפְתִּי בָּעוֹלָם עַל הַכֹּל, לְפִיכָךְ אֲנִי חוֹלָה. רַבִּי יְהוּדָה אָמַר, זוֹ אַהֲבָה שֶׁאוֹהֶבֶת הַנְּשָׁמָה לַגּוּף. שֶׁכֵּיוָן שֶׁנִּשְׁלָם קִצּוֹ שֶׁל גּוּף, אוֹתָם הַיָּמִים שֶׁנִּגְזְרוּ עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר וַיִּהְיוּ חַיֵּי שָׂרָה, מַה כָּתוּב? וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וְגוֹ'."],[10,"","אָמַר רַב יְהוּדָה אָמַר רַב, מַה כָּתוּב בַּפָּסוּק קֹדֶם זֶה? שֶׁכָּתוּב וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאֶרֶץ כְּנָעַן."],[11,"","רַבִּי יִצְחָק אָמַר רַבִּי יוֹחָנָן, בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם וְהִכְנִיס בּוֹ אַרְבָּעָה דְבָרִים הַנֶּחֱלָקִים בַּגּוּף. אָמַר רַבִּי יְהוּדָה, הַמְחֻבָּרִים בַּגּוּף. רַבִּי יִצְחָק אָמַר הַנֶּחֱלָקִים בַּגּוּף, שֶׁהֵם חוֹלְקִים לְהִתְפָּרֵשׁ כָּל אֶחָד לִיסוֹדוֹ כְּשֶׁיּוֹצֵא הָאָדָם מִן הָעוֹלָם הַזֶּה. רַבִּי יְהוּדָה אָמַר, הַמְחֻבָּרִים בַּגּוּף בְּחַיָּיו, מַשְׁמָע מֵהַפָּסוּק שֶׁכָּתוּב וַתָּמָת שָׂרָה - זֶה הַגּוּף. בְּקִרְיַת אַרְבַּע - אֵלּוּ אַרְבָּעָה הַיְסוֹדוֹת. הִיא חֶבְרוֹן - שֶׁהָיוּ מְחֻבָּרִים בְּגוּפוֹ בְּחַיָּיו. בְּאֶרֶץ כְּנָעַן - בָּעוֹלָם הַזֶּה הַבּוֹחֵר אָדָם בִּזְמַן מוּעָט."],[12,"","וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. הַיְנוּ (שכתוב) שֶׁשָּׁנִינוּ, כָּל שִׁבְעַת הַיָּמִים נַפְשׁוֹ שֶׁל אָדָם פּוֹקֶדֶת לְגוּפוֹ וּמִתְאַבֶּלֶת עָלָיו. זֶהוּ שֶׁכָּתוּב (איוב יד) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. כְּמוֹ זֶה, וַיָּבא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. וַיָּבא אַבְרָהָם - זוֹ הִיא הַנְּשָׁמָה. לִסְפֹּד לְשָׂרָה - זֶה הַגּוּף."],[13,"","אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהַנְּשָׁמָה זוֹכָה וְעוֹלָה לִמְקוֹם מַעֲלָתָהּ, הַגּוּף שׁוֹכֵב בְּשָׁלוֹם וְיָנוּחַ עַל מִשְׁכָּבוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה נז) יָבוֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם הֹלֵךְ נְכֹחוֹ. מַה זֶּה הֹלֵךְ נְכֹחוֹ אָמַר רַבִּי יִצְחק, הַנְּשָׁמָה הֹלֵךְ נְכֹחוֹ לִמְקוֹם הָעֵדֶן הַגָּנוּז לָהּ. מַה מַּשְׁמִיעַ? אָמַר רַבִּי יְהוּדָה, מִזֶּה נִשְׁמָע נְכֹחֹה כָּתוּב בְּהֵ\"א. וּבְשָׁעָה שֶׁאֵינָהּ זוֹכָה, וְהִיא רְאוּיָה לְקַבֵּל עָנְשָׁהּ, הוֹלֶכֶת מְשׁוֹמֶמֶת וּמְבַקֶּרֶת בְּכָל יוֹם אֶת הַגּוּף וְאֶת הַקֶּבֶר."],[14,"","אָמַר רַבִּי יוֹסֵי, עֶצֶם הַקּוּלִית (ירך) הַקָּשֶׁה הַזֶּה, כְּשֶׁהוֹלֵךְ בִּסְרִיחוּת לְכָאן וּלְכָאן, הוֹלֵךְ וּמְבַקֵּר אֶת מְקוֹמוֹ שְׁנֵים עָשָׂר חֳדָשִׁים. כָּךְ הַנְּשָׁמָה הַהִיא שֶׁרְאוּיָה לְקַבֵּל עֹנֶשׁ, הוֹלֶכֶת בַּחוּץ בָּעוֹלָם, וּפוֹקֶדֶת אֶת מְקוֹמָהּ שְׁנֵים עָשָׂר חֳדָשִׁים בְּבָתֵּי הַקְּבָרוֹת וּבָעוֹלָם."],[15,"","אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה שֶׁכָּתוּב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וְגוֹ'. אָמַר רַבִּי אַבָּא, וַהֲרֵי שָׁנִינוּ שֶׁכַּאֲשֶׁר הַנְּשָׁמָה הִיא בִּשְׁלֵמוּת עֶלְיוֹנָה, נוֹסֶפֶת לָהּ הֵ\"א, וְנִקְרֵאת אַבְרָהָם בִּשְׁלֵמוּת עֶלְיוֹנָה, וְכָאן אַתָּה אוֹמֵר כַּאֲשֶׁר אֵינוֹ צַדִּיק כָּל כָּךְ, שֶׁכָּתוּב וַיָּקָם אַבְרָהָם. עָשִׂיתָ שֶׁמִּי שֶׁיּוֹשֵׁב בְּכִסֵּא יוֹרֵד לְתוֹךְ קָטָן תַּחְתּוֹן"],[16,"","אֶלָּא כָּךְ גָּזַרְתִּי - וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ. שֶׁאָמַר רַבִּי בּוֹ אָמַר רַבִּי זְרִיקָא, כְּשֶׁהַנְּשָׁמָה רְאוּיָה לַעֲלוֹת לִמְקוֹם עִדְנָהּ, קֹדֶם מְגִנָּה עַל הַגּוּף הַקָּדוֹשׁ שֶׁיּוֹצֵאת מִשָּׁם, וְאַחַר כָּךְ עוֹלָהּ לִמְקוֹם מַעֲלָתָהּ. זֶהוּ שֶׁכָּתוּב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ, זֶה הַגּוּף."],[17,"","וַיְדַבֵּר אֶל בְּנֵי חֵת - אֵלּוּ שְׁאָר גּוּפוֹת הַצַּדִּיקִים שֶׁהֵם (ד\"א בני) חַתְחַתִּים וְנֶהֱלָמִים בָּעוֹלָם לְמַעַן יִרְאַת קוֹנָם, חִתִּים עַל שֶׁהֵם שׁוֹכְנֵי עָפָר. וְלָמָּה צְרִיכָה אוֹתָם? אָמַר רַבִּי יְהוּדָה, הַכֹּל כְּתוּבִים בְּמִנְיָן, וְעַל (שהיה, ד\"א זה היה אותו) הַגּוּף בְּמִנְיָן עִמָּהֶם. וּמָה אָמַר לָהֶם בְּדֶרֶךְ פִּיּוּס וּבְדֶרֶךְ כָּבוֹד?"],[18,"","גֵּר וְתוֹשָׁב אָנֹכִי עִמָּכֶם וְגוֹ'. שֶׁהַגּוּף הַזֶּה יִהְיֶה בְמִנְיָן אֶחָד עִמָּכֶם בַּחִבּוּר הַזֶּה. אָמַר רַבִּי, רְאֵה מַה כָּתוּב, וַיַּעֲנוּ בְנֵי חֵת אֶת אַבְרָהָם וְגוֹ'. כְּמוֹ כֵן בְּדֶרֶךְ כָּבוֹד, בְּדֶרֶךְ פִּיּוּס. זֶהוּ שֶׁכָּתוּב שְׁמָעֵנוּ אֲדנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ."],[19,"","מַה זֶה נְשִׂיא אֱלֹהִים אַתָּה? אָמַר רַבִּי פִּנְחָס, קֹדֶם שֶׁיָּצָא הַצַּדִּיק מִן הָעוֹלָם, בַּת קוֹל יוֹצֵאת בְּכָל יוֹם עַל אוֹתָם הַצַּדִּיקִים בְּגַן עֵדֶן: הָכִינוּ מָקוֹם לִפְלוֹנִי שֶׁיָּבא לְכָאן. וְעַל כֵּן הֵם אוֹמְרִים, מֵאֵת אֱלֹהִים מִלְמַעְלָה אַתָּה נָשִׂיא בְּכָל יוֹם בְּתוֹכֵנוּ. בְּמִבְחַר קְבָרֵינוּ, בְּמִבְחַר הַצַּדִּיקִים, בַּחֲבוּרַת הַצַּדִּיקִים הַמֻּבְחָרִים מְנֵה אוֹתוֹ, הַכְנִיסֵהוּ בְּחֶשְׁבּוֹן עִמָּנוּ, וְאִישׁ מִמֶּנּוּ לֹא יִמְנַע אֶת הַמִּנְיָן, כִּי כֻלָּנוּ שְׂמֵחִים בּוֹ וּמַקְדִימִים לוֹ שָׁלוֹם."],[20,"","אָמַר רַבִּי יוֹסֵי בֶּן פַּזִּי, בּא רְאֵה, כֵּיוָן שֶׁהַנְּשָׁמָה פּוֹגַעַת בָּהֶם וְתִדּוֹן, לְאַחַר כָּךְ פּוֹגַעַת לְאוֹתוֹ הַמַּלְאָךְ הַמְמֻנֶּה עֲלֵיהֶם. שֶׁשָּׁנִינוּ, מַלְאָךְ הַמְמֻנֶּה עַל בָּתֵּי הַקְּבָרוֹת וְדוּמָה שְׁמוֹ, וְהוּא מַכְרִיז בֵּינֵיהֶם בְּכָל יוֹם עַל הַצַּדִּיקִים הָעֲתִידִים לִכָּנֵס בֵּינֵיהֶם, וּמִיָּד פּוֹגַעַת בּוֹ כְּדֵי לְשַׁכֵּן הַגּוּף בְּהַשְׁקֵט וּבְבִטְחָה וּבִמְנוּחָה וּבַהֲנָאָה (עליונה). זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֶל עֶפְרוֹן."],[21,"","אָמַר רַבִּי יֵיסָא, זֶה הַמַּלְאָךְ הַנִּקְרָא דוּמָה. וְלָמָּה נִתְכַּנֶּה שְׁמוֹ עֶפְרוֹן? עַל שֶׁהוּא מְמֻנֶּה עַל שׁוֹכְנֵי עָפָר, וְהֻפְקְדוּ בְיָדוֹ כָּל פִּנְקְסֵי הַצַּדִּיקִים וַחֲבוּרוֹת הַחֲסִידִים הַשּׁוֹכְנִים בֶּעָפָר, וְהוּא עָתִיד לְהוֹצִיאָם בְּחֶשְׁבּוֹן."],[22,"","וְלָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, לֶעָתִיד לָבא כְּשֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, יִקְרָא לַמַּלְאָךְ הַמְמֻנֶּה עַל הַקְּבָרוֹת, וְדוּמָה שְׁמוֹ, וְיִתְבַּע מִמֶּנּוּ מִנְיַן כָּל הַמֵּתִים הַצַּדִּיקִים וְהַחֲסִידִים וְאוֹתָם גֵּרֵי הַצֶּדֶק וְשֶׁנֶּהֶרְגוּ עַל שְׁמוֹ, וְהוּא מוֹצִיאָם בְּחֶשְׁבּוֹן כְּמוֹ שֶׁנְּטָלָם בְּחֶשְׁבּוֹן. זֶהוּ שֶׁכָּתוּב (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ' אִישׁ לֹא נֶעְדָּר."],[23,"","וְלָמַדְנוּ, אָמַר רַבִּי שְׁמוּאֵל בְּרַבִּי יַעֲקֹב, נַפְשׁוֹת הָרְשָׁעִים נְתוּנוֹת בְּיָדוֹ שֶׁל מַלְאָךְ זֶה שֶׁשְּׁמוֹ דוּמָה לְהַכְנִיסָם בַּגֵּיהִנֹּם וְלָדוּן שָׁם. וְכֵיוָן שֶׁנִּמְסָרוֹת בְּיָדוֹ, שׁוּב אֵינָן חוֹזְרוֹת, עַד שֶׁיִּכָּנְסוּ לַגֵּיהִנֹּם. וְזֶה יִרְאַת דָּוִד שֶׁנִּתְיָרֵא כְּשֶׁעָשָׂה אוֹתוֹ עָוֹן, שֶׁנֶּאֱמַר (תהלים צד) לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. אָמַר רַבִּי יֵיסָא, הַנְּשָׁמָה פּוֹגַעַת לוֹ לְהַכְנִיס אוֹתוֹ גוּף עִם שְׁאָר גּוּפוֹת הַצַּדִּיקִים בְּחֶשְׁבּוֹנָם. זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֶל עֶפְרוֹן וְגוֹ'."],[24,"","אָמַר רַבִּי תַּנְחוּם, הַמַּלְאָךְ קוֹדֵם וְאוֹמֵר לוֹ: רְאֵה מַה כָּתוּב לְמַעְלָה - וְעֶפְרוֹן יֹשֵׁב בְּתוֹךְ בְּנֵי חֵת. שִׁחֲתוֹ לִשְׁכֹּן בֶּעָפָר, וְהוּא מַקְדִּים וְאוֹמֵר לוֹ לְהַכְנִיס אוֹתוֹ הַגּוּף בְּחֶשְׁבּוֹן הַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב וַיַּעַן עֶפְרוֹן הַחִתִּי אֶת אַבְרָהָם בְּאָזְנֵי בְנֵי חֵת לְכָל בָּאֵי שַׁעַר עִירוֹ לֵאמֹר. מַה זֶּה לְכֹל בָּאֵי שַׁעַר עִירוֹ? רַב נַחְמָן אָמַר, אוֹתָם שֶׁנִּכְנְסוּ בִּכְתַב חֶשְׁבּוֹן פִּנְקָסוֹ. שֶׁאָמַר רַב נַחְמָן, וְכָךְ נִגְזַר (על) חֶשְׁבּוֹן, עַל יַד דּוּמָה נִכְנָסִים לְבָתֵּי הַקְּבָרוֹת, וּבְחֶשְׁבּוֹן הַפֶּתֶק עָתִיד לְהוֹצִיא אוֹתָם, וְהוּא מְמֻנֶּה עַל שׁוֹכְנֵי הֶעָפָר."],[25,"","מַה זֶּה הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אַשֶׁר בּוֹ? אָמַר רַבִּי יוֹסֵי, אוֹצָר שֶׁל שַׁלְוָה וּמְנוּחָה רַבָּה. אָמַר רַבִּי שָׁלוֹם בַּר מִנְיוֹמֵי, אֵין לְךְ כָּל צַדִּיק צַדִּיק מֵאוֹתָם הָעוֹסְקִים בַּתּוֹרָה שֶׁאֵין לוֹ מָאתַיִם עוֹלָמוֹת וְכִסּוּפִים בּשְׁבִיל הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שיר ח) וּמָאתַיִם לְנֹטְרִים אֶת פִּרְיוֹ. וּמָאתַיִם עַל שֶׁמּוֹסְרִים עַצְמָם בְּכָל יוֹם כְּאִלּוּ הֶרְגוּ עַל קְדֻשַּׁת שְׁמוֹ, וְנִצְּחוֹ כְּמוֹ הַפָּסוּק הַזֶּה. (וכך אמרו בפסוק הזה) שֶׁכָּתַב וְאָהַבְתָּ אֵת ה' וְגוֹ'. לָמַדְנוּ, כָּל הַמְכַוֵּן אֶת לִבּוֹ בַּפָּסוּק הַזֶּה כְּדֵי לִמְסֹר נַפְשׁוֹ עַל קְדֻשַּׁת שְׁמוֹ, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ הֱרָג בְּכָל יוֹם עָלָיו. זֶהוּ שֶׁכָּתוּב (תהלים מד) כי עליך הרגנו כל היום. אמר רב נחמן, כל המוסר נפשו בפסוק זה, נוחל ארבע מאות עולמות לעולם הבא. אמר רב וסף, והרי שנינו מאתים? אמר רב חמן, מאתים על התורה - ומאתם על שמסר עצמו בכל יום על קדשת שמו."],[26,"","וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע. רַבִּי אַבָּא אָמַר, כְּמוֹ זֶה לֹא הָיוּ בְּכָל נְשׁוֹת הָעוֹלָם, שֶׁהֲרֵי נֶאֱמַר חֶשְׁבּוֹן יָמֶיהָ וּשְׁנוֹתֶיהָ וְקִיּוּמָהּ בָּעוֹלָם וְאוֹתוֹ הַמָּקוֹם שֶׁבּוֹ הִיא נִקְבְּרָה. אֶלָּא לְהַרְאוֹת שֶׁלֹּא הָיְתָה כְּמוֹ שָׂרָה בְּכָל נְשׁוֹת הָעוֹלָם."],[27,"","וְאִם תֹּאמַר הִנֵּה מִרְיָם, שֶׁכָּתוּב (במדבר כ) וַתָּמָת שָׁם מִרְיָם וַתִּקָּבֵר שָׁם - זֶה בָּא לְהַרְאוֹת אֶת סִרְחוֹנָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי הַמַּיִם לֹא הָלְכוּ בְּיִשְׂרָאֵל אֶלָּא בִּזְכוּת מִרְיָם. אֲבָל לֹא נֶאֱמַר בְּמִיתָתָהּ כְּמוֹ שֶׁנֶּאֱמַר בְּשָׂרָה."],[28,"","רַבִּי יְהוּדָה פָּתַח, (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ הַחֲבֵרִים, אֲבָל יֵשׁ לָנוּ לְהִסְתַּכֵּל בּוֹ, שֶׁאַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה לָדַעַת כָּל הַדְּרָכִים הַנִּסְתָּרוֹת וּלְגַלּוֹת לָהֶם סוֹדוֹת עֶלְיוֹנִים, וַהֲרֵי זֶה נִתְבָּאֵר."],[29,"","אַשְׁרֵיךָ אֶרֶץ - זוֹ אֶרֶץ הַחַיִּים, מִשּׁוּם שֶׁהַמֶּלֶךְ שֶׁלָּהּ מַזְמִין לָהּ כָּל הַבְּרָכוֹת שֶׁהִתְבָּרְכָה מֵהָאָבוֹת הָעֶלְיוֹנִים, הַסּוֹד שֶׁל וָא\"ו, שֶׁהוּא עוֹמֵד לְהָרִיק עָלֶיהָ בְּרָכוֹת תָּמִיד, וְהוּא בֶּן חוֹרִים, בֶּן הַיּוֹבֵל שֶׁמּוֹצִיא אֶת הָעֲבָדִים לְחֵרוּת, בֶּן הָעוֹלָם הָעֶלְיוֹן שֶׁמּוֹצִיא תָמִיד אֶת כָּל הַחַיִּים וְכָל הָאוֹר וְכָל שֶׁמֶן מִשְׁחָה, וְהַכֹּל מַשְׁפִּיעַ הַבֵּן הַבְּכוֹר הַזֶּה לָאָרֶץ הַזּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) בְּנִי בְּכֹרִי יִשְׂראֵל, וּמִשּׁוּם כָּךְ אַשְׁרֵי\"ךְ אֶרֶץ."],[30,"","וּמַה שֶּׁנֶּאֱמַר אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁהָאָרֶץ הַתַּחְתּוֹנָה הַזּוֹ וְהָעוֹלָם הָעֶלְיוֹן לֹא יוֹנְקִים אֶלָּא מִתּוֹךְ שִׁלְטוֹן (של מעלה) שֶׁל הָעָרְלָה, וְהַכֹּל מֵאוֹתוֹ הַמֶּלֶךְ שֶׁנִּקְרָא נַעַר, כְּמוֹ שֶׁבֵּאֲרוּהָ - אוֹי לְאֶרֶץ שֶׁצְּרִיכָה לִינֹק כָּךְ."]]],[["תָּא חֲזֵי, הַאי נַעַר לֵית לֵיהּ מִגַרְמֵיהּ כְּלוּם בַּר כַּד נָטִיל בִּרְכָאן לְזִמְנִין יְדִיעָן, וְכָל זִמְנִין דְּאִתְמְנָעוּ מִנֵּיהּ וְאִתְפְּגִים סִיהֲרָא וְאִתְחֲשָׁךְ וּבִרְכָאן אִתְמְנָעוּ מִנֵּיהּ, וַוי לְעַלְמָא דְּאִצְטְרִיךְ לִינָקָא בְּהַהִיא שַׁעְתָּא. וְעוֹד בְּכַמָּה דִינִין אִתְדָן הַאי עַלְמָא עַד לָא יָנְקָא מִנֵּיהּ, דְּכוֹלָּא בְּדִינָא אִתְקַיָּים וְאִתְעֲבַד וְאוּקְמוּהָ (הכי).","תָּא חֲזֵי, וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע. רָזָא אִיהוּ, בְּגִין דְּלָא הֲוָה מִיתָתָהּ עַל יְדָא דְּהַהוּא נָחָשׁ עֲקִימָאָה, וְלָא שָׁלַט בָּהּ כִּשְׁאָר בְּנֵי עָלְמָא דְּאִיהוּ שַׁלִּיט בְּהוּ. וְעַל יָדֵיהּ מֵתוּ בְּנֵי עָלְמָא מִיּוֹמָא דְּגָרִים לוֹן אָדָם בַּר משֶׁ\"ה וְאַהֲרֹ\"ן וּמִרְיָ\"ם דִּכְתִיב בְּהוּ עַל פִּי יְיָ. וּבְגִין יְקָרָא דִּשְׁכִינְתָּא לָא כְּתִיב בְּמִרְיָם עַל פִּי יְיָ.","אֲבָל בְּשָׂרָה כְּתִיב בְּקִרְיַת אַרְבַּע, רָזָא דְּקִרְיַת אַרְבַּע בְּרָזָא עִלָּאָה, וְלָא עַל יְדָא אָחֳרָא. בְּקִרְיַת אַרְבַּע, וְלא בְּנָחָשׁ. בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן, דְּאִתְחַבַּר דָּוִד מַלְכָּא בַּאֲבָהָן, וְעַל דָּא לָא הֲוָה מִיתָתָהּ בִּידָא אָחֳרָא אֶלָּא בְּקִרְיַת אַרְבַּע.","תָּא חֲזֵי, כַּד יוֹמִין דְּבַר נָשׁ אִתְקַיְימוּ בְּדַרְגִּין עִלָּאִין, אִתְקָיָּים בַּר נָשׁ בְּעַלְמָא. כֵּיוָן דְּלָא אִתְקַיָּים בְּדַרְגִּין עִלָּאִין, נָפְקֵי וְנָחֲתֵי לְתַתָּא עַד דִּקְרִיבוּ לְהַאי דַרְגָּא דְּמוֹתָא שַׁרְיָא בֵּיהּ, וּכְדֵין נָטִיל רְשׁוּ לְאַפִּיק נִשְׁמָתָא וְטָאס עַלְמָא בְּזִמְנָא חָדָא וְנָטִיל נִשְׁמָתָא וְסָאִיב לֵיהּ לְגוּפָא וְאִשְׁתָּאַר מְסָאֲבָא. זַכָּאִין אִינוּן צַדִּיקַיָּא דְּלָא אִסְתָּאֲבוּ וְלָא אִשְׁתָּאַר בְּהוּ מְסָאֲבוּתָא.","וְתָא חֲזֵי בְּאֶמְצָעוּת דִּרְקִיעָא אִתְקַטַּר חַד אוֹרְחָא קַסְטְרִירָא וְאִיהוּ חִוְיָא דִּרְקִיעָא דְּכָל כֹּכָבִין דַּקִּיקִין כֻּלְהוּ קְטִירִין בֵּיהּ וְקָיְימֵי בֵּיהּ תִּלֵּי תִּלִּין, וְאִינוּן מְמַנָּן בִּסְתִירוּ (ס\"א בסטירו) עוֹבָדֵי בְּנֵי עָלְמָא.","כְּגַוְונָא דָא כַּמָּה חֲבִילֵי טְהִירִין נָפְקֵי לְעַלְמָא מֵהַאי חִוְיָא עִלָּאָה קַדְמָאָה דְּאִתְפַּתָּא בֵּיהּ אָדָם, וְכֻלְהוּ מְמַנָּן בִּסְתִירוּ עוֹבָדֵי עַלְמָא, וּבְגִין כָּךְ אָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה, מְסַיְיעִין לֵיהּ מִלְּעֵילָא, וְסִיּוּעָא דְּמָארֵיהּ סַחֲרָא לֵיהּ וְאִסְתַּמַּר וְאִקְרֵי קָדוֹשׁ."],[[0,"ת\"ח האי נער וכו':","בוא וראה נער הזה, שהוא מטטרון, אין לו מעצמו מאומה, רק מה שמקבל ברכות מהנוקבא לזמנים ידועים. וכל פעם שנמנעו ממנו, כי נפגמה הלבנה שהיא הנוקבא, ונחשכה, שאז נמנעו הברכות ממטטרון, ווי באותה שעה לעולם הצריך לינק ממנו את קיומו, ועור נידון העולם בהרבה דינים, מטרם שיונק ממנו, אלא מן הקליפות, כי הכל מתקיים ונעשה אז בדין. וכבר בארוהו."],[1,"תא חזי ותמת שרה וגו':","הוא סוד, כי לא היה מיתתה על ידי אותו נחש העקלתון, דהיינו מלאך המות, ולא שלט עליה, כמו שהוא שולט על כל בני העולם, שכל בני העולם מתים על ידו, מיום שגרם להם אדם המיתה, חוץ ממשה אהרן ומרים שלא מתו על ידי מלאך המות אלא בנשיקה, שכתוב בהם \u0003על פי ה',\u0004 ומשום כבוד השכינה לא כתוב במרים על פי ה', אע\"פ שגם היא מתה בנשיקה. (כמ\"ש במסכת בבא בתרא דף י\"א ע\"א)."],[2,"אבל בשרה כתיב בקרית ארבע:","שמתה בסוד קרית ארבע, בסוד עליון, ולא על ידי אחר, בקרית ארבע ולא בנחש, בקרית ארבע היא חברון, שנתחבר דוד באבות, ועל כן לא היה מיתתה על ידי אחר אלא בקרית ארבע."],[2,"","פירוש. יש ב' בחינות מלכות הנקראות \u0003רביעאה ושביעאה,\u0004 כמ\"ש לעיל (בראשית א' דף ק\"י אות קי\"ז ד\"ה מלכותא דדוד עש\"ה) שמבחינת למעלה מפרסא, דהיינו מחזה ולמעלה דז\"א, היא נקראת, \u0003רביעאה לאבות\u0004 שהם חג\"ת, ונקראת \u0003מלכותא דדוד,\u0004 וכן \u0003קרית ארבע.\u0004 והיא המתוקנת בסוד \u0003ארץ החיים,\u0004 שעליה נאמר אשריך ארץ שמלכך בן חורין. (כנ\"ל באות ס\"ה) ומבחינת למטה מפרסא, דהיינו מחזה ולמטה דז\"א, היא נבחנת בסוד \u0003שביעאה לבנין\u0004 שהם נה\"י, ונקראת מלכותא \u0003דיוסף,\u0004 כמ\"ש שם. וז\"ש \u0003רזא דקרית ארבע ברזא עלאה,\u0004 הסוד של קרית ארבע היא בסוד העליון, דהיינו מלכותא דדוד, שהיא העליונה שלמעלה מפרסא דז\"א, \u0003ולא על ידא אחרא,\u0004 ולא על ידי האחרת שהיא המלכות התחתונה שלמטה מפרסא שה\"ס \u0003שביעאה,\u0004 כנ\"ל, \u0003בקרית ארבע ולא בנחש,\u0004 וע\"כ נשמע מהכתוב שלא מתה מבחינת הנחש, שהיא מלאך המות, כי אין לו שליטה ואחיזה בהמלכות שמבחינת למעלה מפרסא, הנקראת קרית ארבע. ומוסיף לבאר, ואומר \u0003בקרית ארבע היא חברון,\u0004 שפירושו, \u0003דאתחבר דוד מלכא באבהן,\u0004 שהם חג\"ת שלמעלה מפרסא דז\"א, \u0003ועל דא לא הוה מיתתה בירא אחרא\u0004 על ידי מלאך המות הנמשך ממלכות התחתונה, כמו שמבאר לפנינו, אלא בקרית ארבע."],[3,"ת\"ח כד יומין וכו':","בוא וראה, כאשר ימי האדם מתקיימים במדרגות העליונות, דהיינו בז\"ס חג\"ת נהי\"מ, מתקיים האדם בעולם, כיון שלא נתקיים עוד במדרגות העליונות, דהיינו שכבר גמר חיי שבעים שנה הנמשכים מז\"ס חג\"ת נהי\"מ, נמצאים ימיו יוצאים מהספירות, ויורדים למטה מהספירות, עד שקרבים לאותו מדרגה שהמות שורה בו, דהיינו מלאך המות, שהוא מתחת ספירת המלכות, ששם נאמר, לפתח חטאת רובץ, ואז מקבל רשות להוציא הנשמה. והוא עף כל העולם בעפיפה אחת ונוטל הנשמה ומטמא את הגוף, ונשאר הגוף טמא. אשרי הם הצדיקים שלא נטמאו בו, ולא נשאר בגופם טומאה. ור' יהודה מביא זה לראיה לדבריו, שלא שלט בשרה מלאך המות. כי נתבאר כאן, שענין המיתה בא לאדם אחר שיוצא מז\"ס ובא למתחת מלכות התחתונה, ששם מקומו של מלאך המות, שאז נוטל רשות ומוציא נשמתו. ונמצא ששרה שמעולם לא ירדה מתחת המלכות התחתונה. אלא שמתה בקרית ארבע, שהוא מלכות העליונה שלמעלה מפרסא, שבמקום החזה דז\"א, ודאי הוא, שלא מתה ע\"י מלאך המות."],[4,"ותא חזי באמצעות דרקיעא וכו':","ובוא וראה, באמצעו של הרקיע, נקשר אורח מבהיק. והוא נחש הרקיע שנקרא בפי התוכנים קו החלב, שכל הככבים הדקים כולם קשורים בו, ועומדים בו תלי תלים, דהיינו שהם מקובצים ועומדים בו, כמו הרים על הרים בלי מספר. והם ממונים על מעשים של בני העולם שבסתר. (וכבר נתבאר זה לעיל בראשית ב' דף ע\"ג אות קי\"ב ד\"ה ביאור. ע\"ש)."],[5,"כגוונא דא וכו':","כעין זה, כמה אגודות של אורות הקליפות יצאו לעולם, מאותו נחש העליון הראשון שנתפתה בו אדם, וכולם ממונים על מעשי העולם שבסתר. ומשום זה כשבא האדם להטהר, עוזרים לו מלמעלה, ועזרת רבונו מסבב אותו ונשמר, ונקרא קדוש."]],[[0,"","בֹּא רְאֵה, הַנַּעַר הַזֶּה אֵין לוֹ מֵעַצְמוֹ כְּלוּם, רַק כְּשֶׁנּוֹטֵל בְּרָכוֹת לְעִתִּים יְדוּעִים, וְכָל הַפְּעָמִים שֶׁנִּמְנְעוּ מִמֶּנּוּ, וְנִפְגְּמָה הַלְּבָנָה וְנֶחְשֶׁכֶת, וְהַבְּרָכוֹת נִמְנָעוֹת מִמֶּנּוּ. אוֹי לָעוֹלָם שֶׁצָּרִיךְ לִינֹק בַּשָּׁעָה הַזּוֹ. וְעוֹד, בְּכַמָּה דִינִים נִדּוֹן הָעוֹלָם הַזֶּה טֶרֶם יוֹנֵק מִמֶּנּוּ, שֶׁהַכֹּל מִתְקַיֵּם בְּדִין וְנַעֲשָׂה, וְנִתְבָּאֵר (כך)."],[1,"","בֹּא רְאֵה, וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע - סוֹד הוּא, מִשּׁוּם שֶׁלֹּא הָיְתָה מִיתָתָהּ עַל יְדֵי אוֹתוֹ הַנָּחָשׁ עֲקַלָּתוֹן, וְלֹא שָׁלַט בָּהּ כְּמוֹ שְׁאָר בְּנֵי הָעוֹלָם שֶׁשּׁוֹלֵט בָּהֶם, וְעַל יָדוֹ מֵתוּ בְּנֵי הָעוֹלָם מִיּוֹם שֶׁגָּרַם לָהֶם אָדָם, פְּרָט לְמֹשֶׁ\"ה וְאַהֲרֹ\"ן וּמִרְיָ\"ם, שֶׁכָּתוּב בָּהֶם עַל פִּי ה'. וּמִשּׁוּם כְּבוֹד הַשְּׁכִינָה לֹא כָתוּב בְּמִרְיָם עַל פִּי ה'."],[2,"","אֲבָל בְּשָׂרָה כָּתוּב בְּקִרְיַת אַרְבַּע. הַסּוֹד שֶׁל קִרְיַת אַרְבַּע בְּסוֹד עֶלְיוֹן, וְלֹא עַל יְדֵי אַחֵר. בְּקִרְיַת אַרְבַּע, וְלֹא בְּנָחָשׁ. בְּקִרְיַת אַרְבַּע, הִיא חֶבְרוֹן. שֶׁהִתְחַבֵּר דָּוִד הַמֶּלֶךְ עִם הָאָבוֹת, וְעַל כֵּן לֹא הָיְתָה מִיתָתָהּ בְּיַד אַחֵר אֶלָּא בְּקִרְיַת אַרְבַּע."],[3,"","בֹּא רְאֵה, כַּאֲשֶׁר הַיָּמִים שֶׁל אָדָם הִתְקַיְּמוּ בִּדְרָגוֹת עֶלְיוֹנוֹת, מִתְקַיֵּם הָאָדָם בָּעוֹלָם. כֵּיוָן שֶׁלֹּא מִתְקַיֵּם בַּדְּרָגוֹת הָעֶלְיוֹנוֹת, יוֹצְאִים וְיוֹרְדִים לְמַטָּה, עַד שֶׁקְּרֵבִים לַדַּרְגָּה הַזּוֹ שֶׁבָּהּ שׁוֹרָה הַמָּוֶת. וְאָז נוֹטֶלֶת רְשׁוּת לְהוֹצִיא הַנְּשָׁמָה, וְטָסָה הָעוֹלָם בְּפַעַם אַחַת וְנוֹטֶלֶת הַנְּשָׁמָה, וּמְטַמֵּא אֶת הַגּוּף וְנִשְׁאָר טָמֵא. אַשְׁרֵי הַצַּדִּיקִים שֶׁלֹּא נִטְמְאוּ וְלֹא נִשְׁאֲרָה בָהֶם טֻמְאָה."],[4,"","וּבֹא רְאֵה, בְּאֶמְצַע הָרָקִיעַ נִקְשָׁר דֶּרֶךְ אֶחָד מַבְהִיק, וְהוּא נְחַשׁ הָרָקִיעַ, שֶׁכָּל הַכּוֹכָבִים הַדַּקִּים כֻּלָּם קְשׁוּרִים בּוֹ וְעוֹמְדִים בּוֹ תִּלֵּי תִלִּים, וְהֵם מְמֻנִּים (בצד) עַל מַעֲשֵׂי בְּנֵי הָעוֹלָם שֶׁבַּסֵּתֶר."],[5,"","כְּדֻגְמַת זֶה כַּמָּה קְבוּצוֹת מַלְאֲכֵי דִּין יוֹצְאוֹת לָעוֹלָם מִזֶּה הַנָּחָשׁ הָעֶלְיוֹן הַקַּדְמוֹן שֶׁהִתְפַּתָּה בּוֹ אָדָם, וְכֻלָּם מְמֻנִּים בְּסֵתֶר מַעֲשֵׂי הָעוֹלָם, וּמִשּׁוּם כָּךְ, בָּא אָדָם לְהִטָּהֵר - מְסַיְּעִים אוֹתוֹ מִלְמַעְלָה, וְהַסִּיּוּעַ שֶׁל רַבּוֹ מַקִּיף אוֹתוֹ וְנִשְׁמָר וְנִקְרָא קָדוֹשׁ."]]],[["אָתֵי בַּר נָשׁ לְאִסְתָּאֲבָא, כַּמָּה חֲבִילִין טְהִירִין אִזְדַּמְּנוּ לֵיהּ. וְכֻלְהוּ (סחרן) שַׁרְיָין בֵּיהּ וּמְסַחֲרִין לֵיהּ וּמְסָאֲבִין לֵיהּ וְאִקְרֵי טָמֵא, וְכֻלְּהוּ אָזְלֵי וּמַכְרְזֵי קַמֵּי, טָמֵא טָמֵא כְּמָה דְאַתְּ אָמֵר, (ויקרא י״ג:מ״ה-מ״ו) וְטָמֵא טָמֵא יִקְרָא. וְכֻלְּהוּ קְטִירִין בְּהַהוּא חִיוְיָא קַדְמָאָה וּסְתִירִין בְּכַמָּה עוֹבָדֵי עָלְמָא.","רַבִּי יִצְחָק וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי מִטְּבֶרְיָא לְלוֹד. אָמַר רַבִּי יִצְחָק תְּוַוהֲנָא עַל הַהוּא רָשָׁע דְּבִלְעָם דְּכָל עוֹבָדוֹי דְהַהוּא רָשָׁע הֲווּ מִסִּטְרָא דִּמְסָאֲבָא. וְהָכָא אוֹלִיפְנָא רָזָא חָדָא, דְּכָל זִינֵי נְחָשַׁיָּא דְּעַלְמָא כֻּלְּהוֹן מִתְקַטְּרָן וְנָפְקִין מֵהַהוּא נָחָשׁ קַדְמוֹנִי דְּאִיהוּ רוּחַ מְסָאֲבָא מְזוּהֲמָא, וּבְגִין כָּךְ כָּל חָרָשִׁין דְּעַלְמָא אִקְרוּן עַל שְׁמָא דָא נְחָשִׁים (ועקרבים) וְכֻלְּהוּ מֵהַאי סִטְרָא נָפְקֵי. וּמַאן דְּאִתְמְשַׁךְ בְּהַאי, הָא אִסְתָּאַב.","וְלָא עוֹד אֶלָּא דְּבָעֵי לְאִסְתָּאֲבָא בְּגִין לְאַמְשָׁכָא עֲלֵיהּ הַהוּא סִטְרָא דְּרוּחַ מְסָאֲבָא. דְּהָא תָּנִינָן כְּגַוְונָא דְאִתְעַר בַּר נָשׁ הָכִי נָמֵי אַמְשִׁיךְ עֲלֵיהּ מִלְּעֵילָא, אִי אִיהוּ אִתְעַר בְּסִטְרָא דִקְדוּשָּׁה אַמְשִׁיךְ עֲלֵיהּ קְדוּשָּׁה מִלְּעֵילָא וְאִתְקַדַּשׁ. וְאִי אִיהוּ אִתְעַר בְּסִטְרָא דִּמְסָאֲבָא הָכִי אַמְשִׁיךְ עֲלֵיהּ רוּחַ מְסָאֲבָא וְאִסְתָּאַב. דְּהָא אִתְּמָר עַל מַה דְּתָנִינָן אָתֵי בַּר נָשׁ לְאִסְתָּאֲבָא מְסָאֲבִין לֵיהּ.","בְּגִין כָּךְ הַהוּא רָשָׁע דְּבִלְעָם, בְּגִין לְאַמְשָׁכָא עֲלֵיהּ רוּחַ מְסָאֲבָא מֵהַהוּא נָחָשׁ עִלָּאָה, הֲוָה אִסְתָּאַב בְּכָל לֵילְיָא בַּאֲתָנֵיהּ, וְהֲוָה עָבִיד עִמַּהּ עוֹבָדֵי אִישׁוּת בְּגִין לְאִסְתָּאֲבָא וּלְאַמְשָׁכָא עֲלֵיהּ רוּחַ מְסָאֲבָא, וּכְדֵין עֲבִיד חֳרָשׁוֹי וְעוֹבָדוֹי.","וְשֵׁירוּתָא דְּעוֹבָדוֹי הֲוֵי נָטִיל נָחָשׁ מֵאִינוּן חִוְיָין וְקָטִיר לֵיהּ קַמֵּיהּ וּבָזַע רֵישֵׁיהּ וְאַפִּיק לִישָׁנֵיהּ וְנָטִיל עִשְׂבִּין יְדִיעָן וְאוֹקִיד כֹּלָּא וְעֲבִיד מִנֵּיהּ קְטַרְתָּא חָדָא, לְבָתַר נָטִיל רֵישָׁא דְהַהוּא חִוְיָא וּבְזַע לֵיהּ לְאַרְבַּע סִטְרִין וְעֲבִיד מִנֵּיהּ קְטַרְתָּא אָחֳרָא."],[[0,"אתי בר נש לאסתאבא וכו':","בא האדם להטמא, כמה אגודות אורות של הקליפות נועדו לו, וכולם שורים בו ומסבבים אותו, ומטמאין אותו ונקרא טמא. וכולם הולכים ומכריזים לפניו, טמא טמא. כמש\"א, וטמא טמא יקרא. וכולם קשורים בנחש ההוא הראשון, ונסתרים בכמה מעשים של בני העולם."],[1,"ר' יצחק ור' יוסי וכו':","ר\"י ור\"י היו הולכים מטבריא ללוד. אמר ר' יצחק, תמיהני על רשע ההוא בלעם, כי כל מעשיו של אותו רשע היו מצד הטומאה. וכאן למדנו סוד אחד, שכל מיני נחש וכשפים שבעולם כולם מתקשרים ויוצאים מנחש ההוא הקדמוני, שהוא רוח הטומאה המזוהם, ועל כן כל הכשפים שבעולם נקראים על שם הזה, של נחש הקדמוני, נחשים. וכולם מצד ההוא יוצאים וכל הנמשך בזה, דהיינו אחר כשפים, הוא נטמא."],[2,"ולא עוד וכו':","ולא עוד אלא שצריך להטמא מקודם, אם רוצה לעשות כישוף, כדי להמשיך על עצמו צד ההוא של רוח הטומאה. כי למדנו כמו שאדם נתעורר מלמטה כן הוא ממשיך עליו מלמעלה. אם הוא נתעורר מלמטה בצד הקדושה, ממשיך עליו קדושה מלמעלה, והוא מקודש. ואם הוא נתעורר מלמטה בצד הטומאה, כן הוא ממשיך עליו רוח הטומאה ונטמא. וזה אמרו, על מה שלמדנו, הבא לטמא מטמאים אותו."],[3,"בגין כך וכו':","משום זה, רשע ההוא, בלעם, בשביל להמשיך על עצמו רוח הטומאה מנחש ההוא העליון, היה מטמא את עצמו בכל לילה באתונו, והיה עושה עמה מעשה אישות, בשביל להטמא, ולהמשיך עליו רוח הטומאה, ואחרי זה עשה כשפיו ומעשיו."],[4,"ושירותא דעובדוי וכו':","ותחילת מעשיו היו, לקח נחש מתוך הנחשים, וקשר אותו לפניו, ובקע את ראשו, והוציא את לשונו. ולקח עשבים ידועים ושרף כולם, ועשה מהם קטרת אחת. ואחר כך לקח הראש של אותו הנחש, ובקע אותו לארבע צדדים, ועשה ממנו קטרת אחרת."]],[[0,"","בָּא הָאָדָם לְהִטָּמֵא - כַּמָּה חֲבִילוֹת שֶׁל אוֹרוֹת מִזְדַּמְּנִים לוֹ, וְכֻלָּם (סובבים) שׁוֹרִים בּוֹ וּמְסוֹבְבִים אוֹתוֹ וּמְטַמְּאִים אוֹתוֹ, וְנִקְרָא טָמֵא. וְכֻלָּם הוֹלְכִים וּמַכְרִיזִים לְפָנָיו טָמֵא טָמֵא, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יג) וְטָמֵא טָמֵא יִקְרָא. וְכֻלָּם קְשׁוּרִים בְּאוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי וְנִסְתָּרִים בְּכַמָּה מַעֲשִׂים שֶׁל הָעוֹלָם."],[1,"","רַבִּי יִצְחָק וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מִטְּבֶרְיָא לְלוֹד. אָמַר רַבִּי יִצְחָק, תְּמֵהַנִי עַל אוֹתוֹ בִּלְעָם הָרָשָׁע, שֶׁכָּל מַעֲשֵׂי אוֹתוֹ הָרָשָׁע הָיוּ מִצַּד הַטֻּמְאָה, וְכָאן לָמַדְנוּ סוֹד אֶחָד - שֶׁכָּל מִינֵי נְחָשִׁים שֶׁל הָעוֹלָם, כֻּלָּם קְשׁוּרִים וְיוֹצְאִים מֵאוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי, שֶׁהוּא רוּחַ טֻמְאָה מְזֹהֶמֶת. וּמִשּׁוּם כָּךְ כָּל הַכְּשָׁפִים שֶׁל הָעוֹלָם נִקְרָאִים בַּשֵּׁם הַזֶּה נְחָשִׁים (ועקרבים), וְכֻלָּם יוֹצְאִים מִן הַצַּד הַזֶּה. וּמִי שֶׁנִּמְשָׁךְ לָזֶה, הִנֵּה הוּא נִטְמָא."],[2,"","וְלֹא עוֹד, אֶלָּא שֶׁרוֹצֶה לְהִטָּמֵא כְּדֵי לִמְשֹׁךְ עָלָיו אוֹתוֹ הַצַּד שֶׁל רוּחַ טֻמְאָה. שֶׁהֲרֵי שָׁנִינוּ, כְּמוֹ שֶׁמְּעוֹרֵר הָאָדָם - כָּךְ גַּם מוֹשֵׁךְ עָלָיו מִלְמַעְלָה. אִם הוּא מְעוֹרֵר בְּצַד הַקְּדֻשָּׁה - מוֹשֵׁךְ עָלָיו קְדֻשָּׁה מִלְמַעְלָה וּמִתְקַדֵּשׁ. וְאִם הוּא מְעוֹרֵר בְּצַד הַטֻּמְאָה - כָּךְ מוֹשֵׁךְ עָלָיו רוּחַ הַטֻּמְאָה וְנִטְמָא. שֶׁהֲרֵי נֶאֱמַר עַל מַה שֶּׁשָּׁנִינוּ, בָּא אָדָם לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ."],[3,"","מִשּׁוּם כָּךְ אוֹתוֹ בִּלְעָם הָרָשָׁע, כְּדֵי לִמְשֹׁךְ עָלָיו רוּחַ טֻמְאָה מֵאוֹתוֹ הַנָּחָשׁ הָעֶלְיוֹן, הָיָה נִטְמָא בְּכָל לַיְלָה עִם אֲתוֹנוֹ, וְהָיָה עוֹשֶׂה עִמָּהּ מַעֲשֵׂי אִישׁוּת כְּדֵי לְהִטָּמֵא וְלִמְשֹׁךְ עָלָיו רוּחַ טֻמְאָה, וְאָז עָשָׂה כְשָׁפָיו וּמַעֲשָׂיו."],[4,"","וְרֵאשִׁית מַעֲשָׂיו הָיָה נוֹטֵל נָחָשׁ מֵאוֹתָם נְחָשִׁים, וְקוֹשֵׁר אוֹתוֹ לְפָנָיו, וְקוֹרֵעַ אֶת רֹאשׁוֹ, וּמוֹצִיא אֶת לְשׁוֹנוֹ, וְנוֹטֵל עֲשָׂבִים יְדוּעִים וְשׂוֹרֵף הַכֹּל, וְעוֹשֶׂה מִמֶּנּוּ קְטֹרֶת אַחַת. אַחַר כָּךְ נוֹטֵל אֶת רֹאשׁ אוֹתוֹ הַנָּחָשׁ וְקוֹרֵעַ אוֹתוֹ לְאַרְבָּעָה צְדָדִים, וְעוֹשֶׂה מִמֶּנּוּ קְטֹרֶת אַחֶרֶת."]]],[["וְעֲבִיד עִגּוּלָא חַד, וְהֲוָה אָמַר מִלִּין וְעֲבִיד עוֹבָדִין אָחֳרָנִין, עַד דְּאַמְשִׁיךְ עֲלֵיהּ רוּחִין מְסָאֲבִין, וְאוֹדִיעִין לֵיהּ מַה דְּאִצְטְרִיךְ, וְעֲבִיד בְּהוּ עוֹבָדוֹי כְּפוּם מַה דְּאִינוּן יָדְעֵי מִסִּטְרָא דְהַהוּא חִוְיָא דִּרְקִיעָא. מִתַּמָּן אִתְמַשַּׁךְ בְּעוֹבָדוֹי וְחָרָשׁוֹי עַד דְּאַמְשִׁיךְ עֲלֵיהּ רוּחַ מֵהַהוּא נָחָשׁ קַדְמָאָה.","וּמֵהָכָא הֲוָה יָדַע יְדִיעָן וָחֳרָשִׁין וְקוֹסְמִין. וּבְגִין כָּךְ כְּתִיב וְלא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, נְחָשִׁים וַדַּאי, וְעִקְּרָא וְשָׁרְשָׁא בִּמְסָאֲבוּתָא אִיהוּ כְּמָה דְאִתְּמָר, וּלְבָתַר שֵׁירוּתָא דְּכֹלָּא לָאו אִיהוּ אֶלָּא בְּנָחָשׁ.","אָמַר רַבִּי יוֹסֵי אַמַּאי כָּל זַיְינֵי חֳרָשִׁין וְקוֹסְמִין לָא אִשְׁתַּכָּחוּ אֶלָּא בִּנְשַׁיָּיא. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא מִדַּאֲתָא נָחָשׁ עַל חַוָּה הִטִּיל בָּהּ זוּהֲמָא, בָּהּ אַטִּיל וְלָא בְּבַעֲלָהּ. אָמַר הָכִי הוּא וַדַּאי, אֲתָא רַבִּי יוֹסֵי וּנְשָׁקֵיהּ לְרַבִּי יִצְחָק, אָמַר כַּמָּה זִמְנִין שָׁאִילְנָא הַאי מִלָּה וְלָא זָכִינָא בָּהּ אֶלָּא הַשְׁתָּא.","אָמַר לֵיהּ כָּל הַנֵּי עוֹבָדִין וְכָל מַה דְּיָדַע בִּלְעָם מֵאָן אֲתַר אוֹלִיף לֵיהּ. אָמַר לֵיהּ מֵאֲבוֹי. אֲבָל בְּאִינוּן הַרְרֵי קֶדֶם דְּאִיהוּ אֶרֶץ קֶדֶם אוֹלִיף כָּל חֳרָשִׁין וְכָל זִינֵי קוֹסְמִין. (שמות קיב) בְּגִין דִּבְאִינוּן טוִּרִי אִינוּן מַלְאֲכֵי עֲזָ\"א וַעֲזָאֵ\"ל, דְּאַפִּיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִן שְׁמַיָא וְאִינוּן קְטִירִין בְּשַׁלְשְׁלָאֵי דְפַרְזְלָא וְאוֹדִיעִין חֳרָשִׁין לִבְנֵי נָשָׁא, וּמִתַּמָּן הֲוָה יָדַע בִּלְעָם כְּמָה דְאַתְּ אָמֵר מִן אֲרָם יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב מֵהַרְרֵי קֶדֶם.","אָמַר לֵיהּ וְהָא כְּתִיב וְלא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו. אָמַר לֵיהּ, סִטְרָא תַּתָּאָה דְּאַתְיָא מֵרוּחַ מְסָאֲבָא דִלְעֵילָא, הוּא רוּחַ מְסָאֲבָא דְּשַׁלִּיט בְּמַדְבְּרָא כַּד עָבְדוּ בְּנֵי יִשְׂרָאֵל יַת עֶגְלָא בְּגִין לְאִסְתָּאֲבָא בַּהֲדֵיהּ דְּאִיהוּ תַּתָּאָה, וּבְכֹלָּא עֲבַד חֳרָשׁוֹי בְּגִין דְּיֵכוּל לְאַעֲקָרָא לוֹן לְיִשְׂרָאֵל וְלָא יָכִיל."],[[0,"ועביד עגולא חד וכו':","ועשה סביבותיו עגול אחד, והיה אומר דברים ועשה מעשים אחרים, עד שהמשיך עליו רוחות הטומאה, והודיעו לו מה שצריך. ועשה על פיהם מעשיו, כפי מה שידעו מצד הנחש ההוא של הרקיע, (הנ\"ל באות ע\"א)."],[1,"ומהכא הוה ידע וכו':","ומכאן היה יודע ידיעות וכשפים וקסמים, ומשום זה כתוב, ולא הלך כפעם בפעם לקראת נחשים. היינו נחשים ממש, כי העיקר והשורש בטומאה, הוא כמו שנתבאר (לעיל אות ע\"ז) שתחילת הכל אינו אלא בנחש."],[2,"אמר ר' יוסי וכו':","אר\"י, למה כל מיני כשפים וקסמים אינם נמצאים אלא בנשים. אמר לו, כך למדנו. כשבא נחש על חוה הטיל בה זוהמא, (לעיל ב\"א של\"ז אות תנ\"ה) רק בה הטיל ולא בבעלה, והכשפים נמשכים מזוהמת הנחש כנ\"ל (אות ע\"ד) לפיכך נמצאים הכשפים בנשים. אמר, כן הוא ודאי. בא ר' יוסי ונשקו לר' יצחק, אמר, הרבה פעמים שאלתי דבר זה, ולא זכיתי להבינו אלא עתה."],[3,"א\"ל כל הני עובדין וכו':","אמר לו, כל אלו המעשים שעשה בלעם, דהיינו מעשה הכשפים, וכל מה שידע, מאין למד אותם. אמר לו, מאביו למד אותם, אבל באלו הררי קדם, שהוא ארץ קדם, למד בעיקר כל הכשפים וכל מיני קסמים, משום שבהרים האלו נמצאים המלאכים עזא ועזאל, שהפיל אותם הקב\"ה מן השמים משום שקטרגו על בריאת אדם (כמ\"ש בזהר בלק דף ר\"ז ע\"ב ור\"ו ע\"א ובסולם דף קמ\"ז אות תט\"ז ע\"ש) והם קשורים שם בשלשלאות של ברזל, ומודיעים כשפים לבני אדם. ומשם ידע בלעם, כמש\"א, מן ארם ינחני בלק מלך מואב \u0003מהררי קדם,\u0004 ששם עזא ועזאל."],[4,"א\"ר והא כתיב וכו':","אמר לו, והרי כתוב, ולא הלך וגו' וישת אל המדבר פניו, הרי שלא תמיד הלך לקראת נחשים. א\"ל, הצד התחתון הבא מרוח הטומאה שלמעלה, הוא רוח הטומאה ששלט במדבר, בעת שעשו בני ישראל את העגל, כדי להטמא ממנו, שהוא תחתון. וע\"כ וישת אל המדבר פניו. ומכל הצדדים עשה כשפיו, כדי שיוכל לעקור את ישראל, ולא יכול לעקרם."]],[[0,"","וְעוֹשֶׂה עִגּוּל אֶחָד, וְהָיָה אוֹמֵר דִּבּוּרִים וְעוֹשֶׂה מַעֲשִׂים אֲחֵרִים, עַד שֶׁמָּשַׁךְ עָלָיו רוּחוֹת טְמֵאוֹת וּמוֹדִיעוֹת לוֹ מַה שֶּׁצָּרִיךְ, וְעוֹשֶׂה בָהֶם מַעֲשִׂים כְּפִי מַה שֶּׁהֵם יוֹדְעִים מִצַּד אוֹתוֹ הַנָּחָשׁ שֶׁל הָרָקִיעַ. מִשָּׁם נִמְשַׁךְ בְּמַעֲשָׂיו וּבִכְשָׁפָיו, עַד שֶׁמָּשַׁךְ עָלָיו רוּחַ מֵאוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי."],[1,"","וּמִכָּאן הָיָה יוֹדֵעַ יְדִיעוֹת וּכְשָׁפִים וּקְסָמִים. וּמִשּׁוּם כָּךְ כָּתוּב, וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים. נְחָשִׁים וַדַּאי. וְהָעִקָּר וְהַשֹּׁרֶשׁ בַּטֻּמְאָה הוּא כְּמוֹ שֶׁנִּתְבָּאֵר, וְאַחַר כָּךְ רֵאשִׁית הַכֹּל אֵינוֹ אֶלָּא בְּנָחָשׁ."],[2,"","אָמַר רַבִּי יוֹסֵי, לָמָּה כָּל מִינֵי כְשָׁפִים וּקְסָמִים לֹא נִמְצָאִים אֶלָּא בְּנָשִׁים? אָמַר לוֹ, כָּךְ לָמַדְנוּ, מִשֶּׁבָּא נָחָשׁ עַל חַוָּה, הִטִּיל בָּהּ זֻהֲמָא. הִטִּיל בָּהּ וְלֹא בְּבַעְלָהּ. אָמַר, כָּךְ זֶה וַדַּאי! בָּא רַבִּי יוֹסֵי וְנָשַׁק לְרַבִּי יִצְחָק. אָמַר, כַּמָּה פְעָמִים שָׁאַלְתִּי עַל הַדָּבָר הַזֶּה וְלֹא זָכִיתִי בוֹ, אֶלָּא כָּעֵת."],[3,"","אָמַר לוֹ, כָּל הַמַּעֲשִׂים הַלָּלוּ וְכָל מַה שֶּׁיָּדַע בִּלְעָם, מֵאֵיזֶה מָקוֹם לָמַד אוֹתָם? אָמַר לוֹ, מֵאָבִיו. אֲבָל בְּאוֹתָם הַרֲרֵי קֶדֶם, שֶׁהִיא אֶרֶץ קֶדֶם, לָמַד כָּל הַכְּשָׁפִים וְכָל מִינֵי קְסָמִים, מִשּׁוּם שֶׁבְּאוֹתָם הֶהָרִים הֵם הַמַּלְאָכִים עֲזָ\"א וַעֲזָאֵ\"ל שֶׁהִפִּיל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הַשָּׁמַיִם, וְהֵם קְשׁוּרִים בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל, וּמוֹדִיעִים כְּשָׁפִים לִבְנֵי אָדָם. וּמִשָּׁם הָיָה יוֹדֵעַ בִּלְעָם, כְּמוֹ שֶׁנֶּאֱמַר מִן אֲרָם יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב מֵהַרֲרֵי קֶדֶם."],[4,"","אָמַר לוֹ, וַהֲרֵי כָּתוּב וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו? אָמַר לוֹ, הַצַּד הַתַּחְתּוֹן שֶׁבָּא מֵרוּחַ הַטֻּמְאָה שֶׁלְּמַעְלָה הִיא רוּחַ טֻמְאָה שֶׁשּׁוֹלֶטֶת בַּמִּדְבָּר, כְּשֶׁעָשׂוּ בְּנֵי יִשְׂרָאֵל אֶת הָעֵגֶל כְּדֵי לְהִטָּמֵא עִמּוֹ, שֶׁהוּא תַחְתּוֹן. וּבַכֹּל עָשָׂה אֶת כְּשָׁפָיו, כְּדֵי שֶׁיּוּכַל לַעֲקֹר אֶת יִשְׂרָאֵל, וְלֹא יָכֹל."]]],[["אָמַר רִבִּי יוֹסֵי הַאי דְאָמַרְתְּ בְּקַדְמִיתָא דְּכַד נָחָשׁ אֲתָא עַל חַוָּה אַטִיל בָּהּ זוּהֲמָא שַׁפִּיר, אֲבָל הָא תָּנִינָן דְּכַד קָאִימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי פָּסַק מִנַּיְיהוּ זוּהֲמָא. יִשְׂרָאֵל דְּקַבִּילוּ אוֹרַיְיתָא פָּסַק מִנַּיְיהוּ זוּהֲמָא, אֲבָל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת דְּלָא קַבִּילוּ אוֹרַיְיתָא לָא פָּסְקָא זוּהֲמָא מִנַּיְיהוּ.","אָמַר לֵיהּ שַׁפִּיר קָאֲמַרְתְּ, אֲבָל תָּא חֲזֵי, אוֹרַיְיתָא לָא אִתְיְיהִיבַת אֶלָּא לִדְכוּרֵי דִּכְתִיב, (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם משֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. דְּהָא נַשֵּׁי פְּטִירִין מִפִּקּוּדֵי אוֹרַיְיתָא.","וְעוֹד דְּאַהֲדָרוּ כֻּלְּהוּ לְזוּהֲמָתָן כְּקַדְמִיתָא בָּתַר דְּחָטוּ, וְאִתְּתָא קַשְׁיָא לְאִתְפְּרָשָׁא זוּהֲמָא מִנָּהּ יַתִּיר מִגַּבְרָא. וּבְגִין כָּךְ אִשְׁתַּכָּחוּ נָשִׁין בַּחֲרָשַׁיָא וּבְזוּהֲמָא דָא יַתִּיר מִגּוּבְרִין. דְּהָא נְשַׁיָא מִסִּטְרָא דִשְׂמָאלָא קָא אַתְיָין וְאִתְדַּבָּקוּ בְּדִינָא קַשְׁיָא, וְסִטְרָא דָא אִתְדָּבַּק בְּהוּ יַתִּיר מִגּוּבְרִין כְּמָה דְאִתְּמַר בְּגִין דְּאַתְיָא מִסִּטְרָא דְדִינָא קַשְׁיָא, וְכֹלָּא אִתְדָּבַּק וְאָזִיל בָּתַר זִינֵיהּ.","תָּא חֲזֵי, דְּהָכִי הוּא כְּמָה דַאֲמִינָא, דְּבִלְעָם הֲוָה אִסְתָּאַב בְּקַדְמִיתָא בְּגִין לְאַמְשָׁכָא עֲלֵיהּ רוּחָא מְסָאֲבָא. כְּגַוְונָא דָא אִתְּתָא בְּיוֹמֵי דִּמְסָאֲבוּ דִילָהּ אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מִנָּהּ, בְּגִין דִּבְרוּחַ מְסָאֲבָא אִתְדַּבְּקַת וּבְהַהוּא זִמְנָא אִי אִיהִי תַּעֲבִיד חֳרָשִׁין אַצְלָחוּ בִּידָהָא יַתִּיר מִזִּמְנָא אָחֳרָא, דְּהָא רוּחַ מְסָאֲבָא שַׁרְיָא עִמַּהּ, וְעַל דָּא בְּכָל מַה דְּקָרִיבַת אִסְתָּאַב, כָּל שֶׁכֵּן מַאן דְּקָרִיב בַּהֲדָהּ. זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לוֹן אוֹרַיְיתָא וְאָמַר לוֹן (ויקרא י״ח:י״ט) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ אֲנִי יְיָ."],[[0,"אמר ר' יוסי וכו':","אר\"י, זה שאמרת בתחילה על השאלה, למה נמצאים הכשפים בנשים (באות פ') כשבא נחש על חוה הטיל בה זוהמא, יפה הוא, אבל הרי למדנו, כשעמדו ישראל על הר סיני נפסק מהם הזוהמא, וישראל שקבלו את התורה נפסק מהם הזוהמא, ועכו\"ם שלא קבלו התורה לא נפסק מהם הזוהמא, הרי שכבר נפסק הזוהמא מנשים, ואם כן חזרה שאלתי למקומה, למה הכשפים הם בנשים בעיקר."],[1,"א\"ל שפיר קאמרת וכו':","אמר לו יפה אמרת. אבל בוא וראה, התורה לא נתנה אלא לזכרים, שכתוב וזאת התורה אשר שם משה לפני \u0003בני\u0004 ישראל, שהרי הנשים פטורים ממצות התורה, היינו מצות עשה שהזמן גרמא, ועל כן לא פסקה זוהמתן בעת מתן תורה, ומשום זה הכשפים שהם נמשכים מזוהמא דחויא, נמצאים בעיקר בנשים כנ\"ל."],[2,"ועוד דאהדרו וכו':","ועוד, שאחר העגל חזרו כולם לזוהמתם ואפילו הזכרים, ונשים, קשה להן להפריד את עצמן מן הזוהמא יותר מאנשים, ומשום זה, נמצאים נשים בכשפים ובזוהמא הזו, יותר מאנשים. והטעם, שקשה להם להפרד מן הזוהמא, הוא, משום שנשים באים מצד שמאל, ונתדבקו בדין קשה שבשמאל, וצד זה נתדבק בהם יותר מבאנשים, כמו שאמרנו, משום שבאים מצד דין הקשה. והכל מתדבק והולך אחר מינו."],[3,"תא חזי דהכי הוא וכו':","בוא וראה שכן הוא כמו שאמרתי, שהכשפים נמשכים מזוהמא דחויא, כי בלעם היה מטמא עצמו תחילה כדי להמשיך עליו רוח הטומאה ואח\"כ עשה כשפיו כנ\"ל. כעין זה אשה בימי טומאתה, יש לאדם להשמר ממנה שלא יגע בה, משום שהיא מתדבקת ברוח הטומאה, ובזמן ההוא אם תעשה כשפים, יצליחו בידיה יותר מבזמן אחר. ועל כן בכל מה שהיא נוגעת יטמא,וכל שכן מי שקרב אליה. אשרי הם ישראל שהקב\"ה נתן להם התורה, ואמר להם, ואל אשה בנדת טומאתה לא תקרב לגלות ערותה אני ה'."]],[[0,"","אָמַר רַבִּי יוֹסֵי, מַה שֶּׁאָמַרְתָּ בָּרִאשׁוֹנָה, שֶׁכַּאֲשֶׁר הַנָּחָשׁ בָּא עַל חַוָּה הִטִּיל בָּהּ זֻהֲמָא - זֶה יָפֶה. אֲבָל הֲרֵי שָׁנִינוּ, שֶׁכַּאֲשֶׁר עָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, פָּסְקָה מֵהֶם הַזֻּהֲמָא. וּכְשֶׁיִּשְׂרָאֵל קִבְּלוּ תוֹרָה, פָּסְקָה מֵהֶם הַזֻּהֲמָא. אֲבָל שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם שֶׁלֹּא קִבְּלוּ הַתּוֹרָה, לֹא פָסְקָה מֵהֶם הַזֻּהֲמָא."],[1,"","אָמַר לוֹ, יָפֶה אָמַרְתָּ! אֲבָל בֹּא רְאֵה, הַתּוֹרָה לֹא נִתְּנָה אֶלָּא לַזְּכָרִים, שֶׁכָּתוּב (דברים ד) וְזאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. שֶׁהֲרֵי נָשִׁים פְּטוּרוֹת מִמִּצְווֹת הַתּוֹרָה."],[2,"","וְעוֹד, שֶׁכֻּלָּם חָזְרוּ לְזֻהַמְתָּן כְּמוֹ בָּרִאשׁוֹנָה אַחַר שֶׁחָטְאוּ, וּמֵהָאִשָּׁה קָשֶׁה לְהַפְרִיד אֶת הַזֻּהֲמָא יוֹתֵר מֵהַגֶּבֶר, וּמִשּׁוּם כָּךְ נִמְצְאוּ נָשִׁים בִּכְשָׁפִים וּבַזֻּהֲמָא הַזּוֹ יוֹתֵר מֵאֲשֶׁר בַּגְּבָרִים. שֶׁהֲרֵי הַנָּשִׁים בָּאוֹת מִצַּד הַשְּׂמֹאל וּדְבוּקוֹת בַּדִּין הַקָּשֶׁה, וְהַצַּד הַזֶּה נִדְבָּק בָּהֶם יוֹתֵר מִבַּגְּבָרִים, כְּמוֹ שֶׁנִּתְבָּאֵר, מִשּׁוּם שֶׁבָּאוֹת מִצַּד הַדִּין הַקָּשֶׁה, וְהַכֹּל נִדְבָּק וְהוֹלֵךְ אַחַר מִינוֹ."],[3,"","בֹּא רְאֵה שֶׁכָּךְ הוּא כְּמוֹ שֶׁאָמַרְתִּי - שֶׁבִּלְעָם הָיָה נִטְמָא בָּרִאשׁוֹנָה כְּדֵי לְהַמְשִׁיךְ עָלָיו רוּחַ שֶׁל טֻמְאָה. כְּמוֹ זֶה הָאִשָּׁה בִּימֵי טֻמְאָתָהּ יֵשׁ לְאָדָם לְהִשָּׁמֵר מִמֶּנָּה, מִשּׁוּם שֶׁנִּדְבֶּקֶת בְּרוּחַ שֶׁל טֻמְאָה, וּבְאוֹתוֹ הַזְּמַן אִם הִיא תַּעֲשֶׂה כְשָׁפִים - יַצְלִיחוּ בְיָדָהּ יוֹתֵר מִבִּזְמַן אַחֵר, שֶׁהֲרֵי רוּחַ טֻמְאָה שׁוֹרָה עִמָּהּ, וְעַל כֵּן לְכָל מַה שֶּׁמִּתְקָרֶבֶת - נִטְמָא, כָּל שֶׁכֵּן מִי שֶׁקָּרֵב אֵלֶיהָ. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה וְאָמַר לָהֶם (ויקרא יח) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ אֲנִי ה'."]]],[["אָמַר לֵיהּ הַאי מַאן דְּאִסְתַּכַּל בְּצִפְצוּפוֹי דְּעוֹפֵי אַמַּאי אִקְרֵי נָחָשׁ. אָמַר לוֹ דְּהָא מֵהַהוּא סִטְרָא קָאָתֵי דְּרוּחַ מְסָאֲבָא שַׁרְיָא עַל הַהוּא עוֹפָא וְאוֹדַע מִלִּין בְּעַלְמָא. וְכָל רוּחַ מְסָאֲבָא בְּנָחָשׁ אִתְדַּבָּקוּ וְאַתְיָין לְעַלְמָא וְלֵית מַאן דְּיִשְׁתְּזִיב מִנֵּיהּ בְּעַלְמָא, דְּהָא אִיהוּ אִשְׁתַּכַּח עִם כֹּלָּא, עַד זִמְנָא דְּזָמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לֵיהּ מֵעַלְמָא כְּמָה דְאִתְּמָר דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַע הַמָּוֶת לָנֶצַח וּמָחָה יְיָ אֱלהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגו'. וּכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגו'.","רִבִּי יְהוּדָה אָמַר, אַבְרָהָם יָדַע בְּהַהִיא מְעַרְתָּא סִימָנָא, וְלִבֵּיהּ וּרְעוּתֵיהּ תַּמָּן הֲוָה, בְּגִין דְּמִקַדְּמַת דְּנָא עָאל לְתַמָּן וְחָמָא לְאָדָם וְחַוָּה טְמִירִין תַּמָּן. וּמְנָא הֲוָה יָדַע דְּאִינוּן הֲווּ. אֶלָּא חָמָא דִּיוּקְנֵיהּ, וְאִסְתַּכַּל וְאִתְפַּתַּח לֵיהּ חַד פִּתְחָא דְּגִנְתָּא דְעֵדֶן תַּמָּן וְהַהוּא דִּיוּקְנָא דְאָדָם הֲוָה קָאִים לְגַבֵּיהּ.","וְתָא חֲזֵי כָּל מַאן דְּאִסְתַּכַּל בְּדִיוּקְנָא דְּאָדָם לָא אִשְׁתְּזִיב לְעָלְמִין מִמִּיתָה, בְּגִין דְּהָא בְּשַׁעְתָּא דְּבַר נָשׁ אִסְתַּלַּק מֵעַלְמָא חָמֵי לֵיהּ לְאָדָם וּבְהַהוּא זִמְנָא מִית. אֲבָל אַבְרָהָם אִסְתַּכַּל בֵּיהּ וְחָמָא דִיוּקְנֵיהּ וְאִתְקְיַּים, וְחָמָא נְהוֹרָא דְּנָהִיר בִּמְעַרְתָּא וְחַד שְׁרַגָּא דָּלִיק, כְּדֵין תָּאִיב אַבְרָהָם דִּיּוּרֵיהּ בְּהַהוּא אֲתַר, וְלִבֵּיהּ וּרְעוּתֵיהּ הֲוָה תָּדִיר בִּמְעַרְתָּא.","תָּא חֲזֵי, הַשְׁתָּא אַבְרָהָם בְּחָכְמְתָא עֲבַד בְּזִמְנָא דְּתָבַע קִבְרָא לְשָׂרָה, דְּהָא כַּד תָּבַע לָא תָבַע לִמְעַרְתָּא בְּהַהוּא זִמְנָא, וְלָא אָמַר דְּבָעֵי לְאִתְפָּרְשָׁא מִנַּיְיהוּ. אֶלָּא אָמַר, תְּנוּ לִי אֲחוּזַת קֶבֶר עִמָּכֶם וְאֶקְבְּרָה מֵתִי מִלְּפָנַי. וְאִי תֵימָא דְלָא הֲוָה עֶפְרוֹן תַּמָּן. תַּמָּן הֲוָה, דִּכְתִיב וְעֶפְרוֹן יוֹשֵׁב בְּתוֹךְ בְּנֵי חֵת, וְאַבְרָהָם לָא אָמַר לֵיהּ בְּהַהִיא שַׁעְתָּא כְּלוּם.","אֶלָּא מַה דְּאָמַר לוֹן, אָמַר כְּמָה דִכְתִיב וַיְדַבֵּר אֶל בְּנֵי חֵת וְגו'. וְכִי סָלְקָא דַעְתָּךְ דְּאַבְרָהָם בָּעָא לְאִתְקְבְרָא בֵּינַיְיהוּ בֵּין מְסָאֳבִין אוֹ דְּתִאוּבְתֵּיהּ הֲוָה עִמְּהוֹן, אֶלָּא בְּחָכְמָה עֲבַד."],[[0,"אמר ליה האי מאן וכו':","א\"ל, זה מי שמסתכל בצפצופם של עופות כדי לדעת עתידות, למה נקרא נחש וכשוף, אמר לו משום שנמשך מצד הזה של טומאה, כי רוח הטומאה שורה על אותו העוף, ומודיע דברים בעולם, וכל רוח טומאה, מתדבק ובא לעולם מן הנחש, ואין מי שינצל ממנו בעולם, כי הוא נמצא בכל דבר, עד הזמן שעתיד הקב\"ה להעביר אותו מן העולם, כמו שאמרו, שכתוב, בלע המות לנצח וגו'. וכתוב ואת רוח הטומאה וגו'."],[1,"ר' יהודה אמר וכו':","רי\"א, אברהם היה יודע סימן באותה המערה, היינו מערת המכפלה, ולבו ורצונו שם היה. משום כי מקודם לכן נכנס שם וראה את אדם וחוה צפונים שם. ושואל, ומאין היה יודע שהם היו, שהרי לא הכירם קודם, ומשיב, אלא ראה צורתו של אדם, ונסתכל בה, ונפתח לו שם פתח אחד של גן עדן, והבין, כי צורה ההיא של אדם עומדת אצלו. כי הבין, שמתוך שהיה בחייו בגן עדן, זכה להקבר לאחר פטירתו בפתחו של ג\"ע."],[2,"ותא חזי כל מאן וכו':","ובוא וראה כל מי שמסתכל בצורתו של אדם לא ימלט לעולם ממיתה, אלא מוכרח למות תכף, כי בשעה שאדם מסתלק מן העולם הוא רואה את אדם הראשון, ובאותו זמן מת. אבל אברהם נסתכל בו, וראה צורתו, ונתקיים. וראה אור מאיר בתוך המערה ונר אחד דולק, אז חמד אברהם מקום ההוא למשכנו, ולבו ורצונו היה תמיד במערה."],[3,"ת\"ח השתא וכו':","בוא וראה, בחכמה עשה אברהם עתה, בשעה שבקש קבר לשרה, כי כשבקש, לא בקש מיד באותה שעה המערה, ולא אמר שרוצה להפרד מהם אלא שאמר, תנו לי אחוזת קבר \u0003עמכם\u0004 ואקברה מתי מלפני. ולא הזכיר לא את עפרון ולא את המערה, ואם תאמר, שעפרון לא היה שם. אינו כן, אלא היה שם שכתוב ועפרון יושב בתוך בני חת. ואף על פי כן, לא אמר לו אברהם באותה שעה מאומה."],[4,"אלא מה דאמר וכו':","אלא מה שאמר להם, הוא כמו שכתוב, וידבר אל בני חת וגו'. ושואל, וכי יעלה על דעתך שאברהם רצה להקבר ביניהם בין הטמאים, או שרצונו היה להתחבר עמהם, עד שאמר להם תנו לי אחוזת קבר עמכם. אלא בחכמה עשה."]],[[0,"","אָמַר לוֹ, מִי שֶׁמִּסְתַּכֵּל בְּצִפְצוּפֵי הָעוֹפוֹת לָמָּה נִקְרָא נָחָשׁ? אָמַר לוֹ, שֶׁהִנֵּה מֵאוֹתוֹ הַצַּד בָּאָה, שֶׁרוּחַ טֻמְאָה שׁוֹרָה עַל הָעוֹף הַהוּא וּמוֹדִיעַ דְּבָרִים בָּעוֹלָם. וְכָל רוּחַ טֻמְאָה דְּבוּקִים בַּנָּחָשׁ וּבָאוֹת לָעוֹלָם, וְאֵין מִי שֶׁיִּנָּצֵל מִמֶּנּוּ בָּעוֹלָם, שֶׁהֲרֵי הוּא נִמְצָא עִם הַכֹּל עַד הַזְּמַן שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מִן הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ'. וְכָתוּב (זכריה ג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגוֹ'."],[1,"","רַבִּי יְהוּדָה אָמַר, אַבְרָהָם יָדַע בְּאוֹתָהּ הַמְּעָרָה סִימָן, וְלִבּוֹ וּרְצוֹנוֹ הָיוּ שָׁם, מִשּׁוּם שֶׁמִּקֹּדֶם לָכֵן נִכְנַס לְשָׁם וְרָאָה אֶת אָדָם וְחַוָּה טְמוּנִים שָׁם. וּמִנַּיִן הָיָה יוֹדֵעַ שֶׁהֵם הָיוּ? אֶלָּא רָאָה דְמוּתוֹ וְהִסְתַּכֵּל, וְנִפְתַּח לוֹ פֶּתַח אֶחָד שֶׁל גַּן עֵדֶן שָׁם, וְאוֹתָהּ דְּמוּת שֶׁל אָדָם הָיְתָה עוֹמֶדֶת אֶצְלוֹ."],[2,"","וּבֹא וּרְאֵה, כָּל מִי שֶׁמִּסְתַּכֵּל בִּדְמוּתוֹ שֶׁל אָדָם, אֵינוֹ נִצּוֹל מִמִּיתָה לְעוֹלָמִים, מִשּׁוּם שֶׁהִנֵּה בְּשָׁעָה שֶׁאָדָם מִסְתַּלֵּק מִן הָעוֹלָם, הוּא רוֹאֶה אֶת אָדָם, וּבְאוֹתוֹ הַזְּמַן מֵת. אֲבָל אַבְרָהָם הִסְתַּכֵּל בּוֹ וְרָאָה דְמוּתוֹ וְהִתְקַיֵּם, וְרָאָה הָאוֹר שֶׁמֵּאִיר בַּמְּעָרָה, וְנֵר אֶחָד דּוֹלֵק. אָז הִתְאַוָּה אַבְרָהָם לִמְדוֹרוֹ בַּמָּקוֹם הַהוּא, וְלִבּוֹ וּרְצוֹנוֹ הָיוּ תָמִיד בַּמְּעָרָה."],[3,"","בֹּא רְאֵה, כָּעֵת אַבְרָהָם עָשָׂה בְּחָכְמָה בִּזְמַן שֶׁבִּקֵּשׁ קֶבֶר לְשָׂרָה, שֶׁהֲרֵי כְּשֶׁבִּקֵּשׁ, לֹא בִקֵּשׁ אֶת הַמְּעָרָה בְּאוֹתוֹ זְמַן, וְלֹא אָמַר שֶׁרוֹצֶה לְהִפָּרֵד מֵהֶם, אֶלָּא אָמַר, תְּנוּ לִי אֲחֻזַּת קֶבֶר עִמָּכֶם וְאֶקְבְּרָה מֵתִי מִלְּפָנָי. וְאִם תֹּאמַר שֶׁעֶפְרוֹן לֹא הָיָה שָׁם - הוּא הָיָה שָׁם, שֶׁכָּתוּב וְעֶפְרוֹן יֹשֵׁב בְּתוֹךְ בְּנֵי חֵת. וְאַבְרָהָם לֹא אָמַר לוֹ בְּאוֹתָהּ שָׁעָה כְּלוּם."],[4,"","אֶלָּא מָה שֶׁאָמַר לָהֶם אָמַר, כְּמוֹ שֶׁכָּתוּב וַיְדַבֵּר אֶל בְּנֵי חֵת וְגוֹ'. וְכִי עוֹלֶה בְּדַעְתְּךְ שֶׁאַבְרָהָם רָצָה לְהִקָּבֵר בֵּינֵיהֶם בֵּין הַטְּמֵאִים, אוֹ שֶׁתְּשׁוּקָתוֹ הָיְתָה עִמָּהֶם? אֶלָּא עָשָׂה בְּחָכְמָה."]]],[["וְיַלְפִינָן אוֹרַח אַרְעָא הָכָא בְּמָּה דְעֲבַד אַבְרָהָם, דְּהָא בְּגִין דְּתִאוּבְתֵּיהּ וּרְעוּתֵיהּ הֲוָה בְּהַהִיא מְעַרְתָּא, אַף עַל גַּב דְּהֲוָה תַּמָּן, לָא בָּעָא לְמִשְׁאַל לֵיהּ מִיָּד הַהוּא רְעוּתָא דְּהֲוָה לֵיהּ בִּמְעַרְתָּא, וְשָׁאִיל בְּקַדְמִיתָא מַה דְּלָא אִצְטְרִיךְ לֵיהּ לְאִינוּן אָחֳרָנִין וְלָא לְעֶפְרוֹן.","כֵּיוָן דְּאָמְרוּ לֵיהּ קַמֵּי עֶפְרוֹן שְׁמָעֵנוּ אֲדֹנִי נְשִׂיא אֱלהִים אַתָּה בְּתוֹכֵנוּ וְגו'. מַה כְּתִיב וְעֶפְרוֹן ישֵׁב בְּתוֹךְ בְּנֵי חֵת. יָשַׁב כְּתִיב, מִשֵּׁירוּתָא דְּמִלִּין דְּאָמַר אַבְרָהָם תַּמָּן הֲוָה. כְּדֵין אָמַר שְׁמָעוּנִי וּפִגְעוּ לִי בְּעֶפְרוֹן בֶּן צֹחַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגו'. וְאִי תֵימָא בְּגִין יְקָרָא דִּילִי יַתִּיר מִנַּיְיכוּ אֲנָא עָבִיד דְּלָא רָעֵינָא בְּכוּ. בְּתוֹכְכֶם, בְּגִין לְאִתְקְבָרָא בֵּינַיְיכוּ דְּרָעֵינָא בְּכוּ בְּגִין דְּלָא אִתְפְּרַשׁ מִנַּיְיכוּ.","\u0003תּוֹסֶפְתָּא\u0004 רִבִּי יוֹסֵי בֶּן רַבִּי יְהוּדָה אָזִיל לְמֵיחֱמֵי לְרַבִּי חִיָּיא, אָמַר לֵיהּ לֵימָא מַר אִי שָׁמַע הַאי פַּרְשָׁתָּא הֵיךָ אָמְרוּ מָארֵי מַתְּנִיתָּא דְּפֵּרְשׁוּהָ בְּעִנְיָינָא דְּנִשְׁמָתָּא. אָמַר זַכָּאָה חוּלָקֵיהוֹן דְּצַּדִּיקַיָּא בְּעַלְמָא דְאָתֵּי, דְּכָךָ הִיא אוֹרַיְיתָּא בְּלִבְּהוֹן כְּמַבּוּעָא רַבָּא דְמַיָא, דְּאַף עַל גַּב דְּמַסְתִּימִין לֵיהּ, מִסְגִּיאוּתּ מַיָּיא פָּתְּחִי מַבּוּעִין דְּנָבְעִין לְכָל עֵיבַר.","תָּא שְׁמַע רַבִּי יוֹסֵי רְחִימָא אַתְּ, אֲנָא אֵימָא לָךָ בְּהַאי פָּרְשָׁתָּא, לְעוֹלָם אֵין גּוּף הָאָדָם נִכְנַס בְּחֶשְׁבּוֹן הַצַּדִּיקִים עַל יַד דּוּמָה, עַד שֶׁתַּרְאֶה הַנְּשָׁמָה פִּנְקָס סִימָנָא שֶׁנּוֹתְּנִין לָהּ הַכְּרוּבִים בַּגַּן עֵדֶן. אָמַר רַבִּי יוֹסֵי אֲנָא שְׁמַעֲנָא דְּהָא נִשְׁמָתָּא בָּתַּר דְּעַיְילַתּ תַּמָּן הִיא אָזְלַתּ לְסָלְקָא לְאַתְּרָה לְעֵילָא ולָא לְמֵיחַתּ לְתַּתָּא, אֲבָל קוֹדֶם שֶׁתַּעֲלֶה ותִּכָּנֵס נַעֲשֵׂתּ אַפַּטְרוֹפּוֹס הַגּוּף על יַד דּוּמָה וּמַרְאָה לוֹ שֶׁרָאוּי הוּא לְקַבֵּל שָׂכָר אַרְבַּע מֵאוֹתּ עוֹלָמוֹתּ.","אָמַר רַבִּי חִיָּיא הָא רַבִּי אֶלְעָזָר אָמַר, דְּהָא דוּמָה יָדַע קוֹדֶם מִשׁוּם דְּמַכְרְזֵי עֲלָהּ בְּגִנְתָּא דְעֵדֶן. אֲבָל אֲנָא כָּךָ שָׁמַעְנָא, דִּי בְּעִדָּנָא דְּיָהֲבִין (ליה פנקסא חזר על גופא לאעיל ליה בפתקא דצדיקיא על ידוי דדומה. הדא הוא דכתיב אך אם אתה לו שמעני נתתי כסף השדה קח ממני. מהו כסף השדה, דא כסופא דעלמין ארבע מאות דיהבין ליה לאחסנא).","רַב יוֹסֵף כַּד הֲוָה שָׁמַע פָּרְשָׁתָּא דָא מִמָּארֵיהוֹן דִּמְתִּיבְתָּא, הֲוָה אָמַר, מַאן דְּאִיהוּ עַפְּרָא מַאי קָא (ריקנא) זָכֵי לְהַאי. מַאן יִזְכֶּה וּמַאן יָקוּם הֲדָא הוּא דִכְתִּיב, (תהילים כ״ד:ג׳) מִי יַעֲלֶה בְּהַר יְיָ וגו'.","אָמַר רַבִּי אַבָּא תָּא חֲזֵי מַאי דִכְתִּיב ויִּשְׁמַע אַבְרָהָם אֶל עֶפְּרוֹן ויִּשְׁקֹל אַבְרָהָם לְעֶפְּרוֹן אֶתּ הַכֶּסֶף, דָּא הוּא כִּסוּפָּא רַבָּתָּא דְּאִינוּן עָלְמִין וְכִסוּפִּין. אַרְבַּע מֵאוֹתּ שֶׁקֶל כֶּסֶף, אַרְבַּע מֵאוֹתּ עוֹלָמוֹתּ וְהֲנָאוֹתּ וכִסוּפִּין. עוֹבֵר לַסוֹחֵר. רַב נַחְמָן אָמַר שֶׁיַּעֲבוֹר כָּל שַׁעֲרֵי שָׁמַיִם וירוּשָׁלַיִם שֶׁל מַעְלָה ואֵין מוֹחֶה בְּיָדָהּ.","תָּא חֲזֵי מַה כְּתִּיב ואַחֲרֵי כֵן קָבַר אַבְרָהָם אֶתּ שָׂרָה אִשְׁתּוֹ, ונִמְנֶה עִם שְׁאָר הַצַּדִּיקִים בַּחֲבוּרָתָּם מִפִּתְּקָא דִּמְמַנָּא עַל יְדוֹי דְדוּמָה. אָמַר רַבִּי יִצְּחָק הָכִי גְמִירְנָא כָּל אִינוּן דִּכְתִּיבִין בִּידוֹי דְדוּמָה וּמְמַנָּן עַל יְדוֹי יְקוּמוּן לְזִמְנָא דְּזָמִּין לְאַחֲיָא דָיְירֵי עַפְּרָא. וַוי לְהוֹן לְרַשִׁיעַיָּא דְּלָא כְתִּיבִין על יְדוֹי בְּפִּתְּקָא, שֶׁיֹּאבְדוּ בַּגֵּיהִנָּם לְעָלְמִין, וְעַל דָּא נְאֱמַר (דניאל י״ב:א׳) וּבָעֵתּ הַהִיא יִמָּלֵט עִמְךָ כָּל הַנִּמְצָּא כָּתּוּב בַּסֵפֶּר, (עד כאן תוספתא)","רַבִּי אֶלְעָזָר אָמַר בְּשַׁעְתָּא דְּעָאל אַבְרָהָם בִּמְעַרְתָּא הֵיךְ עָאל. בְּגִין דְּהֲוָה רָהִיט אֲבַתְרֵיהּ דְּהַהוּא עֶגְלָא דִּכְתִיב וְאֶל הַבָּקָר רָץ אַבְרָהָם וְגו'. וְהַהוּא בֶּן בָּקָר עָרַק עַד הַהוּא מְעַרְתָּא וְעָאל אֲבַתְרִיהּ וְחָמָא מַה דְּחָמָא.","תוּ בְּגִין דְּאִיהוּ צַלֵּי כָּל יוֹמָא וְיוֹמָא וְהֲוָה נָפִיק עַד הַהוּא חֲקַל דְּהֲוָה סָלִיק רֵיחִין עִלָּאִין, וְחָמָא נְהוֹרָא דְּנָפִיק מִגּוֹ מְעַרְתָּא וְצַלֵּי תַּמָּן, וְתַמָּן מַלִּיל עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ בָּעָא לֵיהּ, דְּתִאוּבְתֵּיהּ הֲוָה בְּהַהוּא אֲתַר תָּדִיר.","וְאִי תֵימָא אִי הָכִי אַמַּאי לָא בָעָא לָהּ עַד הַשְׁתָּא, בְּגִין דְּלָא יִשְׁגְּחוּן עֲלֵיהּ הוֹאִיל וְלָא אִצְטְרִיךְ לֵיהּ. הַשְׁתָּא דְּאִצְטְרִיךְ לֵיהּ, אָמַר, הָא שַׁעְתָּא לְמִתְבַּע לֵיהּ.","תָּא חֲזֵי, אִי עֶפְרוֹן הֲוָה חָמֵי בִּמְעַרְתָּא מַה דְּהֲוָה חָמֵי אַבְרָהָם בָּהּ, לָא יַזְבִּין לָהּ לְעָלְמִין. אֶלָּא וַדַּאי לָא חָמָא בָהּ וְלא כְלוּם, דְּהָא לֵית מִלָּה אִתְגַּלְּיָא אֶלָּא לְמָארִיהּ, וּבְגִין כָּךְ לְאַבְרָהָם אִתְגַּלְּיָיא וְלָא לְעֶפְרוֹן. לְאַבְרָהָם אִתְגַלְּיָיא דִּילֵיהּ הֲוָה, לְעֶפְרוֹן לָא הֲוַת אִתְגַּלְּיָא לֵיהּ דְּלָא הֲוָה לֵיהּ חוּלָקָא בֵּיהּ. וּבְגִין כָּךְ לָא אִתְגְּלִי לְעֶפְרוֹן כְּלוּם, וְלָא הֲוָה חָמֵי אֶלָּא חֲשׁוֹכָא, וְעַל דָּא זַבִּין לָהּ."],[[0,"וילפינן אורח ארעא וכו':","ואנו למדים דרך ארץ, ממה שעשה אברהם, כי משום שתשוקתו ורצונו היה באותה המערה, אע\"פ שעפרון היה שם, לא רצה לבקש ממנו מיד, ולגלות לו את הרצון שהיה לו במערה, ושאל תחילה מה שלא צריך לו, ולאחרים ולא לעפרון. אלא שאמר לבני חת, תנו לי אחוזת קבר עמכם וגו'."],[1,"כיון דאמרו ליה וכו':","כיון שבני חת אמרו לו בפני עפרון, שמענו אדני נשיא אלקים אתה בתוכנו וגו'. מה כתוב, ועפרון יושב בתוך בני חת, ישב כתוב ביוד קמוצה, כי לא כתוב עם נקודות, ואפשר לנקדו עם קמץ, שזה יורה שעוד בתחילת הדיבורים שאמר אברהם כבר היה שם עפרון."],[1,"כדין אמר וכו':","אז אמר שמעוני ופגעו לי בעפרון בן צחר וגו', ואם תאמרו משום שכבודי מרובה מכבודכם אני עושה זה, לבקש מערת המכפלה מעפרון, כי איני חפץ בכם. לא כן, \u0003בתוככם,\u0004 שאמר יתננה לי בתוככם וגו' כדי להקבר בתוככם כונתי, כי אני חפץ בכם, ואני עושה זאת, כדי שלא להפרד מכם."],[2,"רבי יוסי ברבי יהודה וכו':","ריבר\"י, היה הולך לראות את ר' חייא, אמר לו יאמר אדוני, אם שמע איך אמרו בעלי המשנה פרשה הזו, שפרשוה בעניני הנשמה. אשר אברהם ה\"ס הנשמה, ושרה הגוף. אמר, אשרי חלקם של הצדיקים בעולם הבא, שכך הוא התורה בלבם כמו מעיין גדול, שאע\"פ שסותמים אותו, מרוב המים יפרצו ויפתחו מעינות הנובעים לכל עבר."],[3,"תא שמע ר' יוסי וכו':","בוא ושמע ר' יוסי, חביב אתה, אני אומר לך בפרשה הזו. לעולם אין גוף האדם נכנס אחר פטירתו בחשבון הצדיקים על יד דומה, עד שתראה לו הנשמה מכתב לסימן, שהכרובים נותנים לה בגן עדן."],[3,"אמר ר' יוסי וכו':","אמר ר\"י, אני שמעתי, כי הנשמה אחר שנכנסה שם לגן עדן, היא הולכת לעלות למקומה למעלה, לבינה, ולא לרדת למטה, למלכות, אבל קודם שתעלה ותכנס למקומה, נעשית אפטרופוס הגוף על יד דומה, ומראה לו, לדומה, שהגוף ראוי לקבל שכר, ארבע מאות עולמות."],[4,"אמר ר' חייא וכו':","אר\"ח, הרי ר' אלעזר אמר, כי דומה יודע זה שהגוף ראוי לשכר ת' עולמות קודם שהגוף מראה לו, משום שמכריזים על זה בגן עדן, אבל אני כך שמעתי, שבעת שנותנים להנשמה המכתב לסימן, חוזרת אז על הגוף להכניסו בחשבון הצדיקים על ידיו של דומה, וזהו שכתוב, אך אם אתה לו שמעני נתתי כסף השדה קח ממני. מהו כסף השדה, הוא \u0003הכוסף\u0004 והחמדה לארבע מאות עולמות שנותנים לו להגוף לרשת."],[4,"","ביאור הדברים. כי נתבאר לעיל (דף ד' אות י\"א ד\"ה פירוש) ענין \u0003ודומה קאים ונטיל בחושבנא\u0004 שאלו הצדיקים שזכו לקבל בחייהם אלו המוחין המושפעים על המסך שבקו אמצעי, שנאמר עליהם \u0003קוץ קוציתא,\u0004 מקבל דומה את המסך הזה הנקרא חשבון, ומטהר עמו את גופו של צדיק אחר פטירתו ומכשירו לתחיה, ע\"ש. וחולקים בזה ר' יוסי ור' חייא, ר' יוסי סבר, שקומת האור הוא עיקר המטהר את הגוף, וז\"ש \u0003אנא שמענא\u0004 וכו' \u0003על יד דומה ומראה לו שראוי הוא לקבל שכר ארבע מאות עולמות,\u0004 דהיינו שהגוף זכה בחייו לקבל אלו המוחין הנמשכים מקו אמצעי, הנק' ת' עלמין דכסופין. ואז מקבל דומה את הגוף, ומכשירו לתחיה. ור' חייא סבר שהמסך הנק' חשבון, גם נקרא \u0003פנקס,\u0004 הוא העיקר המטהר את הגוף, וע\"כ כיון שהנשמה זכתה בו כבר היא מתחלת לישא וליתן עם דומה, בשביל הגוף. וז\"ש \u0003אבל אנא כך שמענא\u0004 וכו' \u0003הה\"ד נתתי כסף השדה וגו'.\u0004 כי נתתי פירושו שהכסף כבר מוכן, כמו שפירש\"י. ורומז על המסך, כי כשיש לו מסך, כבר הקומה מוכנת לצאת עליו מאליו (כנ\"ל בכמה מקומות). וסוד הקומה היוצאת על המסך ה\"ס ת' עלמין דכסופין. \u0003מהו כסף השדה, דא כסופא דעלמין ארבע מאות\u0004 וכו', אבל אין צורך לדבר עם עפרון מענין הקומה עצמה, כמ\"ש ר' יוסי, כי כיון שהשיג המסך, כבר מכריזים עליו בגן עדן שהוא צדיק, וראוי לקבל את הקומה, שה\"ס ת' עלמין דכסופין. וז\"ש ר' חייא משום דמכרזי עלה בגנתא דעדן וכו'."],[5,"רב יוסף כד וכו':","ר\"י כששמע פרשה זו מבוארת מבעלי הישיבה, היה אמר, מי שהוא עפר יוכל לזכות לכל זה, היינו לת' עלמין דכסופין, מי יזכה ומי יקום, זה הוא שכתוב מי יעלה בהר ה' ומי יקים במקום קדשו."],[6,"אמר ר' אבא וכו':","בוא וראה, מה שכתוב, וישמע אברהם אל עפרון וישקול אברהם לעפרון את הכסף וגו' זהו כוסף הגדול אחר אלו העולמות החמודים. \u0003ארבע מאות שקל כסף,\u0004 פירושו, ארבע מאות עולמות של הנאות ותשוקות. \u0003עובר לסוחר,\u0004 רב נחמן אמר, שיעבור כל שערי שמים וירושלים של מעלה, ואין מוחה בידו. כלומר שהזוכה לאלו המוחין ד \u0003ת'\u0004 עלמין דכסופין נמצא שלם בכל המדרגות של שערי שמים וירושלים של מעלה, ואין מי שיקטרג עליו שם. ומה שלא אמר גם \u0003בירושלים של מטה.\u0004 הוא משום שסוד ארבע מאות הללו, הם חו\"ב תו\"מ דאורות, שהם מלובשים בכח\"ב ות\"ת דכלים, וחסר לו כתר דאורות משום שחסר לו מלכות מהכלים, כנודע מערך ההפכי שבין האורות לכלים. והמלכות דכלים ה\"ס \u0003ירושלים של מטה,\u0004 כי ירושלים של מעלה ה\"ס בינה, וירושלים של מטה ה\"ס מלכות. והיא לא תתוקן אלא בגמר התקון. ולפיכך מטרם זה אין יותר מארבע מאות שקל כסף, להורות שחסר שם כתר מאורות ומלכות מכלים, וע\"כ אומר בירושלים של מעלה, ואינו אומר בירושלים של מטה. אבל עם כל זה הארתם של אלו ארבע מאות עוברת ומאירה בחלקה גם אל המלכות. וזה סוד מ\"ש עובר \u0003לסוחר,\u0004 כי המלכות נקראת \u0003סוחר,\u0004 בסו\"ה היתה כאניות סוחר וגו'. ועל ידי הארה זו העוברת אליה, נעשית מוכשרת לאט לאט לקבל שלמותה בגמר התקין."],[7,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב, ואחרי כן קבר אברהם את שרה אשתו, דהיינו הגוף, ונמנה בכתב הממונה, עם שאר הצדיקים בחברתם, על ידי דומה שה\"ס החשבון המבואר (לעיל דף ד' אות י\"א ד\"ה פירוש ע\"ש) אמר ר' יצחק כך למדתי, כל אלו הגופים הכתובים בידיו של דומה ונפקדים על ידו, יקומו לתחיה בזמן שעתיד הקב\"ה להחיות שוכני העפר. ווי להם לרשעים שאינם כתובים על ידו בכתב, שהם יאבדו בגיהנם לעולם. ועל זה נאמר, ובעת ההוא ימלט עמך כל הנמצא כתוב בספר. (ע\"כ התוספתא)"],[8,"רבי אלעזר וכו':","רא\"א, בשעה שנכנס אברהם במערה, איך נכנס. כלומר, מה היה הסבה שנכנס אל המערה. ואומר, כי היה רץ אחר אותו העגל, שכתוב בו ואל הבקר רץ אברהם וגו', ובן בקר ההוא ברח עד אותה המערה, ואברהם נכנס אחריו להמערה, וראה מה שראה."],[9,"תו, בגין דאיהו וכו':","עוד, סבה היתה, כי הוא היה מתפלל בכל יום ויום. והיה יוצא עד אותו השדה שהיה מעלה ריחות עליונים, וראה אור יוצא מתוך המערה, והתפלל שם. ושם דבר עמו הקב\"ה. ועל כן חפץ בה, בהמערה, ותשוקתו היתה באותו מקום תמיד."],[10,"ואי תימא וכו':","ואם תאמר, אם כן, למה לא בקש לקנותה עד עתה. ואומר, כיון שלא היה צריך אותה, היה מפחד שלא יסתכלו אחריו, ויבינו את השתוקקותו וחשיבותה של המערה, ואז היו מרבים את המחיר, או שהיו ממאנים למכרה לו לגמרי. עתה שהיה נצרך אליה, אמר, כבר הגיעה השעה לבקש אותה."],[11,"ת\"ח אי עפרון וכו':","בוא וראה, אם עפרון היה רואה בהמערה מה שהיה רואה בה אברהם, לא היה מוכר אותה לעולם. אלא ודאי שעפרון לא ראה בה מאומה, כי אין דבר מתגלה זולת לבעליו, ומשום זה רק לאברהם נתגלה ולא לעפרון, לאברהם נתגלה, כי שלו היתה, ולעפרון לא נתגלה, משום שלא היה לו חלק בה. וע\"כ לא נגלה לעפרון מאומה בהמערה, ולא היה רואה בה אלא חשך, ועל כן מכר אותה."]],[[0,"","וְלָמַדְנוּ כָּאן דֶּרֶךְ אֶרֶץ בְּמַה שֶּׁעָשָׂה אַבְרָהָם, שֶׁהֲרֵי מִשּׁוּם שֶׁתְּשׁוּקָתוֹ וּרְצוֹנוֹ הָיוּ בַּמְּעָרָה הַהִיא - אַף עַל גַּב שֶׁהָיָה שָׁם, לֹא רָצָה לְבַקֵּשׁ אוֹתוֹ מִיָּד אוֹתוֹ הָרָצוֹן שֶׁהָיָה לוֹ בַּמְּעָרָה, וּבִקֵּשׁ בַּתְּחִלָּה מַה שֶּׁלֹּא צָרִיךְ לְאוֹתָם אֲחֵרִים וְלֹא לְעֶפְרוֹן."],[1,"","כֵּיוָן שֶׁאָמְרוּ לוֹ לִפְנֵי עֶפְרוֹן, שְׁמָעֵנוּ אֲדנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ וְגוֹ' - מַה כָּתוּב? וְעֶפְרוֹן יֹשֵׁב בְּתוֹךְ בְּנֵי חֵת. כָּתוּב יָשַׁב. מֵרֵאשִׁית הַדְּבָרִים שֶׁאָמַר אַבְרָהָם שָׁם הָיָה. אָז אָמַר, שְׁמָעוּנִי וּפִגְעוּ לִי בְּעֶפְרוֹן בֶּן צֹחַר, וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגוֹ'. וְאִם תֹּאמַר בִּשְׁבִיל כְּבוֹדִי, יוֹתֵר מִכֶּם אֲנִי עוֹשֶׂה, שֶׁלֹּא רָצִיתִי בָכֶם. בְּתוֹכֲכֶם - כְּדֵי לְהִקָּבֵר בֵּינֵיכֶם, שֶׁרָצִיתִי בָכֶם, כְּדֵי שֶׁלֹּא אֶפָּרֵד מִכֶּם."],[2,"","רַבִּי יוֹסֵי בֶּן רַבִּי יְהוּדָה הָלַךְ לִרְאוֹת אֶת רַבִּי חִיָּיא. אָמַר לוֹ, יֹאמַר מַר אִם שָׁמַע אֶת הַפָּרָשָׁה הַזּוֹ, אֵיךְ אָמְרוּ בַּעֲלֵי הַבָּרַיְתָא שֶׁפֵּרְשׁוּהָ בְּעִנְיַן הַנְּשָׁמָה. אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַבָּא, שֶׁכָּךְ הַתּוֹרָה הִיא בְּלִבָּם כְּמַעְיָן גָּדוֹל שֶׁל מַיִם, שֶׁאַף עַל גַּב שֶׁסּוֹתְמִים אוֹתוֹ - מֵרֹב הַמַּיִם פּוֹתְחִים מַעְיָנוֹת שֶׁנּוֹבְעִים לְכָל עֵבֶר."],[3,"","בֹּא תִשְׁמַע, רַבִּי יוֹסֵי, אָהוּב אַתָּה. אֲנִי אֹמַר לְךְ בַּפָּרָשָׁה הַזּוֹ, לְעוֹלָם אֵין גּוּף הָאָדָם נִכְנָס בְּחֶשְׁבּוֹן הַצַּדִּיקִים עַל יַד דּוּמָה, עַד שֶׁתַּרְאֶה הַנְּשָׁמָה פִּנְקָס סִימָן שֶׁנּוֹתְנִים לָהּ הַכְּרוּבִים בְּגַן עֵדֶן. אָמַר רַבִּי יוֹסֵי, אֲנִי שָׁמַעְתִּי שֶׁהִנֵּה הַנְּשָׁמָה, אַחַר שֶׁנִּכְנֶסֶת לְשָׁם, הִיא הוֹלֶכֶת לַעֲלוֹת לִמְקוֹמָהּ לְמַעְלָה, וְלֹא לָרֶדֶת לְמַטָּה. אֲבָל קֹדֶם שֶׁתַּעֲלֶה וְתִכָּנֵס, נַעֲשֵׂית אֶפּוֹטְרוֹפּוֹס הַגּוּף עַל יַד דּוּמָה, וּמַרְאָה לוֹ שֶׁרָאוּי הוּא לְקַבֵּל שָׂכָר אַרְבַּע מֵאוֹת עוֹלָמוֹת."],[4,"","אָמַר רַבִּי חִיָּיא, הִנֵּה רַבִּי אֶלְעָזָר אָמַר, שֶׁהֲרֵי דּוּמָה יוֹדֵעַ קֹדֶם, מִשּׁוּם שֶׁמַּכְרִיזִים עָלֶיהָ בְּגַן עֵדֶן. אֲבָל אֲנִי כָּךְ שָׁמַעְתִּי - שֶׁבִּזְמַן שֶׁנּוֹתְנִים לָהּ פִּנְקָס, חוֹזֶרֶת עַל הַגּוּף לְהַכְנִיסוֹ בַּפֶּתֶק שֶׁל הַצַּדִּיקִים עַל יְדֵי דוּמָה. זֶהוּ שֶׁכָּתוּב אַךְ אִם אַתָּה לוּ שְׁמָעֵנִי נָתַתִּי כֶּסֶף הַשָּׂדֶה קַח מִמֶּנִּי. מַה זֶּה כֶּסֶף הַשָּׂדֶה? זֶה הַכִּסּוּף שֶׁל אַרְבַּע מֵאוֹת הָעוֹלָמוֹת שֶׁנּוֹתְנִים לוֹ לִירֻשָּׁה."],[5,"","כְּשֶׁרַב יוֹסֵף הָיָה שׁוֹמֵעַ הַפָּרָשָׁה הַזּוֹ מֵרָאשֵׁי הַיְשִׁיבָה, הָיָה אוֹמֵר: מִי שֶׁהוּא עָפָר, מַה הוּא (ריק) זוֹכֶה לָזֶה? מִי יִזְכֶּה וּמִי יָקוּם? זֶהוּ שֶׁכָּתוּב (תהלים כד) מִי יַעֲלֶה בְּהַר ה' וְגוֹ'."],[6,"","אָמַר רַבִּי אַבָּא, בּא רְאֵה מַה שֶּׁכָּתוּב, וַיִּשְׁמַע אַבְרָהָם אֶל עֶפְרוֹן וַיִּשְׁקֹל אַבְרָהָם לְעֶפְרֹן אֶת הַכֶּסֶף. זֶהוּ הַכִּסּוּף הַגָּדוֹל שֶׁהֵם עוֹלָמוֹת וְכִסּוּפִים. אַרְבַּע מֵאוֹת שֶׁקֶל כֶּסֶף - אַרְבַּע מֵאוֹת עוֹלָמוֹת וַהֲנָאוֹת וְכִסּוּפִים. עֹבֵר לַסֹּחֵר - רַב נַחְמָן אָמַר, שֶׁיַּעֲבֹר כָּל שַׁעֲרֵי שָׁמַיִם וִירוּשָׁלַיִם שֶׁל מַעְלָה, וְאֵין מוֹחֶה בְיָדוֹ."],[7,"","בֹּא רְאֵה מַה כָּתוּב, וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ. וְנִמְנָה עִם שְׁאָר הַצַּדִּיקִים בַּחֲבוּרָתָם מִפֶּתֶק שֶׁל הַמְמֻנֶּה עַל יְדֵי דוּמָה. אָמַר רַבִּי יִצְחָק, כָּךְ לָמַדְנוּ, כָּל אוֹתָם שֶׁכְּתוּבִים בִּידֵי דוּמָה וּמְמֻנִּים עַל יָדוֹ, יָקוּמוּ לִזְמַן שֶׁעָתִיד לְהַחֲיוֹת שׁוֹכְנֵי עָפָר. אוֹי לָרְשָׁעִים שֶׁאֵינָם כְּתוּבִים עַל יָדוֹ בַּפֶּתֶק, שֶׁיֹּאבְדוּ בַּגֵּיהִנֹּם לְעוֹלָמִים, וְעַל זֶה נֶאֱמַר (דניאל יב) וּבָעֵת הַהִיא יִמָּלֵט עַמְּךְ כָּל הַנִּמְצָא כָּתוּב בַּסֵּפֶר. עד כאן תוספתא"],[8,"","רַבִּי אֶלְעָזָר אָמַר, בְּשָׁעָה שֶׁנִּכְנַס אַבְרָהָם לַמְּעָרָה, אֵיךְ נִכְנַס? מִשּׁוּם שֶׁהָיָה רָץ אַחַר אוֹתוֹ הָעֵגֶל, שֶׁכָּתוּב וְאֶל הַבָּקָר רָץ אַבְרָהָם וְגוֹ', וְאוֹתוֹ בֶּן בָּקָר בָּרַח עַד אוֹתָהּ הַמְּעָרָה, וְנִכְנַס אַחֲרָיו, וְרָאָה מַה שֶּׁרָאָה."],[9,"","עוֹד, מִשּׁוּם שֶׁהוּא הִתְפַּלֵּל כָּל יוֹם וָיוֹם, וְהָיָה יוֹצֵא עַד אוֹתָהּ הַשָּׂדֶה שֶׁהָיְתָה מַעֲלָה רֵיחוֹת עֶלְיוֹנִים, וְרָאָה הָאוֹר שֶׁיּוֹצֵא מִתּוֹךְ הַמְּעָרָה וְהִתְפַּלֵּל שָׁם, וְשָׁם דִּבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ רָצָה אוֹתָהּ, שֶׁתְּשׁוּקָתוֹ הָיְתָה תָמִיד בְּאוֹתוֹ הַמָּקוֹם."],[10,"","וְאִם תֹּאמַר, אִם כָּךְ, לָמָּה לֹא רָצָה אוֹתָהּ עַד עַכְשָׁו? כְּדֵי שֶׁלֹּא יַבְחִינוּ בוֹ, הוֹאִיל וְלֹא צָרִיךְ אוֹתָהּ. כָּעֵת שֶׁהִצְטָרֵךְ אוֹתָהּ, אָמַר, הִנֵּה הַשָּׁעָה לְבַקֵּשׁ אוֹתָהּ."],[11,"","בֹּא רְאֵה, אִם עֶפְרוֹן הָיָה רוֹאֶה בַּמְּעָרָה מַה שֶּׁרָאָה בָּהּ אַבְרָהָם, לֹא הָיָה מוֹכֵר אוֹתָהּ לְעוֹלָמִים, אֶלָּא וַדַּאי לֹא רָאָה בָּהּ וְלֹא כְלוּם, שֶׁהֲרֵי אֵין הַדָּבָר נִגְלֶה אֶלָּא לִבְעָלָיו, וּמִשּׁוּם כָּךְ לְאַבְרָהָם הִתְגַּלְּתָה וְלֹא לְעֶפְרוֹן. לְאַבְרָהָם הִתְגַּלְּתָה - שֶׁלּוֹ הָיְתָה. לְעֶפְרוֹן לֹא הָיְתָה מִתְגַּלָּה - שֶׁלֹּא הָיָה לוֹ בָּהּ חֵלֶק. וּמִשּׁוּם כָּךְ לֹא הִתְגַּלָּה לְעֶפְרוֹן כְּלוּם, וְלֹא הָיָה רוֹאֶה אֶלָּא חֲשֵׁכָה, וְעַל כֵּן מָכַר אוֹתָהּ."]]],[["וּמַה דְּלָא תָּבַע אַבְרָהָם בְּקַדְמִיתָא דְּיַזְבִּין לֵיהּ זָבִין, דְּהָא אַבְרָהָם לא קָאָמַר אֶלָּא וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגו'. בְּכֶסֶף מָלֵא יִתְּנֶנָּה לִי וְגו', וְאִיהוּ אָמַר הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ לְךָ נְתַתִּיהָ וְגו'. בְּגִין דְּכֹלָּא הֲוָה מָאִיס עֲלֵיהּ דְּעֶפְרוֹן דְּלָא יָדַע מַה הִיא.","וְתָּא חֲזֵי, כַּד עָאל אַבְרָהָם בִּמְעַרְתָּא בְּקַדְמִיתָא, חָמָא תַּמָּן נְהוֹרָא, וְאִתְרְמֵי עַפְרָא קַמֵּיהּ, וְאִתְגְּלִי לֵיהּ תְּרִין קִבְרִין אַדְהָכִי אִסְתַּלַּק אָדָם בִּדִיוּקְנֵיהּ וְחָמָא לֵיהּ לְאַבְרָהָם וְחַיֵּיךְ, וּבֵיהּ (הוה) יָדַע אַבְרָהָם דְּתַמָּן (הוה) הוּא זַמִּין לְאִתְקְבָרָא.","אָמַר לֵיהּ, אַבְרָהָם, בְּמָטוּ מִינָךְ, קוּסְטְרָא קְטִיר אִית הָכָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא טְמָרַנִּי הָכָא וּמֵהַהוּא זִמְנָא עַד הַשְׁתָּא אִתְטַמַּרְנָא כְּגִילְדָא דְּקִירְטָא עַד דַּאֲתִית אַנְתְּ בְּעַלְמָא, הַשְׁתָּא מִכָּאן וָאֵילָךְ הָא קִיּוּמָא לִי וּלְעַלְמָא הֲוָה בְּגִינָךְ.","חָמֵי מַה כְּתִיב וַיָּקָם הַשָּׂדֶה וְהַמְּעָרָה אֲשֶׁר בּוֹ, קִימָה מַמָּשׁ הֲוָה לֵיהּ מַה דְּלָא הֲוָה לֵיהּ עַד הַשְׁתָּא. רַבִּי אַבָּא אָמַר וַיָּקָם הַשָּׂדֶה, וַדַּאי קִימָה מַמָּשׁ דְּקָם וְאִסְתַּלַּק קַמֵּיהּ דְּאַבְרָהָם בְּגִין דְּעַד הַשְׁתָּא לָא אִתְחֲזֵי תַּמָּן כְּלוּם, וְהַשְׁתָּא מַה דְּהֲוָה טָמִיר קָם וְאִסְתַּלִּיק וּכְדֵין קָם כֹּלָּא בְּנִמּוּסוֹי.","אָמַר רַבִּי שִׁמְעוֹן בְּשַׁעְתָּא דְּעָאל אַבְרָהָם בִּמְעַרְתָּא וְאָעִיל שָׂרָה תַּמָּן, קָמוּ אָדָם וְחַוָּה וְלָא קַבִּילוּ לְאִתְקְבָרָא תַּמָּן, אָמְרוּ וּמַה אֲנַן בְּכִסּוּפָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא עַלְמָא בְּגִין הַהוּא חוֹבָא דְּגָרִימְנָא וְהַשְׁתָּא יִתּוֹסַף לָן כִּסּוּפָא אָחֳרָא מִקַּמֵּי עוֹבָדִין טָבִין דִּבְכוּ.","אָמַר אַבְרָהָם הָא אֲנָא זַמִּין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּגִינָךְ דְּלָא תִכְסִיף קַמֵּיהּ לְעָלְמִין. מִיָּד וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ, מַאי וְאַחֲרֵי כֵן. בָּתַר דְּקַבִּיל אַבְרָהָם עֲלֵיהּ מִלָּה דָא."],[[0,"ומה דלא תבע וכו':","וגם מה שלא בקש אברהם מתחילה שימכור לו, מכר לו, כי אברהם לא אמר אלא ויתן לי את מערת המכפלה וגו' והשדה לא הזכיר, ועפרון אמר, \u0003השדה\u0004 נתתי לך והמערה אשר בו לך נתתיה. והוא משום שהכל היה מאוס על עפרון, כי לא ידע מה הוא. ואפילו השדה, שבו היתה המערה, היה מאוס עליו. וע\"כ מכר גם את השדה, אע\"פ שלא בקשו אברהם."],[1,"ותא חזי כד וכו':","ובוא וראה, כשנכנס אברהם לתוך המערה בראשונה, ראה שם אור, והושלך לפניו העפר, ונתגלו לו שני קברים, בין כה וכה, עמד אדם מקברו, בצורתו, וראה את אברהם, ושחק. ובו ידע אברהם שעתיד להקבר שם."],[2,"א\"ל אברהם וכו':","אמר לו אברהם, בבקשה ממך, האם טירה בלתי מקורה כאן. כלומר, שהיה תמה, כי במערת מכפלה, שפירושו מערה לפנים ממערה, מחויב להיות חשך גמור, והוא ראה שם אור כמו בבית פתוח מלמעלה בלי גג. קוסטרא פירושו טירה, דהיינו ארמון או חצר. קטיר, פירושו בלתי מקורה בגג. כמ\"ש (במדות פ\"ב) על הכתוב חצרות קטורות, אין קטורות אלא שאינן מקורות."],[2,"א\"ל קב\"ה וכו'",": אמר לו אדם, הקב\"ה הסתירני כאן, ומאותו זמן עד עתה מסתתר אני כמין הדג שבחפירה, הנקרא גילדא, שיש מין דגים הנקראים \u0003גילדנא\u0004 דבי גילי (ברכות מד:) המסתתרים ויושבים תמיד בחפירות בתוך האשפה שבים. \u0003קירטא,\u0004 בלשון יוני, פירושו חפירה תחת הארץ. עד שאתה באת לעולם, עתה, מכאן ואילך, כבר יש קיום לי ולעולם בשבילך. פירוש. עד שבא אברהם היה אדם והעולם, מחוסרי השלמות, ועל כן היה צריך להסתיר את עצמו שלא יתאחזו בו הקליפות. אבל כשבא אברהם לעולם, תיקן אותו, ואת העולם, ואינו צריך עוד להסתיר את עצמו. וז\"ש מכאן ואילך הא קיומא לי ולעלמא בנינך."],[3,"חמי מה כתיב וכו':","ראה מה שכתוב, ויקם השדה והמערה אשר בו, קימה ממש היה לו להשדה, מה שלא היה לו עד עתה. כלומר, קימה הוא לשון חשיבות, כי בזה שעבר לרשות אברהם קנה השדה חשיבות, וע\"כ כתוב בו ויקם."],[3,"ר' אבא אמר וכו':","רא\"א, ויקם השדה, ודאי פירושו, קימה ממש, שהשדה קם ונתעלה ביד אברהם, כי עד עתה לא נראה שם מאומה, ועתה ביד אברהם, מה שהיה נסתר קם ונתעלה, ואז קם הכל כמשפטו. כמו שצריך להיות."],[4,"אמר ר' שמעון וכו':","בשעה שאברהם נכנס במערה, והביא את שרה שמה, קמו אדם וחוה, ולא רצו להיות קבורים שמה. אמרו, המעט לנו, שאנו בבושה באותו העולם לפני הקב\"ה, מחמת אותו העון שגרמנו, ועתה יהיה נוסף לנו בושה שניה, שנבוש מפני המעשים טובים שלכם."],[5,"אמר אברהם וכו':","הנה אני מוכן להתפלל לפני הקב\"ה עליך, שלא תבוש לפניו לעולם. דהיינו שימחול לו העון לגמרי. מיד, ואחרי כן קבר אבררם את שרה אשתו. מהו ואחרי כן, שאומר הכתוב, היינו, אחר שקבל עליו אברהם דבר הזה. להתפלל על אדם, כנ\"ל."]],[[0,"","וּמַה שֶּׁלֹּא בִקֵּשׁ אַבְרָהָם בָּרִאשׁוֹנָה שֶׁיִּמְכֹּר לוֹ מָכַר, שֶׁהֲרֵי אַבְרָהָם לֹא אָמַר אֶלָּא - וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגוֹ', בְּכֶסֶף מָלֵא יִתְּנֶנָּה לִּי וְגוֹ'. וְהוּא אָמַר, הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ לְךְ נְתַתִּיהָ וְגוֹ'. מִשּׁוּם שֶׁהַכֹּל הָיָה מָאוּס עַל עֶפְרוֹן, שֶׁלֹּא יָדַע מַה הִיא."],[1,"","וּבֹא וּרְאֵה, כְּשֶׁנִּכְנַס אַבְרָהָם בַּתְּחִלָּה לַמְּעָרָה, רָאָה שָׁם אוֹר, וְנִזְרַק לְפָנָיו עָפָר, וְהִתְגַּלּוּ לוֹ שְׁנֵי קְבָרִים. בֵּינְתַיִם עָלָה אָדָם בִּדְמוּתוֹ, וְרָאָה אֶת אַבְרָהָם וְחִיֵּךְ, וּבוֹ (היה) יָדַע אַבְרָהָם שֶׁשָּׁם (היה) הוּא עָתִיד לְהִקָּבֵר."],[2,"","אָמַר לוֹ אַבְרָהָם: בְּבַקָּשָׁה מִמְּךְ, הַאִם טִירָה שֶׁאֵינָהּ מְקֹרָה יֵשׁ כָּאן? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, הִטְמִין אוֹתִי כָּאן, וּמֵאוֹתוֹ הַזְּמַן עַד עַכְשָׁו נִטְמַנְתִּי כְּמוֹ דָּג בַּחֲפִירָה עַד שֶׁאַתָּה בָּאתָ לָעוֹלָם. עַכְשָׁו מִכָּאן וְאֵילָךְ הִנֵּה קִיּוּם לִי וְלָעוֹלָם יֵשׁ בִּשְׁבִילְךְ."],[3,"","רְאֵה מַה כָּתוּב - וַיָּקָם הַשָּׂדֶה וְהַמְּעָרָה אֲשֶׁר בּוֹ. מַמָּשׁ קִימָה הָיְתָה לָהּ מַה שֶּׁלֹּא הָיְתָה לָהּ עַד עַתָּה. רַבִּי אַבָּא אָמַר, וַיָּקָם הַשָּׂדֶה - וַדַּאי קִימָה מַמָּשׁ, שֶׁקָּם וְהִתְעַלָּה לִפְנֵי אַבְרָהָם, מִשּׁוּם שֶׁעַד עַכְשָׁו לֹא נִרְאָה שָׁם כְּלוּם, וְעַכְשָׁו, מַה שֶּׁהָיָה טָמוּן - קָם וְהִתְעַלָּה, וְאָז קָם הַכֹּל כְּמִשְׁפָּטוֹ."],[4,"","אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁנִּכְנַס אַבְרָהָם לַמְּעָרָה וְהִכְנִיס לְשָׁם אֶת שָׂרָה, קָמוּ אָדָם וְחַוָּה, וְלֹא קִבְּלוּ לְהִקָּבֵר שָׁם. אָמְרוּ: וּמָה אָנוּ בְּבוּשָׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ הָעוֹלָם מִשּׁוּם אוֹתוֹ הַחֵטְא שֶׁגָּרַמְנוּ, וְכָעֵת תִּתּוֹסֵף לָנוּ בּוּשָׁה אַחֶרֶת - מִפְּנֵי הַמַּעֲשִׂים טוֹבִים שֶׁבָּכֶם?"],[5,"","אָמַר אַבְרָהָם: הֲרֵינִי מְזֻמָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עֲבוּרְךְ שֶׁלֹּא תִתְבַּיֵּשׁ לְפָנָיו לְעוֹלָמִים. מִיָּד - וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ. מַה זֶּה וְאַחֲרֵי כֵן? אַחַר שֶׁקִּבֵּל עָלָיו אַבְרָהָם אֶת הַדָּבָר הַזֶּה."]]],[["אָדָם עָאל בְּדוּכְתֵּיהּ חַוָּה לָא עָאלַת, עַד דְּקָרִיב אַבְרָהָם וְאָעִיל לָהּ לְגַבֵּי אָדָם וְקַבִּיל לָהּ בְּגִינֵיהּ, הֲדָא הוּא דִכְתִיב וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ, לְשָׂרָה לָא כְּתִיב אֶלָּא אֶת שָׂרָה לְאַסְגָּאָה חַוָּה, וּכְדֵין אִתְיַישְׁבוּ בְּדוּכְתַּיְיהוּ כְּדְקָא יְאוּת, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְתָנִינָן בְּאַבְרָהָם. תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ דָּא אָדָם וְחַוָּה. אֵלֶּה הַשָּׁמַיִם וְהָאָרֶץ לֹא כְּתִיב, אֶלָּא תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ וְלֹא תּוֹלְדוֹת בַּר נָשׁ. וְאִינוּן אִתְקָיְימוּ בְּגִינֵיהּ דְּאַבְרָהָם. וּמְנָא לָן דְּאִתְקָיְימוּ בְּגִינֵיהּ דְּאַבְרָהָם. דִּכְתִיב וַיָּקָם הַשָּׂדֶה וְהַמְּעָרָה אֲשֶׁר בּוֹ לְאַבְרָהָם. וְעַד דְאָתָא אַבְרָהָם לָא אִתְקָיְימוּ אָדָם וְחַוָּה בְּדוּכְתַּיְיהוּ בְּהַהוּא עָלְמָא.","רַבִּי אֶלְעָזָר שָׁאִיל לְרִבִּי שִׁמְעוֹן אֲבוֹי, אָמַר הַאי מְעַרְתָּא לָאו אִיהוּ כָּפֵילְתָּא, דְּהָא כְּתִיב מְעָרַת הַמַּכְפֵּלָה, וּקְרָא קָרֵי לָהּ לְבָתַר מְעָרַת שְׂדֵה הַמַּכְפֵּלָה, מַכְפֵּלָה קָא קָרֵי לֵיהּ לַשָּׂדֶה.","אָמַר לֵיהּ הָכִי קָארֵי לֵיהּ מְעָרַת הַמַּכְפֵּלָה כְּמָה דְאַתְּ אָמֵר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה, אֲבָל וַדַּאי חַיֶּיךָ לָאו מְעַרְתָּא אִיהוּ מַכְפֵּלָה. וְלָאו שָׂדֶה אִקְרֵי מַכְפֵּלָה, אֶלָּא הַאי שָׂדֶה וּמְעַרְתָּא עַל שׁוּם מַכְפֵּלָה אִקְרוּן שְׂדֵה הַמַּכְפֵּלָה וַדַּאי וְלָא מְעַרְתָּא, דְּהָא מְעַרְתָּא בַּשָּׂדֶה אִיהִי, וְהַהוּא שָׂדֶה קָאִים בְּמִלָּה אָחֳרָא.","תָּא חֲזֵי, יְרוּשָׁלַ ם כָּל אַרְעָא דְיִשְׂרָאֵל אִתְכַּפַּל תְּחוֹתָהּ. וְאִיהִי קָיְימָא לְעֵילָא וְתַתָּא, כְּגַוְונָא דָא יְרוּשָׁלַם לְעֵילָא יְרוּשָׁלַ ם לְתַתָּא, אֲחִידָא לְעֵילָא וְאַחִידָא לְתַתָּא, יְרוּשָׁלַ ם לְעֵילָא אֲחִידַת בִּתְרֵין סִטְרִין לְעֵילָא וְתַתָּא (ירושלם לתתא אחידתבתרין סטרין לעילא ותתא) וּבְגִין כָּךְ כָּפֶלְתָּא הִיא.","וְעַל דָּא הַאי שָׂדֶה מֵהַהִיא כָּפֶלְתָּא אִיהוּ דְּבֵיהּ שַׁרְיָא. כְּגַוְונָא דָא כְּתִיב כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ לְעֵילָא וְתַתָּא, וּבְגִין כָּךְ שְׂדֵה הַמַּכְפֵּלָה וַדַּאי וְלָא שָׂדֶה כָּפוּל."],[[0,"אדם עאל וכו':","אדם חזר ונכנס למקומו. חוה לא חזרה ונכנסה, משום שהיא גרמה לאדם לחטא, כמ\"ש האשה אשר נתת עמדי וגו', והיתה מפחדת שאדם לא יקבלנה. עד שקרב אברהם, והכניסה אל אדם, וקיבלה בשביל אברהם. וזהו שכתוב ואחרי כן קבר את שרה אשתו, לשרה לא כתוב, אלא \u0003את\u0004 שרה והוא לרבות חוה. שאברהם החזירה אל הקבר, כנ\"ל."],[0,"וכדין אתיישבו וכו':","ואז נתיישבו אדם וחוה במקומם כראוי. וזהו שכתוב, אלה תולדות השמים והארץ בהבראם, ולמדנו, באברהם, כי בהבראם אותיות באברהם, ויורה, שבשבילו נתקיימו. תולדות השמים וארץ הם אדם וחוה. כי אלה השמים וארץ לא כתוב, אלא תולדות השמים והארץ, להורות, על אדם וחוה, שאינם תולדות של אנשים, ועליהם אומר הכתוב, שנתקיימו בשביל אברהם. דהיינו כמ\"ש לעיל. ומאין לנו, שנתקיימו בשביל אברהם. כי כתוב ויקם השדה והמערה אשר בו לאברהם. ועד שבא אברהם לא נתקיימו אדם וחוה באותו העולם. כלומר, שדורש, \u0003ויקם\u0004 הוא קיום. \u0003השדה והמערה אשר בו,\u0004 יורה על אדם וחוה אשר שם. \u0003לאברהם\u0004 בשביל אברהם. הרי שאדם וחוה נתקיימו בשביל אברהם."],[1,"ר' אלעזר שאיל לאבוי וכו':","ר\"א שאל את אביו, אמר, מערה הזו איננה מכפלה, שהרי כתוב מערת המכפלה, ואחר כך קרא אותה הכתוב, מערת שדה המכפלה, הרי שהשדה נקרא מכפלה, ולא המערה."],[2,"א\"ל הכי וכו':","אמר לו ר\"ש, כן קוראים אותה מערת המכפלה, כמו שאתה אומר, ויתן לי את מערת המכפלה, אבל ודאי, חייך, לא המערה היא מכפלה, ואין השדה נקרא מכפלה, אלא שדה הזה והמערה, נקראים יחד על שם מכפלה. אבל, שדה המכפלה ודאי, ולא המערה, כלומר, רק השדה נושא את השם מכפלה ולא המערה, כי המערה בשדה היא, והשדה הוא בדבר אחר, כמ\"ש לפנינו."],[3,"תא חזי ירושלם וכו':","בוא וראה, ירושלים, כל ארץ ישראל מקופלת תחתיה, שה\"ס המלכות, והיא נמצאת למעלה ולמטה. באופן זה: יש ירושלים למעלה שהוא בינה, ויש ירושלים למטה, שהיא מלכות, כי נאחזת למעלה ונאחזת למטה. ונמצאת ירושלים של מעלה אחוזה בשני צדדים למעלה ולמטה וירושלים של מטה אחוזה בשני צדדים למעלה ולמטה. וע\"כ היא כפולה. פירוש. ירושלים של מעלה היא בינה, וירושלים של מטה היא מלכות. ונודע שבסוד שיתוף מדת הרחמים בדין נכללו זה בזה, ומתוך התכללות הזה נעשו ד' בחינות, שיש בינה ומלכות בבינה, ויש בינה ומלכות במלכות. ונמצא שמדת המלכות היא כפולה, כי יש מלכות בבינה ויש מלכות במלכות."],[4,"ועל דא האי שדה וכו':","ועל כן שדה הזה, הוא ממכפלה ההיא, שהיא מלכות כנ\"ל, ששם הוא שורה, כעין זה שכתוב ראה ריח בני כריח שדה אשר ברכו ה', שהיא המלכות. והיא כפולה למעלה ולמטה, ומשום זה כתוב שדה המכפלה, ודאי, ולא שדה כפול. כי סובב על מלכות הכפולה שנקראת שדה."],[4,"","פירוש. ד' מלכיות הן, ב' מלכיות למעלה מחזה מבחינת בינה ומלכות דבינה, וב' למטה מחזה מבחינת בינה ומלכות דמלכות. וב' המלכיות שלמעלה מחזה שניהן ממותקות ונכללות זו בזו. אבל למטה מחזה רק מלכות הג' ממותקת, ומלכות הד' אינה ממותקת מבינה כלום. כנ\"ל (בראשית ב' דף קצ\"ג אות של\"ח ד\"ה גם עש\"ה). וסוד המערה שנקבר בה אדה\"ר, היא מסוד מלכות הרביעית הבלתי ממותקת. בסו\"ה כי עפר אתה ואל עפר תשוב. אלא כיון שעשה תשובה נכללה המערה בשדה, שה\"ס מלכות השלישית הממותקת. ושם נקבר."],[4,"","וז\"ש \u0003חייך, לאו מערתא איהו מכפלה, ולאו שדה אקרי מכפלה\u0004 כי \u0003המערה\u0004 היא מלכות הד' שאינה ממותקת בבינה. וע\"כ אינה מכפלה בבינה. \u0003והשדה\u0004 שהיא מלכות הג' שהיא ממותקת, עכ\"ז אינה מכפלה, כי במקומה למטה מחזה אין ב' מלכיות, רק למעלה מחזה נקראת המלכות מכפלה ששם ב' מלכיות ממש הנכללות זו בזו, אחת מבינה ואחת ממלכות כנ\"ל. וז\"ש \u0003ירושלים לעילא\u0004 דהיינו למעלה מחזה דנוקבא \u0003אחידת בב' סטרין לעילא ולתתא,\u0004 דהיינו ב' מלכיות שמבחינת בינה ומלכות דבינה, \u0003ירושלים לתתא\u0004 דהיינו למטה מחזה דנוקבא, \u0003אחידת בב' סטרין לעילא ולתתא\u0004 שהם ב' מלכיות שמבחינת בינה ומלכות דמלכות. \u0003ובג\"כ כפלתא היא,\u0004 ומשום זה ירושלים דלעילא הוא כפלתא שיש שם ב' מלכיות ממותקות. \u0003ועל דא האי שדה מההיא כפלתא איהו\u0004 וע\"כ שדה הזה שבכאן, שהיא בחינת מלכות הג' כנ\"ל נבחנת ג\"כ למכפלה, משום שהמכפלה שה\"ס המיתוק דבינה \u0003ביה שריא\u0004 כי הוא ממותקת. ובג\"כ שדה המכפלה ודאי, ולא שדה כפול. כי אם השדה עצמו היה כפול היה צריך לומר שדה כפול לשון זכר. אלא כיון שהוא עצמו אינה מכפלה, אלא שממשכת המכפלה מן ב' המלכיות שלמעלה מחזה, ע\"כ כתוב מכפלה על שם המלכות שלמעלה מחזה."]],[[0,"","אָדָם נִכְנַס לִמְקוֹמוֹ - חַוָּה לֹא נִכְנְסָה, עַד שֶׁקָּרַב אַבְרָהָם וְהִכְנִיס אוֹתָהּ אֵצֶל אָדָם וְקִבֵּל אוֹתָהּ בִּשְׁבִילוֹ. זֶהוּ שֶׁכָּתוּב וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ, וְלֹא כָתוּב לְשָׂרָה, אֶלָּא אֶת שָׂרָה, לְרַבּוֹת חַוָּה. וְאָז הִתְיַשְּׁבוּ בִּמְקוֹמָם כָּרָאוּי. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְשָׁנִינוּ בְּאַבְרָהָם. תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ - זֶה אָדָם וְחַוָּה. לֹא כָתוּב אֵלֶּה הַשָּׁמַיִם וְהָאָרֶץ, אֶלָּא תוֹלְדוֹת הַשָּׁמַיִם הָאָרֶץ, וְלֹא תוֹלְדוֹת בֶּן אָדָם. וְהֵם הִתְקַיְּמוּ בִּשְׁבִיל אַבְרָהָם. וּמִנַּיִן לָנוּ שֶׁהִתְקַיְּמוּ בִּשְׁבִיל אַבְרָהָם? שֶׁכָּתוּב וַיָּקָם הַשָּׂדֶה וְהַמְּעָרָה אֲשֶׁר בּוֹ לְאַבְרָהָם. וְעַד שֶׁבָּא אַבְרָהָם לֹא הִתְקַיְּמוּ אָדָם וְחַוָּה בִּמְקוֹמָם בְּאוֹתוֹ הָעוֹלָם."],[1,"","רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר, הַמְּעָרָה הַזּוֹ אֵינָהּ כְּפוּלָה, שֶׁהֲרֵי כָּתוּב מְעָרַת הַמַּכְפֵּלָה, וְאַחַר כָּךְ הַכָּתוּב קָרָא לָהּ מְעָרַת שְׂדֵה הַמַּכְפֵּלָה. מַכְפֵּלָה הוּא קָרָא לַשָּׂדֶה."],[2,"","אָמַר לוֹ, כָּךְ קוֹרֵא לָהּ - מְעָרַת הַמַּכְפֵּלָה, כְּמוֹ שֶׁנֶּאֱמַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה, אֲבָל וַדַּאי, חַיֶּיךְ, הַמְּעָרָה הִיא מַכְפֵּלָה, וְלֹא הַשָּׂדֶה נִקְרָא מַכְפֵּלָה. אֶלָּא הַשָּׂדֶה וְהַמְּעָרָה נִקְרָאִים עַל שֵׁם מַכְפֵּלָה, שְׂדֵה הַמַּכְפֵּלָה וַדַּאי, וְלֹא הַמְּעָרָה, שֶׁהֲרֵי הַמְּעָרָה הִיא בַּשָּׂדֶה, וְאוֹתוֹ הַשָּׂדֶה עוֹמֵד בְּדָבָר אַחֵר."],[3,"","בֹּא רְאֵה, תַּחַת יְרוּשָׁלַיִם נִכְפְּלָה כָּל אֶרֶץ יִשְׂרָאֵל, וְהִיא עוֹמֶדֶת לְמַעְלָה וּלְמַטָּה. כְּמוֹ כֵן יְרוּשָׁלַיִם לְמַעְלָה - יְרוּשָׁלַיִם מַטָּה. אֲחוּזָה לְמַעְלָה וַאֲחוּזָה לְמַטָּה. יְרוּשָׁלַיִם לְמַעְלָה אֲחוּזָה בִּשְׁנֵי צְדָדִים - לְמַעְלָה וּלְמַטָּה (ירושלים למטה אחוזה בשני צדדים למעלה ולמטה), וּמִשּׁוּם כָּךְ הִיא כְּפוּלָה."],[4,"","וְעַל כֵּן הַשָּׂדֶה הַזּוֹ מֵאוֹתָהּ מַכְפֵּלָה הִיא שֶׁבּוֹ הִיא שׁוֹרָה. כְּמוֹ כֵן כָּתוּב כְּרֵיחַ הַשָּׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', לְמַעְלָה וּלְמַטָּה, וּמִשּׁוּם כָּךְ שְׂדֵה הַמַּכְפֵּלָה וַדַּאי, וְלֹא שָׂדֶה כָּפוּל."]]],[["תוּ רָזָא דְמִלָּה שְׂדֵה הַמַּכְפֵּלָה וַדַּאי, מַאן מַכְפֵּלָה, ה' דְבִשְׁמָא קַדִּישָׁא דְּאִיהִי מַכְפֵּלָה. וְכֹלָּא קָיְימָא כְּחַד, וּבְגִינֵיהּ קָאֲמַר בְּאוֹרַח סָתִים ה' מַכְפֵּלָה דְּלָא הֲוֵי בִּשְׁמָא קַדִּישָׁא אָת אָחֳרָא מַכְפֵּלָּה בַּר אִיהִי.","וְאַף עַל גַּב דִּמְעַרְתָּא כָפֶלְתָּא הֲוָה וַדַּאי דְּאִיהִי מְעַרְתָּא גּוֹ מְעַרְתָּא, אֲבָל עַל שׁוּם אָחֳרָא אִקְרֵי מְעָרַת שְׂדֵה הַמַּכְפֵּלָה כְּמָה דְאִתְּמָר. וְאַבְרָהָם יָדַע, וְכַד אָמַר לִבְנֵי חֵת כַּסֵּי מִלָּה וְאָמַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָּה, עַל שׁוּם דְּאִיהִי מְעַרְתָּא כָּפֶלְתָּא, וְאוֹרַיְיתָא לָא קָרֵי לָהּ אֶלָּא מְעָרַת שְׂדֵה הַמַּכְפֵּלָה כְּדְקָא יְאוּת.","וְקוּדְשָׁא בְּרִיךְ הוּא עָבַד כֹּלָּא לְאִשְׁתַּכָּחָא הַאי עַלְמָא כְּגַוְונָא דִלְעֵילָא, וּלְאִתְדַּבָּקָא דָּא בְּדָא, לְמֶהֱוֵי יְקָרֵיהּ לְעֵילָא וְתַתָּא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי:","וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. רַבִּי יְהוּדָה פָּתַח (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ, הַאי קְרָא (צד ע\"ב) אִתְּמָר, אֲבָל זַכָּאָה הוּא בַּר נָשׁ דְּאוֹרְחוֹי אִתְכַּשְׁרָן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ אִתְרָעֵי בֵּיהּ לְקָרָבָא לֵיהּ לְגַבֵּיהּ.","תָּא חֲזֵי, אַבְרָהָם אִתְקְרִיב לְגַבֵּיהּ וְתִאוּבְתֵּיהּ דִּילֵיהּ הֲוָה כָּל יוֹמוֹי בְּהַאי, וְלָא אִתְקְרִיב אַבְרָהָם בְּיוֹמָא חָדָא אוֹ בְּזִמְנָא חָדָא, אֶלָּא עוֹבָדוֹי קְרִיבוּ לֵיהּ בְּכָל יוֹמוֹי מִדַּרְגָּא לְדַרְגָּא, עַד דְּאִסְתַּלַק בְּדַרְגּוֹי.","כַּד הֲוָה סִיב וְעָאל בְּדַרְגִּין עִלָּאִין כְּדְקָא חָזֵי דִּכְתִיב וְאַבְרָהָם זָקֵן, וּכְדֵין בָּא בַּיָּמִים בְּאִינוּן יוֹמִין עִלָּאִין בְּאִינוּן יוֹמִין יְדִיעָאן בְּרָזָא דִמְהֵימְנוּתָא. וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. דְּמִתַּמָּן נָפְקִין כָּל בִּרְכָאן וְכָל טִיבוּ."],[[0,"תו רזא דמלה וכו':","עוד, סוד הדבר הוא שדה המכפלה ודאי. מי הוא מכפלה, היינו \u0003ה'\u0004 שבשם הקדוש, שהיא מכפלה, שיש ב' ההין בשם הויה, ושתיהן נמצאים בו כאחת. כלומר שנכללין זו בזו בסוד השיתוף דמדת הרחמים בדין כנודע ובשבילה אומר הכתוב בדרך העלם \u0003ה'\u0004 מכפלה, שאין בהשם הקדוש הוי\"ה אות אחר שתהיה כפולה, חוץ ממנה. כלומר, המלה \u0003המכפלה\u0004 עם \u0003ה'\u0004 הידיעה, רומז לה' מכפלה, דהיינו לה\"ת דהויה, שה\"ס מלכות הממותקת בבינה, שהיא \u0003ה'\u0004 ראשונה דהויה, כנ\"ל בדבור הסמוך באורך, ואין כאן חידוש דברים אלא שמרחיב הביאור."],[1,"ואע\"ג דמערתא וכו':","ואף על פי שמערה כפולה היתה ודאי, שהיא מערה לפנים ממערה, אבל, על שם אחר, נקראת מערת שדה המכפלה,כמו שאמרנו דהיינו על שם המיתוק של מלכות בבינה ולא על מה שהמערה היתה מכופלת. ואברהם ידע זה, וכשאמר לבני חת העלים הדבר, ואמר ויתן לי \u0003מערת המכפלה,\u0004 דהיינו על שם, שהמערה היתה כפולה, ולא אמר שדה המכפלה על שם המיתוק דבינה. אבל התורה אינה קורא אותה, אלא \u0003מערת שדה המכפלה,\u0004 כראוי להיות, דהיינו על שם המיתוק של המלכות בבינה, שהיא שורה רק בשדה, ולא במערה כנ\"ל."],[2,"וקב\"ה עבד וכו':","והקב\"ה עושה הכל, שיהיה נמצא בעולם הזה, שהיא מלכות, כעין שנמצא למעלה, בבינה. ושיתדבקו זה בזה, שיהיה כבודו למעלה ולמטה. אשרי חלקם של הצדיקים, שהקב\"ה חפץ בהם בעולם הזה ובעולם הבא."],[3,"ואברהם זקן בא בימים וגו':","ר' יהודה פתח, אשרי תבחר ותקרב ישכון חצריך. מקרא זה נתבאר אבל אשרי האיש שדרכיו רצוים לפני הקב\"ה, והוא חפץ בו לקרבו אליו."],[4,"ת\"ח אברהם וכו':","בוא וראה. אברהם נתקרב אל הקב\"ה. וכל ימיו היה תשוקתו בזה, שיתקרב אליו, ולא נתקרב אברהם ביום אחד או בפעם אחת, אלא מעשיו הטובים הקריבו אותו בכל יום ויום ממדרגה למדרגה, עד שנתעלה במדרגתו."],[5,"כד הוה סיב וכו':","כשהיה זקן, ונכנס במדרגות העליונות כראוי, שכתוב ואברהם זקן, אז בא בימים, דהיינו בימים אלו העליונים, בימים אלו הידועים בסוד האמונה. וה' ברך את אברהם בכל. היינו יסוד דאו\"א עלאין הנקרא \u0003כל,\u0004 שמשם יוצאות כל הברכות וכל טוב. כי שפעו אינו נפסק לעולם."]],[[0,"","עוֹד סוֹד הַדָּבָר - שְׂדֵה הַמַּכְפֵּלָה וַדַּאי. מִי הַמַּכְפֵּלָה? (ה') שֶׁבַּשֵּׁם הַקָּדוֹשׁ שֶׁהִיא מַכְפֵּלָה. הַכֹּל עוֹמֵד יַחַד, וּבִשְׁבִילָהּ אָמַר בְּדֶרֶךְ נִסְתָּר הַ' מַּכְפֵּלָה, שֶׁלֹּא הָיְתָה בַּשֵּׁם הַקָּדוֹשׁ אוֹת אַחֶרֶת מַכְפֵּלָה פְּרָט לָזֶה."],[1,"","וְאַף עַל גַּב שֶׁמְּעָרַת הַמַּכְפֵּלָה הָיְתָה וַדַּאי, שֶׁהִיא מְעָרָה בְּתוֹךְ מְעָרָה, אֲבָל עַל שֵׁם אַחֵר נִקְרֵאת מְעָרַת הַמַּכְפֵּלָה, כְּמוֹ שֶׁנֶּאֱמַר. וְאַבְרָהָם יָדַע, וּכְשֶׁאָמַר לִבְנֵי חֵת, כִּסָּה אֶת הַדָּבָר, וְאָמַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה, עַל שֵׁם שֶׁהִיא מְעָרָה כְּפוּלָה, וְהַתּוֹרָה לֹא קָרְאָה לָהּ אֶלָּא מְעָרַת שְׂדֵה הַמַּכְפֵּלָה כָּרָאוּי."],[2,"","וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הַכֹּל שֶׁיִּמָּצֵא הָעוֹלָם הַזֶּה, כְּמוֹ שֶׁלְּמַעְלָה, וּלְהַדְבִּיק זֶה עִם זֶה שֶׁיִּהְיֶה כְבוֹדוֹ לְמַעְלָה וּלְמַטָּה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[3,"","וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. רַבִּי יְהוּדָה פָּתַח, (תהלים סח) אַשְׁרֵי תִבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ. הַפָּסוּק הַזֶּה נִתְבָּאֵר, אֲבָל אַשְׁרֵי הָאִישׁ שֶׁדְּרָכָיו כְּשֵׁרוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא הִתְרַצָּה בּוֹ לְקָרְבוֹ אֵלָיו."],[4,"","בֹּא רְאֵה, אַבְרָהָם הִתְקָרֵב אֵלָיו, וּתְשׁוּקָתוֹ הָיְתָה כָּל יוֹם בָּזֶה. וְלֹא הִתְקָרֵב אַבְרָהָם בְּיוֹם אֶחָד אוֹ בְּפַעַם אַחַת, אֶלָּא מַעֲשָׂיו קֵרְבוּהוּ בְּכָל יָמָיו מִדַּרְגָּה לְדַרְגָּה, עַד שֶׁהִתְעַלָּה בְּדַרְגָּתוֹ."],[5,"","כְּשֶׁהָיָה זָקֵן וְנִכְנַס לִדְרָגוֹת עֶלְיוֹנוֹת כָּרָאוּי, שֶׁכָּתוּב וְאַבְרָהָם זָקֵן, וְאָז בָּא בַּיָּמִים, בְּאוֹתָם יָמִים עֶלְיוֹנִים, בְּאוֹתָם יָמִים יְדוּעִים בְּסוֹד הָאֱמוּנָה. וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. שֶׁמִּשָּׁם יוֹצְאוֹת כָּל הַבְּרָכוֹת וְכָל טוֹב."]]],[["זַכָּאִין אִינוּן מָארֵיהוֹן דִּתְשׁוּבָה דְּהָא בְּשַׁעְתָּא חָדָא בְּיוֹמָא חָדָא בְּרִגְעָא חָדָא קְרֵיבִין לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, מַה דְּלָא הֲוָה הָכִי אֲפִילּוּ לְצַדִּיקִים גְּמוּרִים דְּאִתְקְרִיבוּ גַּבֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּכַמָּה שְׁנִין. אַבְרָהָם לָא עָאל בְּאִינוּן יוֹמִין עִלָּאִין עַד דְּהֲוָה סִיב כְּמָה דְאִתְּמָר. וְכֵן דָּוִד דִּכְתִיב (מלכים א א׳:א׳) וְהַמֶּלֶךְ דָּוִד זָקֵן בָּא בַּיָּמִים. אֲבָל מָארִיהּ דִּתְשׁוּבָה מִיָּד עָאל וְאִתְדָּבַּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא.","רַבִּי יוֹסֵי אָמַר תָּנִינָן אֲתַר דְּמָארֵיהוֹן דִּתְשׁוּבָה קָיְימֵי בֵּיהּ, בְּהַהוּא עַלְמָא, צַדִּיקִים גְּמוּרִים לֵית לוֹן רְשׁוּ לְקָיְימָא בֵּיהּ, בְּגִין דְּאִינוּן קְרֵיבִין לְמַלְכָּא יַתִּיר מִכֻּלְּהוּ, וְאִינוּן מָשְׁכֵי עֲלַיְיהוּ בִּרְעוּתָא דְלִבָּא יַתִּיר וּבְחֵילָא סַגְיָא לְאִתְקְרָבָא לְמַלְכָּא.","תָּא חֲזֵי, כַּמָּה אַתְרִין מְתוּקָנִין לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא עַלְמָא, וּבְכֻלְּהוּ בֵּי מוֹתְבֵי לוֹן לַצַּדִּיקִים. כָּל חַד וְחַד לְפוּם דַּרְגֵּיהּ כְּדְקָא חָזֵי לֵיהּ.","כְּתִיב, (תהילים ס״ה:ה׳) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךָ, דְּקוּדְשָׁא בְּרִיךְ הוּא קָרִיב לוֹן לְגַבֵּיהּ דְּסָלְקִין אִינוּן נִשְׁמָתִין מִתַּתָּא לְעֵילָא וּלְאִתְאַחֲדָא בְּאַחְסַנְתֵּיהוֹן דְּאִתְתַּקְנָן לְהוּ. יִשְׁכֹּן חֲצֵרֶיךָ, אִלֵּין אַתְרִין וְדַרְגִּין לְבַר, וּמַאן אִינוּן, כְּמָא דְאַתְּ אָמֵר (זכריה ג׳:ז׳) וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים הָאֵלֶּה. וְהַאי הוּא דַּרְגָּא בֵּין קַדִּישִׁין עִלָּאִין.","וּמַאן דְּזַכָּאִין לְדַרְגָּא דָא, אִינוּן שְׁלִיחָן דְּמָארֵי עַלְמָא כְּאִינוּן מַלְאָכִין וְעָבְדִין שְׁלִיחוּתָא תָּדִיר בִּרְעוּתָא דְּמָארִיהוֹן, בְּגִין דְּאִלֵּין (אתקדשו) תָּדִיר בִּקְדוּשָּׁה וְלָא אִסְתָּאֲבוּ.","כְּגַוְונָא דָא, מַאן דְּאִסְתָּאַב בְּהַאי עַלְמָא אִיהוּ מָשִׁיךְ עֲלֵיהּ רוּחַ מְסָאָב, וְכַד נָפַק נִשְׁמָתֵיהּ מִנֵּיהּ מְסָאֲבִין לֵיהּ וּמְדוֹרֵיהּ בֵּין אִינוּן מְסָאֲבִין וְאִלֵּין אִינוּן מַזִּיקִין דְּעַלְמָא. כְּמָה דְאִתְמְשַׁךְ בַּר נָשׁ גַּרְמֵיהּ בְּהַאי עַלְמָא הָכִי הוּא מְדוֹרֵיהּ וְאִתְמְשַׁךְ בְּהַהוּא עַלְמָא (נט ואינון רוחי מסאבי מסאבין ליה ואעלין ליה לגיהנם.)","תָּא חֲזֵי מַאן דְּאִתְקַדַּשׁ וְנָטִיר גַּרְמֵיהּ בְּהַאי עַלְמָא דְּלָא אִסְתָּאַב. מְדוֹרֵיהּ בְּהַהוּא עַלְמָא בֵּין אִינוּן קַדִּישִׁין עִלָּאִין וְעָבְדִין שְׁלִיחוּתָא תָּדִיר, וְאִלֵּין קָיְימֵי בַּחָצֵר כְּמָא דְאַתְּ אָמֵר, (שמות כ״ז:ט׳) אֵת חֲצַר הַמִּשְׁכָּן."],[[0,"זכאין אינון וכו':","אשריהם לבעלי תשובה שבשעה אחת, ביום אחד, ברגע אחד, הם קרבים אל הקב\"ה, מה שלא היה כן אפילו לצדיקים גמורים, שהם נתקרבו אל הקב\"ה בכמה שנים. אברהם לא נכנס באלו הימים העליונים, עד שהיה זקן, כמו שנתבאר, וכן דוד, שכתוב והמלך דוד זקן בא בימים, אבל בעל תשובה, מיד נכנס ומתדבק בהקב\"ה."],[1,"ר' יוסי אמר וכו':","רי\"א, למדנו, במקום שבעלי תשובה עומדים בו, באותו העולם, אין לצדיקים גמורים רשות לעמוד בו. משום שהם קרובים אל המלך יותר מכולם, והם מושכים השפע מלמעלה עם יותר כונת הלב, ועם כח גדול ביותר, להתקרב אל המלך."],[2,"ת\"ח כמה אתרין וכו':","בוא וראה. כמה מקומות מתוקנים יש לו להקב\"ה בעולם ההוא, ובכולם יש בתי דירה לצדיקים, לכל אחד ואחד לפי מדרגתו כראוי לו."],[3,"כתיב, אשרי תבחר ותקרב ישכון חצריך:","היינו אותם אשר הקב\"ה קרבם אליו, שאלו הנשמות עולות ממטה למעלה להתאחד בנחלתם שנתתקן להם. \u0003ישכון חצריך,\u0004 פירושו, מקומות ומדרגות שהם לחוץ מהיכל. ומי הם. הוא כמו שאתה אומר, ונתתי לך מהלכים בין העומדים האלה. וזה הוא מדרגה ידועה בין קדושים העליונים."],[4,"ומאן דזכאין וכו':","וכל הזוכים למדרגה זו, הם שליחי רבון העולם, כמו המלאכים, כי מהלכים, פירושו שליחים, ועושים שליחות תמיד, בחפץ רבונם, משום שאלו הם תמיד בקדושה, ולא נטמאו."],[5,"כגוונא דא וכו':","כעין זה, מי שנטמא בעולם הזה, מושך על עצמו רוח הטומאה, וכשנשמתו יוצאת ממנו, מטמאים אותו, הס\"א, ודירתו בין אלו הטמאים, ואלו הם מזיקי העולם. כי כמו שאדם ממשיך על עצמו בעולם הזה, כן הוא דירתו וכן נמשך בעולם הנצחי."],[6,"ת\"ח מאן דאתקדש וכו':","בוא וראה, כל המקדש עצמו, ושומר עצמו בעולם הזה שלא יטמא, דירתו בעולם ההוא, בין קדושים העליונים, ועושים שליחות של הקב\"ה תמיד, והם עומדים בחצר. כמו שאתה אומר, את חצר המשכן. ועליהם כתוב אשרי וגו' ישכון חצריך."]],[[0,"","אַשְׁרֵיהֶם בַּעֲלֵי הַתְּשׁוּבָה, שֶׁהֲרֵי בְּשָׁעָה אַחַת בְּיוֹם אֶחָד (בפעם אחת) בְּרֶגַע אֶחָד קְרֵבִים לַקָּבָּ\"ה, מַה שֶּׁלֹּא הָיָה כָּךְ אֲפִלּוּ לְצַדִּיקִים גְּמוּרִים שֶׁהִתְקָרְבוּ לַקָּבָּ\"ה בְּכַמָּה שָׁנִים. אַבְרָהָם לֹא נִכְנַס בְּאוֹתָם הַיָּמִים הָעֶלְיוֹנִים עַד שֶׁהָיָה זָקֵן, כְּמוֹ שֶׁנֶּאֱמַר. וְכֵן דָּוִד, שֶׁכָּתוּב (מלכים א א) וְהַמֶּלֶךְ דָּוִד זָקֵן בָּא בַּיָּמִים. אֲבָל בַּעַל הַתְּשׁוּבָה מִיָּד נִכְנָס וְנִדְבָּק בַּקָּבָּ\"ה."],[1,"","רַבִּי יוֹסֵי אָמַר, שָׁנִינוּ, הַמָּקוֹם שֶׁבַּעֲלֵי הַתְּשׁוּבָה עוֹמְדִים בָּעוֹלָם הַהוּא, אֵין לְצַדִּיקִים גְּמוּרִים רְשׁוּת לַעֲמֹד בּוֹ, מִשּׁוּם שֶׁהֵם קְרוֹבִים לַמֶּלֶךְ יוֹתֵר מִכֻּלָּם, וְהֵם מוֹשְׁכִים עֲלֵיהֶם בִּרְצוֹן הַלֵּב יוֹתֵר וּבְכֹחַ רַב לְהִתְקָרֵב לַמֶּלֶךְ."],[2,"","בֹּא רְאֵה, כַּמָּה מְקוֹמוֹת מְתֻקָּנִים לַקָּבָּ\"ה בָּעוֹלָם הַהוּא, וּבְכֻלָּם בֵּית מוֹשָׁבִים לַצַּדִּיקִים, כָּל אֶחָד וְאֶחָד לְפִי דַרְגָּתוֹ כָּרָאוּי לוֹ."],[3,"","כָּתוּב (תהלים סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְקָרֵב אוֹתָם אֵלָיו, שֶׁעוֹלִים אוֹתָם הַנְּשָׁמוֹת מִמַּטָּה לְמַעְלָה וּלְהֵאָחֵז בְּנַחֲלָתָם שֶׁנִּתְקְנָה לָהֶן. יִשְׁכֹּן חֲצֵרֶיךְ - אֵלּוּ הַמְּקוֹמוֹת וְהַדְּרָגוֹת שֶׁבַּחוּץ, וּמִי הֵם? כְּמוֹ שֶׁנֶּאֱמַר (זכריה ג) וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה. וְזוֹהִי דַרְגָּה בֵּין קְדוֹשִׁים עֶלְיוֹנִים."],[4,"","וּמִי שֶׁזַּכָּאִים לַדַּרְגָּה הַזּוֹ הֵם שְׁלִיחִים שֶׁל רִבּוֹן הָעוֹלָם, כְּמוֹ אוֹתָם הַמַּלְאָכִים, וְתָמִיד עוֹשִׂים שְׁלִיחוּת בִּרְצוֹן רִבּוֹנָם, מִשּׁוּם שֶׁאֵלּוּ (התקדשו) תָמִיד בִּקְדֻשָּׁה וְלֹא נִטְמְאוּ."],[5,"","כְּמוֹ כֵן מִי שֶׁנִּטְמָא בָּעוֹלָם הַזֶּה, הוּא מוֹשֵׁךְ עָלָיו רוּחַ טֻמְאָה, וּכְשֶׁיּוֹצֵאת מִמֶּנּוּ נִשְׁמָתוֹ, מְטַמְּאִים אוֹתוֹ, וּמְדוֹרוֹ בֵּין אוֹתָם הַטְּמֵאִים, וְאֵלּוּ הֵם הַמַּזִּיקִים שֶׁל הָעוֹלָם. כְּמוֹ שֶׁמַּמְשִׁיךְ אָדָם אֶת עַצְמוֹ בָּעוֹלָם הַזֶּה - כָּךְ הוּא מְדוֹרוֹ וְנִמְשָׁךְ בְּאוֹתוֹ הָעוֹלָם (ואותן רוחות הטמאות מטמאות אותו ומכניסות אותו לגיהנם)."],[6,"","בֹּא רְאֵה, מִי שֶׁמִּתְקַדֵּשׁ וְשׁוֹמֵר אֶת עַצְמוֹ בָּעוֹלָם הַזֶּה שֶׁלֹּא יִטָּמֵא, מְדוֹרוֹ בָּעוֹלָם הַהוּא בֵּין אוֹתָם קְדוֹשִׁים עֶלְיוֹנִים וְעוֹשִׂים תָּמִיד שְׁלִיחוּת, וְאֵלּוּ עוֹמְדִים בֶּחָצֵר, כְּמוֹ שֶׁנֶּאֱמַר (שמות כז) אֵת חֲצַר הַמִּשְׁכָּן."]]],[["וְאִית אָחֳרָנִין דְּאִינוּן לְגוֹ יַתִּיר, דְּלָאו אִינוּן בַּחָצֵר אֶלָּא בְּבֵיתָא כְּמָא דְאַתְּ אָמֵר, (תהילים ס״ה:ה׳) נִשְׂבְּעָה בְּטוּב בֵּיתֶךָ. אָמַר דָּוִד נִשְׂבְּעָה בְּטוּב בֵּיתֶךָ, כֵּיוָן דְּאָמַר יִשְׁכֹּן חֲצֵרֶיךָ, אַמַּאי כְּתִיב נִשְׂבְּעָה בְּטוּב בֵּיתֶךָ, יִשְׂבַּע בְּטוּב בֵּיתֶךָ מִיבָּעֵי לֵיהּ כְּמָה דִכְתִיב יִשְׁכֹּן. אֶלָּא הָא תָּנִינָן לֵית יְשִׁיבָה בָּעֲזָרָה אֶלָּא לְמַלְכֵי בֵּית דָּוִד בִּלְחוּדַיְיהוּ.","וְאִית אֲתַר לַחֲסִידֵי עֶלְיוֹנִין דְּעַיְילֵי לְגוֹ, וּמַאי אִינוּן, כְּדִכְתִיב, (במדבר ג׳:ל״ח) וְהַחוֹנִים לִפְנֵי הַמִּשְׁכָּן קֵדְמָה לִפְנֵי אֹהֶל מוֹעֵד מִזְרָחָה משֶׁה וְאַהֲרֹן וּבָנָיו וְגו'. וְכַמָּה מָדוֹרִין עַל מָדוֹרִין וּנְהוֹרִין עַל נְהוֹרִין מִתְפָּרְשָׁן בְּהַהוּא עַלְמָא, וְכָל חַד אִכְסִיף מִנְּהוֹרָא דְּחַבְרֵיהּ, כְּמָה דְעוֹבָדִין אִתְפָּרְשָׁן בְּהַאי עַלְמָא הָכִי נָמֵי דּוּכְתִּין וּנְהוֹרִין מִתְפָּרְשָׁן בְּהַהוּא עָלְמָא.","וְתָא חֲזֵי הָא אִתְּמָר דְּאָפִילּוּ בְּהַאי עַלְמָא כַּד בַּר נָשׁ נָּאִים עַל עַרְסֵיהּ, וְנִשְׁמָתִין אִצְטְרִיכוּ לְאִתְשׁוֹטְטָא בְּעַלְמָא וְנָפְקוּ מִגּוֹ גּוּפָא, לָאו כָּל נִשְׁמָתָא וְנִשְׁמָתָא סַלְקָא וְשַׁטְיָא לְמֶחזֵי בִּיקָר סֵבֶר אַפֵּי דְּעַתִּיק יוֹמִין, אֶלָּא כְּמָא דְאִתְמְשִׁיךְ תָּדִיר וּכְפוּם עוֹבָדֵי הָכִי נִשְׁמָתֵיהּ סָלְקָא.","אִי אִסְתָּאַב אִיהוּ נָאִים וְנִשְׁמָתָא נָפְקָא וְכָל אִינוּן רוּחִין מְסָאֲבִין נָקְטִין לָהּ וְאִתְדַּבְּקַת בְּהוּ בְּאִינוּן דַּרְגִּין תַּתָּאִין דְּשָׁטְיָין בְּעַלְמָא וְאִינוּן מוֹדִיעִין לָהּ מִלִּין דְּאִינוּן קְרֵיבִין לְמֵיתֵי בְּעַלְמָא, וּלְזִמְנִין דְּמוֹדְעִין לָהּ מִלִּין כְּדִיבָן וְחָיְיכָן בָּהּ וְהָא אוּקְמוּהָ.","וְאִי זָכֵי בַּר נָשׁ כַּד אִיהוּ נָאִים, וְנִשְׁמָתֵיהּ סָלְקָא אָזְלָא וְשָׁטְיָא וּבָקְעָא בֵּין אִלֵּין רוּחִין מְסָאֲבִין, וְכֻלְּהוּ מַכְרִיזִין וְאָמְרִין, פַּנּוּן אֲתַר פַּנּוּן, לָאו דָּא מִסִּטְרָנָא, וְאִיהִי סָלְקָא בֵּין אִינוּן קַדִּישִׁין וּמוֹדָעֵי לָהּ מִלָּה חָדָא דִקְשׁוֹט.","וְכַד נָחֲתָא כָּל אִינוּן חֲבִילִין טְרִיקִין בָּעָאן לְאִתְקְרָבָא בַּהֲדָהּ לְמִנְדַע הַהִיא מִלָּה, וְאִינוּן מוֹדָעִין לָהּ מִלִּין אָחֳרָנִין, וְהַהִיא מִלָּה דְּנָטְלָא גּוֹ אִינוּן קַדִּישִׁין בֵּין אִינוּן אָחֳרָנִין אִיהוּ כְּעִבּוּרָא גּוֹ תִּיבְנָא. וְהַאי (מאן איהו דזכי יתיר בעוד דאיהו קאים ונשמתא קיימא בהאי עלמא.)"],[[0,"ואית אחרנין וכו':","ויש אחרים שהם יותר בפנימיות, שאינם בחצר אלא בבית, כמו שאתה אומר, נשבעה בטוב ביתך. אמר דוד נשבעה בטוב ביתך, ושואל, כיון דאמר ישכון חצריך, אמאי כתיב, נשבעה בטוב ביתך, ישבע בטוב ביתך צריך לומר, כמ\"ש ישכון חצריך. אלא הרי למדנו, שאין ישיבה בעזרה אלא למלכי בית דוד בלבד. וע\"כ אמר, כמדבר בעדו, נשבעה בטוב ביתך שכונתו היה על עצמו ועל שאר המלכים, שיש להם ישיבה בעזרה, שה\"ס ביתך, דהיינו בית המקדש."],[1,"ואית אתר וכו':","ויש מקום לחסידים העליונים הנכנסים עוד יותר בפנימיות, דהיינו לבחינת היכל. ומי הם. הם כמו שכתוב והחונים לפני המשכן קדמה וגו'. ועליהם נאמר, קדוש היכלך. וכמה מדורים על מדורים ואורות על אורות, נבדלים זה מזה בעולם ההוא וכל אחד ואחד מתביש מאורו של חברו. כי כמו שהמעשים טובים נבדלים בין איש לחבירו בעולם הזה, כן מקומות הדירה והאורות שלהם נבדלים בעולם ההוא."],[2,"ות\"ח הא אתמר וכו':","ובוא וראה, הרי למדנו, שאפילו בעולם הזה, כשהאדם ישן על מטתו, והנשמות יוצאות מהגוף, וצריכות לשוטט בעולם, לא כל נשמה ונשמה משוטטת ועולה, לראות בכבוד סבר פנים של עתיק יומין, אלא כפי מה שנמשך תמיד, וכפי מעשיו, כן נשמתו עולה."],[3,"אי אסתאב וכו':","אם נטמא, כשהוא ישן, והנשמה יצאה ממנו, כל רוחות הטומאה אוחזים בה, והיא מתדבקת בהם, באלו מדרגות התחתונות המשוטטות בעולם, והם מודיעים לה דברים הקרובים לבא בעולם. ממה ששמעו מאחורי הפרגוד. ולפעמים הם מודיעים לה דברי שקר, ומצחקים בה. וכבר בארוהו."],[4,"ואי זכי ב\"נ וכו':","ואם האדם זכה, כשהוא ישן ונשמתו עולה, הולכת ומשוטטת ובוקעת לה דרך, בין רוחות הטומאה, וכולם מכריזים ואומרים פנו מקום, פנו, אין זה מן הצד שלנו, והיא עולה ובאה בין אלו הקדושים והם מודיעים לה דבר אמת אחד."],[5,"וכד נחתא וכו':","וכשיורדת, כל אלו מחנות המעורבבות, כלומר מלאכים כאלו, שקדושה וחול וטומאה משמשים בהם בערבוביא, רוצים להתקרב אל הנשמה, לדעת אותו הדבר אמת ששמעה, והמה מודיעים לה דברים אחרים. ואותו הדבר שלקחה מן הקדושים, בין הדברים שלקחה ממחנות המעורבבות, דומה עליה, כמו תבואה המעורבת תוך קש ותבן. וזה הוא הזוכה ביותר בעוד שהוא בחיים, והנשמה עוד נמצאת בעולם הזה. \u0003חבילין\u0004 פירושו מחנות, מלשון חבל נביאים. (שמואל א' י') טריקין, פירושו עירוב דברים, מלשון ולטרוקינהו בהדי הדדי, (שבת ק\"י) שלא טרקו (ב\"ק קט\"ו)."]],[[0,"","וְיֵשׁ אֲחֵרִים שֶׁהֵם בִּפְנִים יוֹתֵר שֶׁאֵינָם בֶּחָצֵר, אֶלָּא בַּבַּיִת, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סה) נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ. אָמַר דָּוִד, נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ. כֵּיוָן שֶׁאָמַר יִשְׁכֹּן חֲצֵרֶיךְ, לָמָּה כָּתוּב נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ? יִשְׂבַּע בְּטוּב בֵּיתֶךְ הָיָה צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁכָּתוּב יִשְׁכֹּן! אֶלָּא הֲרֵי שָׁנִינוּ, אֵין יְשִׁיבָה בָּעֲזָרָה אֶלָּא לְמַלְכֵי דָוִד לְבַדָּם."],[1,"","וְיֵשׁ מָקוֹם לַחֲסִידִים עֶלְיוֹנִים שֶׁנִּכְנָסִים לִפְנִים, וּמִי הֵם? כַּכָּתוּב (במדבר ג) וְהַחֹנִים לִפְנֵי הַמִּשְׁכָּן קֵדְמָה לִפְנֵי אֹהֶל מוֹעֵד מִזְרָחָה מֹשֶׁה וְאַהֲרֹן וּבָנָיו וְגוֹ'. וְכַמָּה מְדוֹרִים עַל מְדוֹרִים וְאוֹרוֹת עַל אוֹרוֹת נִפְרָדִים בָּעוֹלָם הַהוּא, וְכָל אֶחָד מִתְבַּיֵּשׁ מֵאוֹר חֲבֵרוֹ. כְּמוֹ שֶׁהַמַּעֲשִׂים נִפְרָדִים בָּעוֹלָם הַזֶּה, כָּךְ גַּם מְקוֹמוֹת וְאוֹרוֹת נִפְרָדִים בָּעוֹלָם הַהוּא."],[2,"","וּבֹא וּרְאֵה, הֲרֵי נֶאֱמַר שֶׁאֲפִלּוּ בָּעוֹלָם הַזֶּה, כְּשֶׁאָדָם יָשֵׁן עַל מִטָּתוֹ וְהַנְּשָׁמוֹת צְרִיכוֹת לְשׁוֹטֵט בָּעוֹלָם וְיָצְאוּ מִתּוֹךְ הַגּוּף, אֵין כָּל נְשָׁמָה וּנְשָׁמָה עוֹלָה וּמְשׂוֹטֶטֶת לִרְאוֹת בִּכְבוֹד סֵבֶר פְּנֵי עַתִּיק הַיָּמִים, אֶלָּא כְּמוֹ שֶׁנִּמְשָׁךְ תָּמִיד וּכְפִי הַמַּעֲשִׂים, כָּךְ נִשְׁמָתוֹ עוֹלָה."],[3,"","אִם נִטְמָא - הוּא יָשֵׁן וְהַנְּשָׁמָה יוֹצֵאת, וְכָל אוֹתָן רוּחוֹת טְמֵאוֹת לוֹקְחוֹת אוֹתָהּ, וְנִדְבֶּקֶת בָּהֶן בְּאוֹתָן הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁמְּשׁוֹטְטוֹת בָּעוֹלָם, וְהֵם מוֹדִיעוֹת לָהּ דְּבָרִים שֶׁקְּרוֹבִים לָבֹא לָעוֹלָם. וְלִפְעָמִים שֶׁמּוֹדִיעִים לָהּ דְּבָרִים כּוֹזְבִים וְצוֹחֲקִים עָלֶיהָ, וַהֲרֵי פֵּרְשׁוּהָ."],[4,"","וְאִם זוֹכֶה אָדָם, כְּשֶׁהוּא יָשֵׁן וְנִשְׁמָתוֹ עוֹלָה, הוֹלֶכֶת וְשָׁטָה וּבוֹקַעַת בֵּין הָרוּחוֹת הַטְּמֵאוֹת הַלָּלוּ, וְכֻלָּם מַכְרִיזִים וְאוֹמְרִים: פַּנּוּ מָקוֹם, פַּנּוּ. זֶה אֵינוֹ מִצִּדֵּנוּ! וְהִיא עוֹלָה בֵּין אוֹתָם הַקְּדוֹשִׁים, וּמוֹדִיעִים לָהּ דָּבָר אֶחָד אֱמֶת."],[5,"","וּכְשֶׁיּוֹרֶדֶת, כָּל אוֹתָם מַחֲנוֹת שֶׁל עִרְבּוּב רוֹצִים לְהִתְקָרֵב אֵלֶיהָ לָדַעַת אוֹתוֹ הַדָּבָר, וְהֵם מוֹדִיעִים לָהּ דְּבָרִים אֲחֵרִים. וְהַדִּבּוּר הַהוּא שֶׁנּוֹטֶלֶת בְּתוֹךְ אוֹתָם קְדוֹשִׁים בֵּין אוֹתָם הָאֲחֵרִים הוּא כִּתְבוּאָה בְּתוֹךְ הַתֶּבֶן. וְזֶה (מי) הוּא זוֹכֶה יוֹתֵר בְּעוֹד שֶׁהוּא עוֹמֵד וְהַנְּשָׁמָה עוֹמֶדֶת בָּעוֹלָם הַזֶּה."]]],[["כְּגַוְונָא דָּא כַּד נָפְקִין נִשְׁמָתִין מִגּוּפָא מֵהַאי עַלְמָא, בָּעָאן לְסַלְקָא, וְכַמָּה תַּרְעִין חֲבִילֵי טְהִירִין קָיְימֵי, (ו) אִי אִינוּן מִסִּטְרַיְיהוּ כֻּלְּהוּ אָחֲדִין בְּהוּ בְּאִינוּן נַפְשָׁאן וּמָסְרֵי לוֹן בִּידָא דְדוּמָה לְאָעֳלָא לוֹן בַּגֵּיהִנָּם.","וּלְבָתַר סָלְקָן וְאָחֲדָן בְּהוּ וְאִינוּן נָטְלֵי לְהוֹן וּמַכְרְזֵי בְּהוּ אִלֵּין אִינוּן דְּעָבְרוּ עַל פִּקּוּדֵי דְּמָארֵיהוֹן, וְכֵן שָׁטְיָין בְּכָל עָלְמָא. וּלְבָתַר מְהַדְּרֵי לְהוּ לַגֵּיהִנֹּם, וְכֵן עַד תְּרֵיסַר יַרְחֵי. לְבָתַר תְּרֵיסַר יַרְחֵי מִשְׁתַּכְּכֵי בְּהַהוּא אֲתַר דְּאִתְחֲזֵי לוֹן. אִינוּן נִשְׁמָתִין דְּזָכוּ סָלְקֵי לְעֵילָא כְּמָה דְאִתְּמָר וְזָכָאן בְּדוּכְתַּיְיהוּ.","תָּא חֲזֵי, זַכָּאִין אִינוּן צַדִּיקַיָא דְּאִתְגְּנִיז לְהוּ כַּמָּה טָבִין לְהַהוּא עַלְמָא, וְלֵית אֲתַר פְּנִימָאָה בְּכָל אִינוּן כְּאִינוּן דְּיָדְעֵי רָזָא דְמָארֵיהוֹן וְיָדְעֵי לְאִתְדַּבְּקָא בְּהוּ בְּכָל יוֹמָא, עַל אִלֵּין כְּתִיב, (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלהִים זוּלָתֶךָ, יַעֲשֶׂה לִמְחַכֵּה לוֹ.","מַאי לִמְחַכֵּה לוֹ, כְּמָא דְאַתְּ אָמֵר (איוב ל״ב:ד׳) חִכָּה אֶת אִיּוֹב בִּדְבָרִים. וְאִלֵּין אִינוּן דְּדָחֲקִין לְמִלָּה דְחָכְמְתָא, וְדָיְיקִין לָהּ, וּמְחַכָּאן לָהּ לְמִנְדַע בְּרִירָא דְמִלָּה, וְאִשְׁתְּמוֹדְעָא לְמָארֵיהוֹן, אִלֵּין אִינוּן דְּמָארֵיהוֹן מִשְׁתַּבַּח בְּהוֹן בְּכָל יוֹמָא, אִלֵּין אִינוּן דְּעָאלִין בֵּין עִלָּאִין קַדִּישִׁין, וְאִלֵּין עָאלִין כָּל תַּרְעֵי דִלְעֵילָא וְלֵית מַאן דְּיִמְחֵי בִּידֵהוֹן, זַכָּאָה חוּלָקֵיהוֹן בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.","תָּא חֲזֵי, אַבְרָהָם עָאל לְמִנְדַע וּלְאִתְדַּבְּקָא בְּמָארֵיהּ כְּדְקָא יָאוֹת לְבָתַר דְּאַקְדִּים עוֹבָדוֹי בְּקַדְמִיתָא, וְזָכָה בְּאִינוּן יוֹמִין עִלָּאִין, וְאִתְבָּרַךְ מֵאֲתַר דְּכָל בִּרְכָאן נָפְקֵי מִתַּמָּן, דִּכְתִיב וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. מַאי בַּכֹּל. אֲתַר דְּנַהֲרָא דְּלָא פַּסְקֵי מֵימוֹי לְעָלְמִין.","אָמַר רִבִּי חִיָּיא תָּא חֲזֵי, דְּאַבְרָהָם לָא בָּעָא לְאִתְעָרְבָא בִּנְשֵׁי עַלְמָא וּלְאִתְדַּבְּקָא בִּשְׁאָר עַמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, בְּגִין דִּנְשַׁיָּיא דִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אִינוּן סָאֲבִין לְגוּבְרַיְיהוּ וּלְאִינוּן דְּמִתְדַּבְּקִין בְּהוֹן, בְּגִין דְּכַד אַבְרָהָם יָדַע חָכְמְתָא, יָדַע עִקְרָא וְשָׁרְשָׁא וּמֵאָן אֲתַר נָפְקֵי וְשַׁטְיָין רוּחֵי מְסָאֲבִין בְּעַלְמָא, וְעַל דָּא אוֹמֵי לְעַבְדֵּיהּ דְּלָא יִסַּב אִתְּתָא לִבְרֵיהּ מִשְּׁאָר עַמִּין.","\u0003מדרש הנעלם\u0004 וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וגו'. מַתְנִיתִין. אָמַר רַבִּי אֶלְעָזָר עַל כָּל פָּנִים כָּךְ הוּא דְּהַאי מַתְנִיתִין שַׁפִּיר, דְּאִתְעֲבִיד נִשְׁמָתָא הַהוּא דִכְתִיב בֵּיהּ (יחזקאל א׳:ט״ו) והִנֵּה אוֹפַן אֶחָד בָּאָרֶץ אֵצֶּל הַחַיּוֹת לְאַרְבַּעַת פָּנָיו. כִּדְאָמוּר בְּהַהִיא מַתְנִיתָא קַמַּיְיתָא.","אָמַר לֵיהּ רִבִּי אַבָּא לֵימָא לָן מַר מֵהַהִיא מַתְנִיתִין אָמַר לֵיהּ הָכִי אִתְפְּרַשׁ בִּתְלַת עֶשֶׂר מְכִילָן דְּרַחֲמֵי בְּפָרְשָׁתָא דִּילֵיהּ, אֲבָל הָכָא אִית לָן לְמֵימַר. פָּתַח וְאָמַר (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ וגו'. אָמַר רִבִּי אֶלְעָזָר מַאי הִיא דְּאֲנַן קָרִינָן הָכָא בְּשִׁיר הַשִּׁירִים לִישְׁנָא דְּנוּקְבְתָא, וְהָתָם בְּאוֹרַיְיתָא לִישְׁנָא דִּדְכוּרָא.","אֶלָא אָמַר רַבִּי אֶלְעָזָר הָכָא בַּתּוֹרָה נִקְרָא בְּלָשׁוֹן זָכָר אֵצֶּל הַגּוּף מִפְּנֵי שֶׁהַגּוּף אֵצֶּל הַנְּשָׁמָה כְּאִשָּׁה אֵצֶּל הַזָּכָר, וְהַנְּשָׁמָה לְגַבֵּי מַעְלָה, כִּנְקֵבָה בִּפְנִי הַזָּכָר וְכָל אֶחָד מַעֲלָתוֹ יוֹרֵשׁ.","תְּנַן הָתָם בְּאַרְבָּעָה פְּעָמִים (נ\"א בשנה) בְּשָׁעָה בְּכָל יוֹם, עֵדֶן מְנַטֵף עַל הַגָּן, וְיוֹצֵּא מֵאוֹתָם הַטִפּוֹת נָהָר גָּדוֹל הַמִּתְחַלֵּק לְאַרְבָּעָה רָאשִׁים, וּשְׁמֹנֶה וְאַרְבָּעִים טִפּוֹת מְנַטֵף בְּכָל יוֹם וּמִשָּׁם שְׂבֵעִים אִילָנֵי הַגַּן הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ט״ז) יִשְׂבְּעוּ עֲצֵּי יְיָ. רַבִּי תַּנְחוּם אָמַר מֵהָכָא (תהלים קו) מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו, אֵיזוֹ הִיא עֲלִיָּה זֶהוּ עֵדֶן. וְעֵדֶן בְּאֵיזֶה מָקוֹם הוּא. רַבִּי יְהוּדָה אָמַר לְמַעְלָה מֵעֲרָבוֹת הוּא. רַבִּי יוֹסֵי אָמַר בַּעֲרָבוֹת הוּא, דְּהָא תְּנַן שָׁם גִּנְזֵי חַיִּים טוֹבִים, בְּרָכָה וְשָׁלוֹם וְנִשְׁמָתָן שֶׁל צַּדִּיקִים והַגָּנוּז הָעֶלְיוֹן הוּא עֵדֶן, לְמַטָה מְכוּון כְּנְגְדוֹ גַּן בָּאָרֶץ וְנוֹטֵל מִמֶּנּוּ שֶׁפַע בְּכָל יוֹם.","אָמַר רַבִּי אַבָּהוּ שְׁמֹנָה וְאַרְבָּעִים נְבִיאִים עָמְדוּ לָהֶם לְיִשְׂרָאֵל וְכָל אֶחָד נָטַל בְּחֶלְקוֹ תַּמְצִּית טִפָּה אַחַת מֵאוֹתָם טִפּוֹת שֶׁל עֵדֶן שֶׁהֵם שְׁמֹנֶה וְאַרְבָּעִים טִפּוֹת. וּמַה אִם כָּל נָבִיא שֶׁנָּטַל טִפָּה אַחַת מֵהֶן הָיְתָה מַעֲלָתוֹ בְּרוּחַ הַקּוֹדֶשׁ עַל כָּל הַשְּׁאָר. אָדָם הָרִאשׁוֹן שֶׁהָיָה מְקַבֵּל מִשְּׁמֹנָה וְאַרְבָּעִים לֹא כָּל שֶׁכֵּן, מִכָּאן אַתָּה לָמֵד כַּמָּה הָיְתָה חָכְמָתוֹ.","רַבִּי בָּא אָמַר רַב כַּהֲנָא וכִי מֵאַיִן הָיָה לָהֶם לַנְּבִיאִים מֵאוֹתָם הַטִפּוֹת, אֶלָּא הָכִי תְּנַן, בְּכָל טִפָּה וְטִפָּה הַיּוֹצֵּאת מֵעֵדֶן רוּחַ חָכְמָה יוֹצֵּא עִמּוֹ, וְעַל כֵּן אִתְגְּזַר בְּמַתְנִיתִין, אִית מַיָא מְגַדְּלָן חַכִּימִין, וְאִית מַיָא מְגַדְּלָן טִפְּשִׁין, ואִינוּן מַיָא דִּמְגַדְּלָן חַכִּימִין אִינוּן מַיָא הֲווּ מִטִפִּין דְּעֵדֶן.","דְּאָמַר רַבִּי יוֹסֵי, מַיָא דְבֵיהּ טִפִּין יָתְבִין (נ\"א יתירין) מִכָּל אִינוּן אַרְבַּע נַהֲרֵי קַדְמָאָה הוּא דִּכְתִיב, (בראשית ב׳:י״א) שֵׁם הָאֶחָד פִּישׁוֹן. מַאי שֵׁם הָאֶחָד פִּישׁוֹן. הַמְיוּחָד מִכּוּלָּם פִּישׁוֹן והוּא הַנּוֹפֵל בְּאֶרֶץ מִצְּרַיִם, וּלְפִיכָךְ הָיְתָה חָכְמַת (לישראל) מִצְּרַיִם יוֹתֵר מִכָּל הָעוֹלָם.","וּמִשֶּׁנִּגְזְרָה גְזִרָה שְׁאָבְדָה חָכְמַת מִצְּרַיִם, נָטַל קוּדְשָׁא בְּרִיךְ הוּא אוֹתָם טִפִּין וְזָרַק לוֹן בְּהַהוּא גִּנָּא, בְּהַהוּא נַהֲרָא דְּגִנְתָא דְעֵדֶן דִּכְתִיב, (בראשית ב׳:י׳) ונָהָר יוֹצֵּא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְזְה הָיָה מוֹלִיד אַרְבָּעָה אֲחֵרִים וְהָאֶחָד הַמְיוּחָד הַנּוֹלַד מִמֶּנּוּ פִּישׁוֹן הָיָה. מִשֶּׁנִּטְלוּ אֵלּוּ הַטִפּוֹת שֶׁלֹּא יָצְּאוּ מֵהַגַּן אָבְדָה הַחָכְמָה מִמִּצְּרַיִם.","וּמֵאוֹתוֹ הָרוּחַ שֶׁהָיָה יוֹצֵּא מֵעֵדֶן, תִּמְצּוּ' (נ\"ל ימצו) כָּל נָבִיא ונָבִיא, והַיינוּ דִּכְתִיב מִתְהַלֵּךְ בַּגַּן לְרוּחַ הַיּוֹם. וגָנוּז זֶה בְּגַּן עֵדֶן לֶעָתִיד לָבוֹא, וְזֶה הוּא הַנָּהָר שֶׁרָאָה יְחֶזְקֵאל בִּנְבוּאָתוֹ. וְעַל כֵּן אָמַר הַכָּתוּב (ישעיהו י״א:ט׳) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ וְגו'. שֶׁאוֹתָם מַיִם תָּמִיד מְגַדְּלִים הַיְדִיעָה בָּעוֹלָם.","תָּנוּ רַבָּנָן כָּל נִשְׁמָתָן שֶׁל צַּדִּיקִים לְמַעְלָה בְּעֵדֶן הֵן. וּמַה מִּמַּה שֶּׁיּוֹרֵד מֵעֵדֶן יִשְׂגֶא הַחָכְמָה בָּעוֹלָם, לָעוֹמְדִים בּוֹ ונֶהֱנִין מֵהֲנָאוֹתָיו וְכִסּוּפָיו, עַל אַחַת כַּמָּה וְכַמָּה.","אָמַר רַבִּי יִצְּחָק כֵּיוָן שֶׁהַנְּשָׁמָה זוֹכָה לִיכָּנֵס בְּשַׁעֲרֵי יְרוּשָׁלַיִם שֶׁל מַעְלָה. מִיכָאֵ\"ל הַשַּׂר הַגָּדוֹל הוֹלֵךְ עִמָּהּ וּמַקְדִּים לָהּ שָׁלוֹם. מַלְאֲכֵי הַשָּׁרֵת תְּמֵהִים בּוֹ וְשׁוֹאֲלִים עָלֶיהָ (שיר השירים ג׳:ו׳) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר. מִי זֹאת עוֹלָה בֵּין הָעֶלְיוֹנִים מֵהַגּוּף הֶחָרֵב שֶׁדּוֹמֶה לְהֶבֶל דִּכְתִיב, (תהילים קמ״ד:ד׳) אָדָם לַהֶבֶל דָּמָה. הוּא מֵשִׁיב וְאוֹמֵר (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי, אַחַת הִיא מְיוּחֶדֶת הִיא. אַחַת הִיא לְאִמָּהּ, לְאִמָּהּ זוֹ הִיא כִּסֵּא הַכָּבוֹד שֶׁהִיא אֵם לַנְּשָׁמָה וְיוֹלֶדֶת לָהּ שֶׁנִּגְזְרָה מִמֶּנָּה.","רָאוּהָ בָּנוֹת וַיְאַשְׁרוּהָ. אֵלּוּ שְׁאָר הַנְּשָׁמוֹת שֶׁהֵן בְּמַעֲלָתָן לְמַעְלָה וְהֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם. אָמַר רַבִּי יוֹסֵי הָא חָזַרְנָא עַל מַה דְּאֲמָרָן אֵלּוּ נִקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם, וְהָאֲחֵרוֹת נִקְרָאוֹת בְּנוֹת לוֹט. רָאוּהָ בָּנוֹת וַיְאַשְׁרוּהָ. שְׁאָר הַנְּשָׁמוֹת מְשַׁבְּחוֹת לָהּ, וְאוֹמְרוֹת שָׁלוֹם בּוֹאֵךְ. מְלָכוֹת וּפִלַגְּשִׁים, מְלָכוֹת אֵלּוּ הָאָבוֹת שֶׁהֵם מְלָכוֹת. וּפִלַגְּשִׁים, הֵן גֵּירֵי הַצֶּדֶק. כּוּלָּם מְשַׁבְּחוֹת וּמְקַלְּסוֹת אוֹתָהּ עַד שֶׁנִּכְנְסֶת לְמַעְלָה, וְאֲזַי הַנְּשָׁמָה בְּמַעֲלָתָהּ וּמִתְקַיְּימָא אֲרִיכוּת הַיָּמִים הֲדָא הוּא דִכְתִיב וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים. נִכְנַס בַּאֲרִיכוּת הַיָּמִים לָעוֹלָם הַבָּא.","רַבִּי אַבָּא סָבָא קָם עַל רַגְלוֹי וְאָמַר, מְנוּחָה וְשָׁלוֹם גָּרְמִין יְהֵא לָךְ רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי דְּחָזָרַת עֲטָרָה לְיוֹשְׁנָהּ. דְּתָנִינָן בְּמַתְנִיתָּא קַדְמָאָה דְּכֵיוָן שֶׁהַנְּשָׁמָה הִיא בְּתַשְׁלוּמָהּ בְּאֲתַר עִלָּאָה (לזמנא בתרא עאלין) לָא תָבַאת לְגוּפָא, אֶלָּא אִתְבְּרִיאָן מִנָּהּ נִשְׁמֵי אָחֳרָנִין דְּנָפְקֵי מִנָּהּ ואִיהִי אִשְׁתְּאָרַת בְּקִיּוּמָא, עַד דְּאֲתָא רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי וְדָרַשׁ וּמַה אִם בָּעוֹלָם הַזֶּה שֶׁהוּא הֶבֶל וְהַגּוּף שֶׁהוּא טִפָּה סְרוּחָה נִכְנֶסֶת בּוֹ אוֹתָהּ הַנְּשָׁמָה. לֶעָתִיד לָבֹא שֶׁיִּצָּרְפוּ כּוּלָּם וְיִהְיְה הַגּוּף מוּבְחָר בְּקִיּוּם וְתַשְׁלוּם יוֹתֵר, אֵינוֹ דִין לְהִכָּנֵס אוֹתָהּ הַנְּשָׁמָה בּוֹ בְּכָל הַתַּשְׁלוּמִין והָעִלּוּיִין שֶׁבָּהּ.","אָמַר רַבִּי אַחָא אוֹתָהּ הַנְּשָׁמָה (בו בכל התשלומין והעלויין שבה) מַמָּשׁ ואוֹתוֹ הַגּוּף מַמָּשׁ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲמִידָן בְּקִיּוּמָן לֶעָתִיד לָבֹא, אֲבָל שְׁנִיהֶם יִהְיוּ שְׁלֵמִים בְּתַשְׁלוּם הַדַּעַת לְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיגוּ בָּעוֹלָם הַזְּה:","וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וגו'. רַבִּי בּוֹ אָמַר רַבִּי יוֹחָנָן (באותם הימים) בְּאוֹתוֹ הָעוֹלָם שֶׁהוּא יָמִים, וְלֹא בָּעוֹלָם הַזְּה שֶׁהוּא לַיְלָה. אָמַר רַבִּי יַעֲקֹב בְּאוֹתָם הָעוֹלָמוֹת שֶׁהֵם יָמִים בְּאוֹתָם הַהֲנָאוֹת וְהַכִּסּוּפִין שֶׁהוּא נוֹחֵל: וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. בְּאוֹתוֹ הַמִּשְׂרָה (נ\"א המעשר) שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְּׁמוֹ, שֶׁהִיא אוֹת ה\"א, שֶׁבּוֹ נִבְרָא הָעוֹלָם.","וְתַנְיָא אָמַר רַבִּי יוֹחָנָן מטטרון שַׂר הַפָּנִים שֶׁהוּא נַעַר עֶבֶד מֵרַבּוֹ הָאָדוֹן הַמּוֹשֵׁל עָלָיו, מְמוּנֶּה עַל הַנְּשָׁמָה בְּכָל יוֹם לְהַסְפִּיק לָהּ מֵאוֹתוֹ הָאוֹר שֶׁנִּצְּטַוָּה, והוּא עָתִיד לְמֵיסַב חוּשְׁבַּן פִּתְקָא בְּבָתֵּי קִבְרֵי מִן דּוּמָה וּלְאַחֲזָאָה לֵיהּ קַמֵּי מָארֵיהּ, והוּא זַמִּין לְמֶעְבַּד חָמִיר הַהוּא גַּרְמָא תְּחוֹת אַרְעָא לְתַקָּנָא לְגוּפַיָיא וּלְקָיְימָא לוֹן בִּשְׁלֵימוּתָא דְּגוּפָא בְּלָא נִשְׁמָתָא (בזמנא) דְּקוּדְשָׁא בְּרִיךְ הוּא יְשַׁדַּר לָהּ לְאַתְרָהּ.","אָמַר רַבִּי יִצְּחָק בְּאוֹתָהּ שָׁעָה מַה כְּתִיב, וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ זְקַן בֵּיתוֹ הַמּוֹשֵׁל וְגו'. מַהוּ אֶל עַבְדּוֹ, אִי בְּחָכְמְתָא דָא נִסְתַּכֵּל מַהוּ אֶל עַבְדּוֹ. אָמַר רַבִּי נְהוֹרָאי לֹא נִסְתַּכֵּל אֶלָּא בַּמֶּה שֶׁאָמַר עַבְדּוֹ, עַבְדּוֹ שֶׁל מָקוֹם. (זקן ביתו) הַקָּרוֹב לַעֲבוֹדָתוֹ, וּמַאן אִיהוּ, זְה מטטרו\"ן כִּדְקָאֲמָרָן, דְּאִיהוּ עָתִיד לְיַפּוֹת לַגּוּף בְּבָתֵּי קִבְרֵי.","הֲדָא הוּא דִכְתִיב וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ, זְה מטטרון עַבְדּוֹ שֶׁל מָקוֹם. (קפא א) זְקַן בֵּיתוֹ, שֶׁהוּא תְּחִלַּת בְּרִיּוֹתָיו שֶׁל מָקוֹם. הַמּוֹשֵׁל בְּכָל אֲשֶׁר לוֹ, שֶׁנָּתַן לוֹ קוּדְשָׁא בְּרִיךְ הוּא מֶמְשָׁלָה עַל כָּל צִבְאוֹתָיו.","וְתָאנָא אָמַר רַבִּי שִׁמְעוֹן אָמַר רַבִּי יוֹסֵי אָמַר רַב, כָּל צִּבְאוֹתָיו שֶׁל אוֹתוֹ עֶבֶד נוֹטְלִים אוֹר ונֶהֱנִין מִזִּיו הַנְּשָׁמָה, דְּתָאנָא אוֹר הַנְּשָׁמָה לָעוֹלָם הַבָּא גָּדוֹל מֵאוֹר הַכִּסֵּא. והָא מֵהַכִּסֵּא נִטְלָה הַנְּשָׁמָה. אֶלָּא זְה לְפִי הָרָאוּי לוֹ וְזֶה לְפִי הָרָאוּי לוֹ. רַב נַחְמָן אָמַר גָּדוֹל מֵאוֹר הַכִּסֵּא מַמָּשׁ דִּכְתִיב, (יחזקאל א׳:כ״ו) דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמַעְלָה, מַאי עָלָיו עַל זָהֳרוֹ.","וּכְשֶׁהוּא הוֹלֵךְ לַעֲשׂוֹת שְׁלִיחוּתוֹ כָּל צִּבְאוֹתָיו וְהַמֶּרְכָּבָה שֶׁלּוֹ נִזּוֹנִין מֵאוֹתוֹ הַזּוֹהַר. הֲדָא הוּא שֶׁהַנְּשָׁמָה אוֹמֶרֶת לוֹ (דכתיב) שִׂים נָא יָדְךָ, כְּלוֹמַר סִיעָתְךָ, תַּחַת יְרֵכִי, זְהוּ אוֹר הַנִּשְׁפַּע מִן הַנְּשָׁמָה עֲלֵיהֶם.","אָמַר רַבִּי יְהוּדָה בְּרַבִּי שָׁלוֹם כָּךְ קִבַּלְנוּ בְּשָׁעָה שֶׁזֶּה הוֹלֵךְ בִּשְׁלִיחוּתוֹ שֶׁל מָקוֹם, קוּדְשָׁא בְּרִיךְ הוּא מֵנִיעַ כָּל צִּבְאוֹתָיו שֶׁל מַעְלָה בְּאוֹת אַחַת מִשְׁמוֹ. אָמַר רַב הוּנָא כָּךְ יְרֵכִ\"י בְּגִימַטְרִיָּא רָ\"ם. כְּלוֹמַר הַנְּשָׁמָה אוֹמֶרֶת שִׂים נָא יָדְךָ סִיעָתְךָ תַּחַת מַעֲלָתוֹ שֶׁל רָם ונִשָּׂא הַמּוֹשֵׁל עַל הַכֹּל וּלְאַחַר שֶׁצִּוָּה סִיעַת עֶלְיוֹנִים תַּחַת יָדוֹ אֲנִי מַשְׁבִּיעֲךָ שְׁבוּעָה גְדוֹלָה בּוֹ.","אָמַר רַבִּי יִצְּחָק אֱלהֵי הַשָּׁמַיִם וִאלהֵי הָאָרֶץ. הוֹאִיל וְאָמַר בְּיְיָ שֶׁהוּא הַכֹּל, לָמָּה נֶאֱמַר אֱלֹהֵי הַשָּׁמַיִם, אָמַר רַבִּי יְהוּדָה שֶׁהוּא אָדוֹן עַל הַכֹּל, בְּבַת אַחַת וּבְרֶגַע אֶחָד הוּא מֵנִיעַ לַכֹּל וְכֻלָּם כְּאַיִן נְגְדוֹ. רַבִּי יִצְּחָק אוֹמֵר עַל שְׁתַּיִם אוֹתִיּוֹת מִשְּׁמוֹ לְהוֹרוֹת שֶׁהוּא הַכֹּל ואֵין אַחֵר בִּלְתּוֹ:","וְאַשְׁבִּיעֲךָ בַּיְיָ אֱלֹהֵי הַשָּׁמַיִם וִאלֹהֵי הָאָרֶץ. אָמַר רַב הוּנָא וְאִי הֲוִינָא עִמְּהוֹן דְּמָארֵי מַתְנִיתָּא כַּד גִּלּוּ רָזָא דְּנָא לָא אִיפְרַשְׁנָא מִנְּהוֹן הָכִי, דְּהָא אֲנָא חָזֵי עֲמִיקִין סַגִּיאִין בְּפוּמַיְיהוּ דְּגָלוּ וְלָא אִתְחַזְּיָין לְכָל אֵינִישׁ. תָּא חֲזֵי, שְׁבוּעַת קְיָימָא דָא אוֹמֵי לָהּ נִשְׁמָתָא דִּכְתִיב אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי.","אָמַר רַבִּי יִצְּחָק מֵהָכָא מַשְׁמַע שֶׁהוֹאִיל וְאַתָּה הוֹלֵךְ בִּשְׁלִיחוּת זֶה לֹא תִקַּח אִשָּׁה לִבְנִי, כְּלוֹמַר שֶׁלֹּא תִקַּח גּוּף לִבְנִי (ד\"א לבנייני) לִיכָּנֵס בְּגוּף אַחֵר בְּגוּף זָר בְּגוּף שֶׁאֵינוֹ רָאוּי לוֹ, אֶלָּא בְּהַהוּא מַמָּשׁ שֶׁהוּא שֶׁלִּי, בְּהַהוּא מַמָּשׁ שֶׁיָּצָּאתִי מִמֶּנּוּ, הֲדָא הוּא דִכְתִיב כִּי אִם אֶל אַרְצִּי וְאֶל מוֹלַדְתִּי תֵּלֵךְ.","אָמַר רַבִּי יוֹסֵי מַהוּ וְלָקַחְתָּ אִשָּׁה לִבְנִי לְיִצְּחָק. אָמַר רַבִּי יִצְּחָק אוֹתוֹ הַגּוּף שֶׁנִּצְּטָעֵר עִמִּי בְּאוֹתוֹ הָעוֹלָם, וְלֹא הָיָה לוֹ הֲנָאָה וְכִסּוּף בּוֹ מִפְּנֵי יִרְאַת קוֹנוֹ, אוֹתוֹ הַגּוּף מַמָּשׁ תִּקַּח לִיצְּחַק עִמּוֹ בְּהַאי שִׂמְחַת הַצַּדִּיקִים. לִיצַּחֵק עִמּוֹ בְּשִׂמְחַת הַקָּדוֹשׁ בָּרוּךְ הוּא, לִיצַּחֵק עִמּוֹ דְּעַכְשָׁיו עֵת שְׂחוֹק בָּעוֹלָם הֲדָא הוּא דִכְתִיב, (תהילים קכ״ו:ב׳) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וגו'.","אָמַר רַבִּי יְהוּדָה בַּר יִצְּחָק תָּא שְׁמַע אֵין מַלְאָךְ אֶחָד עוֹשֶׂה אֶלָא שְׁלִיחוּת אֶחָד, וְלֹא ב' שְׁלִיחוּת בְּבַת אַחַת. וְתַנְיָא אָמַר רַבִּי אַבָּא מַלְאָךְ אֶחָד אֲשֶׁר קֶסֶת הַסּוֹפֵר בְּמָתְנָיו עָתִיד לְהַרְשִׁים כָּל אֶחָד וְאֶחָד עַל מִצְּחוֹ, וּלְאַחַר כֵּן הַשַּׂר הַגָּדוֹל הוֹלֵךְ לְתַקֵּן כָּל אֶחָד וְאֶחָד וּלְהַעֲמִידוֹ לְקַבֵּל נִשְׁמָתוֹ, הֲדָא הוּא דִכְתִיב הוּא יִשְׁלַח מַלְאָכוֹ לְפָנֶיךָ וְלָקַחְתָּ אִשָּׁה, מַאי לְפָנֶיךָ לִפְנֵי שְׁלִיחוּתְךָ.","רַבִּי (אלעזר) אֱלִיעֶזֶר אֲזַל לְמֶחֱמֵי לְרַבָּן יוֹחָנָן בֶּן זַכַּאי רַבֵּיהּ, והַהוּא יוֹמָא רֵישׁ יַרְחָא הֲוָה, כַּד מָטָא גַבֵּיהּ","אָמַר לֵיהּ חַיָּיב אָדָם לְהַקְבִּיל פְּנֵי רַבּוֹ. אָמַר לֵיהּ לָאו עַל כָּךְ אֲמָרִית. אֶלָּא אֲנָא חָמֵי בְּאַנְפָּךְ דְּמִלָּה חַדְתָּא אִית גַּבָּךְ מֵאִינוּן עֲמִיקִים דְּאַתְּ עָתִיד לְמִתְבַּע.","אָמַר לֵיהּ, חָמֵינָא הַאי אוֹר הָרִאשׁוֹן דְּמַטְלָנוֹי עֲשָׂרָה וּבַעֲשָׂרָה נָטִיל, וּבְרָזָא דַעֲשָׂרָה נָהִיג לְכֹלָּא, וּבְאַתְוָותָא דַּעֲשָׂרָה עָבִיד עוֹבָדוֹי. וְתָאנָא עֲשָׂרָה פִּתְקִין עֲשָׂרָה מַפְתְּחָן דְּבֵי קַצְּרֵי בִּידוֹי, וּפִתְקִין עֲשָׂרָה נָטִיל בְּגִינְתָא דְעֵדֶן לְאַתְקָנָא אַרְעָא עַל גּוּפֵיהוֹן דְּצַּדִּיקַיָּא.","אָמַר לֵיהּ אֱלִיעֶזֶר בְּרִי חָמִית הֲוִית יַתִּיר מִמַּלְאָכָא קַדִּישָׁא דְּעַלְמָא, בַּעֲשָׂרָה אִתְבְּרֵי, בַּעֲשָׂרָה אִתְנְהִיג. בַּעֲשָׂרָה כֻּרְסְיָיא קַדִּישָׁא, בַּעֲשָׂרָה אוֹרַיְיתָא, הוּא בַּעֲשָׂרָה מַטְלָנוֹי, בַּעֲשָׂרָה עַלְמִין עִלָּאִין (בעשרה) וְחַד עִלָּאָה עַל כֹּלָּא בְּרִיךְ הוּא.","וְאֵימָא לָךְ מִלָּה דַּעְתֵּיהּ דְּמָארֵי דְּמַתְנִיתָּא הֲוָה בְּהַאי מַה כְּתִיב וַיִּקַּח הָעֶבֶד עֲשָׂרָה גְמַלִּים מִגְּמַלֵּי אֲדֹנָיו וַיִּלֶךְ. אָמַר לֵיהּ רִבִּי זָכִינָא לִפְסוּקָא דָא, אֲבָל וְכָל טוּב אֲדֹנָיו בְּיָדוֹ מַהוּ. אָמַר לֵיהּ הוּא שְׁמֵיהּ דְּמָארֵיהּ דְּאָזִיל גַּבֵּי לְאֲעָלָא לֵיהּ וּלְאַנְהָגָא (ולאגנא) לֵיהּ, אָמַר דָּא וַדַּאי הוּא כִּי שְׁמִי בְּקִרְבּוֹ.","תְּנַן אָמַר רַבִי אַבָּהוּ תָּא חֲזֵי, מַאן דְּיָדַע שְׁמֵיהּ עַל בּוּרְיֵיהּ, יָדַע דְּהוּא וּשְׁמֵיהּ חַד הוּא, קוּדְשָׁא בְּרִיךְ הוּא וּשְׁמֵיהּ חַד דִּכְתִיב, (זכריה יד) יְיָ אֶחָד וְגו' (כלהו) כְּלוֹמַר הַשֵּׁם וְהוּא אֶחָד.","אָמַר רַבִּי אַבָּא אִית לְאִסְתַּכָּלָא בְּפָרְשָׁתָא דָא: וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמַּיִם. אָמַר רַבִּי אַבָּא מִחוּץ לָעִיר, דָּא הוּא בֵּי קִבְרֵי. אֶל בְּאֵר הַמָּיִם, דְּתַנְיָא הַנִּקְדָּמִים בְּבָתֵּי קִבְרֵי אוֹתָם שֶׁנָּשְׂאוּ וְנָתְנוּ בַּתּוֹרָה, דְּהָא תְּנַן כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר מַה דְּשָׁאֲלוּ לֵיהּ תְּחִילָּה אִם קָבַע עִתִּים לַתּוֹרָה דִּכְתִיב, (ישעיהו ל״ג:ו׳) והָיָה אֱמוּנַת עִתֶּךָ וְגו'. וּכְשֶׁיֵּצֵּא אֵינוֹ דִּין (לקיימם) לַהֲקִימָם בַּתְּחִלָּה.","אָמַר רַבִּי אַבָּא לְעֵת עֶרֶב זֶהוּ יוֹם שִׁשִּׁי שֶׁהוּא עֶרֶב הַשַּׁבָּת שֶׁאָז הַזְּמַן לְקָיְימָא מֵתַיָּיא, מַאי מַשְׁמַע דִּתְנַן שִׁיתָּא אַלְפֵי שְׁנִין הֲוִי עַלְמָא, והוּא אֶלֶף הַשִּׁשִּׁי שֶׁהוּא סִיּוּם הַכֹּל, וְהַיְינוּ לְעֵת עֶרֶב, זְמַן סִיּוּם הַכֹּל. לְעֵת צֵּאת הַשּׁוֹאֲבוֹת, אֵלּוּ הֵם תַּלְמִידֵי חֲכָמִים הַשּׁוֹאֲבִים מֵימֶיהָ שֶׁל תּוֹרָה שֶׁהוּא עֵת לָצֵּאת וּלְהִתְנַעֵר מִן הֶעָפָר.","וְאֲמַר רַבִּי אַבָּא עוֹד יִשׁ לָדַעַת דִּתְנַן אוֹתָם הַמִּתְעַסְּקִים לָדַעַת אֶת בּוֹרְאָם בָּעוֹלָם הַזֶּה וְנִשְׁמָתָם בְּתַשְׁלוּמָהּ לָעוֹלָם הַבָּא זָכוּ לָצֵּאת מִשְּׁבוּעוֹת הַנְּשָׁמָה הוֹלֵךְ לָדַעַת מִי הוּא גוּפָהּ מַמָּשׁ וּמַאי הוּא. הִנֵּה אָנֹכִי נִצָּב עַל עֵין הַמָּיִם אַף עַל גַּב שֶׁתַּלְמִיד חָכָם הוּא הוֹלֵךְ אַחַר הַתַּשְׁלוּם, דִּכְתִיב וְהָיָה הָעַלְמָה הַיּוֹצֵּאת לִשְׁאוֹב וְאָמַרְתִּי אֵלֶיהָ הַשְׁקִינִי נָא מְעַט מַיִם מִכַּדֵּךְ אֱמוֹר לִי רֶמֶז יְדִיעָתוֹ מִמַּה שֶּׁהִשַּׂגְתָּ.","וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה, אַף אַתָּה עֶבֶד (כמוך) כָּמוֹנִי וְלֹא נִתְחַלֵּף לִי (על) יְדִיעָתְךָ בִּידִיעָתוֹ שֶׁל מָקוֹם בָּרוּךְ הוּא, וְצָּרִיךְ אַתָּה לְהַשִּׂיג שֶׁאַתָּה נִבְרָא כָּמוֹנִי.","וְגַם לִגְמַלֶּיךָ אֶשְׁאָב, כְּלוֹמַר יְדִיעַת הַשָּׂגָתִי שֶׁלא הִשִּׂיגוּ סִיעָתְךָ, וְיָדַעְתִּי כִּי מַעֲלָה יִשׁ לִי עָלֶיךָ והֵיאַךְ נִבְרָא אַתָּה מִזִּיו הַנָּתוּן אֶצְּלְךָ. אִם הוּא אוֹמֵר סִימָן זֶה יְהִי מָסוּר בְּיָדִי עַל כָּל דְּבָרִים אֵלּוּ, וְאֵדַע שֶׁהִיא הָאִשָּׁה הוּא הַגּוּף מֵאוֹתָהּ הַנְּשָׁמָה הַשְּׁבוּעָה שֶׁהִשְׁבִּיעַנִי:","וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְגו'. רִבִּי יִצְּחָק אָמַר רִבִּי יְהוּדָה בְּעוֹד שֶׁכָּל הָעִנְיָינִים הוּא רוֹצֶּה לְנַסּוֹת עַל הַגּוּף, מַאי כְּתִיב וְהִנֵּה רִבְקָה יוֹצֵּאת, זֶהוּ הַגּוּף קָדוֹשׁ שֶׁנִּתְעַסָּק בְּדִּבְרֵי תּוֹרָה וְכִתֵּת גּוּפוֹ לְהַשִּׂיג וְלָדַעַת אֶת קוֹנוֹ. אֲשֶׁר יָלְדָה לִבְתוּאֵל, אָמַר רַב יְהוּדָה בִּתּוֹ שֶׁל אֵל. בֶּן מִלְכָּה, בֶּן מַלְכָּהּ שֶׁל עוֹלָם. אֵשֶׁת נָחוֹר אֲחִי אַבְרָהָם. חֶבְרַת הַשֵּׂכֶל גּוּף שֶׁנִּדְבַּק בַּשֵּׂכֶל וְהִיא אָח הַנְּשָׁמָה. וְכַדָּהּ עַל שִׁכְמָהּ, מַשָּׂא הַחָכְמָה עָלֶיהָ.","ויָּרָץ הָעֶבֶד לִקְרָאתָהּ. זְה מטטרו\"ן. וַיֹּאמֶר הַגְּמִיאִינִי נָא מְעַט מַיִם מִכַּדֵּךְ, אֱמוֹר לִי רֶמֶז חָכְמָתָא בִּידִיעַת בּוֹרְאֵךְ מִמַּה שֶּׁעָסַקְתְּ בָּעוֹלָם שֶׁיָּצָּאת מִמֶּנּוּ. אָמַר רִבִּי אַבָּא כִּדְפָרְשִׁינָן, אַחַר כָּל זֶה מַה כְּתִיב ואָשִׂים הַנֶּזֶם עַל אַפָּהּ וְהַצְּמִידִים עַל ידֶיהָ. אָמַר רַבִּי אַבָּא אוֹתָם הָעֲצָּמוֹת שֶׁנִּפְזְרוּ לְכָאן וּלְכָאן, הוּא צּוֹמֵד אוֹתָם וְשׁוֹקְלָם זֶה עַל זְה כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ״ח:י״א) וְעַצְּמוֹתֶיךָ יַחְלִיץ. אָמַר רִבִּי אַבָּא בְּאוֹתָהּ שָׁעָה אוֹתוֹ הַגּוּף עוֹמֵד בְּאֶרֶץ יִשְׂרָאֵל וְשָׁם נִכְנַס בּוֹ נִשְׁמָתוֹ.","אָמַר רִבִּי יוֹחָנָן מִי מוֹלִיךְ הַגּוּף לְאֶרֶץ יִשְׂרָאֵל, אָמַר רִבִּי זֵירָא קוּדְשָׁא בְּרִיךְ הוּא עוֹשֶׂה מְחִילוֹת תַּחַת הָאָרֶץ וְהֵם מִתְגַּלְגְּלִים וְהוֹלְכִים לְאֶרֶץ יִשְׂרָאֵל הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) ואֶרְץ רְפָאִים תַּפִּיל.","אָמַר רִבִּי יִצְּחָק גַּבְרִיאֵ\"ל מוֹלִיךְ אוֹתָם לְאֶרֶץ יִשְׂרָאֵל, מְנָא לָן דִּכְתִיב, (בראשית כ״ד:נ״ח) הֲתֵלְכִי עִם הָאִישׁ הַזְּה, וּכְתִיב הָתָם (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל. אָמַר רִבִּי יוֹסֵי מַאי דִכְתִיב וּלְרִבְקָה אָח וּשְׁמוֹ לָבָן. אָמַר רַבִּי יִצְּחָק אֵין יִצֶּר הָרָע בָּטֵל מִן הָעוֹלָם, אַף עַל פִּי שֶׁכֻּלּוֹ לֹא נִמְצָּא קְצָּתוֹ נִמְצָּא.","תָּא חֲזֵי, בַּתְּחִלָּה כְּשֶׁהָיָה מוּטָל בָּעוֹלָם הַזֶּה נִקְרָא לוֹט, לָעוֹלָם הַבָּא (יבדל) יִבָּטֵל מִן הָעוֹלָם, אֲבָל (לעתיד לבא) לא כּוּלּוֹ, ונִקְרָא לָבָן לא מְנוּוָל כְּבָרִאשׁוֹנָה אֶלָּא כְּמַאן דְּסָחֵי מִנִּוּוּלוֹ. לָבָן לְמַאי אִצְּטְרִיךְ. אָמַר רַבִּי שִׁמְעוֹן לְמֶעְבַּד פְּרִיָּה וּרְבִיָּה אִצְּטְרִיךְ, דְּאָמַר רַבִּי שִׁמְעוֹן אִם אֵין יֵצֶּר הָרָע נִמְצָּא, פְּרִיָּה וּרְבִיָּה אֵינוֹ מָצּוּי.","תָּא שְׁמַע כֵּיוָן שֶׁהַגּוּף נִבְנָה וְעוֹמֵד בְּקִיּוּמוֹ, מַאי כְּתִיב וַיְשַׁלְּחוּ אֶת רִבְקָה אֲחוֹתָם וְגו'. מַאי (הוי) וְאֶת מֵנִיקְתָּהּ, זֶה כֹּחַ הַתְּנוּעָה. רִבִּי יִצְּחָק אָמַר זְה כֹּחַ הַגּוּף.","רִבִּי אַבָּהוּ פָּתַח בְּהַאי קְרָא (שיר השירים ד׳:ח׳) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי מִלְּבָנוֹן תָּבֹאִי וגו', אָמַר רִבִּי אַבָּהוּ כֵּיוָן שֶׁהַגּוּף נִבְנֶה עַל קִיּוּמוֹ וּמְבִיאִין אוֹתוֹ לְקַבֵּל נִשְׁמָתוֹ לְאֶרֶץ יִשְׂרָאֵל, הַנְּשָׁמָה מַמְתֶּנֶת אֵלָיו וְיוֹצֵּאת לִקְרָאתוֹ כְּמָה דְאַתְּ אָמֵר וַיֵּצֵּא יִצְּחָק לָשׂוּחַ בַּשָּׂדֶה. הֲדָא הוּא דִכְתִיב אִתִּי מִלְּבָנוֹן כַּלָּה. זוֹ הִיא הַנְּשָׁמָה. תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה, הַיְינוּ דִכְתִיב וַיִּשָּׂא עֵינָיו וַיַּרְא.","אָמַר רַבִּי יְהוּדָה אִם הִיא הַנְּשָׁמָה, תֵּינַח אַבְרָהָם כִּדְקָאֲמָרָן, אֲבָל יִצְּחָק מַהוּ. אָמַר רַבִּי אַבָּהוּ הָא חַבְרַיָּיא אָמְרוּ דְּעַכְשָׁיו אִתְקְרֵי יִצְּחָק עַל שׁוּם חֶדְוָותָא סַגִּיאָה דִּבְעָלְמָא.","אָמַר רַבִּי אַבָּהוּ בַּתְּחִלָּה נִקְרֵאת הַנְּשָׁמָה אַבְרָהָם וְהַגּוּף שָׂרָה, עַכְשָׁיו נִקְרֵאת הַנְּשָׁמָה יִצְּחָק וְהַגּוּף רִבְקָה. תְּנַן בְּמַתְנִיתִין, אָמַר רַבִּי שִׁמְעוֹן אַרְבָּעִים שָׁנָה קוֹדֶם קִיּוּם הַגּוּף מַמְתֶּנֶת הַנְּשָׁמָה לַגּוּף בְּאֶרֶץ יִשְׂרָאֵל. בְּאֵיזֶה מָקוֹם בְּמָקוֹם הַמִּקְדָּשׁ.","אָמַר רַבִּי אַבָּהוּ תָּא חֲזֵי, וַיִּקַּח אֶת רִבְקָה וַתְּהִי לוֹ לְאִשָּׁה וַיְּאֱהָבֶהָ וַיִּנָּחֵם יִצְּחָק אַחֲרֵי אִמּוֹ. אוֹהֵב לְאוֹתוֹ הַגּוּף וּמִתְנַחֵם עִמּוֹ, והוּא עֵת לִשְׂחוֹק וְהַחֶדְוָה בָּעוֹלָם.","אָמַר רִבִּי יְהוּדָה הָא כָּל פָּרְשָׁתָא דָא אִתְבְּרַר לָן, אֲבָל לָא יָכִילְנָא לְמִנְדַע מַהוּ: וַיּוֹסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. וּלְשִׁקּוּלָא דְדַעְתָּא כָּל פָּרְשָׁתָא דָא לִיסְתּוּרֵי.","כַּד אֲתָא רַב דִּימִי, אָמַר, הַאי פָּרְשָׁתָא דָא שָׁמַעְנָא וְלָא אִדְכַּרְנָא, אָמְרוּ דְּעִלָּאִין תַּקִּיפִין לָא זִמְנוּהָ לְגַלָּאָה ואֲנַן מַאי נֵימָא. קָם רִבִּי יְהוּדָה וְאָמַר מִמְתִיבְתָּא דְּחַבְרָנָא מָארֵי מַתְנִיתָּא גַּלְיָא.","קָמוּ וְאֲזְלוּ הוּא ורִבִּי יִיסָא וְרִבִּי חִיָּיא, אַשְׁכְּחוּהָ לְרִבִּי אֶלְעָזָר בְּרִבִּי שִׁמְעוֹן וְהֲוָה מְגַלֶּה רָזִין דִּתְפִילִּין. עָאלוּ קַמֵּיהּ וְאָמְרוּ בְּמַאי אִתְעַסַּק מַר. אָמַר לוֹן טַעְמָא דִתְפִילִּין אֲמִינָא, דְּהָא זַכָּאָה הוּא בַּר נָשׁ דְּמָנַח תְּפִילִּין וְיָדַע טַעְמָא דִידְהוּ.","אָמְרוּ אִי נִיחָא קַמֵּיהּ דְּמַר לֵימָא לָן מִלָּה. אָמְרוּ שְׁמַעְנָא מֵאֲבוּךְ דְּקוּדְשָׁא בְּרִיךְ הוּא בִּרְחִימוּ סַגִּיאָה דְּהֲוָה לֵיהּ עִם יִשְׂרָאֵל אָמַר לוֹן לְמֶעְבַּד לֵיהּ בֵּי מַשְׁכְּנָא כְּגַוונָא דִּרְתִיכָא עִלָּאָה דִלְעֵילָא וְיֵיתֵי דִיּוּרֵיהּ עִמְּהוֹן הֲדָא הוּא דִכְתִיב, (שמות כ״ה:ח׳) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְשָׁמַעְנָא מֵאֲבוּךְ דְּהָכָא סָתִים טַעְמָא דִּתְפִילִּין בְּהַאי פְּסוּקָא.","אָמַר לֵיהּ תָּא חֲזִי, כְּגַוְונָא עִלָּאָה אִתְעֲבַד מִקְדָּשׁ בִּרְתִיכוֹי קַדִּישִׁין, וּבָתַר כֵּן אַשְׁרֵי קוּדְשָׁא בְּרִיךְ הוּא דִּיּוּרֵיהּ עִמְּהוֹן, כְּעִנְיָינָא דָא, וּכְגַוונָא דָא אִתְעָרוּ חַבְרַיָּיא מָארֵי מַתְנִיתָּא בְּטַעְמָא דִּתְפִלִּין, לְמֶהֱוִי הַהוּא גַבְרָא דּוּגְמָא דִרְתִיכֵי עִלָּאִין, רְתִיכָא תַּתָּאָה רְתִיכָא עִלָּאָה, לְמֵיתֵי מַלְכוּתָא דִילֵיהּ וְיַשְׁרֵי דִּיּוּרֵיהּ עִלָוִיה.","וְתָנִינָן אִית בֵּיהּ רָזִין עִלָּאִין וְדוּגְמֵיהוֹן, וְאִית בֵּיהּ תְּלַת רְתִיכִין, דּוּגְמַת עִלָּאִין קַדִּישִׁין רָזִין דִּתְלַת אַתְוָותָא דִּשְׁמָהָן קַדִּישֵׁי, עָלְמִין תְּלַת, רְתִיכִין תְּלָתָא אַתְוָותָא, אַרְבַּע פָּרָשִׁיּוֹת שַׁלִּיט עַל אַרְבַּע, וְעַל כָּךְ רָזָא דְשי\"ן דִּתְלַת כִּתְרִין, ושי\"ן דְּאַרְבַּע כִּתְרִין, תְּלָתָא מְלָכִין שַׁלִּיטִין בְּגוּפָא תְּפִילִּין עֲלוֹי קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא, אִלֵּין תְּפִילִּין דְּרֵישָׁא, תְּפִילִּין דִּדְרוֹעָא אַרְבַּע פָּרָשִׁיָּין.","לִבָּא רָכִיב דּוּגְמָא דִּרְתִיכָא תַּתָּאָה וְתַתָּאָה רָכִיב. עוֹד תָּנִינָן דָּא רְכִיבָא דִּדְרוֹעָא לְתַתָּא. וְלִבָּא רָכִיב, דּוּגְמָא דְּאִיהוּ לְתַתָּא וְאִתְמַסְּרוּן בִּידֵיהּ לְאַעֲלָאָה לוֹן כָּל חֵילֵי שְׁמַיָא, כָּךְ לִבָּא הוּא רָכִיב לְתַתָּא ואִתְמַסְּרוּ בִּידוֹי כָּל אֵבְרֵי גוּפָא.","וְעֵילָא מִנִּיהּ אַרְבָּע פָּרָשִׁיָּין עַל מוֹחָא דְרֵישָׁא אִיהוּ, אֲבָל קוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיטָא עִלָּאָה מַלְכָּא מִכֹּלָּא. (ורוח) ורָזָא דְחָכְמְתָא דָא, הוּא כְּגַוונָא דְמַקְדְּשָׁא דִּכְתִיב וַעֲשֵׂה כְּרוּב אֶחָד מִקָּצָּה מִזֶּה וּכְרוּב אֶחָד מִקָּצָּה. וְעֲלַיְיהוּ דִּיּוּרֵיהּ דְּמַלְכָּא בְּאַרְבַּע אַתְוָון תְּרֵין רְתִיכִין.","וּכְהַאי גַוונָא לִבָּא וּמוֹחָא, לִבָּא מִכָּאן וּמוֹחָא מִכָּאן וְעֲלַיְיהוּ מְדוֹרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּאַרְבַּע (ד\"א ארבע) פָּרָשִׁיָּין. אָמַר רַבִּי אֶלְעָזָר מִכָּאן וּלְהָלְאָה רָזֵי דְּכִתְרֵי אַתְוָותָא וּפָרָשִׁיָּין בְּגוּפַיְיהוּ וּרְצּוּעוֹתֵיהוֹן. הֲלָכָה לְמשֶׁה מִסִּינַי וּרְמִיזָא דִלְהוֹן אִתְגְּלִי וְטַעְמָא דְּכֹלָּא בִּתְלַת עֶשֶׂר מְכִילָן (דרחמי).","אָמַר רִבִּי יְהוּדָה אִלְמָלֵא לָא אָתֵינָא אֶלָּא בְּדִיל רָזָא דָא דַּיַּי. אָמְרוּ לֵיהּ זַכָּאָה חוּלָקָךְ לְעַלְמָא דְאָתֵי דְּכָל רָז לָא אָנִיס לָךְ. אָמְרוּ לֵיהּ אָתֵינָא קַמֵּיהּ דְּמַר לְמִנְדַע רָזָא דְהַאי פְּסוּקָא וַיּוֹסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה.","אָמַר פֵּירוּשָׁא דְהַאי פְּסוּקָא כְּמָה דְגָלוּ חַבְרָנָא מָארֵי מַתְנִיתִין, דְּכַד נִשְׁמָתָא יֵיתֵי בְּהַהוּא גוּפָא קַדִּישָׁא דִילָהּ, הָא מִילַיָּיא הֲווּ עַל חַיָּיבַיָא דִּיקוּמוּן ויִכְשְׁרוּן עוֹבָדִין וְיִתֵּן לְהוּ מִזִּיוָא יְקָרָא דִילֵיהּ דְּיִנְדְּעוּן וִיתוּבוּן וְיִזְכּוּן זְכוּתָא שְׁלֵימָתָא.","וְכַד חָמָא שְׁלמֹה דָא הֲוָה סַגֵּי (ד\"א תוה סגי) וְאָמַר (קהלת ח׳:י׳) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים ובָאוּ וּמִמְקוֹם קָדוֹשׁ יְהַלֵּכוּ, שֶׁיָּבֹאוּ וְיִחְיוּ מִמְקוֹם קָדוֹשׁ. ותָנִינָן אָמַר רַבִּי אַבָּא אָמַר רַבִּי יוֹחָנָן כְּתִיב, (ירמיה ג) הֲיַהֲפֹךְ כּוּשִׁי עוֹרוֹ וְנָמֵר חֲבַרְבֻּרֹתָיו, כָּךְ הָרְשָׁעִים שֶׁלא זָכוּ לָשׁוּב בָּעוֹלָם הַזֶּה וּלְהַקְטִיר מַעֲשִׂים טוֹבִים לָעוֹלָם, לא יַקְטִירוּ בָּעוֹלָם הַבָּא. רְאֵה מַה כְּתִיב וַיּוֹסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה, וְשֶׁרוֹצֶּה לַעֲשׂוֹת לָהֶם נְשָׁמָה לְגוּפָם וּלְקַרְבָם בִּתְשׁוּבָה, כְּמָא דְאַתְּ אָמֵר וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן.","אָמַר רִבִּי אֶלְעָזָר תָּא חֲזֵי, מַה כְּתִיב ותֵּלֶד לוֹ אֶת זִמְרָן וְאֶת יָקְשָׁן, הַרְבֵּה מַעֲשִׂים רָעִים עַד שֶׁנִּגְרָשִׁים מִן הָעוֹלָם דִּכְתִיב וַיְשַׁלְּחֵם מֵעַל יִצְּחָק בְּנוֹ. וַעֲלֵיהֶם נְאֱמַר (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנֵי אַדְמַת עָפָר יָקִיצּוּ וְגו', וְעַל הָאֲחֵרִים נֶאֱמַר וְהַמַּשְׂכִּילִים יַזְהִירוּ כְּזהַר הָרָקִיעַ וגו'.","אָמַר רִבִּי יְהוּדָה הַאי מַשְׁמַע עַל פָּרְשָׁתָא, וּמַשְׁמַע דְּאוֹתוֹ זְמַן (נקרא) (ס\"א אבד) עֲבַד שֵׁם (הנשמה) אַבְרָהָם, וּבִמְקוֹמוֹ נִקְרֵאת יצְּחָק כִּדְקָאֲמָרָן, הֲדָא הוּא דִכְתִיב ויְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְּחָק בְּנוֹ, וַיִּשֶׁב יִצְּחָק עִם בְּאֵר לַחַי רֹאִי. עִם יְדִיעַת הַחַי שֶׁהוּא חַי הָעוֹלָמִים לָדַעַת וּלְהַשִּׂיג מַה שֶּׁלא הִשִּׂיג בָּעוֹלָם הַזֶּה הֲדָא הוּא דִכְתִיב, (ישעיהו י״א:ט׳) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ, (עד כאן מדרש הנעלם)","רִבִּי יִצְחָק פָּתַח וְאָמַר, (קהלת י״ב:ז׳) וְיָשֹׁב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לָאָדָם, נָטַל עֲפָרֵיהּ מֵאֲתַר דְּמַקְדְּשָׁא, וּבָנָה גוּפֵיהּ מֵאַרְבַּע סִטְרִין דְּעַלְמָא, דְּכֻלְּהוּ יָהֲבוּ לֵיהּ חֵילָא, לְבָתַר אִתְרַק עֲלֵיהּ רוּחָא דְחַיֵּי כְּמָא דְאַתְּ אָמֵר, (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וְגו' לְבָתַר קָם וְיָדַע דְּאִיהוּ מֵעֵילָא וְתַתָּא, וּכְדֵין אִתְדָּבַּק וְיָדַע חָכְמָה עִלָּאָה.","כְּגַוְונָא דָא כָּל בַּר נָשׁ דְּעַלְמָא אִיהוּ כָּלִיל מֵעֵילָא וְתַתָּא, וְכָל אִינוּן דְּיָדְעִין לְאִתְקַדְּשָׁא בְּהַאי עַלְמָא כְּדְקָא יְאוּת, כַּד אוֹלִידוּ בַּר, מָשְׁכִין עֲלֵיהּ רוּחַ קַדִּישָׁא מֵאֲתַר דְּכָל קַדִּישֵׁי נָפְקִין מִנֵּיהּ, וְאִלֵּין אִקְרוּן בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּגוּפָא אִתְעֲבִיד בִּקְדוּשָׁה כְּדְקָא יָאוֹת, הָכִי נָמֵי יָהֲבִין לֵיהּ רוּחָא מֵאֲתַר עִלָּאָה קַדִּישָׁא כְּדְקָא חָזֵי וְהָא אִתְּמַר.","תָּא חֲזֵי, בְּשַׁעְתָּא דְּזַמִּין בַּר נָשׁ לְמֵיהַב חוּשְׁבַּן עוֹבָדוֹי עַד לָא יִפּוּק מֵעַלְמָא, הַהוּא יוֹמָא, יוֹמָא דְּחוּשְׁבַּן אִיהוּ, דְּגוּפָא וְנִשְׁמָתָא יָהֲבֵי חוּשְׁבְּנָא. לְבָתַר נִשְׁמָתָא אִתְפָּרְשָׁא מִינֵיהּ, וְגוּפָא תָּב לְאַרְעָא, וְכֹלָּא תָּב לְאַתְרֵיהּ דְּאִתְנָסִיב מִתַּמָּן וְהָא אוּקְמוּהָ, עַד זִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לַאֲחָיָיא מֵתַיָיא כֹּלָּא גָּנִיז קַמֵּיהּ.","וְהַהוּא גּוּפָא מַמָּשׁ וְהַהִיא נִשְׁמָתָא מַמָּשׁ זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאֲתָבָא לְעַלְמָא כְּמִלְּקַדְמִין וּלְחַדְתָּא אַנְפֵּי עַלְמָא הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ נְבֵלָתִי יְקוּמוּן. וְהַהִיא נִשְׁמָתָא מַמָּשׁ גְּנִיזָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְתָבַת לְאַתְרָהּ כְּפוּם אָרְחָהָא כְּמָא דְאַתְּ אָמֵר וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. וּלְזִמְנָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָיא, זַמִּין אִיהוּ לְאֲרָקָא טַלָּא מֵרִישֵׁיהּ עֲלַיְיהוּ, וּבְהַהוּא טַלָּא יְקוּמוּן כֹּלָּא מֵעַפְרָא.","הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ. מַאי טַל אוֹרוֹת, אוֹרוֹת מַמָּשׁ מֵאִינוּן נְהוֹרִין דִּלְעֵילָא דִּבְהוֹן זַמִּין לַאֲרָקָא חַיִּין לְעַלְמָא, בְּגִין דְּאִילָנָא דְחַיֵּי יָרִיק חַיִּין דְּלָא פָּסְקִין לְעָלְמִין, דְּהָא הַשְׁתָּא פָּסְקִין בְּגִין דְּהָא חִוְיָא בִּישָׁא שָׁלְטָא וְאִתְכַּסֵּי סִיהֲרָא. וּבְגִין כָּךְ כִּבְ\"יָכוֹל פָּסְקִין מֵימוֹי וְחַיִּין לָא שָׁלְטִין בְּעַלְמָא כְּדְקָא יְאוּת."],[[0,"כגוונא דא כד וכו':","כעין זה הוא כשהנשמות יוצאות מהגוף מעולם הזה, דהיינו אחר הפטירה, הם מבקשים לעלות, וכמה שומרי הפתח, ומחנות מזיקים נמצאים, אם הם מן הצד שלהם, כולם אוחזים באלו הנפשות ומוסרים אותן ביד דומה להכניסם בגיהנם."],[1,"ולבתר סלקן וכו':","ואחר כך עולות מגיהנם, ואוחזות בהם, והם לוקחים אותן ומכריזים עליהן: אלו הן שעברו על מצות רבונן, וכן משוטטים עמהן בכל העולם. ואחר כך מחזירים אותן לגיהנם, וכן, עושים עמהן, דהיינו שמוציאים אותן מגיהנם ומכריזים וכו', ואח\"כ שוב מחזירים אותן וחוזר חלילה, עד שנים עשר חדשים. לאחר שנים עשר חודש הן משתככות, ובאות במקום הראוי להם. אבל אלו הנשמות הזוכות, עולות למעלה כמו שביארנו, וזוכות במקומותיהן."],[2,"ת\"ח זכאין וכו':","בוא וראה, אשריהם הצדיקים, שנצפן להם הרבה טוב לעולם ההוא, ואין מקום פנימי כל כך לכל אלו הצדיקים כמו אותם היודעים סוד רבונם, ויודעים להדבק בו בכל יום. על אלו כתוב, עין לא ראתה וכו'."],[3,"מאי למחכה לו וכו':","שואל למחכה לו מה פירושו. ואומר, הוא כמו שאתה אומר, חכה את איוב בדברים, ואלו הם הדוחקים להבין דבר חכמה, \u0003ומחכים\u0004 לה להבין ברורו של הדבר, ולדעת את רבונם, אלו הם שרבונם משתבח בהם בכל יום, אלו הם הבאים בין עליונים הקדושים, ואלו נכנסים בכל שערים העליונים, ואין מי שימחה בידיהם. אשרי חלקם בעולם הזה ובעולם הבא."],[4,"ת\"ח אברהם וכו':","בוא וראה, אברהם נכנס לדעת ולהתדבק ברבונו כראוי אחר שהקדים מעשים טובים מתחלה, וזכה באלו ימים העליונים ונתברך מן המקום שכל הברכות יוצאות משם, שכתוב, וה' ברך את אברהם בכל. מהו \u0003בכל,\u0004 הוא מקום הנהר שמימיו אינם פוסקים לעולם. דהיינו יסוד דאו\"א עלאין שזווגם לא פסיק לעלמין."],[5,"א\"ר חייא ת\"ח וכו':","אר\"ח, בוא וראה, כי אברהם לא רצה להתערב בנשי העולם, ולהתדבק בעמים האחרים עובדי ע\"ז, משום שנשיהם של עמים האחרים עובדי ע\"ז, הם מטמאים לבעליהן, ולאלו המתדבקים בהן. כי כשאברהם ידע חכמה, ידע העיקר והשורש ומאיזה מקום, יוצאים ומשוטטים רוחות הטומאה בעולם. ועל כן השביע את עבדו, שלא יקח אשה לבנו מעמים האחרים."],[6,"ואברהם זקן וגו': מתניתין:","אמר ר' אלעזר על כל פנים כך הוא, שמשנה זו יפה היא, שלמדנו, שאותו שכתוב בו, והנה אופן אחד וגו', נעשה נשמה. כמו שנאמר באותה משנה ראשונה. כלומר, אע\"פ שאופן בכל מקום הוא שם הנפש, מכל מקום אומרת המשנה, שהשם אופן שבכתוב זה חזר ונעשה נשמה, ואומר, שאין קושיא, ויפה היא, ולא פירש למה."],[7,"אמר ליה ר' אבא וכו':","א\"ל ר\"א, יאמר לנו אדוני, מאותו המשנה, מה היא. אמר לו, כך נתבאר במשנה, שסו\"ה אופן א' בארץ נעשה נשמה, בפרשה שלו, בי\"ג מדת הרחמים. אבל בפרשה זו שבכאן, יש לנו לבאר. פתח ואמר אחת היא יונתי תמתי אחת היא וגו' שמקרא זה רומז על הנשמה, אמר ר' אלעזר מה היא שכאן בשיר השירים אנו קוראים הנשמה בלשון נקבה, דהיינו יונתי תמתי וגו', ושם בתורה קוראים לה בלשון זכר, דהיינו אברהם."],[8,"אלא אמר ר' אלעזר וכו':","אלא אר\"א, כאן בהתורה נקרא הנשמה בלשון זכר, כלפי הגוף, מפני שהגוף בערך הנשמה הוא כערך אשה כלפי זכר. וכן הנשמה כלפי מדרגה עליונה ממנה, היא כנקבה בפני הזכר וכל אחד יורש מעלתו, לפי הענין. וע\"כ בשיר השירים, כשהמלך ששלום שלו, מדבר על הנשמה, שהוא מדרגה עליונה ממנה, ע\"כ נחשבת לו כמו נקבה, וקורא אותה בלשון נקבה יונתי תמתי וכו'. אבל בתורה, המדובר הוא בנשמה לפי עצמה. ע\"כ קורא אותה בלשון זכר, אברהם."],[9,"תנן התם בארבעה פעמים בשעה וכו', ושמנה וארבעים טפות מנטף בכל יום.","פירוש. כי י\"ב שעות הם ביום, וד' פעמים מנטף בכל שעה, ד\"פ י\"ב הרי מ\"ח טפות. מכאן עד אות קמ\"ז א\"צ ביאור."],[13,"ומשנגזרה גזרה שאבדה חכמת מצרים","היה זה מטעם. כי \u0003נטל קב\"ה אותם טפין וכו':\u0004 ומשנטלו אלו הטפות שלא יצאו מהגן אבדה החכמה ממצרים."],[14,"ומאותו הרוח שהיה יוצא מעדן המצו וכו':","המצו, הוא מלשון הכתוב, מי מלא ימצו למו (תהלים ע\"ג), דהיינו מציצה וסחיטה. עד אות קנ\"ב א\"צ ביאור."],[18,"ר' אבא סבא וכו':","שלמדנו במשנה ראשונה, כיון שהנשמה היא בתשלומה במקום העליון, אינה חוזרת עוד לגוף, אלא שנשמות אחרות נבראות ויוצאות ממנה, והיא נשארת במצבה. וכו' עד אות קנ\"ד א\"צ פירוש."],[20,"ואברהם זקן בא בימים:","רבי בו אמר ר' יוחנן, באותו העולם שהוא ימים דהיינו אור, ולא בעולם הזה שהוא לילה. פירוש. \u0003בא בימים\u0004 היינו ספירות העליונות שבעולם העליון שהם אורות, ונקראים ימים. אמר ר' יעקב, \u0003בא בימים,\u0004 פירושו שבא באותם העולמות שהם נבחנים לימים, מטעם אותם ההנאות והכסופין שהוא נוחל. ואינו חולק על ר' יוחנן אלא מבאר יותר."],[20,"וה' ברך את אברהם בכל: בכל,","היינו באותו המשרה, דהיינו השררה, שנתן לו הקב\"ה משמו, שהוא אות ה' שבו נברא העולם."],[21,"ותניא אר\"י וכו':","אר\"י, מטטרון שר הפנים, שהוא נער עבד מרבו האדון המושל עליו, הוא ממונה על הנשמה, להשפיע לה בכל יום מאותו אור שנצטוה להשפיע לה. והוא עתיד לקבל חשבון בכתב מבית הקברות, מיד דומה, מכל גוף וגוף, ולהראותו לפני אדונו. כמ\"ש לעיל (דף ד' ד\"ה כלהו ע\"ש) והוא עתיד לעשות אותו העצם \u0003לוז\u0004 שאור, לבנין הגוף, תחת הארץ ולתקן את הגוף ולהחיותו בשלמות הראוי אל גוף בלא נשמה, והקב\"ה ישלח אח\"כ הנשמה למקומה בגוף. והיינו אחר שבא לארץ ישראל כמ\"ש לפנינו."],[21,"","וצריכים להבין היטב כאן, ענין העצם הנשאר בהקבר ואינו נרקב, אשר אומר כאן, שהמלאך מטטרון עושה אותו שאור לבנין הגוף. והנה חז\"ל אמרו (מדה\"נ תולדות נ\"א.) שהעצם הזה נקרא לוז, ואינו נהנה ממאכל ומשקה, שהאדם אוכל ושותה, ועל כן אינו נרקב בקבר כשאר עצמות. וממנו חוזר ונבנה גוף האדם כשעומד לתחיית המתים. ויש להבין, למה נקרא לוז, ולמה אינו אוכל ושותה, ואינו נרקב בקבר, ומה יחוסו, שרק ממנו יבנה הגוף לעת התחיה."],[21,"","וכבר נתבאר שאלו המוחין מקבל בחייו, מסוד קו אמצעי, הם הגורמים לו להרקב בקבר, (כנ\"ל דף ד' ד\"ה פירוש) ובכדי שתבין זה היטב, אביא לך מענין יעקב ועשו. כי יעקב ה\"ס קו אמצעי, ועשו ה\"ס קו שמאל שאינו כלול מימין. וכתוב ויזד יעקב נזיד וגו' דהיינו המוחין הנמשכים מקו אמצעי שנקרא יעקב, ויבא עשו מן השדה והוא עיף וגו' ויאמר הלעיטני נא מן האדם האדם הזה וגו'. שרצה שקו האמצעי ישפיע לו המוחין שלו, אשר קו שמאל כלול בהם בימין, שמשם החיים כנודע. אבל יעקב אמר לו מכרה כיום בכורתך לי וגו'. כי נודע שהמוחין דחכמה נמשכים בקו שמאל, שה\"ס בכרה וגדלות, וע\"כ אינו רוצה להכלל בימין שהוא אור חסדים הקטן הרבה ממנו, אבל התחתונים אינם יכולים לקבל הארת השמאל מטרם התלבשותו בחסדים מקו ימין. וז\"ס שעשו היה עיף, וז\"ס שאמר הנה אנכי הולך למות ולמה זה לי בכרה. וע\"כ מכר לו הבכרה, וכן ויבז את הבכרה מחמת שהיה מוכרח לקבל מיעקב המוחין מהתכללות הימין. והנך מוצא שעם קבלת עשו את המוחין דקו אמצעי בטל את הבכרה שלו, שהוא הארת החכמה משמאל בלי ימין, ולא עוד אלא שביזה אותה. כי גילה דעתו שמהארת השמאל בא רק מות, כמ\"ש הנה אנכי הולך למות וגו', ומהארת קו אמצעי באים החיים. וכעין זה תקיש אל גוף האדם, כי כל גוף נפל תחת שליטת ס\"מ, שרו של עשו, בעת החטא דעץ הדעת, שמשם נגזר המיתה על הגוף, ושליטה זו ה\"ס הזוהמא דחויא, שאינה סרה מגוף מטרם שנרקב בקבר. ועל כן הצדיקים מטהרים את גופם הבא מכח השמאל עד שראוי לקבל את המוחין מקו האמצעי. ועם קבלת המוחין נמצא הגוף, שמבזה את הבכרה שלו כמו עשו. ורושם מביזוי הזה נשאר בגוף גם לאחר מיתה, עד שגורם לו רקבון, שפירושו, ביטול גמור של כל כח הקבלה שלו, עד שלא נשאר זכר ממנו, והבן היטב."],[21,"","אמנם לפי\"ז קשה, איך אפשר עוד שיקום לתחיית המתים. כיון שכבר נרקב. והענין הוא כמו שיש בקו שמאל ג\"ר וו\"ק, כן בגוף, שהוא המקבל ממנו, יש ג\"כ ג\"ר וו\"ק. וכן בעשו היה ג\"ר וו\"ק, דהיינו כלי לקבלת ג\"ר וכלי לקבלת ו\"ק. ונתבאר שהמוחין דקו אמצעי שקבל עשו, גרם לו לבזות את הבכרה, וכן גורמים לכל גוף שירקב בעפר, אמנם המוחין הבאים מקו אמצעי אינם אלא ו\"ק דג\"ר, ואין בהם כלום מג\"ר דג\"ר כנודע, ונמצא שרק הו\"ק של עשו ביזו את הבכרה, כי נתגלה על ידם שמקו שמאל בא המות ומקו אמצעי החיים. כנ\"ל, אבל הג\"ר של עשו, שלא קבלו כלום מהמוחין דיעקב, להיותם רק ו\"ק דג\"ר, א\"כ נשארו תחת שליטת השמאל, ולא בזו כלל את הבכרה, כי בין כך ובין כך מתו, כי קו אמצעי לא היה לו מה ליתן להם, ועל דרך זה הגופים של כל אדם, אשר מסבת המוחין שמקבלים בחיים הם נרקבים בקבר, זהו דוקא לבחינת הכלים דו\"ק של הגוף, שהם הנהנים מקו אמצעי, משא\"כ הכלים דג\"ר של הגוף, שלא נהנו מעולם מאלו המוחין דקו אמצעי, הם אינם נרקבים בקבר, כמ\"ש בג\"ר דעשו, כיון שלא נהנו ע\"כ לא בזו, וז\"ס שאמרו ז\"ל שיש עצם שאינו נרקב בקבר, דהיינו חלק הגוף המיוחס לקבלת ג\"ר דג\"ר, שהוא אינו נהנה ממאכל ומשתה, שה\"ס המוחין הבאים מקו אמצעי, וע\"כ אינו נרקב, כמבואר, וע\"כ יבנה הגוף ממנו לתחיית המיתים."],[21,"","והטעם שנקרא לוז, הוא בסו\"ה ויקרא את שם המקום ההוא בית אל ואולם לוז שם העיר לראשונה (בראשית כ\"ח) פירוש הדברים, כי כל דבר יש להבחין בג' הבחנות, שהם עולם שנה ונפש, כמבואר בספר יצירה. וענין הארת השמאל בלי ימין, בבחינת \u0003עולם,\u0004 היתה העיר \u0003לוז,\u0004 ועל כן היתה נקראת לוז, שהוא מלשון הכתוב תועבת ה' נלוז, (משלי ג' ל\"ב) וכן ונלוזים במעגלותם. (משלי ב' י\"ד). ויעקב שה\"ס קו אמצעי תקן את העיר, והשרה בה האלקיות וע\"כ קרא שמה בית אל. אשר לפני זה היה שמה לוז. אמנם כפי שנתבאר שקו האמצעי אינו יכול לתקן רק את בחינת הו\"ק דג\"ר, אבל לא את הג\"ר דג\"ר, נמצא שלא כל העיר \u0003לוז\u0004 קבלה את תיקונה, להיות נקראת \u0003בית אל\u0004 אלא רק בחינת הו\"ק של עיר הזאת קבלה תיקונה ונעשית \u0003בית אל,\u0004 אבל הג\"ר דג\"ר מבחינת העיר, נשאר בה השם הראשון \u0003לוז,\u0004 כי יעקב לא היה יכול לתקן אותה, וזהו מבחינת \u0003עולם.\u0004 וכן מבחינת \u0003נפש,\u0004 נבחן כל גוף כמו העיר לוז, אשר הצדיקים הזוכים לקבל המוחין דקו אמצעי וגופם זוכה להשראת השכינה, אז נקרא גופם \u0003בית אל,\u0004 תחת השם הקודם \u0003לוז,\u0004 אמנם בחינת ג\"ר של הגוף שלהם, שאין להם מה לקבל מקו אמצעי כנ\"ל, לא נתקנו כלום ואינם נקראים \u0003בית אל,\u0004 אלא נשארו בשם הקודם \u0003לוז,\u0004 הרי שעצם הזה המיוחס לג\"ר דג\"ר נקרא לוז, דהיינו שנשאר בזוהמתו ואינו ראוי לשום תקון במשך שתא אלפי שני, כי המוחין דקו אמצעי אינם מפרנסים אותו."],[21,"","וזה שאמרו ז\"ל, עתיד הקב\"ה להחיות המתים במומם, שלא יאמרו אחר הוא. וכבר נתבאר זה בהקדמתי לזהר אות כ\"ח, ועם הנתבאר מובן שסוד העצם \u0003לוז\u0004 ה\"ס המום שבגוף, שאינו יכול להרפא בשתא אלפי שני, בסו\"ה מעות לא יכול להתקן וחסרון לא יוכל להמנות. וממנו יעמוד הגוף לתחיית המתים, כדי שלא יאמרו אחר הוא מצורתו שבא\"ס ברוך הוא. כמו שביארתי בהקדמה אות כ\"ח עש\"ה, ואין להכפיל דברים. והנה נתבאר היטב, למה נקרא לוז, ולמה אינו אוכל ושותה, ולמה אינו נרקב בקבר, ולמה דוקא ממנו יעמוד הגוף לתחיית המתים. וזכור הדברים,כי הם המפתח לכל המאמר שלפנינו."],[22,"אמר ר' יצחק וכו':","אר\"י באותה שעה מה כתוב, ויאמר אברהם אל עבדו וגו': מהו אל עבדו. אם בחכמה זו נסתכל, דהיינו בנוגע לתחיית המתים, מהו הפירוש אל עבדו. כי אברהם ה\"ס הנשמה כמ\"ש לעיל (דף מ\"ב אות קמ\"א) וא\"כ, ויאמר אברהם אל עבדו היא העבד של הנשמה, והיכן מצינו שיש עבד לנשמה. אמר רבי נהוראי, לא נסתכל אלא במה שאמר \u0003עבדו,\u0004 ולא נייחס אותו אל אברהם כמשמעות הכתוב אלא הפירוש הוא עבדו של מקום, הקרוב לעבודתו. ומי הוא, הוא מטטרון, כמו שאמרנו, שהוא עתיד ליפות הגוף בקבר."],[23,"הה\"ד ויאמר אברהם אל עבדו:","זהו מטטרון, עבדו של מקום. \u0003זקן ביתו,\u0004 להיותו תחלת בריותיו של מקום. \u0003המושל בכל אשר לו,\u0004 פירושו שנתן לו הקב\"ה ממשלה על כל צבאותיו. דהיינו על כל מלאכי מעלה."],[24,"ותנא אר\"ש וכו':","ולמדנו, אמר ר' שמעון אמר ר' יוסי אמר רב, כל צבאותיו של אותו עבד, נוטלים אור ונהנין מזיו הנשמה, שלמדנו אור הנשמה גדול מאור הכסא דהיינו כסא הכבוד. והמלאכים נוטלים אורם מהכסא, הרי שאור הנשמה גדול מאור הכסא. ומקשה, והרי מהכסא נטלה הנשמה, ובהכרח שהמקבל הוא קטן מהמשפיע. ומתרץ אלא זה לפי הראוי לו וזה לפי הראוי לו."],[24,"","והדברים עמוקים מאד, ואבארם משורשם. כי שורשם, של אדם היושב על הכסא והכסא, ה\"ס או\"א וישסו\"ת. אשר ישסו\"ת ה\"ס הכסא וסוד שמאל. ואו\"א ה\"ס האדם היושב על הכסא וסוד הימין. ומהם נמשכים ז\"א ונוקביה, שז\"א ה\"ס אדם היושב על הכסא, והנוקבא ה\"ס הכסא. ומהם נמשכים הנשמות, ומט\"ט וסיעתו. שהנשמות באים מסוד אדם היושב על הכסא. ומטטרון וסיעתו באים מסוד הכסא, ונודע שהתחתונים צריכים להארת חכמה וכל זמן שאין להם הארת חכמה אע\"פ שמקבלים אור החסדים מז\"א ומאו\"א עלאין עדיין הם בבחינת ו\"ק בלי ראש, עד שמקבלים ג\"כ הארת החכמה, הנמשכת מהכסא ומהנוקבא ומישסו\"ת שאז קונים ג\"ר. ונמצא שהנשמה מטרם שמקבלת אור הכסא, הוא בבחינת ו\"ק בלי ראש דהיינו ו\"ק דו\"ק, והיא קטנה מאור הכסא שהוא ג\"ר דו\"ק, אבל אחר שמקבלת הארת החכמה מאור הכסא נעשית גדולה הרבה מאור הכסא, כי אור הכסא נמשכת מהנוקבא ומישסו\"ת, והוא בחינת ג\"ר דו\"ק, ואור הנשמה נמשכת מז\"א ואו\"א, והוא בחינת ג\"ר ממש."],[24,"","וזהו שמקשה איך תאמר שאור הנשמה גדול מהכסא, \u0003והא מהכסא נטלה הנשמה,\u0004 שהיא קטנה מהכסא. כי הנשמה מטרם שמקבלת מהכסא, היא ו\"ק דו\"ק, והכסא הוא ג\"ר דו\"ק. וע\"כ היא מקבלת מהכסא. ומתרץ \u0003אלא זה לפי הראוי לו וזה לפי הראוי לו.\u0004 כלומר שהם שני אורות משונים זה מזה. כי הנשמה היא אור חסדים בעצם והכסא הוא הארת החכמה בעצם, וע\"כ כשהנשמה צריכה להארת חכמה מחויבת לקבל מהכסא, אע\"פ שמשורשה הנשמה גדולה מאור הכסא. \u0003ר\"נ אמר גדול מאור הכסא ממש, דכתיב דמות כמראה אדם עליו מלמעלה. מאי עליו. על זהרו.\u0004 כי \u0003עליו\u0004 ברוחניות, שאינו תופס זמן ומקום, הוא בהכרח רק בחינת מעלה בלבד. הרי שאור הנשמה גדול מאור הכסא, להיותה משורשה בסוד אדם היושב על הכסא כנ\"ל."],[25,"וכשהוא הולך וכו':","וכשהולך לעשות שליחותו של הקב\"ה, כל צבאותיו והמרכבה שלו נזונים מאותו הזהר, של הנשמה, דהיינו מאור החסדים מסוד האדם היושב על הכסא הנמשך מז\"א המקבל מאו\"א עלאין כנ\"ל, וזה הוא שהנשמה אומרת לו \u0003שים נא ידך,\u0004 כלומר סיעתך, דהיינו הצבאות של מטטרון, \u0003תחת\u0004 ירכי, זהו אור הנשפע מן הנשמה, כי \u0003ירכי\u0004 פירושו נה\"י, שזהו מעלת הנשמה עליהם, שיש לה נה\"י דכלים וג\"ר דאורות, וע\"כ אמרה לו, שים נא ידך תחת ירכי, שיקבל אור הג\"ר הנכלל בנה\"י שלה. שאור זה ה\"ס השבועה שהשביעה אותו."],[26,"אמר ר' יהודה ברבי שלום וכו':","אריב\"ש, כך קבלנו, בשעה שזה הולך בשליחותו של מקום, הקב\"ה מניע כל צבאותיו של מעלה באות אחת משמו, דהיינו בי' של הויה, שה\"ס או\"א, שהוא שורש אור הנשמה כנ\"ל בסמוך. אמר רב הונא כך, ירכ\"י בגימטריא \u0003רם,\u0004 כלומר, הנשמה אומרת, שים נא \u0003ידך,\u0004 סיעתך, תחת מעלתו של \u0003רם\u0004 ונשא, המושל על הכל. שזה רומז לבחינת עתיק המאיר באו\"א שהם אות י' הנ\"ל. ולאחר שהנשמה צותה סיעת עליונים, דהיינו אור או\"א עלאין, תחת ידו, אמרה לו, אני משביעך שבועה גדולה בו."],[27,"אמר ר' יצחק וכו':","אר\"י, כתוב אלקי השמים ואלקי הארץ, כיון שכבר אמר בה', דהיינו אני משביעך בה', למה נאמר עוד אלקי השמים וגו'. הקשה לר' יהודה שאמר, שבשעה שהולך וכו' מניע כל צבאותיו באות אחת משמו, שה\"ס י' דהיינו אור החסדים דאו\"א עלאין כנ\"ל, והקשה לו, לפי זה, למה אמר בלשון השבועה, אלקי השמים ואלקי הארץ, ששמים ה\"ס ז\"א הנמשך מאו\"א עלאין, והארץ ה\"ס הנוקבא הממשכת מישסו\"ת כנ\"ל והיה מספיק להשביעו בה' לבד."],[27,"אמר רבי יהודה וכו':","והשיב לו ר\"י, שע\"כ נאמר אלקי השמים ואלקי הארץ, להורות שהוא אדון על הכל בבת אחת, וברגע אחד הוא מניע לכל, וכלם כאין נגדו. כלומר, שמשיב, דע\"כ הזכיר שמים וארץ בלשון השבועה, שה\"ס האור של אות הי', להורות, שאור זה מושל על כל המדרגות, וכולם כאין נגדו. ר' יצחק אומר, על שתים אותיות משמו מניע כל צבאותיו בעת שמטטרון הולך בשליחותו. להורות, שהוא הכל ואין אחר בלתו. פירוש. כי ר' יצחק חולק על ר' יהודה, שאמר לעיל שכשהוא הולך וכו' מניע וכו' באות אחת משמו, דהיינו רק באור הימין מאו\"א שה\"ס \u0003י'\u0004 דהויה, ועל זה הקשה לו מלשון השבועה שאמר, \u0003אלקי השמים,\u0004 שאורו ה\"ס או\"א, \u0003ואלקי הארץ\u0004 שאורו ה\"ס ישסו\"ת, שה\"ס שמאל. ומוכיח ר' יצחק מזה שבשעה שמט\"ט הולך בשליחות הקב\"ה מניע כל צבאותיו בב' אותיות משמו, שה\"ס \u0003י\"ה\u0004 מהוי\"ה. אשר \u0003י'\u0004 ה\"ס אור או\"א עלאין, ו \u0003ה'\u0004 ה\"ס אור ישסו\"ת. דהיינו גם בהארת החכמה הנמשכת מישסו\"ת. אשר הארת החכמה מבער הקליפות והכל רואים שהוא הכל ואין אחר בלתו."],[28,"ואשביעך בה' אלקי השמים וגו':","אמר רב הונא, אם הייתי עם בעלי הברייתא בשעה שגילו סוד הכתוב הזה, לא הייתי נפרש מהם כך, בלי שאדע הכל, כי אני רואה עמקות גדולה בפיהם, כי גלו, ואעפ\"כ אינם מובנים לכל איש."],[28,"ת\"ח שבועת קיימא דא וכו':","בוא וראה, שבועת הברית הזאת, משבעת הנשמה, שכתוב אשר לא תקח אשה לבני. כי אברהם רומז על הנשמה כנ\"ל (באות מ\"ח)."],[29,"אמר ר' יצחק וכו':","מכאן נשמע, שהנשמה אמרה למטטרון, כיון שאתה הולך בשליחות הזו, דהיינו להחיות המתים, לא תקח אשה לבני, כלומר, שלא תקח גוף לבני, כי הגוף בערך הנשמה נקרא אשה ולכנס בגוף אחר, בגוף זר, בגוף שאינו ראוי לו, אלא בגוף ההוא ממש שהוא שלי, בההוא ממש שיצאתי ממנו, וזהו שכתוב כי אם אל ארצי ואל מולדתי תלך. פירוש. כמ\"ש לעיל (בדף מ\"ז ד\"ה וזה וכמ\"ש בהקדמתי להזהר דף י' אות כ\"ח), בביאור דחז\"ל,, עתידים המתים להחיות במומם שלא יאמרו אחר הוא, שהפירוש הוא שיהיה באותה הצורה כמו בהתכללות בא\"ס ב\"ה, עש\"ה לכן משבעת הנשמה למטטרון, \u0003אל ארצי ואל מולדתי תלך,\u0004 דהיינו לגוף שלי, שנשאר בסוד עצם לוז, שה\"ס הגוף שיצאתי ממנו, והוא הראוי לתחיית המתים (כנ\"ל דף מ\"ו ד\"ה וצריכים ע\"ש) ואחר שיתרפא ממומו, ראוי להתלבשות הנשמה לנצחיות. (כמ\"ש בהקדמתי הנ\"ל. עש\"ה, כי אין להכפיל דברים.)"],[30,"אמר ר' יוסי וכו':","מהו ולקחת אשה לבני ליצחק, אם הכוונה להתלבשות הנשמה היה צריך לומר לאברהם. אמר ר' יצחק, אותו הגוף שנצטער עמי באותו העולם, ולא היה לו הנאה וכסוף בו מפני יראת קונו. דהיינו עצם לוז שאינה נהנה ממאכל ומשתה בעוה\"ז (כנ\"ל דף מ\"ו ד\"ה וצריכים) אותו הגוף ממש תקח לצחק עמו, בשמחה הזו של הצדיקים, לצחק עמו בשמחת הקב\"ה, לצחק עמו, משום שעתה, בזמן תחיית המתים, עת שחוק בעולם. וזהו שכתוב, אז ימלא שחוק פינו."],[31,"א\"ר יהודה ב\"ר יצחק וכו':","אר\"י בר\"י, בוא ושמע, אין מלאך אחד עושה רק שליחות אחת ולא שתי שליחות בבת אחת. פירוש. כי יש כאן ב' שליחיות א) להחיות הגוף בקברו ב) להעלותו לארץ ישראל ששם מתלבש בו הנשמה. וזהו שמקשה, אין מלאך אחד עושה ב' שליחות."],[31,"ותניא א\"ר אבא וכו':","ומשיב, ולמדנו אמר ר' אבא, מלאך אחד, אשר קסת הסופר במתניו, שהוא גבריאל, עתיד להרשים כל אחד ואחד על מצחו דהיינו שיתקן את הגוף, ולאחר כן, השר הגדול היינו מטטרון, הולך לתקן כל אחד ואחד, ולהעמידו לקבל נשמתו. וזהו שכתוב, הוא ישלח מלאכו לפניך ולקחת אשה, מהו \u0003לפניך\u0004, הוא יורה, לפני שליחותך, שהקב\"ה ישלח מלאך מקודם לתקן את הגוף, ואח\"כ יביאהו מטטרון להתלבשות הנשמה, מטעם שאין מלאך אחד עושה ב' שליחות."],[32,"ר' אליעזר אזל למחמי וכו':","ר\"א הלך לראות את ר' יוחנן בן זכאי רבו. ואותו יום ראש חדש היה. כשהגיע אליו, אמר לו. באר אשר לרואים, וממלאים אותו במים שאובים ונובע ממקורו עצמו עוד יותר מהם, מה הוא מבקש כאן. אמר לו חייב אדם להקביל פני רבו בראש חדש. דלסריין, פירושו אשר לרואים והוא מלשון (עירובין ס\"ג) \u0003סייר\u0004 נכסיה כל יומא (ב\"ב כ\"א) דגים יהבי \u0003סיירא.\u0004 ושורש המלה הוא \u0003סר,\u0004 כמו (חולין ק\"ה) \u0003סר\u0004 סכינא שפירושם ראויה והשגחה. ודלסריין הוא כמו דלסיירין, ובירא דלסריין פירושו באר של רואים, והוא מלשון הכתוב, באר לחי רואי, וראיה פירושו הארת חכמה. והמשיל את ר' אליעזר לבאר נובע מעצמו, משום שעיקר נשמתו היה מאור החסדים דאו\"א עלאין שזווגם לא פסיק לעלמין ומשום שממשיך הארת החכמה מישסו\"ת, כינה אותו באר של רואים, על שם החכמה שמקבל מישסו\"ת, ונבחן זה, שממלאים אותו בשאובים ממקום אחר, כי שורשו עצמו אינו נמשך מישסו\"ת רק מאו\"א עלאין, ומשום זה והוא \u0003נביע מדידיה יתיר,\u0004 שהחסדים שלו משורשו עצמו, הנמשכים מאו\"א, בבחינת \u0003נביע\u0004 דלא פסיק, חשובים הרבה יותר, מהארת החכמה שממלאים אותו מישסו\"ת. כי ערך או\"א אל ישסו\"ת. כערך ג\"ר אל ו\"ק כנודע."],[33,"אמר ליה חייב וכו':","א\"ל חייב אדם להקביל פני רבו בר\"ח. א\"ל לא על זה אמרתי מאי בעא הכא, אלא אני רואה בפניך, שיש לך, דבר חדש, מאלו סודות העמוקים, שאתה עתיד לשאול. ע\"ז אמרתי, כיון שאתה גדול כל כך, מה אתה מבקש אצלי."],[34,"א\"ל חמינא וכו':","אמר לו רואה אני אותו אור הראשון, ששימש בימי בראשית, ואח\"כ גנזו לצדיקים לעתיד לבא שמסעיו עשרה. ובעשרה נוסע, ובסוד עשרה מנהיג הכל, ובעשרה אותות עושה מעשיו. ולמדנו, עשרה כתבים, עשרה מפתחות של בית החולים בידיו, ועשרה כתבים לוקח בגן עדן, לתקן הארץ בשביל גופים של הצדיקים."],[34,"","פירוש. מספר עשרה רומז על אור החסדים. כמ\"ש לעיל בהקדמת הזהר (בדף ז' במראות הסולם ד\"ה ועם זה. ע\"ש) ואור הראשון שנגנז לצדיקים ה\"ס אור החכמה, כי ע\"כ היה אדם הראשון מסתכל בו מסוף העולם עד סופו, כי אור העינים והראיה ה\"ס אור החכמה, כנודע. ואומר \u0003שאור הראשון מסעיו עשרה\u0004 דהיינו שאור החכמה מתגלה בהתלבשות עשרה, שהוא אור החסדים. ואיך הוא בא להתלבשות הזה, הולך ומפרש, שהוא משום שבא בג' קוין שכל קו מלובש בעשרה. וז\"ש \u0003ובעשרה נטיל,\u0004 שנוסע ומשפיע בעשרה, והוא קו ימין שעצם השפעתו הוא אור החסדים. \u0003וברזא דעשרה נהיג לכלא\u0004 שבסוד עשרה מנהיג הכל. והוא קו שמאל, שאע\"פ שעצם השפעתו הוא חכמה שה\"ס נקודת השורק כנודע, עכ\"ז אינו מנהיג ומשפיע. זולת על ידי התלבשות בחסדים שה\"ס \u0003רזא דעשרה.\u0004 כמבואר. \u0003ובאתוותא דעשרה עביד עובדוי,\u0004 ובעשרה אותות עושה מעשיו, וזהו קו אמצעי המכריע בין ב' הקוין הללו שממנו נמשכים כל האותות והמופתים שמצד הקדושה, ומה המה מעשיו, הולך ומפרש \u0003ותאנא עשרה פתקין, עשרה מפתחן דבי קצרי,\u0004 פתקין, פירושו מסכים (כנ\"ל דף ל' ד\"ה ביאור ע\"ש) ומפתחן, היינו קומות אורות החסדים היוצאות על הפתקין. שבקומות האור האלו הוא רופא החולים. כי כל המחלות, נמשכים מקו שמאל בהיותו בלי התכללות הימין, וכשבא קו האמצעי עם סוד המסך דחירק שעליו יוצא קומת אור החסדים, שבזה מכריע בין הקוים עד שנכללים זה בזה (כנ\"ל ב\"א דף קל\"א ד\"ה תליתאה) מתרפאים אז כל החולים. וע\"כ נקראים קומות אור שלו \u0003מפתחן דבי קצרי.\u0004 מפתחות לרפואות החולים. והם \u0003בעשרה,\u0004 להיותם אור החסדים. \u0003ופתקין עשרה נטיל בגינתא דעדן לאתקנא ארעא על גופיהון דצדיקיא,\u0004 פתקין עשרה ה\"ס \u0003פנקס סימנא שנותנין לה הכרובים בג\"ע\u0004 המובא לעיל לך (דף מ\"א אות ק\"ד ע\"ש) שה\"ס המסך דקו אמצעי זה, שע\"י נכנס בחשבון הצדיקים על יד המלאך דומה ומובטחים בזה לעמוד בתחיית המתים בסו\"ה וכפר אדמתו עמו (ועי' לעיל דף ד' ד\"ה פירוש יש שנתבאר שם בארוכה.) וז\"ש \u0003לאתקנא ארעא על גופיהון דצדיקיא\u0004 דהיינו לתקן הקבר בסו\"ה וכפר אדמתו עמו, שיהיו ראוים לסו\"ה ופתחתי את קברותיכם וגו'."],[35,"א\"ל אליעזר ברי וכו':","אמר לו אליעזר בני, היית רואה יותר ממלאך קדוש, דהיינו כנ\"ל (דף מ\"ח ד\"ה וזהו) שאור הנשמה גדול מאור המלאכים ע\"ש, וכיון שר\"א ביאר סוד העשרה רק בג' קוין העליונים, שהם \u0003חכמה בינה דעת,\u0004 הולך ריב\"ז ומבאר סוד העשרה גם בז\"ס תחתונות, ואומר \u0003דעלמא בעשרה אתברי.\u0004 שהעולם, שהוא \u0003מלכות\u0004 נברא בעשרה. \u0003בעשרה אתנהיג,\u0004 ומנוהגת בעשרה, שהוא \u0003יסוד\u0004 שמנהג את המלכות הנקראת עולם. \u0003כרסיא קדישא, בעשרה,\u0004 הכסא הקדוש, שהוא \u0003נצח והוד,\u0004 הנקראים כסא תתאה, הוא בעשרה. \u0003אורייתא הוא בעשרה.\u0004 התורה, שה\"ס \u0003תפארת,\u0004 הוא בעשרה. \u0003מטלנוי בעשרה.\u0004 נסיעותיו, היינו \u0003גבורה,\u0004 הוא בעשרה. \u0003עלמין עלאין בעשרה,\u0004 עולמות עליונים דהיינו \u0003חסד,\u0004 שהוא העליון מז\"ס תחתוניות, הוא בעשרה, \u0003וחד עלאה על כלא, בריך הוא,\u0004 ואחד העליון על כל ברוך הוא, דהיינו \u0003כתר.\u0004 שממנו נמשך הכל, הן אור החסדים המרומז בסוד עשרה, והן אור החכמה."],[36,"ואימא לך מלה וכו':","ואומר לך דבר, שדעת בעלי המשנה היה בזה. מה כתוב, ויקח העבד עשרה גמלים וגו'. אמר לו ר' אליעזר: רבי, כבר זכיתי לדעת מקרא הזה. כלומר, שאינך צריך לפרשו לי, אבל, מהו, וכל טוב אדוניו בידו. שאיני יודע מהו פירושו. כי איך אפשר, שכל רכושו של אברהם יהיה נשא בידו. אמר לו, זהו שמו של רבונו, דהיינו השכינה, שנקראת \u0003שם,\u0004 שהלכה עמו להביא אותו למקום הנרצה, ולהגן עליו, שלא יאונה לו מכשול. אמר ר' אליעזר, זה ודאי הוא סוד הכתוב, כי שמי בקרבו."],[37,"תנן, אמר ר' אבהו וכו':","תנן אמר ר' אבהו, בוא וראה, כל מי שיודע שמו לאמתו. יודע שהוא ושמו אחד. הוא היינו הקב\"ה, ושמו אחד, היינו השכינה. שכתוב ה' אחד ושמו אחד וגו', כלומר \u0003השם,\u0004 שהוא השכינה. \u0003והוא,\u0004 שהוא ז\"א, אחד. וביאור הדברים תמצא בהסולם לעיל בראשית א' דף קי\"ח ד\"ה וביאור."],[38,"אמר ר' אבא וכו':","אר\"א, יש להסתכל בפרשה זו, שכתוב ויברך הגמלים מחוץ לעיר אל באר המים. אמר ר' אבא, מחוץ לעיר, פירושו בבית הקברות. אל באר המים, פירושו, כי למדנו, הנקדמים לתחית המתים בבית הקברות, הם אותם שנשאו ונתנו בתורה, שהרי תנן, כשנכנס אדם לקבר, מה ששואלים לו מתחילה, הוא, אם קבע עתים לתורה, שכתוב והיה אמונת עתך וגו', ומכל שכן כשיצא, אינו שאלה, להחיות אותם מתחילה."],[39,"אמר ר' אבא וכו':","אר\"א, לעת ערב, זהו יום הששי, שהוא ערב השבת, שאז הזמן להחיות המתים, ושואל מהו המשמעות של הדברים ואומר, כי למדנו ששה אלף שנים עומד העולם, וערב שבת, הוא אלף הששי. שהוא סיום הכל, והיינו \u0003לעת ערב,\u0004 שפירושו זמן סיום הכל. \u0003לעת צאת השואבות,\u0004 אלו הם תלמידי חכמים השואבים מימיה של תורה, שהוא עת לצאת, ולהתנער מן העפר, דהיינו לקום לתחיה."],[40,"ואמר ר' אבא עוד וכו':","ואר\"א, עוד יש לדעת, שלמדנו, אותם המתעסקים לדעת את רבונם בעוה\"ז, ונשמתם בשלמותה לעולם הבא, זכו לצאת מהקבר משבועת הנשמה שהשביעה למטטרון, כנ\"ל. כי מטטרון הולך לדעת מי הוא גופה ממש, כמו שהנשמה השביעו, ומה הוא, הוא כמ\"ש, הנה אנכי נצב על עין המים. אף על פי שגוף תלמיד חכם הוא, הולך מטטרון לבחון אחר השלמות, שכתוב והיה העלמה היוצאת לשאוב ואמרתי אליה השקיני נא מעט מים מכדך, שפירושו, אמור לי רמז ידיעת השם ממה שהשגת."],[41,"ואמרה אלי גם אתה שתה:","פירושו שנתנת לו לדעת, ג' ידיעות, א) \u0003אף אתה עבד כמוני,\u0004 דהיינו שחסר ג\"ר. ב) \u0003ולא נתחלף לי ידיעתך בידיעתו של מקום,\u0004 שלא טעתה שיש שלמות אחרונה בהמוחין שלו, שמשפיע לנשמות. כמו שלמותו של הקב\"ה. ג) \u0003וצריך אתה להשיג שאתה נברא כמוני.\u0004 אע\"פ שאתה מלאך, מכל מקום אתה כמו נברא, דהיינו בעל חסרון, כמוני."],[42,"וגם לגמליך אשאב:","דהיינו שגם לצבאותיו תתן לדעת ממה שהשיגה ושאבה, כי גמליך פירושו לצבאותיך כנ\"ל. כלומר, \u0003ידיעת השגתו\u0004 הוא א) \u0003שלא השיגו סיעתך,\u0004 שהמה מחוסרי השגה. ב) \u0003וידעתי כי מעלה יש לי עליך,\u0004 דהיינו בחינת התכללות מנקודה דעוה\"ז, שהיא חסרה למלאכי מעלה. ג) \u0003והאיך\u0004 נברא אתה מזיו הנתון אצלך, דהיינו שהשיגה גם סוד בריאתו. \u0003אם הוא אומר,\u0004 אם הגוף אומר כל השגותיו הנ\"ל, \u0003סימן זה יהי מסור בידי על כל דברים אלו, כי סימן זה,\u0004 שעשית לי, \u0003יהי מסור בידי על כל דברים אלו,\u0004 שהגוף יאמר לו כל הדברים הנ\"ל אף אחד מהם לא יחסר, אז \u0003ואדע שהיא האשה, הוא הגוף, מאותה הנשמה,\u0004 כפי \u0003השבועה שהשביעני.\u0004"],[43,"ויהי הוא טרם כלה וכו'","מכאן עד אות קפ\"א א\"צ ביאור."],[47,"תא חזי בתחלה וכו'.","לא מנוול כבראשונה, אלא כמי שרחץ עצמו מטנופו. ושואל, לבן למה נצרך. כלומר, למה נצרך זה, שישאר היצה\"ר בעולם. מכאן עד אות קפ\"ז א\"צ ביאור."],[53,"א\"ר יהודה הא כל וכו':","אר\"י הנה נתברר לנו כל הפרשה, אבל לא אוכל לדעת מהו ויוסף אברהם ויקח אשה ושמה קטורה. ולשיקול הדעת כל פרשה זו היא בסתירה. כלומר, שהיא בסתירה להמשכת הביאור בדבר הנשמה והגוף, שבזמן התחיה."],[54,"כד אתא רב דימי וכו':","כשבא רב דימי, אמר, פרשה זו שמעתי ביאורה ואיני זוכר. אמרו, שעליונים החזקים היינו מדרגות העליונות, לא המציאו אותה לגילוי, ואנו מה נאמר. פירוש. בעת שחכמי האמת מבארים סודות הכתובים, הנה אותן המדרגות שהכתובים מדברים מהן, באות בעצמן לאותם החכמים, בעת ההוא, וממציאות את עצמן שיביאו אותן לגילוי. וזולת הסיוע שלהן לא היה להם כח לגלות שום סוד. וזה שאמר רב דימי, שעליונים החזקים לא המציאו את עצמם ולא סייעו לגלות הכתובים שבפרשה זו. קם ר\"י ואמר, בישיבה של חברינו בעלי המשנה הפרשה מגולה."],[55,"קמו ואזלו וכו':","קמו והלכו הוא ור' ייסא ור' חייא. מצאו את ר' אלעזר בר\"ש, והיה מגלה סוד התפילין. נכנסו לפניו ואמרו לו, במה מתעסק אדונינו, אמר להם טעם התפילין אני אומר. כי אשרי האדם המניח תפילין ויודע הטעם שלהן."],[56,"אמרו אי ניחא וכו':","אמרו, אם טוב הוא לפני אדונינו, יאמר לנו איזה דבר. אמרו שמענו מאביך, שהקב\"ה ברוב אהבתו שהיה לו לישראל, אמר להם, לעשות לו משכן, כעין המרכבה העליונה של מעלה, ויבא לשכון עמהם. וזהו שכתוב, ועשו לי משכן ושכנתי בתוכם. ושמענו מאביך שכאן, במקרא הזה, נסתם טעם התפילין."],[57,"א\"ל ת\"ח וכו':","אמר להם בוא וראה המקדש נעשה כעין העליון, בצורות מרכבותיו הקדושות, ואחרי כן, השרה הקב\"ה את שכינתו עמהם. כענין הזה וכאופן הזה, העירו החברים בעלי המשנה, בטעם התפילין, שאותו האדם ומניחם, יהיה דוגמא למרכבות העליונות: למרכבה התחתונה ולמרכבה העליונה. כדי שתבא המלכות שלו וישרה שכינתו עליו."],[57,"","ביאור הדברים. כבר נתבאר סוד ב' המרכבות, (לעיל ב\"א דף פ\"ה ד\"ה ביאור ע\"ש כל ההמשך) ואין להכפיל דברים. ולשתיהן צריכים. כי יש מעלה במרכבה עלאה שלמעלה מחזה, שאינה במרכבה תתאה שלמטה מחזה. כי אין זווג נוהג אלא במחזה ולמעלה ששם פני אדם, ולא במחזה ולמטה שחסר שם פני אדם. וכן יש מעלה במרכבה תתאה שמחזה ולמטה, שאינה במרכבה עלאה שמחזה ולמעלה, כי מקום גילוי החכמה הוא בהמרכבה שמחזה ולמטה ולא במרכבה שמחזה ולמעלה (כנ\"ל ב\"א דף ע\"ד ד\"ה ועלמא דאתגליא עש\"ה) לפיכך אין גילוי השלמות זולת בשתי המרכבות ביחד: כי המרכבה תתאה עולה ונכללת בזווג שיש מחזה ולמעלה במרכבה עלאה, ואז מתגלה החכמה במרכבה תתאה. (עי' לעיל ב\"א דף פ\"ו ד\"ה אמנם)."],[57,"","וז\"ש \u0003כגוונא עלאה אתעבד מקדש ברתיכוי קדישין,\u0004 שהמשכן וכליו נסתדרו בדוגמא לב' המרכבות. ו \u0003בתר כן אשרי קב\"ה דיוריה עמהם,\u0004 כי אז עלתה מרכבה תתאה למקום מרכבה עלאה, ונכללה בזווג אשר שם, ואז נתגלה החכמה במרכבה תתאה, שה\"ס השראת השכינה בתחתונים. \u0003כעניינא דא וכגוונא דא, וכו' למהוי ההוא גברא דוגמא דרתיכי עלאין,\u0004 כן צריך האדם המניח תפילין לכוון באלו ב' המרכבות והסדרים שבהם \u0003למיתי מלכותא דיליה וישרי דיוריה עלויה,\u0004 כי אז תבא המלכות של הקב\"ה, וישרה הקב\"ה שכינתו עליו. כי אין גילוי החכמה אלא בסוד המלכות שה\"ס מחזה ולמטה, ונקראת שכינה. אבל אין זווג להמשכת החכמה אלא מחזה ולמעלה, וע\"כ על ידי שתי המרכבות ביחד מתגלה השלמות."],[58,"ותנינן אית ביה וכו':","ולמדנו שיש בתפילין סודות עליונים ודוגמות שלהם. ויש בו במחזה ולמטה ששם המלכות, שלש מרכבות, בדומה לעליונים הקדושים, שהן סודות שלש האותיות של שמו הקדוש יה\"ו. כי ג' מרכבות הן, שהן ג' אותיות \u0003יה\"ו.\u0004 ארבע פרשיות שולטות על ארבע אותיות שמו הקדוש. ועל כך הוא סוד ה \u0003ש'\u0004 של שלש כתרים ו \u0003ש'\u0004 של ד' כתרים, שפירושן, ג' מלכים שולטים בגוף, היינו מחזה ולמטה, שהם כנגד \u0003ש'\u0004 דג' ראשים, ותפילין שעל הקב\"ה למעלה, שהם תפילין של ראש ותפילין של יד, והם ד' פרשיות, שהם כנגד \u0003ש'\u0004 דד' ראשים."],[58,"","פירוש, שמבאר ההפרש בין מרכבה עלאה שלמעלה מחזה, למרכבה תתאה שלמטה מחזה. דהיינו כמ\"ש בדבור הסמוך, שבמרכבה תתאה חסר פני אדם שה\"ס ה' תתאה של שם הויה. ונמצא שאין במרכבה תתאה רק ג' אותיות יה\"ו, וחסר ה' תתאה. ורק במרכבה למעלה מחזה יש ד' אותיות כולם. וז\"ש \u0003ואית ביה תלת רתיכין, דוגמת\u0004 וכו' \u0003דתלת אתוותא\u0004 וכו', שיש בה רק ג' מרכבות שה\"ס ג' אותיות שמו הקדוש הויה, יה\"ו, שה\"ס חכמה בינה תפארת, והמלכות חסרה, שהיא ה' תתאה. והם כלולות זו מזו ונבחנים לג\"פ יה\"ו, שהם ג' מרכבות, אחר שתעלנה להזווג שבמרכבה עלאה, כנ\"ל בדיבור הסמוך. \u0003ארבע פרשיות שליט על ארבע,\u0004 ארבע פרשיות שבתפילין ה\"ס חו\"ב תו\"מ והם שולטים על ארבע אותיות הויה, כי ארבע אותיות הויה, הם חו\"ב תו\"מ כנודע. ואומר, שז\"ס \u0003ש'\u0004 של ג' כתרים ושל ד' כתרים אשר ה \u0003ש'\u0004 מג' כתרים רומזת על בחינת המרכבה התחתונה, שאין לה מעצמה אלא ג' אותיות יה\"ו וחסרה ה' תתאה, וה\"ס ג' מלכים השולטים בגוף מחזה ולמטה שהם נה\"י, ונקראים מלכים משום שמחזה ולמטה שייך הכל אל המלכות. ו \u0003ש'\u0004 של ד' כתרים רומזת על בחינת המרכבה עלאה שיש לה ד' אותיות הויה בשלמות. וה\"ס ד' פרשיות של התפילין."],[59,"לבא רכיב וכו':","הלב רוכב, בדומה, כמו על מרכבה התחתונה, והתחתון, שה\"ס הנוקבא, רוכב. עוד למדנו, שזה המרכבה של הזרוע, הוא למטה, דהיינו הנוקבא סוד התפילין של יד, הנקראת זרוע, והלב שהוא בחינת מחזה ולמעלה, רוכב, בדוגמא שהוא למטה מחזה, ונמסרו בידו להכניס כל צבאות השמים. וכך הלב רוכב למטה ונמסר בידו כל אברי הגוף."],[59,"","פירוש. כי התגלות הארת החכמה נקרא רוכב על המרכבה. ולפיכך רק המלכות היא הרוכב, שבה נוהג גילוי. ונתבאר לעיל בדבור הסמוך, שהמרכבה עלאה שמחזה ולמעלה היא בחינת חסדים מכוסים, אבל שם הוא מקום הזווג, ולא במרכבה תתאה ע\"ש. ונמצא שעיקר גילוי החכמה הוא בהכרח במרכבה עלאה, אלא לא לעצמו אלא כדי להשפיע למרכבה תתאה. והמלכות דמרכבה עלאה שלמעלה מחזה, נקראת משום זה, \u0003לב.\u0004 על שם ל\"ב נתיבות החכמה שמתגלות בה. ועל כן יש ב' בחינות גילוי חכמה בלב, א) כשהוא למעלה מחזה במקומו, שאז אינה מתגלה החכמה לעצמו אלא כדי להשפיע למרכבה תתאה. ב) כשמרכבה תתאה עולה ונכלל בו ומקבל ממנו החכמה, ונבחן אשר מלכות זו דהיינו הלב, יורד עמהם למטה מחזה, ומגלה שם הארת החכמה למטה."],[59,"","וז\"ש \u0003לבא רכיב דוגמא דרתיכא תתאה,\u0004 דהיינו בחינה א' דגילוי החכמה, שאינה לצורך עצמו, וע\"כ נבחן שמאיר בדומה למרכבה תחתונה, כלומר רק להשפיע, ולא הארה ממשית לעצמו. ואומר הטעם שהוא משום, \u0003ותתאה רכיב,\u0004 שרק במרכבה תתאה שלמטה מחזה, שייך רכיבה ממש. וז\"ש עוד תנינן \u0003דא רכיבא דדרועא,\u0004 רכיבה זו של הזרוע, שה\"ס תפילין של יד דהיינו המלכות, \u0003לתתא,\u0004 נוהג רק למטה מחזה. \u0003ולבא רכיב,\u0004 בחכמה למעלה מחזה, \u0003דוגמא דאיהו לתתא,\u0004 דהיינו בדומה כמו למטה, כי צריך להשפיע חכמה למטה למרכבה תתאה. ומשום שאינה מאירה לעצמו אינה נבחנת בו להארה ממשית. כנ\"ל. \u0003ואתמסרון בידיה לאעלאה לון כל חילי שמיא,\u0004 בשעה שהחכמה מתגלית בו נמסר בידו כל צבאות השמים, כי הארת החכמה, כוללת ומכנסת תחתיה כל המדרגות. \u0003כך לבא הוא רכיב לתתא\u0004 דהיינו גילוי החכמה מבחינה ב) הנ\"ל, שהלב נכלל במרכבה תתאה ונמשך עמהם ובא ומאיר למטה מחזה. \u0003ואתמסרו בידוי כל אברי גופא,\u0004 ונמסרו בידיו כל מדרגות הגוף. דהיינו שמחזה ולמטה. מחזה ולמעלה דז\"א נבחן לבחינת ז\"א שנקרא \u0003שמים,\u0004 וע\"כ כל המדרגות התליות שם מכונים \u0003צבאות השמים.\u0004 ומחזה ולמטה דז\"א נבחן לבחינת הנוקבא, הנקראת \u0003גוף,\u0004 והמדרגות התליות שם מכונים אברי הגוף."],[60,"ועילא מניה וכו':","ולמעלה מן הלב, הם ארבע פרשיות על מוח הראש, אבל הקב\"ה שליט עליון עליהם, מלך הכל. פירוש תפילין של יד, נבחן לבחינת הלב שהיא מלכות כנ\"ל, שבה נוהג גילוי חכמה, כנ\"ל. אבל תפילין של ראש נבחן לבחינת מוח, שה\"ס ז\"א, שהוא מלך שליט בחסדים מכוסים שמקבל מאו\"א עלאין, בסוד כי חפץ חסד הוא, ואין הארת חכמה יכולה להגלות במקומו. וז\"ש אבל \u0003קב\"ה שליטא עלאה מלכא מכלא,\u0004 שבארבע פרשיות של ראש, הקב\"ה, שה\"ס ז\"א, הוא השולט, ואין גילוי הארת חכמה נוהג שם."],[60,"ורזא דחכמתא דא וכו':","וסוד החכמה, זה הוא כמו בבית המקדש, שכתוב ועשה כרוב אחד מקצה מזה וכרוב אחד מקצה מזה, ועליהם שכינת המלך בארבע אותיות הוי\"ה, י\"ה על כרוב הימני ו\"ה על כרוב השמאלי, ובשתי מרכבות, דהיינו מרכבה עלאה על כרוב הימני ומרכבה תתאה על כרוב השמאלי."],[61,"וכהאי גוונא לבא וכו':","וכעין זה הוא, הלב והמוח, שהם תפילין של יד ותפילין של ראש, הלב מכאן, והמוח מכאן, ועליהם שכינת המלך, בד' פרשיות. א\"ר אלעזר, מכאן ואילך, הם סודות של כתרי האותיות: הפרשות בגופיהם, דהיינו הבתים, ורצועותיהן הם הלכה למשה מסיני. והרמז שלהם כבר נגלה, דהיינו בביאור שלפנינו, וטעם הכל, הוא בסוד י\"ג מדות הרחמים."],[62,"א\"ר יהודה וכו':","אר\"י, אלמלא לא באנו אלא בשביל סוד הזה די לנו. אמרו לו, אשרי חלקך לעולם הבא, שכל סוד לא נעלם ממך. אמרו לו, באנו לפני אדונינו לדעת הסוד של פסוק הזה. ויוסף אברהם ויקח אשה ושמה קטורה."],[63,"אמר פירושא וכו':","אמר, הפירוש של פסוק הזה הוא כמו שגילו החברים בעלי המשנה, שבעת שהנשמה תבוא באותו גוף הקדוש שלה, אז אלו הדברים, דהיינו ויוסף וגו' יהיו נאמרים על הרשעים, שיקומו לתחיה, ויטיבו מעשיהם, והנשמה תתן להם מזיו יקר שלה, כדי שידעו וישובו ויזכו זכות שלמה."],[64,"וכד חמי שלמה וכו':","וכששלמה ראה את זה, היה תוהה מאד, ואמר, ובכן ראיתי רשעים קבורים ובאו, וממקום קדוש יהלכו, דהיינו שיבואו ויחיו ממקום קדוש. דהיינו שיקומו בתחית המתים."],[64,"ותנינן א\"ר אבא וכו':","ולמדנו, אר\"א אמר ר' יוחנן, כתוב היהפוך כושי עורו ונמר חברברותיו, כך הרשעים, שלא זכו לשוב בעולם הזה, ולהקטיר מעשים טובים, לעולם לא יקטירו לעולם הבא. כלומר שגם שיקומו לתחיית המתים, מכל מקום לא יכלו לעשות מעשים טובים, משום שלא זכו בחייהם. מכאן ואילך עד הסיום של מדרש הנעלם, א\"צ ביאור."],[67,"ר' יצחק פתח וכו':","ר\"י פתח ואמר. וישוב העפר על הארץ כשהיה והרוח וגו', בוא וראה, כאשר ברא הקב\"ה את האדם, לקח עפרו ממקום המקדש, ובנה גופו מארבע רוחות העולם שכל אחד נתן לו כח. ואחר כך, הריק עליו רוח החיים, כמו שאתה אומר, ויפח באפיו נשמת חיים. אחר כך קם, וידע שהוא כלול מלמעלה ומלמטה, ואז נתדבק בה', וידע חכמה עליונה."],[68,"כגוונא דא וכו':","כעין זה, כל אנשי העולם כלולים מלמעלה ומלמטה. וכל אלו היודעים לקדש את עצמם בעולם הזה כראוי, כשהם מולידים בן, ממשיכים עליו רוח קדוש, מן המקום, שכל הקדושות יוצאות ממנו, ואלו נקראים בנים למקום, משום שהגוף שלהם נעשה בקדושה כראוי. וכן נותנים לו רוח ממקום קדוש עליון כראוי. והוא נתבאר."],[69,"ת\"ח בשעתא וכו':","בוא וראה, בשעה שאדם עתיד לתת חשבון על מעשיו, מטרם שיצא מן העולם, יום זה הוא יום של חשבון, אשר הגוף והנשמה נותנים חשבון. אחר זה הנשמה יוצאת מן הגוף ונפרדת ממנו, והגוף, שנברא מעפר, שב לעפר, והכל חוזר אל המקום שלוקחו משם. וכבר בארוהו, ועד הזמן שהקב\"ה עתיד להחיות המתים, יהיה הכל גנוז לפניו."],[70,"וההוא גופא וכו':","ואותו הגוף ממש, ואותה הנשמה ממש, עתיד הקב\"ה להחזיר לעולם כבתחלה ולחדש פני העולם. וזה שכתוב, יחיו מתיך נבלתי יקומון. ואותה הנשמה ממש גנוזה לפני הקב\"ה, שחוזרת למקומה אחר פטירת האדם לפי מעשיה, כמו שאתה אומר, והרוח תשוב אל האלקים אשר נתנה, ובזמן שהוא עתיד להחיות המתים, הוא עתיד להריק טל מראשו עליהם, ובטל הזה יקומו כל הגופים מעפר."],[71,"הה\"ד כי טל אורות טלך:","ושואל מהו טל אורות. ואומר, הוא אורות ממש, מאלו האורות של מעלה, שבהם עתיד להוריק חיים לעולם, אשר עץ החיים, שהוא ז\"א, יריק אז חיים שאינם נפסקים לעולם. כי עתה החיים נפסקים, משום כי בעת שנחש הרע שולט, הלבנה מתכסה, דהיינו שנפסק הזווג של חמה ולבנה העליונים, שהם זו\"ן, ומשום זה, נפסקים כביכול מימיו של ז\"א, שה\"ס עץ החיים, ועל כן החיים אינם שולטים כראוי בעולם."]],[[0,"","כְּמוֹ כֵן כְּשֶׁיּוֹצְאוֹת הַנְּשָׁמוֹת מֵהַגּוּף מֵהָעוֹלָם הַזֶּה, רוֹצוֹת לַעֲלוֹת, וְכַמָּה שׁוֹמְרֵי הַפֶּתַח וּמַחֲנוֹת מַזִּיקִים נִמְצָאִים. אִם הֵם מִצִּדָּם - כֻּלָּם אוֹחֲזִים בָּהֶם בְּאוֹתָן הַנְּפָשׁוֹת, וּמוֹסְרִים אוֹתָם בְּיַד דוּמָה לְהַכְנִיסָם לַגֵּיהִנֹּם."],[1,"","וְאַחַר כָּךְ עוֹלוֹת וְאוֹחֲזִים בָּהֶם, וְהֵם נוֹטְלִים אוֹתָם, וּמַכְרִיזִים בָּהֶם: אֵלּוּ הֵם שֶׁעָבְרוּ עַל מִצְווֹת רִבּוֹנָם. וְכֵן מְשׁוֹטְטוֹת בְּכָל הָעוֹלָם. וְאַחַר כָּךְ מַחֲזִירִים אוֹתָם לַגֵּיהִנֹּם, וְכֵן עַד שְׁנֵים עָשָׂר חֳדָשִׁים. אַחַר שְׁנֵים עָשָׂר חֳדָשִׁים הֵם שׁוֹכְכִים בְּאוֹתוֹ מָקוֹם שֶׁרָאוּי לָהֶם. אוֹתָם הַנְּשָׁמוֹת שֶׁזָּכוּ עוֹלוֹת לְמַעְלָה, כְּמוֹ שֶׁנִּתְבָּאֵר, וְזוֹכוֹת בִּמְקוֹמוֹתֵיהֶם."],[2,"","בֹּא רְאֵה, אַשְׁרֵי הַצַּדִּיקִים שֶׁנִּגְנְזוּ לָהֶם כַּמָּה טוֹבוֹת לָעוֹלָם הַהוּא, וְאֵין מָקוֹם פְּנימִי בְּכָל אוֹתָם כְּאוֹתָם שֶׁיּוֹדְעִים אֶת סוֹד רִבּוֹנָם וְיוֹדְעִים לִדְבֹּק בָּהֶם בְּכָל יוֹם. עַל אֵלּוּ כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ."],[3,"","מַה זֶּה לִמְחַכֵּה לוֹ? כְּמוֹ שֶׁנֶּאֱמַר (איוב לב) חִכָּה אֶת אִיּוֹב בִּדְבָרִים. וְאֵלּוּ הֵם שֶׁדּוֹחֲקִים לְדָבָר שֶׁל חָכְמָה וּמְדַיְּקִים אוֹתָהּ וּמְחַכִּים לָדַעַת אֶת בֵּרוּר הַדָּבָר, וְהֵם מֻכָּרִים לְרִבּוֹנָם. אֵלּוּ הֵם שֶׁרִבּוֹנָם מִשְׁתַּבֵּחַ בָּהֶם בְּכָל יוֹם. אֵלּוּ הֵם שֶׁנִּכְנָסִים בֵּין עֶלְיוֹנִים קְדוֹשִׁים, וְאֵלּוּ נִכְנָסִים בְּכָל הַשְּׁעָרִים שֶׁלְּמַעְלָה, וְאֵין מִי שֶׁיִּמְחֶה בְיָדָם. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[4,"","בֹּא רְאֵה, אַבְרָהָם נִכְנַס לָדַעַת וּלְהִדָּבֵק בְּרִבּוֹנוֹ כָּרָאוּי לְאַחַר שֶׁהִקְדִּים אֶת מַעֲשָׂיו שֶׁבָּרִאשׁוֹנָה, וְזָכָה לְאוֹתָם הַיָּמִים הָעֶלְיוֹנִים, וְהִתְבָּרֵךְ מֵהַמָּקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת מִשָּׁם, שֶׁכָּתוּב וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. מַה זֶּה בַּכֹּל? הַמָּקוֹם שֶׁל הַנָּהָר שֶׁאֵין פּוֹסְקִים מֵימָיו לְעוֹלָמִים."],[5,"","אָמַר רַבִּי חִיָּיא, בֹּא רְאֵה שֶׁאַבְרָהָם לֹא רָצָה לְהִתְעָרֵב עִם נְשׁוֹת הָעוֹלָם וּלְהִדָּבֵק בִּשְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁנְּשׁוֹת שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת הֵם מְטַמְּאוֹת אֶת הַגְּבָרִים שֶׁלָּהֶם וּלְאוֹתָם שֶׁנִּדְבָּקִים בָּהֶם. מִשּׁוּם שֶׁכְּשֶׁאַבְרָהָם יָדַע אֶת הַחָכְמָה, יָדַע הָעִקָּר וְהַשֹּׁרֶשׁ, וּמֵאֵיזֶה מָקוֹם יוֹצְאוֹת וּמְשׁוֹטְטוֹת רוּחוֹת טְמֵאוֹת בָּעוֹלָם, וְעַל כֵּן הִשְׁבִּיעַ אֶת עַבְדּוֹ שֶׁלֹּא יִקַּח אִשָּׁה לִבְנוֹ מִשְּׁאָר הָעַמִּים."],[6,"","אַבְרָהָם זָקֵן בָּא בַּיָּמִים וְגוֹ'. מִשְׁנָה: אָמַר רַבִּי אֶלְעָזָר, עַל כָּל פָּנִים כָּךְ הוּא, שֶׁהַמִּשְׁנָה הַזּוֹ יָפָה, שֶׁנַּעֲשֵׂית הַנְּשָׁמָה, הַהוּא שֶׁכָּתוּב בּוֹ (יחזקאל א) והנה אופן אחד בארץ אצל החיות לארבעת פניו, כמו שאמור באותה הבריתא הראשונה."],[7,"","אָמַר לוֹ רַבִּי אַבָּא, יֹאמַר לָנוּ מַר מִאוֹתָהּ הַמִּשְׁנָה. אָמַר לוֹ, כָּךְ הִתְפָּרֵשׁ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים בַּפָּרָשָׁה שֶׁלּוֹ, אֲבָל כָּאן שׁ לָנוּ לוֹמַר. פָּתַח וְאָמַר, (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לאִמָּהּ וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, מַה הִיא שֶׁאָנוּ קוֹרְאִים כָּאן בְּשִׁיר הַשִּׁירִים לְשׁוֹן נְקֵבָה, וְשָׁם בַּתּוֹרָה לְשׁוֹן זָכָר?"],[8,"","אְלָּא, אָמַר רַבִּי אֶלְעָזָר, כָּאן בַּתּוֹרָה נִקְרָא בִּלְשׁוֹן זָכָר אֵצֶל הַגּוּף, מִפְּנֵי שֶׁהַגּוּף אֵצֶל הַנְּשָׁמָה כְּאִשָּׁה אֵצֶל הַזָּכָר, וְהַנְּשָׁמָה כְּלַפֵּי מַעְלָה כִּנְקֵבָה בִּפְנֵי הַזָּכָר, וְכָל אֶחָד יוֹרֵשׁ מַעֲלָתוֹ."],[9,"","שָׁנִינוּ שָׁם, בְּאַרְבַּע פְּעָמִים (בשנה) בְּשָׁעָה בְּכָל יוֹם הָעֵדֶן מְנַטֵּף עַל הַגָּן, וְיוֹצֵא מֵאוֹתָם הַטִּפּוֹת נָהָר גָּדוֹל הַמִּתְחַלֵּק לְאַרְבָּעָה רָאשִׁים, וּשְׁמוֹנֶה וְאַרְבָּעִים טִפּוֹת מְנַטֵּף בְּכָל יוֹם, וּמִשָּׁם שְׂבֵעִים אִילָנֵי הַגָּן. זֶהוּ שֶׁכָּתוּב (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה'. רַבִּי תַּנְחוּם אָמַר, מִכָּאן (שם) מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו. אֵיזוֹ הִיא עֲלִיָּה? זֶהוּ עֵדֶן. וְעֵדֶן בְּאֵיזֶה מָקוֹם הוּא? רַבִּי יְהוּדָה אָמַר, לְמַעְלָה מֵעֲרָבוֹת הוּא. רַבִּי יוֹסֵי אָמַר, בַּעֲרָבוֹת הוּא, שֶׁהֲרֵי שָׁנִינוּ, שָׁם גִּנְזֵי חַיִּים טוֹבִים בְּרָכָה וְשָׁלוֹם וְנִשְׁמָתָן שֶׁל צַדִּיקִים, וְהַגָּנוּז הָעֶלְיוֹן. הוּא עֵדֶן לְמַטָּה מְכֻוָּן כְּנֶגְדּוֹ גַּן בָּאָרֶץ וְנוֹטֵל מִמֶּנּוּ שֶׁפַע בְּכָל יוֹם."],[10,"","אָמַר רַבִּי אַבָּהוּ, שְׁמוֹנָה וְאַרְבָּעִים נְבִיאִים עָמְדוּ לָהֶם לְיִשְׂרָאֵל, וְכָל אֶחָד נָטַל בְּחֶלְקוֹ תַּמְצִית טִפָּה אַחַת מֵאוֹתָם טִפּוֹת שֶׁל עֵדֶן, שֶׁהֵם שְׁמוֹנֶה וְאַרְבָּעִים טִפּוֹת. וּמָה אִם כָּל נָבִיא שֶׁנָּטַל טִפָּה אַחַת מֵהֶן הָיְתָה מַעֲלָתוֹ בְּרוּחַ הַקֹּדֶשׁ עַל כָּל הַשְּׁאָר - אָדָם הָרִאשׁוֹן שֶׁהָיָה מְקַבֵּל מִשְּׁמוֹנֶה וְאַרְבָּעִים לֹא כָּל שֶׁכֵּן. מִכָּאן אַתָּה לָמֵד כַּמָּה הָיְתָה חָכְמָתוֹ."],[11,"","רַבִּי בָּא אָמַר רַב כַּהֲנָא, וְכִי מֵאַיִן הָיָה לָהֶם לַנְּבִיאִים מֵאוֹתָן הַטִּפּוֹת? אֶלָּא כָּךְ שָׁנִינוּ, בְּכָל טִפָּה וְטִפָּה הַיּוֹצֵאת מֵעֵדֶן, רוּחַ חָכְמָה יוֹצֵאת עִמּוֹ, וְעַל כֵּן נִגְזַר בַּמִּשְׁנָה: יֵשׁ מַיִם שֶׁמְּגַדְּלִים חֲכָמִים, וְיֵשׁ מַיִם שֶׁמְּגַדְּלִים טִפְּשִׁים. וְאוֹתָם הַמַּיִם שֶׁמְּגַדְּלִים חֲכָמִים, אוֹתָם הַמַּיִם הָיוּ מִטִּפּוֹת שֶׁל עֵדֶן."],[12,"","שֶׁאָמַר רַבִּי יוֹסֵי, הַמַּיִם שֶׁבָּהֶם טִפּוֹת יוֹשְׁבִים (נ\"א: יתרים) מִכָּל אוֹתָם אַרְבַּעַת הַנְּהָרוֹת הָרִאשׁוֹנִים, הוּא שֶׁכָּתוּב (בראשית ב) שֵׁם הָאֶחָד פִּישׁוֹן. מַה זֶּה שֵׁם הָאֶחָד פִּישׁוֹן? הַמְיֻחָד מִכֻּלָּם פִּישׁוֹן, וְהוּא הַנּוֹפֵל בְּאֶרֶץ מִצְרַיִם, וּלְפִיכָךְ הָיְתָה חָכְמַת (לישראל) מִצְרַיִם יוֹתֵר מִכָּל הָעוֹלָם."],[13,"","וּמִשֶּׁנִּגְזְרָה הַגְּזֵרָה שֶׁאָבְדָה חָכְמַת מִצְרַיִם, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם הַטִּפּוֹת וְזָרַק אוֹתָם בְּאוֹתוֹ הַגָּן, בְּאוֹתוֹ הַנָּהָר שֶׁל גַּן עֵדֶן, שֶׁכָּתוּב (שם) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְזֶה הָיָה מוֹלִיד אַרְבָּעָה אֲחֵרִים, וְהָאֶחָד הַמְיֻחָד הַנּוֹלַד מִמֶּנּוּ פִּישׁוֹן הָיָה. מִשֶּׁנִּטְּלוּ אֵלּוּ הַטִּפּוֹת שֶׁלֹּא יָצְאוּ מֵהַגָּן, אָבְדָה הַחָכְמָה מִמִּצְרַיִם."],[14,"","וּמֵאוֹתָהּ הָרוּחַ שֶׁהָיְתָה יוֹצֵאת מֵעֵדֶן, תִּמְצוּ (ימצו) כָּל נָבִיא וְנָבִיא, וְהַיְנוּ שֶׁכָּתוּב מִתְהַלֵּךְ בַּגַּן לְרוּחַ הַיּוֹם. וְגָנוּז זֶה בְּגַן עֵדֶן לֶעָתִיד לָבֹא, וְזֶה הוּא הַנָּהָר שֶׁרָאָה יְחֶזְקֵאל בִּנְבוּאָתוֹ, וְעַל כֵּן אָמַר הַכָּתוּב (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה' וְגוֹ'. שֶׁאוֹתָם מַיִם תָּמִיד מְגַדְּלִים הַיְדִיעָה בָּעוֹלָם."],[15,"","שָׁנוּ רַבּוֹתֵינוּ, כָּל נִשְׁמָתָן שֶׁל צַדִּיקִים לְמַעְלָה, בְּעֵדֶן הֵן. וּמַה מִּמַּה שֶּׁיּוֹרֵד מֵעֵדֶן יִשְׂגֶּא הַחָכְמָה בָּעוֹלָם - לָעוֹמְדִים בּוֹ וְנֶהֱנִים מֵהֲנָאוֹתָיו וְכִסּוּפָיו עַל אַחַת כַּמָּה וְכַמָּה."],[16,"","אָמַר רַבִּי יִצְחָק, כֵּיוָן שֶׁהַנְּשָׁמָה זוֹכָה לִכָּנֵס בְּשַׁעֲרֵי יְרוּשָׁלַיִם שֶׁל מַעְלָה, מִיכָאֵ\"ל הַשַּׂר הַגָּדוֹל הוֹלֵךְ עִמָּהּ וּמַקְדִּים לָהּ שָׁלוֹם. מַלְאֲכֵי הַשָּׁרֵת תְּמֵהִים בָּהּ וְשׁוֹאֲלִים עָלֶיהָ (שיר ג) מִי זֹאת עֹלָה מִן הַמִּדְבָּר. מִי זֹאת עֹלָה בֵּין הָעֶלְיוֹנָה מֵהַגּוּף הֶחָרֵב שֶׁדּוֹמֶה לְהֶבֶל, שֶׁכָּתוּב (תהלים קמד) אָדָם לַהֶבֶל דָּמָה. הוּא מֵשִׁיב וְאוֹמֵר, (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי. אַחַת הִיא - מְיֻחֶדֶת הִיא. אַחַת הִיא לְאִמָּהּ - לְאִמָּהּ זוֹ הִיא כִּסֵּא הַכָּבוֹד שֶׁהִיא אֵם לַנְּשָׁמָה וְיוֹלֶדֶת לָהּ, שֶׁנִּגְזְרָה מִמֶּנָּה."],[17,"","רָאוּהָ בָנוֹת וַיְאַשְּׁרוּהָ - אֵלּוּ שְׁאָר הַנְּשָׁמוֹת שֶׁהֵן בְּמַעֲלָתָן לְמַעְלָה, וְהֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם. אָמַר רַבִּי יוֹסֵי, הִנֵּה חָזַרְנוּ עַל מַה שֶּׁאָמַרְנוּ - אֵלּוּ נִקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם, וְהָאֲחֵרוֹת נִקְרָאוֹת בְּנוֹת לוֹט. רָאוּהָ בָנוֹת וַיְאַשְּׁרוּהָ - שְׁאָר הַנְּשָׁמוֹת מְשַׁבְּחוֹת לָהּ וְאוֹמְרוֹת שָׁלוֹם בּוֹאֵךְ. מְלָכוֹת וּפִילַגְשִׁים - מְלָכוֹת אֵלּוּ הָאָבוֹת שֶׁהֵם מְלָכוֹת, וּפִילַגְשִׁים הֵם גֵּרֵי הַצֶּדֶק. כֻּלָּם מְשַׁבְּחוֹת וּמְקַלְּסוֹת אוֹתָהּ עַד שֶׁנִּכְנֶסֶת לְמַעְלָה, וַאֲזַי הַנְּשָׁמָה בְּמַעֲלָתָהּ וּמִתְקַיֶּמֶת אֲרִיכוּת יָמִים. זֶהוּ שֶׁכָּתוּב וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים. נִכְנַס בַּאֲרִיכוּת יָמִים לָעוֹלָם הַבָּא."],[18,"","רַבִּי אַבָּא הַזָּקֵן קָם עַל רַגְלָיו וְאָמַר, מְנוּחָה וְשָׁלוֹם עֲצָמוֹת יִהְיוּ לְךְ, רַבִּי שִׁמְעוֹן, שֶׁהֶחֱזַרְתָּ עֲטָרָה לְיָשְׁנָהּ. שֶׁשָּׁנִינוּ בַּבָּרַיְתָא הָרִאשׁוֹנָה, שֶׁכֵּיוָן שֶׁהַנְּשָׁמָה הִיא בִּשְׁלֵמוּתָהּ בְּמָקוֹם עֶלְיוֹן (לזמן אחר נכנסים), לֹא שָׁבָה לַגּוּף, אֶלָּא נִבְרָאוֹת מִמֶּנָּה נְשָׁמוֹת אֲחֵרוֹת שֶׁיּוֹצְאוֹת מִמֶּנָּה, וְהִיא נִשְׁאֶרֶת בְּקִיּוּם, עַד שֶׁבָּא רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי וְדָרַשׁ, וּמָה אִם בָּעוֹלָם הַזֶּה שֶׁהוּא הֶבֶל, וְהַגּוּף שֶׁהוּא טִפָּה סְרוּחָה, נִכְנֶסֶת בּוֹ אוֹתָהּ הַנְּשָׁמָה - לֶעָתִיד לָבא שֶׁיִּצָּרְפוּ כֻלָּם וְיִהְיֶה הַגּוּף מֻבְחָר בְּקִיּוּם וְתַשְׁלוּם יוֹתֵר, אֵינוֹ דִין לְהִכָּנֵס אוֹתָהּ הַנְּשָׁמָה בּוֹ בְּכָל הַתַּשְׁלוּמִים וְהָעִלּוּיִים שֶׁבָּהּ?"],[19,"","אָמַר רַבִּי אָחָא, אוֹתָהּ הַנְּשָׁמָה (בו בכל התשלומים והעלויים שבה) מַמָּשׁ, וְאוֹתוֹ הַגּוּף מַמָּשׁ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲמִידָן בְּקִיּוּמָן לֶעָתִיד לָבא, אֲבָל שְׁנֵיהֶם יִהְיוּ שְׁלֵמִים בְּתַשְׁלוּם הַדַּעַת לְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיגוּ בָּעוֹלָם הַזֶּה."],[20,"","וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וְגוֹ'. רַבִּי בּוֹ אָמַר רַבִּי יוֹחָנָן, (באותם הימים) בְּאוֹתוֹ עוֹלָם שֶׁהוּא יָמִים, וְלֹא בָּעוֹלָם הַזֶּה שֶׁהוּא לַיְלָה. אָמַר רַבִּי יַעֲקֹב, בְּאוֹתָם הָעוֹלָמוֹת שֶׁהֵם יָמִים, בְּאוֹתָם הַהֲנָאוֹת וְהַכִּסּוּפִים שֶׁהוּא נוֹחֵל. וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. בְּאוֹתָהּ הַמִּשְׂרָה (נ\"א: המעשר) שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְּׁמוֹ, שֶׁהִיא אוֹת הֵ\"א, שֶׁבָּהּ נִבְרָא הָעוֹלָם."],[21,"","וְלָמַדְנוּ, אָמַר רַבִּי יוֹחָנָן, מטטרו\"ן שַׂר הַפְּנִים, שֶׁהוּא נַעַר עֶבֶד מֵרַבּוֹ הָאָדוֹן הַמּוֹשֵׁל עָלָיו, מְמֻנֶּה עַל הַנְּשָׁמָה בְּכָל יוֹם לְהַסְפִּיק לָהּ מֵאוֹתוֹ הָאוֹר שֶׁנִּצְטַוָּה, וְהוּא עָתִיד לָקַחַת חֶשְׁבּוֹן פֶּתֶק בְּבָתֵּי הַקְּבָרוֹת מִדּוּמָה, וּלְהַרְאוֹת אוֹתוֹ לִפְנֵי רַבּוֹ, וְהוּא עָתִיד לַעֲשׂוֹת שְׂאוֹר אוֹתוֹ הָעֶצֶם תַּחַת הָאָרֶץ, לְתַקֵּן אֶת הַגּוּפוֹת וּלְקַיְּמָם בִּשְׁלֵמוּת שֶׁל גּוּף בְּלִי הַנְּשָׁמָה, (בזמן) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁלַח אוֹתָהּ לִמְקוֹמָהּ."],[22,"","אָמַר רַבִּי יִצְחָק, בְּאוֹתָהּ שָׁעָה מַה כָּתוּב? וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ זְקַן בֵּיתוֹ הַמּוֹשֵׁל וְגוֹ'. מַהוּ אֶל עַבְדּוֹ? אִם בַּחָכְמָה הַזּוֹ נִסְתַּכֵּל, מַה זֶּה אֶל עַבְדּוֹ? אָמַר רַבִּי נְהוֹרַאי, לֹא נִסְתַּכֵּל אֶלָּא בְּמַה שֶּׁאָמַר עַבְדּוֹ, עַבְדּוֹ שֶׁל מָקוֹם, (זקן ביתו) הַקָּרוֹב לַעֲבוֹדָתוֹ, וּמִי הוּא? זֶה מטטרו\"ן, כְּפִי שֶׁאָמַרְנוּ. שֶׁהוּא עָתִיד לְיַפּוֹת אֶת הַגּוּף בְּבָתֵּי הַקְּבָרוֹת."],[23,"","זְהִוּ שֶׁכָּתוּב וַיֹּאמֶר אַבְרָהָם אֶל עָבְדּוֹ, זֶה מטטרו\"ן עַבְדּוֹ שֶׁל מָקוֹם. זְקַן בֵּיתוֹ, שֶׁהוּא תְחִלַּת בְּרִיּוֹתָיו שֶׁל מָקוֹם. הַמֹּשֵׁל בְּכָל אֲשֶׁר לוֹ, שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֶמְשָׁלָה עַל כָּל צִבְאוֹתָיו."],[24,"","וְלָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן אָמַר רַבִּי יוֹסֵי אָמַר רַב, כָּל צִבְאוֹתָיו שֶׁל אוֹתוֹ עֶבֶד נוֹטְלִים אוֹר וְנֶהֱנִים מִזִּיו הַנְּשָׁמָה. שֶׁלָּמַדְנוּ, אוֹר הַנְּשָׁמָה לָעוֹלָם הַבָּא גָּדוֹל מֵאוֹר הַכִּסֵּא. וַהֲרֵי מֵהַכִּסֵּא נִטְּלָה הַנְּשָׁמָה? אֶלָּא זֶה לְפִי הָרָאוּי לוֹ, וְזֶה לְפִי הָרָאוּי לוֹ. רַב נַחְמָן אָמַר, גָּדוֹל מֵאוֹר הַכִּסֵּא מַמָּשׁ, שֶׁכָּתוּב (יחזקאל א) דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. מַה זֶּה עָלָיו? עַל זָהֳרוֹ."],[25,"","וּכְשֶׁהוּא הוֹלֵךְ לַעֲשׂוֹת שְׁלִיחוּתוֹ, כָּל צִבְאוֹתָיו וְהַמֶּרְכָּבָה שֶׁלּוֹ נִזּוֹנִים מֵאוֹתוֹ הַזֹּהַר. זֶהוּ שֶׁהַנְּשָׁמָה אוֹמֶרֶת לוֹ, (שכתוב) שִׂים נָא יָדְךְ, כְּלוֹמַר סִיעָתְךְ. תַּחַת יְרֵכִי - זֶהוּ אוֹר הַנִּשְׁפָּע מִן הַנְּשָׁמָה עֲלֵיהֶם."],[26,"","אָמַר רַבִּי יְהוּדָה בְּרַבִּי שָׁלוֹם, כָּךְ קִבַּלְנוּ, בְּשָׁעָה שֶׁזֶּה הוֹלֵךְ בִּשְׁלִיחוּתוֹ שֶׁל מָקוֹם, הַקָּדוֹשׁ בָּרוּךְ הוּא מֵנִיעַ כָּל צִבְאוֹתָיו שֶׁל מַעְלָה בְּאוֹת אַחַת מִשְּׁמוֹ. אָמַר רַב הוּנָא, כָּךְ יְרֵכִ\"י בְּגִימַטְרִיָּא רָ\"ם. כְּלוֹמַר, הַנְּשָׁמָה אוֹמֶרֶת שִׂים נָא יָדְךְ, סִיעָתְךְ, תַּחַת מַעֲלָתוֹ שֶׁל רָם וְנִשָּׂא הַמּוֹשֵׁל עַל הַכֹּל. וּלְאַחַר שֶׁצִּוָּה סִיעַת הָעֶלְיוֹנִים תַּחַת יָדוֹ, אֲנִי מַשְׁבִּיעֲךְ שְׁבוּעָה גְדוֹלָה בּוֹ."],[27,"","אָמַר רַבִּי יִצְחָק, אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ - הוֹאִיל וְאָמַר בַּה' שֶׁהוּא הַכֹּל, לָמָּה נֶאֱמַר אֱלֹהֵי הַשָּׁמַיִם? אָמַר רַבִּי יְהוּדָה, שֶׁהוּא אָדוֹן עַל הַכֹּל. בְּבַת אַחַת וּבְרֶגַע אֶחָד הוּא מֵנִיעַ לַכֹּל, וְכֻלָּם כְּאַיִן נֶגְדּוֹ. רַבִּי יִצְחָק אוֹמֵר עַל שְׁתַּיִם אוֹתִיּוֹת מִשְּׁמוֹ, לְהוֹרוֹת שֶׁהוּא הַכֹּל וְאֵין אַחֵר בִּלְתּוֹ."],[28,"","וְאַשְׁבִּיעָךָ בַּה' אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ. אָמַר רַב הוּנָא, וְאִם הָיִיתִי עִמָּהֶם שֶׁל בַּעֲלֵי הַבָּרַיְתָא כְּשֶׁגִּלּוּ הַסּוֹד הַזֶּה, לֹא נִפְרָד הָיִיתִי מֵהֶם כָּךְ, שֶׁהֲרֵי אֲנִי רוֹאֶה עֳמָקִים רַבִּים בְּפִיהֶם שֶׁגִּלּוּ וְלֹא רְאוּיִים לְכָל אָדָם. בֹּא רְאֵה, שְׁבוּעַת הַבְּרִית הַזּוֹ נִשְׁבַּעַת הַנְּשָׁמָה, שֶׁכָּתוּב אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי."],[29,"","אָמַר רַבִּי יִצְחָק, מִכָּאן מַשְׁמָע, שֶׁהוֹאִיל וְאַתָּה הוֹלֵךְ בִּשְׁלִיחוּת זוֹ, לֹא תִקַּח אִשָּׁה לִבְנִי. כְּלוֹמַר שֶׁלֹּא תִקַּח גּוּף לִבְנִי (לבניני) לְהִכָּנֵס בְּגוּף אַחֵר, בְּגוּף זָר, בְּגוּף שֶׁאֵינוֹ רָאוּי לוֹ, אֶלָּא בְּהַהוּא מַמָּשׁ שֶׁהוּא שֶׁלִּי, בְּהַהוּא מַמָּשׁ שֶׁיָּצָאתִי מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב כִּי אִם אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ."],[30,"","אָמַר רַבִּי יוֹסֵי, מַהוּ וְלָקַחְתָּ אִשָּׁה לִבְנִי לְיִצְחָק? אָמַר רַבִּי יִצְחָק, אוֹתוֹ הַגּוּף שֶׁנִּצְטַעֵר עִמִּי בְּאוֹתוֹ הָעוֹלָם וְלֹא הָיָה לוֹ הֲנָאָה וְכִסּוּף בּוֹ מִפְּנֵי יִרְאַת קוֹנוֹ, אוֹתוֹ הַגּוּף מַמָּשׁ תִּקַּח לִצְחַק עִמּוֹ בְּשִׂמְחַת הַצַּדִּיקִים הַזּוֹ, לִצְחַק עִמּוֹ בְּשִׂמְחַת הַקָּדוֹשׁ בָּרוּךְ הוּא, לִצְחַק עִמּוֹ שֶׁעַכְשָׁו עֵת שְׂחוֹק בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים קכו) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וְגוֹ'."],[31,"","אָמַר רַבִּי יְהוּדָה בַּר יִצְחָק, בּא תִשְׁמַע, אֵין מַלְאָךְ אֶחָד עוֹשֶׂה אֶלָּא שְׁלִיחוּת אַחַת, וְלֹא שְׁתֵּי שְׁלִיחֻיּוֹת בְּבַת אַחַת. וְלָמַדְנוּ, אָמַר רַבִּי אַבָּא, מַלְאָךְ אֶחָד, אֲשֶׁר קֶסֶת הַסּוֹפֵר בְּמָתְנָיו, עָתִיד לְהַרְשִׁים כָּל אֶחָד וְאֶחָד עַל מִצְחוֹ, וּלְאַחַר כֵּן הַשַּׂר הַגָּדוֹל הוֹלֵךְ לְתַקֵּן כָּל אֶחָד וְאֶחָד וּלְהַעֲמִידוֹ לְקַבֵּל נִשְׁמָתוֹ. זֶהוּ שֶׁכָּתוּב הוּא יִשְׁלַח מַלְאָכוֹ לְפָנֶיךְ וְלָקַחְתָּ אִשָּׁה. מַה זֶּה לְפָנֶיךְ? לִפְנֵי שְׁלִיחוּתְךְ."],[32,"","רַבִּי (אלעזר) אֱלִיעֶזֶר הָלַךְ לִרְאוֹת אֶת רַבָּן יוֹחָנָן בֶּן זַכַּאי רַבּוֹ, וְאוֹתוֹ הַיּוֹם הָיָה רֹאשׁ חֹדֶשׁ. כְּשֶׁהִגִּיעַ אֵלָיו, אָמַר לוֹ, הַבְּאֵר שֶׁמְּנֻקֶּה מִכָּל טִנֹּפֶת, וּמְמַלְּאִים אוֹתוֹ וְנוֹבֵעַ מִשֶּׁלּוֹ יוֹתֵר, מָה רוֹצֶה כָּאן?"],[33,"","אָמַר לוֹ, חַיָּב אָדָם לְהַקְבִּיל פְּנֵי רַבּוֹ. אָמַר לוֹ, לֹא כָּךְ אָמַרְתִּי, אֶלָּא אֲנִי רוֹאֶה בְפָנֶיךְ שֶׁדָּבָר חָדָשׁ יֵשׁ אֶצְלְךְ מֵאוֹתָם הָעֲמֻקִּים שֶׁאַתָּה עָתִיד לִשְׁאֹל."],[34,"","אָמַר לוֹ, רָאִיתִי אֶת הָאוֹר הָרִאשׁוֹן הַזֶּה שֶׁמַּסְעוֹתָיו עֲשָׂרָה, וְנוֹסֵעַ בַּעֲשָׂרָה, וּבַסּוֹד שֶׁל עֲשָׂרָה מַנְהִיג אֶת הַכֹּל, וּבָאוֹתִיּוֹת שֶׁל עֲשָׂרָה עוֹשֶׂה אֶת מַעֲשָׂיו. וְלָמַדְנוּ, עֲשָׂרָה פְתָקִים, עֲשָׂרָה מַפְתְּחוֹת שֶׁל בֵּית חוֹלִים בְּיָדוֹ, וַעֲשָׂרָה פְתָקִים נוֹטֵל בְּגַן עֵדֶן לְהַתְקִין אֶרֶץ עַל גּוּפוֹת הַצַּדִּיקִים."],[35,"","אָמַר לוֹ, אֱלִיעֶזֶר בְּנִי, הָיִיתָ רוֹאֶה יוֹתֵר מִמַּלְאָךְ קָדוֹשׁ שֶׁל הָעוֹלָם, בַּעֲשָׂרָה נִבְרָא, בַּעֲשָׂרָה מֻנְהָג. בַּעֲשָׂרָה הַכִּסֵּא הַקָּדוֹשׁ. בַּעֲשָׂרָה הַתּוֹרָה, הוּא בַּעֲשָׂרָה מַסְעוֹתָיו. בַּעֲשָׂרָה עוֹלָמוֹת. עֶלְיוֹנִים (בעשרה). וְאֶחָד עֶלְיוֹן עַל הַכֹּל בָּרוּךְ הוּא."],[36,"","וְאֹמַר לְךְ דָּבָר, דַּעְתּוֹ שֶׁל בַּעַל הַמִּשְׁנָה הָיְתָה בָּזֶה. מַה כָּתוּב? וַיִּקַּח הָעֶבֶד עֲשָׂרָה גְמַלִּים מִגְּמַלֵּי אֲדנָיו וַיֵּלֶךְ. אָמַר לוֹ, רַבִּי, זָכִיתִי לַפָּסוּק הַזֶּה, אֲבָל וְכָל טוּב אֲדנָיו בְּיָדוֹ מַהוּ? אָמַר לוֹ, הוּא שְׁמוֹ שֶׁל רַבּוֹ שֶׁהָלַךְ אֵלָיו לְהַכְנִיסוֹ וּלְהַנְהִיג (ולהגן) אוֹתוֹ. אָמַר, זֶהוּ וַדַּאי, כִּי שְׁמִי בְּקִרְבּוֹ."],[37,"","שָׁנִינוּ, אָמַר רַבִּי אַבָּהוּ, בֹּא רְאֵה, מִי שֶׁיּוֹדֵעַ אֶת שְׁמוֹ עַל בֻּרְיוֹ, יוֹדֵעַ שֶׁהוּא וּשְׁמוֹ אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁמוֹ אֶחָד, שֶׁכָּתוּב (זכריה יד) ה' אֶחָד וְגוֹ'. (כלם) כְּלוֹמַר, הַשֵּׁם וְהוּא אֶחָד."],[38,"","אָמַר רַבִּי אַבָּא, יֵשׁ לְהִסְתַּכֵּל בַּפָּרָשָׁה הַזּוֹ: וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמָּיִם. אָמַר רַבִּי אַבָּא, מִחוּץ לָעִיר - זֶהוּ בֵּית הַקְּבָרוֹת. אֶל בְּאֵר הַמָּיִם - שֶׁלָּמַדְנוּ, הַנִּקְדָּמִים בְּבָתֵּי הַקְּבָרוֹת - אוֹתָם שֶׁנָּשְׂאוּ וְנָתְנוּ בַּתּוֹרָה. שֶׁהֲרֵי שָׁנִינוּ, כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר, מַה שֶּׁשָּׁאֲלוּ אוֹתוֹ בַּתְּחִלָּה - אִם קָבַע עִתִּים לַתּוֹרָה, שֶׁכָּתוּב (ישעיה לג) וְהָיָה אֱמוּנַת עִתֶּךְ וְגוֹ'. וּכְשֶׁיֵּצֵא, אֵינוֹ דִּין (לקימם) לַהֲקִימָם בַּתְּחִלָּה."],[39,"","אָמַר רַבִּי אַבָּא, לְעֵת עֶרֶב - זֶהוּ יוֹם שִׁשִּׁי, שֶׁהוּא עֶרֶב הַשַּׁבָּת, שֶׁאָז הַזְּמַן לְהַעֲמִיד אֶת הַמֵּתִים. מַה מַּשְׁמָע? שֶׁשָּׁנִינוּ. שֵׁשֶׁת אַלְפֵי שָׁנִים הוּא הָעוֹלָם, וְהוּא אֶלֶף הַשִּׁשִּׁי שֶׁהוּא סִיּוּם הַכֹּל. וְהַיְנוּ לְעֵת עֶרֶב, זְמַן סִיּוּם הַכֹּל. לְעֵת צֵאת הַשּּׁאֲבֹת - אֵלּוּ הֵם תַּלְמִידֵי חֲכָמִים הַשּׁוֹאֲבִים מֵימֶיהָ שֶׁל תּוֹרָה, שֶׁהוּא עֵת לָצֵאת וּלְהִתְנַעֵר מִן הֶעָפָר."],[40,"","וְאָמַר רַבִּי אַבָּא, עוֹד יֵשׁ לָדַעַת, שֶׁשָּׁנִינוּ, אוֹתָם הַמִּתְעַסְּקִים לָדַעַת אֶת בּוֹרְאָם בָּעוֹלָם הַזֶּה וְנִשְׁמָתָם בְּתַשְׁלוּמָהּ לָעוֹלָם הַבָּא, זָכוּ לָצֵאת מִשְּׁבוּעוֹת הַנְּשָׁמָה, הוֹלֵךְ לָדַעַת מִי הוּא גוּפָהּ מַמָּשׁ וּמַה הוּא. הִנֵּה אָנֹכִי נִצָּב עַל עֵין הַמָּיִם, אַף עַל גַּב שֶׁתַּלְמִיד חָכָם הוּא, הוֹלֵךְ אַחַר הַתַּשְׁלוּם, שֶׁכָּתוּב וְהָיָה הָעַלְמָה הַיֹּצֵאת לִשְׁאֹב וְאָמַרְתִּי אֵלֶיהָ הַשְׁקִינִי נָא מְעַט מַיִם מִכַּדֵּךְ - אֱמֹר לִי רֶמֶז יְדִיעָתוֹ מִמַּה שֶּׁהִשַּׂגְתָּ."],[41,"","וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה - אַף אַתָּה עֶבֶד (כמוך) כָּמוֹנִי, וְלֹא נִתְחַלֵּף לִי (על) יְדִיעָתְךְ בִּידִיעָתוֹ שֶׁל מָקוֹם בָּרוּךְ הוּא, וְצָרִיךְ אַתָּה לְהַשִּׂיג, שֶׁאַתָּה נִבְרָא כָּמוֹנִי."],[42,"","וְגַם לִגְמַלֶּיךְ אֶשְׁאָב - כְּלוֹמַר, יְדִיעַת הַשָּׂגָתִי שֶׁלֹּא הִשִּׂיגוּ סִיעָתְךְ, וְיָדַעְתִּי כִּי מַעֲלָה יֵשׁ לִי עָלֶיךְ וְהֵיאַךְ נִבְרָא אַתָּה מִזִּיו הַנָּתוּן אֶצְלְךְ. אִם הוּא אוֹמֵר סִימָן זֶה יְהִי מָסוּר בְּיָדִי עַל כָּל דְּבָרִים אֵלּוּ, וְאֵדַע שֶׁהִיא הָאִשָּׁה, הוּא הַגּוּף מֵאוֹתָהּ הַנְּשָׁמָה, הַשְּׁבוּעָה שֶׁהִשְׁבִּיעַנִי."],[43,"","וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְגוֹ'. רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, בְּעוֹד שֶׁכָּל הָעִנְיָנִים הוּא רוֹצֶה לְנַסּוֹת עַל הַגּוּף, מַה כָּתוּב? וְהִנֵּה רִבְקָה יצֵאת, זֶהוּ הַגּוּף קָדוֹשׁ שֶׁנִּתְעַסֵּק בְּדִבְרֵי תוֹרָה וְכִתֵּת גּוּפוֹ לְהַשִּׂיג וְלָדַעַת אֶת קוֹנוֹ. אֲשֶׁר יֵלְּדָה לִבְתוּאֵל - אָמַר רַב יְהוּדָה, בִּתּוֹ שֶׁל אֵל. בֶּן מִלְכָּה - בֶּן מַלְכָּהּ שֶׁל עוֹלָם. אֵשֶׁת נָחוֹר אֲחִי אַבְרָהָם - חֶבְרַת הַשֵּׂכֶל, גּוּף שֶׁנִּדְבָּק בַּשֵּׂכֶל, וְהִיא אַח הַנְּשָׁמָה. וְכַדָּהּ עַל שִׁכְמָהּ - מַשָּׂא הַחָכְמָה עָלֶיהָ."],[44,"","וַיָּרָץ הָעֶבֶד לִקְרָאתָהּ - זֶה מטטרו\"ן. וַיֹּאמֶר הַגְמִיאִינִי מְעַט מַיִם מִכַּדֵּךְ - אֱמֹר לִי רֶמֶז חָכְמָה בִּידִיעַת בּוֹרַאֲךְ מִמַּה שֶּׁעָסַקְתָּ בָּעוֹלם שֶׁיָּצָאתָ מִמֶּנּוּ. אָמַר רַבִּי אַבָּא, כְּמוֹ שֶׁפֵּרַשְׁנוּ, אַחַר כָּל זֶה מַה כָּתוּב? וָאָשִׂם הַנֶּזֶם עַל אַפָּהּ וְהַצְּמִידִים עַל יָדֶיהָ. אָמַר רַבִּי אַבָּא, אוֹתָם הָעֲצָמוֹת שֶׁנִּפְזְרוּ לְכָאן וּלְכָאן, הוּא צוֹמֵד אוֹתָם וְשׁוֹקְלָם זֶה עַל זֶה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נח) וְעַצְמֹתֶיךְ יַחֲלִיץ. אָמַר רַבִּי אַבָּא, בְּאוֹתָהּ שָׁעָה אוֹתוֹ הַגּוּף עוֹמֵד בְּאֶרֶץ יִשְׂרָאֵל, וְשָׁם נִכְנָס בּוֹ נִשְׁמָתוֹ."],[45,"","אָמַר רַבִּי יוֹחָנָן, מִי מוֹלִיךְ הַגּוּף לְאֶרֶץ יִשְׂרָאֵל? אָמַר רַבִּי זֵירָא, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מְחִלּוֹת תַּחַת הָאָרֶץ, וְהֵם מִתְגַּלְגְּלִים וְהוֹלְכִים לְאֶרֶץ יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (שם כו) וָאָרֶץ רְפָאִים תַּפִּיל."],[46,"","אָמַר רַבִּי יִצְחָק, גַּבְרִיאֵ\"ל מוֹלִיךְ אוֹתָם לְאֶרֶץ יִשְׂרָאֵל, מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית כד) הֲתֵלְכִי עִם הָאִישׁ הַזֶּה, וְכָתוּב שָׁם (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל. אָמַר רַבִּי יוֹסֵי, מַהוּ שֶׁכָּתוּב וּלְרִבְקָה אָח וּשְׁמוֹ לָבָן? אָמַר רַבִּי יִצְחָק, אֵין יֵצֶר הָרָע בָּטֵל מִן הָעוֹלָם. אַף עַל פִּי שֶׁכֻּלּוֹ לֹא נִמְצָא - קְצָתוֹ נִמְצָא."],[47,"","בֹּא רְאֵה, בַּתְּחִלָּה כְּשֶׁהָיָה מֻטָּל בָּעוֹלָם הַזֶּה, נִקְרָא לוֹט. לָעוֹלָם הַבָּא (יבדל) יִבָּטֵל מִן הָעוֹלָם, אֲבָל (לעתיד לבא) לֹא כֻּלּוֹ, וְנִקְרָא לָבָן, לֹא מְנֵוּל כְּבָרִאשׁוֹנָה, אֶלָּא כְּמִי שֶׁרוֹחֵץ מִנִּוּוּלוֹ. לָמָּה צָרִיךְ לָבָן? אָמַר רַבִּי שִׁמְעוֹן, לַעֲשׂוֹת פְּרִיָּה וּרְבִיָּה צָרִיךְ. שֶׁאָמַר רַבִּי שִׁמְעוֹן, אִם אֵין יֵצֶר הָרָע נִמְצָא, פְּרִיָּה וּרְבִיָּה אֵינוֹ מָצוּי."],[48,"","בֹּא תִשְׁמַע, כֵּיוָן שֶׁהַגּוּף נִבְנֶה וְעוֹמֵד בְּקִיּוּמוֹ, מַה כָּתוּב? וַיְשַׁלְּחוּ אֶת רִבְקָה אֲחֹתָם וְגוֹ'. מַה זֶּה וְאֶת מֵנִקְתָּהּ? זֶה כֹּחַ הַתְּנוּעָה. רַבִּי יִצְחָק אָמַר, זֶה כֹּחַ הַגּוּף."],[49,"","רַבִּי אַבָּהוּ פָּתַח בַּפָּסוּק הַזֶּה, (שיר ד) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי מִלְּבָנוֹן תָּבֹאִי וְגוֹ'. אָמַר רַבִּי אַבָּהוּ, כֵּיוָן שֶׁהַגּוּף נִבְנֶה עַל קִיּוּמוֹ וּמְבִיאִין אוֹתוֹ לְקַבֵּל נִשְׁמָתוֹ לְאֶרֶץ יִשְׂרָאֵל, הַנְּשָׁמָה מַמְתֶּנֶת אֵלָיו וְיוֹצֵאת לִקְרָאתוֹ, כְּמוֹ שֶׁנֶּאֱמַר וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה. זֶהוּ שֶׁכָּתוּב אִתִּי מִלְּבָנוֹן כַּלָּה, זוֹ הִיא הַנְּשָׁמָה. תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה, הַיְנוּ שֶׁכָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא."],[50,"","אָמַר רַבִּי יְהוּדָה, אִם הַנְּשָׁמָה הִיא, יָפֶה אַבְרָהָם כְּפִי שֶׁאָמַרְנוּ. אֲבָל מַה זֶּה יִצְחָק? אָמַר רַבִּי אַבָּהוּ, הִנֵּה הַחֲבֵרִים אָמְרוּ שֶׁעַכְשָׁו נִקְרָא יִצְחָק עַל שֵׁם הַשִּׂמְחָה הָרַבָּה שֶׁבָּעוֹלָם."],[51,"","אָמַר רַבִּי אַבָּהוּ, בַּתְּחִלָּה נִקְרֵאת הַנְּשָׁמָה אַבְרָהָם וְהַגּוּף שָׂרָה. עַכְשָׁו נִקְרֵאת הַנְּשָׁמָה יִצְחָק וְהַגּוּף רִבְקָה. שָׁנִינוּ בַּמִּשְׁנָה, אָמַר רַבִּי שִׁמְעוֹן, אַרְבָּעִים יוֹם קֹדֶם קִיּוּם הַגּוּף מַמְתֶּנֶת הַנְּשָׁמָה לַגּוּף בְּאֶרֶץ יִשְׂרָאֵל. בְּאֵיזֶה מָקוֹם? בִּמְקוֹם הַמִּקְדָּשׁ."],[52,"","אָמַר רַבִּי אַבָּהוּ, בּא רְאֵה, וַיִּקַּח אֶת רִבְקָה וַתְּהִי לוֹ לְאִשָּׁה וַיֶּאֱהָבֶהָ וַיִּנָּחֵם יִצְחָק אַחֲרֵי אִמּוֹ. אוֹהֵב אֶת אוֹתוֹ הַגּוּף וּמִתְנַחֵם עִמּוֹ, וְהוּא עֵת לִשְׂחֹק וְהַחֶדְוָה בָּעוֹלָם."],[53,"","אָמַר רַבִּי יְהוּדָה, הֲרֵי כָּל הַפָּרָשָׁה הַזּוֹ הִתְבָּרְרָה לָנוּ, אֲבָל לֹא יָכֹלְנוּ לָדַעַת מַהוּ. וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. וּלְשִׁקּוּל הַדַּעַת כָּל הַפָּרָשָׁה הַזּוֹ לִסְתֹּר."],[54,"","כְּשֶׁבָּא רַב דִּימִי, אָמַר, הַפָּרָשָׁה הַזּוֹ שָׁמַעְתִּי וְלֹא נִזְכַּרְתִּי. אָמְרוּ שֶׁעֶלְיוֹנִים תַּקִּיפִים לֹא זִמְּנוּהָ לְגַלּוֹת, וְאָנוּ מַה נֹּאמַר? קָם רַבִּי יְהוּדָה וְאָמַר, מִישִׁיבַת חֲבֵרֵינוּ בַּעֲלֵי הַמִּשְׁנָה גְּלוּיָה."],[55,"","קָמוּ וְהָלְכוּ הוּא וְרַבִּי יֵיסָא וְרַבִּי חִיָּיא. מָצְאוּ אֶת רַבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן, וְהָיָה מְגַלֶּה אֶת סוֹדוֹת הַתְּפִלִּין. נִכְנְסוּ לְפָנָיו וְאָמְרוּ, בַּמֶּה מִתְעַסֵּק מַר? אָמַר לָהֶם, אֶת טַעַם הַתְּפִלִּין אָמַרְתִּי, שֶׁהֲרֵי אַשְׁרֵי הָאִישׁ שֶׁמֵּנִיחַ תְּפִלִּין וְיוֹדֵעַ אֶת הַטַּעַם שֶׁלָּהֶן."],[56,"","אָמְרוּ, אִם נוֹחַ לִפְנֵי מַר, יֹאמַר לָנוּ הַדָּבָר. אָמְרוּ, שָׁמַעְנוּ מֵאָבִיךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַהֲבָה רַבָּה שֶׁהָיְתָה לוֹ עִם יִשְׂרָאֵל אָמַר לָהֶם לַעֲשׂוֹת לוֹ בֵּית מִשְׁכָּן כְּמוֹ הַמֶּרְכָּבָה הָעֶלְיוֹנָה שֶׁלְּמַעְלָה, וְיָבִיא אֶת דִּיּוּרוֹ עִמָּהֶם. זֶהוּ שֶׁכָּתוּב (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְשָׁמַעְנוּ מֵאָבִיךְ, שֶׁכָּאן סָתוּם הַטַּעַם שֶׁל הַתְּפִלִּין בַּפָּסוּק הַזֶּה."],[57,"","אָמַר לוֹ, בּא רְאֵה, כְּמוֹ הָעֶלְיוֹן נַעֲשָׂה הַמִּקְדָּשׁ בְּמַרְכְּבוֹתָיו הַקְּדוֹשׁוֹת, וְאַחַר כָּךְ הִשְׁרָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת דִּיּוּרוֹ עִמָּהֶם כָּעִנְיָן הַזֶּה. וּכְמוֹ כֵן הִתְעוֹרְרוּ הַחֲבֵרִים בַּעֲלֵי הַמִּשְׁנָה בְּטַעַם הַתְּפִלִּין, שֶׁיִּהְיֶה אוֹתוֹ הָאִישׁ דֻּגְמָא שֶׁל הַמֶּרְכָּבוֹת הָעֶלְיוֹנוֹת, מֶרְכָּבָה תַחְתּוֹנָה מֶרְכָּבָה עֶלְיוֹנָה, לְהָבִיא אֶת מַלְכוּתוֹ וְיַשְׁרֶה דִיּוּרוֹ עָלָיו."],[58,"","וְשָׁנִינוּ, יֵשׁ בּוֹ סוֹדוֹת עֶלְיוֹנִים וְדֻגְמָתָם, וְיֵשׁ בּוֹ שָׁלֹשׁ מֶרְכָּבוֹת, דֻּגְמַת הָעֶלְיוֹנִים הַקְּדוֹשִׁים סוֹדוֹת שֶׁל שָׁלֹשׁ אוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים, שְׁלֹשָׁה עוֹלָמוֹת, מֶרְכָּבוֹת שָׁלֹשׁ אוֹתִיּוֹת, אַרְבַּע פָּרָשִׁיּוֹת שׁוֹלֵט עַל אַרְבַּע. וְעַל כֵּן סוֹד הַשִּׁי\"ן שֶׁל שְׁלֹשָׁה כְתָרִים, וְשִׁי\"ן שֶׁל אַרְבָּעָה כְתָרִים, שְׁלֹשָׁה מְלָכִים שׁוֹלְטִים בַּגּוּף, תְּפִלִּין עָלָיו, הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה. אֵלּוּ תְּפִלִּין שֶׁל רֹאשׁ. הַתְּפִלִּין שֶׁל זְרוֹעַ אַרְבַּע פָּרָשִׁיּוֹת."],[59,"","הַלֵּב רוֹכֵב, דֻּגְמָא שֶׁל הַמֶּרְכָּבָה הַתַּחְתּוֹנָה, וְהַתַּחְתּוֹן רוֹכֵב. עוֹד שָׁנִינוּ, זֶה הָרֶכֶב שֶׁל הַזְּרוֹעַ לְמַטָּה. וְהַלֵּב רוֹכֵב, דֻּגְמָא שֶׁהוּא לְמַטָּה, וְנִמְסְרוּ בְיָדוֹ לְהַכְנִיס אוֹתָם כָּל חֵילוֹת הַשָּׁמַיִם. כָּךְ הַלֵּב רוֹכֵב לְמַטָּה, וְנִמְסְרוּ בְיָדוֹ כָּל אֵיבְרֵי הַגּוּף."],[60,"","וּמֵעָלָיו אַרְבַּע פָּרָשִׁיּוֹת עַל הַמֹּחַ, שֶׁהוּא הָרֹאשׁ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא שַׁלִּיט עֶלְיוֹן, הַמֶּלֶךְ מֵהַכֹּל. (ורוח) וְסוֹד הַחָכְמָה הַזּוֹ הוּא כְּמוֹ שֶׁהַמִּקְדָּשׁ, שֶׁכָּתוּב וַעֲשֵׂה כְּרוּב אֶחָד מִקָּצָה מִזֶּה וּכְרוּב אֶחָד מִקָּצָה. וַעֲלֵיהֶם דִּיּוּר הַמֶּלֶךְ בְּאַרְבַּע אוֹתִיּוֹת שְׁתֵּי מֶרְכָּבוֹת."],[61,"","וּכְמוֹ זֶה הַלֵּב וְהַמֹּחַ, הַלֵּב מִכָּאן וְהַמֹּחַ מִכָּאן, וַעֲלֵיהֶם מְדוֹרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַרְבַּע (ארבע) פָּרָשִׁיּוֹת. אָמַר רַבִּי אֶלְעָזָר, מִכָּאן וָהָלְאָה סוֹדוֹת הַכְּתָרִים, הָאוֹתִיּוֹת וְהַפָּרָשִׁיּוֹת בְּגוּפָם וּבִרְצוּעוֹתֵיהֶם. הֲלָכָה לְמֹשֶׁה מִסִּינַי וְהָרֶמֶז שֶׁלָּהֶם הִתְגַּלָּה, וְהַטַּעַם שֶׁל הַכֹּל בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת (הרחמים)."],[62,"","אָמַר רַבִּי יְהוּדָה, אִלְמָלֵא לֹא בָאתִי אֶלָּא עֲבוּר הַסּוֹד הַזֶּה - דַּי לִי. אָמְרוּ לוֹ, אַשְׁרֵי חֶלְקְךְ בָּעוֹלָם הַבָּא, שֶׁכָּל רָז אֵינוֹ אָנוּס לְךְ. אָמְרוּ לוֹ, בָּאנוּ לִפְנֵי מַר לָדַעַת אֶת סוֹד הַפָּסוּק הַזֶּה, וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה."],[63,"","אָמַר, פֵּרוּשׁ שֶׁל הַפָּסוּק הַזֶּה כְּמוֹ שֶׁגִּלּוּ חֲבֵרֵינוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁכַּאֲשֶׁר הַנְּשָׁמָה תָּבוֹא בְּאוֹתוֹ הַגּוּף הַקָּדוֹשׁ שֶׁלָּהּ, הִנֵּה הַדְּבָרִים הָיוּ עַל הָרְשָׁעִים שֶׁיָּקוּמוּ וְיַכְשִׁירוּ אֶת מַעֲשֵׂיהֶם, וְיִתֵּן לָהֶם מִזִּיו כְּבוֹדוֹ שֶׁיֵּדְעוּ וְיָשׁוּבוּ וְיִזְכּוּ זְכוּת שְׁלֵמָה."],[64,"","וּכְשֶׁרָאָה אֶת זֶה שְׁלֹמֹה, הָיָה (תמה הרבה) הַרְבֵּה וְאָמַר, (קהלת ח) וּבְכֵן רָאִיתִי רְשָׁעִים קְבֻרִים וָבָאוּ וּמִמְּקוֹם קָדוֹשׁ יְהַלֵּכוּ, שֶׁיָּבֹאוּ וְיִחְיוּ מִמְּקוֹם קָדוֹשׁ. וְשָׁנִינוּ, אָמַר רַבִּי אַבָּא אָמַר רַבִּי יוֹחָנָן, כָּתוּב (ירמיה ג) הֲיַהֲפֹךְ כּוּשִׁי עוֹרוֹ וְנָמֵר חֲבַרְבֻּרֹתָיו. כָּךְ הָרְשָׁעִים שֶׁלֹּא זָכוּ לָשׁוּב בָּעוֹלָם הַזֶּה וּלְהַקְטִיר מַעֲשִׂים טוֹבִים, לְעוֹלָם לֹא יַקְטִירוּ בָּעוֹלָם הַבָּא. רְאֵה מַה כָּתוּב, וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה, וְשֶׁרוֹצֶה לַעֲשׂוֹת לָהֶם נְשָׁמָה לְגוּפָם וּלְקָרְבָם בִּתְשׁוּבָה, כְּמוֹ שֶׁנֶּאֱמַר וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן."],[65,"","אָמַר רַבִּי אֶלְעָזָר, בּא רְאֵה מַה כָּתוּב, וַתֵּלֶד לוֹ אֶת זִמְרָן וְאֶת יָקְשָׁן. הַרְבֵּה מַעֲשִׂים רָעִים עַד שֶׁנִּגְרָשִׁים מִן הָעוֹלָם, שֶׁכָּתוּב וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ. וַעֲלֵיהֶם נֶאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹ'. וְעַל הָאֲחֵרִים נֶאֱמַר וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ וְגוֹ'."],[66,"","אָמַר רַבִּי יְהוּדָה, זֶה מַשְׁמָע עַל הַפָּרָשָׁה, וּמַשְׁמָע שֶׁאוֹתוֹ זְמַן (נקרא) (אבד) שֵׁם (הנשמה) אַבְרָהָם, וּבִמְקוֹמוֹ נִקְרֵאת יִצְחָק, כְּפִי שֶׁאָמַרְנוּ. זֶהוּ שֶׁכָּתוּב וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי. עִם יְדִיעַת הַחַי שֶׁהוּא חַי הָעוֹלָמִים, לָדַעַת וּלְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיג בָּעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה'. (עד כאן מדרש הנעלם)"],[67,"","רַבִּי יִצְחָק פָּתַח וְאָמַר, (קהלת יב) וְיָשֹׁב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, נָטַל עֲפָרוֹ מִמְּקוֹם הַמִּקְדָּשׁ, וּבָנָה אֶת גּוּפוֹ מֵאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם, שֶׁכֻּלָּם נָתְנוּ לוֹ כֹּחַ. אַחַר כָּךְ הֵרִיק עָלָיו רוּחַ חַיִּים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וְגוֹ'. אַחַר כָּךְ קָם וְיָדַע שֶׁהוּא מִמַּעְלָה וּמַטָּה, וְאָז נִדְבַּק וְיָדַע אֶת הַחָכְמָה הָעֶלְיוֹנָה."],[68,"","כְּמוֹ זֶה כָּל אָדָם שֶׁבָּעוֹלָם הוּא כָּלוּל מִמַּעְלָה וּמַטָּה, וְכָל אוֹתָם שֶׁיּוֹדְעִים לְהִתְקַדֵּשׁ בָּעוֹלָם הַזֶּה כָּרָאוּי, כְּשֶׁמּוֹלִידִים בֵּן, מוֹשְׁכִים עָלָיו רוּחַ קְדֻשָּׁה מֵהַמָּקוֹם שֶׁכָּל הַקְּדוֹשִׁים יוֹצְאִים מִמֶּנּוּ, וְאֵלּוּ נִקְרָאִים בָּנִים לַקָּבָּ\"ה. מִשּׁוּם שֶׁהַגּוּף נַעֲשָׂה בִּקְדֻשָּׁה כָּרָאוּי, כָּךְ גַּם נוֹתְנִים לוֹ רוּחַ מִמָּקוֹם עֶלְיוֹן קָדוֹשׁ כָּרָאוּי, וַהֲרֵי זֶה נִתְבָּאֵר."],[69,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁעָתִיד אָדָם לָתֵת חֶשְׁבּוֹן מַעֲשָׂיו טֶרֶם יָצָא מִן הָעוֹלָם, אוֹתוֹ הַיּוֹם הוּא יוֹם הַחֶשְׁבּוֹן שֶׁגּוּף וּנְשָׁמָה נוֹתְנִים חֶשְׁבּוֹן. אַחַר כָּךְ הַנְּשָׁמָה נִפְרֶדֶת מִמֶּנּוּ, וְהַגּוּף שָׁב לָאָרֶץ, וְהַכֹּל שָׁב לִמְקוֹמוֹ שֶׁנִּלְקַח מִשָּׁם, וַהֲרֵי פֵּרְשׁוּהָ. עַד הַזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת מֵתִים, הַכֹּל גָּנוּז לְפָנָיו."],[70,"","וְאוֹתוֹ גוּף מַמָּשׁ וְאוֹתָהּ נְשָׁמָה מַמָּשׁ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב לָעוֹלָם כְּמוֹ מִקֹּדֶם וּלְחַדֵּשׁ אֶת פְּנֵי הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כו) יִחְיוּ מֵתֶיךְ נְבֵלָתִי יְקוּמוּן. וְאוֹתָהּ הַנְּשָׁמָה מַמָּשׁ גְּנוּזָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁבָה לִמְקוֹמָהּ כְּפִי דַרְכָּהּ, כְּמוֹ שֶׁנֶּאֱמַר וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. וּבִזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת מֵתִים, עָתִיד הוּא לְהָרִיק טַל מֵרֹאשׁוֹ עֲלֵיהֶם, וּבְאוֹתוֹ הַטַּל כֻּלָּם יָקוּמוּ מֵהֶעָפָר."],[71,"","זְהִוּ שֶׁכָּתוּב (שם) כִּי טַל אוֹרוֹת טַלֶּךְ. מַה זֶּה טַל אוֹרוֹת? אוֹרוֹת מַמָּשׁ מֵאוֹתָם הָאוֹרוֹת שֶׁל מַעְלָה שֶׁבָּהֶם עָתִיד לְהָרִיק חַיִּים לָעוֹלָם, מִשּׁוּם שֶׁעֵץ הַחַיִּים יָרִיק חַיִּים שֶׁלֹּא פוֹסְקִים לְעוֹלָמִים. שֶׁהֲרֵי עַכְשָׁו פּוֹסְקִים מִשּׁוּם שֶׁהַנָּחָשׁ הָרָע הַזֶּה שׁוֹלֵט וְהַלְּבָנָה מִתְכַּסָּה. וּמִשּׁוּם כָּךְ כִּבְיָכוֹל פּוֹסְקִים מֵימָיו, וְהַחַיִּים לֹא שׁוֹלְטִים בָּעוֹלָם כָּרָאוּי."]]],[["וּבְהַהוּא זִמְנָא הַהוּא יֵצֶר הָרָע דְּאִיהוּ חִוְיָא בִישָׁא יִסְתַּלַּק מֵעַלְמָא וְיַעֲבַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְאִתְּמָר (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וּלְבָתַר דְּאִיהוּ יִתְעֲבַר מֵעַלְמָא, סִיהֲרָא לָא אִתְכַּסְיָא, וְנַהֲרָא דְּנָגִיד וְנָפִיק לָא יִפָּסְקוּן מַבּוּעוֹי, וּכְדֵין כְּתִיב, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים וְגו'.","אָמַר רַבִּי חִזְקִיָּה אִי תֵימָא דְּכָל גּוּפִין דְּעַלְמָא יְקוּמוּן וְיִתְעָרוּן מֵעַפְרָא, אִינוּן גּוּפֵי דְּאִתְנְטִיעוּ בְּנִשְׁמָתָא חָדָא מַה תְּהֵא מִנַּיְיהוּ. אָמַר רַבִּי יוֹסֵי אִינוּן גּוּפִין דְּלָא זָכוּ וְלָא אַצְלָחוּ הֲרֵי אִינוּן כְּלָא הֲווּ, כְּמָה דְּהֲווּ עֵץ יָבֵשׁ בְּהַהִיא עַלְמָא הָכִי נָמֵי בְּהַהוּא זִמְנָא, וְגוּפָא בַּתְרָאָה דְּאִתְנְטַע וְאַצְלַח וְנָטַל שָׁרָשׁוֹי כְּדְקָא יְאוּת יָקוּם.","וְעֲלֵיהּ כְּתִיב, (ירמיהו י״ז:ח׳) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְגו' וְהָיָה עָלֵהוּ רַעֲנָן וְגו'. דְּעֲבַד אִיבִּין וְנָטַע שָׁרָשִׁין וְאַצְלַח כְּדְקָא יְאוּת. וְעַל הַהוּא גּוּפָא קַדְמָאָה דְּלָא עֲבַד אִיבִּין וְלָא נָטַע שָׁרָשִׁין (ולא זכה ולא אצלח) כְּתִיב, (ירמיהו י״ז:ו׳) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלא יִרְאֶה כִּי יָבֹא טוֹב וְגו'. כִּי יָבֹא טוֹב דָּא תְּחִיַּית הַמֵּתִים.","וְיִתְנְהִיר הַהוּא נְהוֹרָא דְּזַמִּין לְאַנְהָרָא לְהוּ לְצַדִּיקַיָּא דְּהֲוָה גָנִיז קַמֵּיהּ מִיּוֹמָא דְּאִתְבְּרֵי עַלְמָא דִּכְתִיב, (בראשית א׳:ד׳) וַיַּרְא אֱלהִים אֶת הָאוֹר כִּי טוֹב. וּכְדֵין זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָיא, וּכְתִיב, (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וְגו', וּכְדֵין יִתְגַּבַּר טוֹב בְּעַלְמָא, וְהַהוּא דְּאִתְקְרֵי רַע יִתְעֲבַר מֵעַלְמָא כִּדְאֲמָרָן. וּכְדֵין אִינוּן גּוּפִין קַדְמָאֵי לֶהֱווֹ כְּלָּא הֲווּ.","אָמַר רִבִּי יִצְחָק זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲרָקָא עֲלַיְיהוּ עַל אִינוּן גּוּפִין רוּחִין אָחֳרָנִין, וְאִי זָכָאן בְּהוֹן יְקוּמוּן בְּעַלְמָא כְּדְקָא יְאוּת, וְאִי לָאו יְהוֹן קִטְמָא תְּחוֹת רַגְלֵיהוֹן דְּצַדִּיקַיָא דִּכְתִיב (מלאכי ג), וּכְתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגו'. וְכֹלָּא אִתָּקַם וְאִתְעַתַּד קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ בְּמִנְיָינָא הֲווּ כְּמָא דְאַתְּ אָמֵר (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפַּר צְבָאָם וְגו'.","תָּא חֲזֵי, הָא אִתְּמָר כָּל אִינוּן מֵתִין דִּבְאַרְעָא דְיִשְׂרָאֵל יְקוּמוּן בְּקַדְמִיתָא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יִתְעַר עֲלַיְיהוּ וְיוֹקִים לוֹן, עֲלַיְיהוּ כְּתִיב יִחְיוּ מֵתֶיךָ, אִלֵּין אִינוּן דִּי בְאַרְעָא דְיִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן, אִלֵּין אִינוּן דִּבְגוֹ אַרְעָאן אָחֳרָנִין, דְּלָא כְּתִיב בְּהוּ תְּחִיָּיה אֶלָּא קִימָה. דְּהָא רוּחָא דְחַיֵּי לָא תִשְׁרֵי אֶלָּא בְּאַרְעָא קַדִּישָׁא דְיִשְׂרָאֵל, וּבְגִין כָּךְ כְּתִיב בְּהוּ יִחְיוּ מֵתֶיךָ, וְאִינוּן דִּלְבַר, יִתְבְּרֵי גוּפָא דִלְהוֹן וִיקוּמוּן גּוּפָא בְּלָא רוּחָא. וּלְבָתַר יִתְגַּלְגְּלוּן תְּחוֹת עַפְרָא עַד דְּיִמְטוּן לְאֶרֶץ יִּשְׂרָאֵל, וְתַמָּן יְקַבְּלוּן נִשְׁמָתָא, וְלָא בִּרְשׁוּ אָחֳרָא, בְּגִין דְּיִתְקַיְּימוּן בְּעַלְמָא כְּדְקָא חָזֵי.","רִבִּי אֶלְעָזָר וְרִבִּי יֵיסָא הֲווּ יַתְבֵי לֵילְיָא חַד וְעָסְקֵי בְּאוֹרַיְיתָא. אָמַר רִבִּי אֶלְעָזָר תָּא חֲזֵי, בְּשַׁעְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לַאֲחָיָיא מֵתַיָיא, כָּל אִינוּן נִשְׁמָתִין דְּיִתְעָרוּן קַמֵּיהּ כֻּלְּהוּ קָיְימִין דִּיוּקְנִין דִּיוּקְנִין קַמֵּיהּ בְּהַהוּא דִּיוּקְנָא מַמָּשׁ דְּהֲווּ בְּהַאי עַלְמָא, וְנָחִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְיִקְרֵי לוֹן בִּשְׁמָהָן כְּמָה דְאַתְּ אָמֵר, (ישעיה נח) לְכֻלָּם בְּשֵׁם יִקְרָא. וְכָל נִשְׁמָתָא תֵּיעוֹל לְדוּכְתָּהָּ, וִיקוּמוּן בְּקִיּוּמָא בְּעַלְמָא כְּדְקָא חָזֵי, וּכְדֵין יְהֵא עַלְמָא שְׁלִים, וְעַל הַהוּא זִמְנָא כְּתִיב, (ישעיהו כ״ה:ח׳) וְחֶרְפַת עַמּוֹ יָסִיר וְגו', מַאי וְחֶרְפַּת עַמּוֹ יָסִיר. דָּא יֵצֶר הָרָע דְּאַחְשִׁיךְ אַנְפֵּי בִּרְיָין וְשַׁלִּיט בְּהוּ.","אָמַר רִבִּי יוֹסֵי הָא חָמִינָן כָּל זִמְנָא דְּבַר נָשׁ קָאִים בְּרוּחָא דָא. לָאו אִיהוּ מְסָאָב, נָפְקָא נִשְׁמָתֵיהּ מִנֵּיהּ אִיהוּ מְסָאָב. אָמַר לֵיהּ וַדַּאי הָכִי הוּא, וְהָכִי אִתְּמָר דְּהָא הַהוּא יֵצֶר הָרָע כַּד נָטִיל רוּחָא דְּבַר נָשׁ סָאִיב לֵיהּ וְאִשְׁתָּאַר גּוּפָא מְסָאָב, וּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת כַּד אִינוּן בְּחַיֵּיהוֹן אִינוּן מְסָאֲבִין דְּהָא מִסִּטְרָא מִסָּאֲבָא אִית לוֹן נִשְׁמָתִין, וְכַד אִתְרִיק מִנֵּיהּ הַהוּא מְסָאֲבוּ אִשְׁתָּאַר גּוּפָא בְּלָא מְסָאֲבוּ כְּלָל."],[[0,"ובההוא זמנא וכו':","ובעת ההוא, אותו יצר הרע, שהוא נחש הרע, יסתלק מן העולם, ויעביר אותו הקב\"ה. כמו שנאמר, ואת רוח הטומאה אעביר מן הארץ. ואחר שהוא יעבר מן העולם, הלבנה אינה מתכסה עוד, והנהר הנמשך ויוצא מן העדן, שהוא ז\"א, לא יפסקו מבועיו, ואז כתוב, והיה אור הלבנה כאור החמה ואור החמה וגו'."],[1,"אמר ר' חזקיה וכו':","אר\"ח, אם תאמר, שכל הגופים שבעולם יקומו לתחיה ויתעוררו מעפר, יש לשאול, אלו הגופים שנוטעו בנשמה אחת דהיינו שנשמה אחת נתגלגלה בכמה גופים, בזה אחר זה, כנודע, מה יהיה מהם, אם יקומו כולם לתחיית המתים או האחרון בלבד. אמר ר' יוסי, אלו הגופים שלא זכו במעשים טובים, ולא הצליחו להשלים הנשמה, הרי הם כמו שלא היו, כמו שהם עץ יבש בעולם ההוא, כן הם יהיו לעת תחית המתים, ורק גוף אחרון, שנוטע והצליח וקבל שרשיו הרוחנים כראוי, הוא יקום לתחית המתים."],[2,"ועליה כתיב וכו':","ועליו כתוב, והיה כעץ שתול על מים וגו', והיה עלהו רענן וגו'. כי עשה פירות דהיינו מעשים טובים, ונטע שרשים כראוי, למעלה בעולם העליון, שמכל מצוה מתגלה כנגדה שורש רוחני למעלה, כנודע. וגוף הקודם שלא עשה פירות ולא נטע שרשים, עליו כתוב, והיה כערער בערבה ולא יראה כי יבא טוב וגו', כי יבא טוב, זהו תחיית המתים."],[3,"ויתנהיר ההוא וכו':","ויאיר, אותו האור העתיד להאיר לצדיקים, שהיה גנוז לפניו מיום שנברא העולם, שכתוב, וירא אלקים את האור כי טוב. ואז עתיד הקב\"ה להחיות המתים. וכתוב, וזרחה לכם יראי שמי שמש צדקה וגו', כי אז יתגבר הטוב בעולם, ואותו שנקרא רע יהיה נעבר מן העולם. כמו שאמרנו. ואז אלו גופים הקודמים להאחרון, יהיו כמו שלא היו, כנ\"ל."],[4,"אמר ר' יצחק וכו':","אר\"י, עתיד הקב\"ה להריק עליהם, על אלו גופים הקודמים לאחרון, רוחות אחרים, ואם הם זוכים בהם, שיוכלו ללכת בדרך הישר, יקומו בעולם כראוי, ואם לא, יהיו אפר תחת רגלי הצדיקים, שכתוב ורבים מישני אדמת עפר יקיצו וגו'. והכל הוקם ונועד לפני הקב\"ה. וכולם הם במנין לעת התחיה, כמש\"א, המוציא במספר צבאם וגו'."],[5,"תא חזי הא אתמר וכו':","בוא וראה, הרי למדנו, שכל המתים שבארץ ישראל יקומו לתחיה בתחלה. כי הקב\"ה יעיר עליהם רוח, ויקום אותם. עליהם כתוב, \u0003יחיו מתיך\u0004 אלו הם, שבארץ ישראל. \u0003נבלתי יקומון,\u0004 אלו הם שבארצות אחרות, שלא כתוב בהם תחיה אלא קימה, כי רוח החיים אינו שורה, אלא בארץ הקודש של ישראל, ומשום זה כתוב רק בהם יחיו מתיך. ואלו שמחוץ לארץ יהיה נברא הגוף שלהם, ויקומו לתחיה גוף בלא רוח, ואחר כך יתגלגלו תחת עפר הארץ, עד שיגיעו לארץ ישראל, ושם יקבלו הנשמה, ולא ברשות אחר, בשביל שיתקיימו בעולם כראוי."],[6,"ר' אלעזר ור' ייסא וכו':","ר\"א ור\"י, היו יושבים לילה אחד ועוסקים בתורה. אמר ר' אלעזר, בוא וראה, בשעה שעתיד הקב\"ה להחיות המתים, כל אלו הנשמות שיתעוררו לפניו, תהיינה עומדות כולן לפניו צורות צורות, באותה הצורה ממש שהיו בעולם הזה ויוריד אותן הקב\"ה אל הגופים שלהם, ויקרא אותן בשמות, כמו שאתה אומר, לכלם בשם יקרא. וכל נשמה תכנס למקומה בגוף, ויקומו לתחיה בעולם כראוי, ואז יהיה העולם שלם. ועל אותו זמן כתוב. וחרפת עמו יסיר וגו', מהו וחרפת עמו יסיר, זהו יצר הרע, שיסיר מן העולם, המחשיך פניהם של הבריות ושולט בהם."],[7,"אמר ר' יוסי וכו':","אר\"י, הרי אנו רואים, כל זמן שהאדם נמצא ברוח זה, אינו טמא, יצא נשמתו ממנו, הוא טמא. ובקש לידע הטעם. אמר לו ודאי כן הוא, וכן למדנו, כי יצר הרע ההוא, כשנוטל רוחו של אדם, כי הוא יצה\"ר והוא מלאך המות, מטמא אותו, ונשאר אחריו הגוף טמא. כי עם כח הזוהמא של עצה\"ד נוטל נשמתו של אדם, וזוהמא הזו, הוא שורש כל הטומאה. ועמים האחרים עובדי עבודת כו\"מ, הוא להיפך, כשהם בחיים הם טמאים, כי מצד הטומאה נמשכות להם נשמותיהם, וכשגופם נתרוקן מן טומאה ההוא, דהיינו שמתים והנשמה יוצאת מהם, נשאר הגוף בלי שום טומאה, וע\"כ אינם מטמאים, והיינו כמ\"ש ר\"ש, קברי עכו\"ם אינם מטמאים באהל."]],[[0,"","וּבְאוֹתוֹ זְמַן אוֹתוֹ יֵצֶר הָרָע, שֶׁהוּא הַנָּחָשׁ הָרָע, יִסְתַּלֵּק מִן הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲבִיר אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְאַחַר שֶׁהוּא יָעֳבַר מִן הָעוֹלָם, הַלְּבָנָה לֹא תִתְכַּסֶּה. וְהַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, לֹא יִפָּסְקוּ מַעְיָנָיו. וְאָז כָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים וְגוֹ'."],[1,"","אָמַר רַבִּי חִזְקִיָּה, אִם תֹּאמַר שֶׁכָּל הַגּוּפוֹת שֶׁל הָעוֹלָם יָקוּמוּ וְיִתְעוֹרְרוּ מִן הֶעָפָר - אוֹתָם הַגּוּפוֹת שֶׁנִּטְּעוּ בִּנְשָׁמָה אַחַת מַה יִּהְיֶה מֵהֶם? אָמַר רַבִּי יוֹסֵי, אוֹתָם הַגּוּפוֹת שֶׁלֹּא זָכוּ וְלֹא הִצְלִיחוּ, הֲרֵי הֵם כְּלֹא הָיוּ. כְּמוֹ שֶׁהָיוּ עֵץ יָבֵשׁ בָּעוֹלָם הַהוּא, כָּךְ גַּם בְּאוֹתוֹ הַזְּמַן. וְהַגּוּף הָאַחֲרוֹן שֶׁנִּנְטַע וְהִצְלִיחַ וְנָטַל שָׁרָשָׁיו כָּרָאוּי יָקוּם."],[2,"","וְעָלָיו כָּתוּב (ירמיה יז) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְגוֹ' וְהָיָה עָלֵהוּ רַעֲנָן וְגוֹ'. שֶׁעָשָׂה פֵּרוֹת וְנָטַע שָׁרָשִׁים וְהִצְלִיחַ כָּרָאוּי. וְעַל אוֹתוֹ גוּף רִאשׁוֹן שֶׁלֹּא עָשָׂה פֵּרוֹת וְלֹא נָטַע שָׁרָשִׁים (ולא זכה ולא הצליח), כָּתוּב (שם) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבוֹא טוֹב וְגוֹ'. כִּי יָבוֹא טוֹב - זוֹ תְּחִיַּת הַמֵּתִים."],[3,"","וְיָאִיר אוֹתוֹ הָאוֹר שֶׁעָתִיד לְהָאִיר לַצַּדִּיקִים שֶׁהָיָה גָנוּז לְפָנָיו מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְאָז עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, וְכָתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וְגוֹ'. וְאָז יִתְגַּבֵּר הַטּוֹב בָּעוֹלָם, וְאוֹתוֹ שֶׁנִּקְרָא רַע יַעֲבֹר מִן הָעוֹלָם, כְּמוֹ שֶׁאָמַרְנוּ, וְאָז אוֹתָם הַגּוּפִים הָרִאשׁוֹנִים יִהְיוּ כְּלֹא הָיוּ."],[4,"","אָמַר רַבִּי יִצְחָק, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָרִיק עַל אוֹתָם הַגּוּפִים רוּחוֹת אֲחֵרוֹת, וְאִם זוֹכִים בָּהֶם - יָקוּמוּ בָּעוֹלָם כָּרָאוּי, וְאִם לֹא - יִהְיוּ אֵפֶר תַּחַת רַגְלֵי הַצַּדִּיקִים, שֶׁכָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹ', וְהַכֹּל יוּקַם וְיִוָּעֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם כֻּלָּם בְּמִנְיָן, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ'."],[5,"","בֹּא רְאֵה, הֲרֵי נֶאֱמַר, כָּל אוֹתָם הַמֵּתִים שֶׁבְּאֶרֶץ יִשְׂרָאֵל יָקוּמוּ בָּרִאשׁוֹנָה, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר עֲלֵיהֶם וְיָקִים אוֹתָם. עֲלֵיהֶם כָּתוּב יִחְיוּ מֵתֶיךְ. אֵלּוּ הֵם שֶׁבְּאֶרֶץ יִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן - אֵלּוּ הֵם שֶׁבְּתוֹךְ אֲרָצוֹת אֲחֵרוֹת, שֶׁלֹּא כְתוּבָה בָהֶם תְּחִיָּה, אֶלָּא קִימָה. שֶׁהֲרֵי רוּחַ הַחַיִּים לֹא תִשְׁרֶה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל הַקְּדוֹשָׁה, וּמִשּׁוּם כָּךְ כָּתוּב בָּהֶם יִחְיוּ מֵתֶיךְ, וְאוֹתָם שֶׁבַּחוּץ יִבְרָא הַגּוּף שֶׁלָּהֶם, וְיָקוּמוּ גוּף בְּלִי רוּחַ. אַחַר כָּךְ יִתְגַּלְגְּלוּ תַּחַת הֶעָפָר עַד שֶׁיַּגִּיעוּ לְאֶרֶץ יִשְׂרָאֵל, וְשָׁם יְקַבְּלוּ נְשָׁמָה, וְלֹא בִּרְשׁוּת אַחֶרֶת, כְּדֵי שֶׁיִּתְקַיְּמוּ בָּעוֹלָם כָּרָאוּי."],[6,"","רַבִּי אֶלְעָזָר וְרַבִּי יֵיסָא הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת אֶת הַמֵּתִים, כָּל אוֹתָם הַנְּשָׁמוֹת שֶׁיִּתְעוֹרְרוּ לְפָנָיו, כֻּלָּם עוֹמְדוֹת דְּמֻיּוֹת דְּמֻיּוֹת לְפָנָיו, בְּאוֹתָהּ דְּמוּת מַמָּשׁ שֶׁהָיוּ בָּעוֹלָם הַזֶּה, וְיוֹרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְיִקְרָא לָהֶם בְּשֵׁמוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם) לְכֻלָּם בְּשֵׁם יִקְרָא. וְכָל נְשָׁמָה תִּכָּנֵס לִמְקוֹמָהּ, וְיָקוּמוּ בְּקִיּוּם בָּעוֹלָם כָּרָאוּי, וְאָז יִהְיֶה הָעוֹלָם שָׁלֵם. וְעַל אוֹתוֹ הַזְּמַן כָּתוּב (שם כה) וְחֶרְפַּת עַמּוֹ יָסִיר וְגוֹ'. מַה זֶּה וְחֶרְפַּת עַמּוֹ יָסִיר? זֶה יֵצֶר הָרָע שֶׁמַּחְשִׁיךְ אֶת פְּנֵי הַבְּרִיּוֹת וְשׁוֹלֵט בָּהֶם."],[7,"","אָמַר רַבִּי יוסֵי, הֲרֵי רָאִינוּ, כָּל זְמַן שֶׁאָדָם עוֹמֵד בָּרוּחַ הַזּוֹ - אֵינוֹ טָמֵא. יָצְאָה נִשְׁמָתוֹ מִמֶּנּוּ - הוּא טָמֵא. אָמַר לוֹ, וַדַּאי שֶׁזֶּה כָּךְ, וְכָךְ נֶאֱמַר, שֶׁהֲרֵי אוֹתוֹ יֵצֶר הָרָע, כְּשֶׁנּוֹטֵל אֶת הָרוּחַ שֶׁל הָאָדָם, הוּא מְטַמֵּא אוֹתוֹ, וְנִשְׁאָר גּוּף טָמֵא. וּשְׁאָר עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּשֶׁהֵם בְּחַיֵּיהֶם הֵם טְמֵאִים, שֶׁהֲרֵי יֵשׁ לָהֶם נְשָׁמוֹת מִצַּד הַטֻּמְאָה, וּכְשֶׁמִּתְרוֹקֶנֶת מִמֶּנּוּ אוֹתָהּ טֻמְאָה, נִשְׁאָר הַגּוּף בְּלִי טֻמְאָה כְּלָל."]]],[["בְּגִין כָּךְ מַאן דְּאִתְדָּבַּק בְּאִתְּתָא דִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת אִסְתָּאַב אִיהוּ. וְהַהוּא בְּרָא דְּאִתְיְלִיד לֵיהּ יְקַבֵּל עֲלֵיהּ רוּחַ מְסָאֲבָא. וְאִי תֵימָא הָא בְּסִטְרָא דְּאֲבוֹי מִיִּשְׂרָאֵל קָא אַתְיָא, אַמַּאי יְקַבֵּל עֲלֵיהּ רוּחַ מְסָאֳבָא. תָּא חֲזֵי, דְּהָא בְּקַדְמִיתָא אִסְתָּאַב אֲבוֹי בְּשַׁעְתָּא דְּאִתְדָּבַּק בְּהַהִיא אִתְּתָא דְּאִיהִי מְסָאֳבָא, וְכֵיוָן דְּאָב אִיהוּ אִסְתָּאָב בְּהַהִיא אִתְּתָא דְּאִיהִי מְסָאֳבָא, כָּל שֶׁכֵּן דְּאִיהוּ בְּרָא דְּאִתְיְלִיד מִינָּהּ יְקַבֵּל עֲלֵיהּ רוּחַ מְסָאֳבָא. וְלָא עוֹד אֶלָּא דְּעֲבַר עַל אוֹרַיְיתָא דִּכְתִיב, (שמות לה) כִּי לא תִשְׁתַּחֲוֶה לְאֵל אַחֵר, כִּי יְיָ קַנָּא שְׁמוֹ בְּגִין דְּקַנֵּי עַל הַאי בְּרִית קַדִּישָׁא.","אָמַר רִבִּי אֶלְעָזָר תָּא חֲזֵי דְּהָא אִתְּמָר דְּכֵיוָן דְּיָדַע אַבְרָהָם אָבִינוּ חָכְמְתָא בָּעָא לְאִתְפְּרָשָׁא מִכָּל שְׁאָר עַמִּין וְלָא לְאִתְדַּבָּקָא בְּהוּ, וּבְגִין כָּךְ כְּתִיב וְאַשְׁבִּיעֲךָ בַּיְיָ אֱלקֵי הַשָּׁמַיִם וִאלֹקֵי הָאָרֶץ אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי מִבְּנוֹת הַכְּנַעֲנִי וְגו', מִבְּנוֹת הַכְּנַעֲנִי וַדַּאי, (מאי) רָזָא אִיהוּ כְּמָא דְאַתְּ אָמֵר (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נִכָר. אֲשֶׁר אָנֹכִי יוֹשֵׁב בְּקִרְבּוֹ. אָנֹכִי דַיְיקָא כְּתִיב הָכָא אֲשֶׁר אָנֹכִי, וּכְתִיב הָתָם (ישעיה מד אנכי עשיתי ארץ. וכל דא בגין דלא לאסתאבא בהו.)","תָּא חֲזֵי, הַאי מַאן דְּאָעִיל הַאי בְּרִית קַדִּישָׁא בְּהַהִיא אִתְּתָא דִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, גָּרִים לְאִסְתָּאֲבָא אֲתַר אָחֳרָא. וְעַל דָּא כְּתִיב (משלי ל׳:כ״א) תַּחַת שָׁלשׁ רָגְזָה אֶרֶץ וְגו'. וְאַף עַל גַּב דְּאוֹמֵי לֵיהּ בְּהַאי בְּרִית, לָא אַבְטַח בֵּיהּ אַבְרָהָם עַד דְּצַלֵּי צְלוֹתֵיהּ קַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאָמַר יְיָ אֱלֹקֵי הַשָּׁמַיִם וְגו', הוּא יִשְׁלַח מַלְאָכוֹ, וַדַּאי דָא מַלְאַךְ הַבְּרִית, בְּגִין דְּיִתְנְטִיר הַאי בְּרִית וְלָא יִסְתָּאַב בֵּין אִינוּן עַמִּין:","רַק אֶת בְּנִי לֹא תָשֵׁב שָׁמָּה. מַאי טַעְמָא, בְּגִין דְּיָדַע אַבְרָהָם דְּהָא בְּכֻלְּהוּ לָא הֲוָה מַאן דְּאִשְׁתְּמוֹדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בַּר אִיהוּ בִּלְחוֹדוֹי, וְלָא בָּעָא דְּלֵהְווּ מְדוֹרֵיהּ דְּיִצְחָק בֵּינַיְיהוּ, אֶלָּא דִּיהֵא מְדוֹרֵיהּ עִמֵּיהּ, וְיִצְחָק יוֹלִיף מִנֵּיהּ תָּדִיר אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא. וְעַל דָּא לָא בָּעָא אַבְרָהָם דִּלְהֱוֵי מְדוֹרֵיהּ דְּיִצְחָק תַּמָּן.","אָמַר רִבִּי יֵיסָא וַדַּאי זְכוּתֵיהּ דְּאַבְרָהָם אָעֳרַע קַמֵּיהּ דְּהַהוּא עַבְדָא, דְּהַהוּא יוֹמָא נָפַק, וְהַהוּא יוֹמָא מָטָא לְעֵינָא דְמַיָּא, דִּכְתִיב וָאָבֹא הַיּוֹם אֶל הָעָיִן. וְהָא אוּקְמוּהָ.","רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהילים קי״ט:י״ח) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךָ. כַּמָה אִינוּן בְּנִי נְשָׁא טִפְּשִׁין דְּלָא יָדְעִין וְלָא מִסְתַּכְּלִין לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, בְּגִין דְּאוֹרַיְיתָא כָּל חַיִּין וְכָל חֵירוּ וְכָל טוּב בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. (ההוא חירו דעלמא דין ודעלמא דאתי איהו) (נ\"א ההוא חירו דעלמא דאתי איהו חיין בעלמא דין). חַיִּין אִינוּן בְּעַלְמָא דֵין דְּיִזְכּוּן לְיוֹמִין שְׁלֵמִין בְּהַאי עַלְמָא כְּמָא דְאַתְּ אָמֵר, (שמות כ״ג:כ״ו) אֶת מִסְפַּר יָמֶיךָ אֲמַלֵּא. וּלְיוֹמִין אֲרִיכִין בְּעַלְמָא דְאָתֵי. בְּגִין דְּאִינוּן חַיִּין שְׁלֵימִין, אִינוּן חַיִּין דְּחֵידוּ, חַיֵּי בְּלָא עֲצִיבוּ, חַיִּין דְּאִינוּן חַיִּין. חֵירוּ בְּעַלְמָא דֵין חֵירוּ דְּכֹלָּא, דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא לָא יָכְלִין לְשַׁלְטָאָה עֲלוֹי כָּל עַמִּין דְּעַלְמָא.","וְאִי תֵימָא אִינוּן בְּנִי שְׁמַד. גְּזֵרָה הִיא מִלְּעֵילָא כְּגוֹן רַבִּי עֲקִיבָא וְחֲבֵרוֹי, וְכָךְ סָלִיק בְּמַחֲשָׁבָה. חֵירוּ דְּמַלְאַךְ הַמָּוֶת דְּלָא יָכִיל לְשַׁלְטָאָה עֲלוֹי, וְהָכִי הוּא וַדַּאי דְּאִי אָדָם הֲוָה אִתְדָּבַּק בְּאִילָנָא דְחַיֵּי דְּאִיהוּ אוֹרַיְיתָא, לָא גָרִים מוֹתָא לֵיהּ וּלְכָל עַלְמָא. וּבְגִין כָּךְ כַּד יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל מַה כְּתִיב בָּהּ חָרוּת עַל הַלּוּחוֹת וְהָא אוּקְמוּהָ. וְאִלְמָלֵא אִינוּן לָא חָטוּ וְשָׁבְקוּ אִילָנָא דְחַיֵּי, לָא גָרְמוּ מוֹתָא לְעַלְמָא כְּמִלְקַדְּמִין. וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר (תהילים פ״ב:ו׳) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וּבְנֵי עֶלְיוֹן כֻּלְּכֶם. חֲבַלְתּוּן גַּרְמֵיכוֹן אָכֵן כְּאָדָם תְּמוּתוּן וְגו'. וְעַל דָּא כָּל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא לָא יָכִיל לְשַׁלְטָאָה עֲלוֹי הַהוּא חִוְיָא בִּישָׁא דְּאַחְשִׁיךְ עָלְמָא.","אָמַר רַבִּי יֵיסָא אִי הָכִי משֶׁה אַמַּאי מִית, דְּאִי הָכִי כֵּיוָן דְּלָא חָב לָא יְמוּת (ואמאי ימות). אָמַר לֵיהּ וַדַּאי מִית, אֲבָל לָא שָׁלָטָא בֵּיהּ קָאַמְרִינָן, אֶלָּא לָא מִית עַל יְדוֹי וְלָא אִסְתָּאַב בֵּיהּ, וְלָא מִית וַדַּאי אֶלָּא אִתְדָּבַּק בִּשְׁכִינְתָּא וְאָזִיל לְחַיֵּי עָלְמָא."],[[0,"בגין כך מאן וכו':","משום זה, מי שנתדבק באשה, מעמים אחרים עובדי עבודת כו\"ם, הוא נטמא, והבן הנולד לו ממנה, מקבל עליו רוח הטומאה. ואם תאמר, הלא מצד אביו בא מישראל ולמה יקבל עליו רוח הטומאה."],[0,"ת\"ח דהא וכו':","בוא וראה, כי בתחלה נטמא אביו, בשעה שנתדבק באשה ההיא הטמאה, וכיון שהאב נטמא באשה ההיא שהיא טמאה, מכל שכן שהבן הנולד ממנה, יקבל עליו רוח הטומאה. ולא עוד, אלא שעבר על התורה, שכתוב, כי לא תשתחוה לאל אחר, כי ה' \u0003קנא\u0004 שמו, דהיינו שהוא \u0003מקנא\u0004 על ברית ההוא, שלא יחלל אותו באשה מעמים אחרים."],[1,"אמר ר' אלעזר ת\"ח:","אר\"א, בוא וראה, כי למדנו, מכיון שידע אברהם חכמה רצה להפרד מכל העמים האחרים, ולא להתדבק בהם, וע\"כ כתוב, ואשביעך בה' אלקי השמים ואלקי הארץ אשר לא תקח אשה וגו'. \u0003מבנות הכנעני,\u0004 ודאי הוא, שהוא סוד, כמש\"א, ובעל בת אל נכר, \u0003אשר אנכי יושב בקרבו, אנכי\u0004 הוא בדיוק, כתוב כאן אשר \u0003אנכי\u0004 וכתוב שם \u0003אנכי\u0004 עשיתי ארץ, מה שם אנכי הוא השכינה, אף כאן אנכי הוא השכינה, כי היתה בגלות. וכל זה, השביע אותו, כדי שלא להטמא בהם."],[2,"ת\"ח האי מאן וכו':","בוא וראה, כל מי שמכניס ברית קדוש הזה באשה מעמים אחרים עעכו\"ם, גורם מקום אחר להטמא, דהיינו שפוגם ברית העליון וגורם שישפיע להשפחה ועל כן כתוב תחת שלש רגזה ארץ וגו'. ואף על פי שהשביע אותו בברית, עוד לא בטח בו אברהם, אלא שהתפלל תפלתו לפני הקב\"ה, ואמר, ה' אלקי השמים וגו', הוא ישלח מלאכו, \u0003מלאכו\u0004 פירושו ודאי מלאך הברית. שישלח אותו כדי שיהיה נשמר ברית הזה, ולא יתחלל בין העמים."],[3,"רק את בני לא תשב שמה:","ושואל מה הטעם. ואומר, בשביל שידע אברהם, אשר חוץ ממנו בלבדו, לא היה בכולם, בכל משפחתו, מי שיכיר את הקב\"ה, ולא רצה שתהיה דירתו של יצחק ביניהם. אלא שתהיה דירתו עמו, ויצחק ילמד תמיד ממנו דרכיו של הקב\"ה, שלא יטה לא לימין ולא לשמאל, אלא בקו אמצעי. ועל כן לא רצה אברהם, שתהיה דירתו של יצחק ביניהם."],[4,"אמר ר' ייסא וכו':","אר\"י, בודאי, זכותו של אברהם היה עם העבד, שבו ביום יצא, ובו ביום הגיע לעין המים, שכתוב, ואבא \u0003היום\u0004 אל העין. וכבר בארוה."],[5,"ר' אלעזר פתח וכו':","ר\"א פתח ואמר, כתוב גל עיני ואביטה נפלאות מתורתך, כמה הם שוטים בני אדם, שאינם יודעים ואינם מסתכלים לעסוק בתורה, שהרי התורה, הוא כל החיים, וכל חירות, וכל הטוב, בעולם הזה ובעולם הבא. ומפרש חיים הוא בעולם הזה, היינו שיזכו לימים שלמים בעולם הזה, כמש\"א את מספר ימיך אמלא. ויזכה לימים ארוכים בעולם הבא, בשביל שהם חיים שלמים הם חיים של שמחה, חיים בלי עצבות, חיים שהם חיים, חירות בעולם הזה, חירות מכל, כי כל מי שעוסק בתורה לא יוכלו לשלוט עליו כל עמי העולם."],[6,"ואי תימא וכו':","ואם תאמר, הרי אלו בני השמד, דהיינו הרוגי מלכות, מחמת שעסקו בתורה, בזמן שגזרו שלא לעסוק בתורה, ומשיב, הוא גזירה מלמעלה. כמו ר' עקיבא וחביריו, שנהרגו משום שעסקו בתורה, וכך עלה במחשבה של מעלה, בעת שנברא העולם. אבל בדרך כלל, התורה הוא חירות ממלאך המות, שאינו יכול לשלוט עליו."],[6,"והכי הוא ודאי וכו':","וכן הוא בודאי, שהרי אם אדם היה מתדבק בעץ החיים, שהוא התורה, לא היה גורם מות לו ולכל העולם, אלא משום שעזב את עץ החיים שהוא התורה, ואכל מעץ הדעת, גרם מיתה לו ולעולם. ומשום זה כשנתן הקב\"ה התורה לישראל, מה כתוב בה, \u0003חרות\u0004 על הלוחות, וכבר בארוה דהיינו אל תקרי חרות, אלא \u0003חירות\u0004 כי נעשו אז חירות ממלאך המות, ואלמלא לא חטאו ישראל בעגל, ולא עזבו את עץ החיים שהוא התורה, לא היו גורמים שיחזור המות לעולם כמתחילה. והקב\"ה אמר, אני אמרתי אלקים אתם ובני עליון כלכם, היינו, בקבלת התורה, כיון שחבלתם בעצמכם, שחטאתם. אכן כאדם תמותון וגו'. ועל כן כל מי שעוסק בתורה אינו יכול לשלוט עליו, אותו נחש הרע שהחשיך העולם."],[7,"אמר ר' ייסא וכו':","אר\"י, אם כן הוא, שמי שלא חטא לא ימות. אם כן, למה מת משה, אמר לו ודאי מת, אבל רק שאין מלאך המות שולט בו אמרנו, והוא לא מת על ידו ולא נטמא בו. וע\"כ נבחן שודאי לא מת אלא שנתדבק בשכינה והלך לחיי העולם."]],[[0,"","מִשּׁוּם כָּךְ מִי שֶׁנִּדְבָּק בְּאִשָּׁה שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת, הוּא נִטְמָא, וְאוֹתוֹ בֵּן שֶׁיִּוָּלֵד לוֹ יְקַבֵּל עָלָיו רוּחַ שֶׁל טֻמְאָה. וְאִם תֹּאמַר, הֲרֵי מִצַּד אָבִיו הוּא בָּא מִיִּשְׂרָאֵל, לָמָּה יְקַבֵּל עָלָיו רוּחַ טֻמְאָה? בֹּא רְאֵה, שֶׁהֲרֵי בָּרִאשׁוֹנָה נִטְמָא אָבִיו בְּשָׁעָה שֶׁנִּדְבַּק עִם אוֹתָהּ אִשָּׁה שֶׁהִיא טְמֵאָה, וְכֵיוָן שֶׁהָאָב נִטְמָא בְּאוֹתָהּ אִשָּׁה שֶׁהִיא טְמֵאָה, כָּל שֶׁכֵּן שֶׁאוֹתוֹ הַבֵּן שֶׁנּוֹלַד מִמֶּנָּה יְקַבֵּל עָלָיו רוּחַ טֻמְאָה. וְלֹא עוֹד, אֶלָּא שֶׁעָבַר עַל הַתּוֹרָה, שֶׁכָּתוּב (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר, כִּי ה' קַנָּא שְׁמוֹ, מִשּׁוּם שֶׁהוּא מְקַנֵּא עַל בְּרִית הַקֹּדֶשׁ הַזּוֹ."],[1,"","אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, שֶׁהֲרֵי נֶאֱמַר שֶׁכֵּיוָן שֶׁיָּדַע אַבְרָהָם אָבִינוּ חָכְמָה, רָצָה לְהִפָּרֵד מִכָּל שְׁאָר הָעַמִּים וְלֹא לְהִדָּבֵק בָּהֶם, וּמִשּׁוּם כָּךְ כָּתוּב: וְאַשְׁבִּיעֲךְ בַּה' אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי מִבְּנוֹת הַכְּנַעֲנִי וְגוֹ'. מִבְּנוֹת הַכְּנַעֲנִי וַדַּאי. (מה) סוֹד הוּא, כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ב) וּבָעַל בַּת אֵל נֵכָר. אֲשֶׁר אָנֹכִי יוֹשֵׁב בְּקִרְבּוֹ, אָנֹכִי בִּמְדֻיָּק. כָּתוּב כָּאן אֲשֶׁר אָנֹכִי, וְכָתוּב שָׁם (ישעיה מד) אָנֹכִי עָשִׂיתִי אֶרֶץ. וְכָל זֶה כְּדֵי לֹא לְהִטָּמֵא עִמָּהֶם."],[2,"","בֹּא רְאֵה, מִי שֶׁמַּכְנִיס אֶת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ בָּאִשָּׁה הַהִיא שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, גּוֹרֵם לְטַמֵּא מָקוֹם אַחֵר, וְעַל זֶה כָּתוּב (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ'. וְאַף עַל גַּב שֶׁהִשְׁבִּיעַ אוֹתוֹ בַּבְּרִית הַזּוֹ, לֹא בָטַח בּוֹ אַבְרָהָם, עַד שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר, ה' אֱלֹהֵי הַשָּׁמַיִם וְגוֹ', הוּא יִשְׁלַח מַלְאָכוֹ. וַדַּאי זֶה מַלְאַךְ הַבְּרִית כְּדֵי שֶׁיִּשְׁמֹר הַבְּרִית הַזּוֹ וְלֹא יִטָּמֵא בֵּין אוֹתָם הָעַמִּים."],[3,"","רַק אֶת בְּנִי לֹא תָשֵׁב שָׁמָּה. מָה הַטַּעַם? מִשּׁוּם שֶׁיָּדַע אַבְרָהָם שֶׁהִנֵּה בְּכֻלָּם לֹא הָיָה מִי שֶׁהִכִּיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, רַק הוּא לְבַדּוֹ, וְלֹא רָצָה שֶׁיִּהְיֶה מְדוֹרוֹ שֶׁל יִצְחָק בֵּינֵיהֶם, אֶלָּא שֶׁיִּהְיֶה מְדוֹרוֹ עִמּוֹ, וְיִצְחָק יִלְמַד מִמֶּנּוּ תָּמִיד אֶת דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא יִסְטֶה יָמִינָה וּשְׂמֹאלָה, וְעַל כֵּן לֹא רָצָה אַבְרָהָם שֶׁמְּדוֹרוֹ שֶׁל יִצְחָק יִהְיֶה שָׁם."],[4,"","אָמַר רַבִּי יֵיסָא, וַדַּאי שֶׁזְּכוּתוֹ שֶׁל אַבְרָהָם הָיְתָה לִפְנֵי הָעֶבֶד הַהוּא, שֶׁהַיּוֹם הַהוּא יָצָא, וּבְאוֹתוֹ הַיּוֹם הִגִּיעַ לְעֵין הַמַּיִם, שֶׁכָּתוּב וָאָבֹא הַיּוֹם אֶל הָעָיִן. וְהִנֵּה פֵּרְשׁוּהָ."],[5,"","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ. כַּמָּה טִפְּשִׁים הָאֲנָשִׁים שֶׁלֹּא יוֹדְעִים וְלֹא מִסְתַּכְּלִים לְהִשְׁתַּדֵּל בַּתּוֹרָה, מִשּׁוּם שֶׁהַתּוֹרָה כָּל הַחַיִּים וְכָל הַחֵרוּת וְכָל הַטּוֹב בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (החרות ההיא של העולם הזה ושל הבא היא) (נ\"א: החרות ההיא של העולם הבא היא החיים בעולם הזה) הַחַיִּים הֵם בָּעוֹלָם הַזֶּה, שֶׁיִּזְכּוּ לְיָמִים שְׁלֵמִים בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) אֶת מִסְפַּר יָמֶיךְ אֲמַלֵּא. וּלְיָמִים אֲרֻכִּים בָּעוֹלָם הַבָּא, מִשּׁוּם שֶׁהֵם חַיִּים שְׁלֵמִים, הֵם חַיִּים שֶׁל שִׂמְחָה, חַיִּים בְּלִי עַצְבוּת, חַיִּים שֶׁהֵם חַיִּים. חֵרוּת בָּעוֹלָם הַזֶּה, חֵרוּת שֶׁל הַכֹּל. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אֵין יְכוֹלִים לִשְׁלֹט עָלָיו כָּל הָעַמִּים שֶׁל הָעוֹלָם."],[6,"","וְאִם תֹּאמַר, אוֹתָם בְּנֵי הַשְּׁמָד? גְּזֵרָה הִיא מִלְמַעְלָה, כְּמוֹ רַבִּי עֲקִיבָא וַחֲבֵרָיו, וְכָךְ עָלְתָה בְּמַחֲשָׁבָה. חֵרוּת שֶׁל מַלְאַךְ הַמָּוֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וְכָךְ זֶה וַדַּאי. שֶׁאִם אָדָם הָיָה נִדְבָּק בְּעֵץ הַחַיִּים, שֶׁהִיא הַתּוֹרָה, לֹא הָיָה גוֹרֵם מָוֶת לוֹ וּלְכָל הָעוֹלָם. וּמִשּׁוּם כָּךְ, כְּשֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה לְיִשְׂרָאֵל, מַה כָּתוּב בָּהּ? חָרוּת עַל הַלֻּחֹת, וַהֲרֵי פֵּרְשׁוּהָ. וְאִלְמָלֵא הֵם לֹא חָטְאוּ וְעָזְבוּ אֶת עֵץ הַחַיִּים, לֹא הָיוּ גוֹרְמִים מָוֶת לָעוֹלָם כְּבַתְּחִלָּה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, (תהלים פב) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וּבְנֵי עֶלְיוֹן כֻּלְּכֶם. חִבַּלְתֶּם אֶת עַצְמְכֶם - אָכֵן כְּאָדָם תְּמוּתוּן וְגוֹ'. וְעַל כֵּן, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אֵין יָכוֹל לִשְׁלֹט עָלָיו הַנָּחָשׁ הָרָע הַהוּא שֶׁהֶחְשִׁיךְ אֶת הָעוֹלָם."],[7,"","אָמַר רַבִּי יֵיסָא, אִם כָּךְ, לָמָּה מֹשֶׁה מֵת? שֶׁאִם כָּךְ, כֵּיוָן שֶׁלֹּא חָטָא - לֹא יָמוּת! (ולמה ימות)? אָמַר לוֹ, וַדַּאי מֵת, אֲבָל לֹא שָׁלַט בּוֹ אָמַרְנוּ, אֶלָּא לֹא מֵת עַל יָדוֹ וְלֹא נִטְמָא בּוֹ, וְלֹא מֵת וַדַּאי. אֶלָּא נִדְבַּק בַּשְּׁכִינָה וְהָלַךְ לְחַיֵּי עוֹלָם."]]],[["וְהַאי חַי אִקְרֵי, כְּמָה דְאוֹקִימְנָא דִּכְתִיב (שמואל ב:כג) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי וְגו'. וְעַל דָּא כָּל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא חֵירוּ אִית לֵיהּ מִכֹּלָּא בְּעַלְמָא דֵין מִשִּׁעְבּוּדָא דִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. חֵירוּ בְּעַלְמָא דְאָתֵי בְּגִין דְּלָא יִתְבְּעוּן מִנֵּיהּ דִּינָא בְּהַהוּא עַלְמָא כְּלָל.","תָּא חֲזֵי, בְּאוֹרַיְתָא כַּמָּה רָזִין עִלָּאִין סְתִימִין אִית בָּהּ, בְּגִין כָּךְ כְּתִיב, (משלי ג) יְקָרָה הִיא מִפְּנִינִים. כַּמָּה גְנִיזִין טְמִירִין אִית בָּהּ, וְעַל דָּא כַּד אִסְתַּכַּל דָּוִד בְּרוּחָא דְחָכְמְתָא וְיָדַע כַּמָּה פְּלִיאָן נָפְקִין מֵאוֹרַיְיתָא פָּתַח וְאָמַר, (תהילים קי״ט:י״ח) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךָ.","תָּא חֲזֵי, וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יוֹצֵאת. יוֹצֵאת, בָּאָה מִבָּעֵי לֵיהּ, מַאי יוֹצֵאת. דְּקוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לָהּ מִכָּל אִינוּן בְּנֵי מָתָא דְּכֻלְּהוּ חַיָּיבִין, וְהִיא יוֹצֵאת מִכְּלָלָא דִּלְהוֹן. וַתֵּרֶד הָעַיְנָה כְּתִיב בְּה\"א, רָזָא אִיהוּ דְּאִעָרְעַת תַּמָּן בֵּירָא דְּמִרְיָם, וּבְגִין כָּךְ כְּתִיב הָעַיְנָה בְּה\"א וּסְלִיקוּ לָהּ מַיָא.","דָּבָר אַחֵר וְהִנֵּה רִבְקָה יוֹצֵאת כְּמָה דִכְתִיב יוֹצְאוֹת לִשְׁאוֹב מַיִם, אַמַּאי יוֹצְאוֹת וְלא הוֹלְכוֹת וְלֹא בָאוֹת. אֶלָּא בְּגִין דִּטְמִירִין הֲווּ כָּל יוֹמָא וּבְהַהִיא שַׁעְתָּא נָפְקִין לְשָׁאֲבָא מַיָא, וְסִימָנָא נָקִיט בִּידֵיהּ.","תָּא חֲזֵי, כַּד מָטָא עַבְדָא לְחָרָן וְאַשְׁכַּח לָהּ לְרִבְקָה לְעֵת עֶרֶב הֲוָה עִידָן צְלוֹתָא דְמִנְחָה. בְּהַהִיא שַׁעְתָּא דְּמָטָא יִצְחָק לְצַלָּאָה צְלוֹתָא דְמִנְחָה, בְּהַהִיא שַׁעְתָּא מָטָא עַבְדָא לְגַבָּהּ דְּרִבְקָה. וּבְהַהִיא שַׁעְתָּא דְּמָטָא יִצְחָק לִצְלוֹתָא דְמִנְחָה כְּמִלְקַדְּמִין מָטַאת רִבְקָה לְגַבֵּיהּ. לְאִשְׁתַּכָּחָא כֹּלָּא בְּאַתְרֵיהּ דְּאִצְטְרִיךְ כְּדְקָא יְאוּת, וְכֹלָּא מָטָא בְּרָזָא דְחָכְמְתָא, וְעַל דָּא אֲתָא הַהוּא עַבְדָא לִבְאֵר הַמַּיִם רָזָא דִכְתִיב (שיר השירים ד׳:ט״ו) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנוֹזְלִים מִן לְבָנוֹן, וְאוֹקִימְנָא, וְכֹלָּא רָזָא אִיהוּ.","רִבִּי שִׁמְעוֹן הֲוָה אָתֵי לִטְבֶרְיָה וְהֲוָה עִמֵּיהּ רִבִּי אַבָּא. אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אַבָּא נִזִיל, דְּהָא אֲנַן חָמֵינָן דְּבַר נָשׁ חַד יִמְטֵי הַשְׁתָּא לְגַבָּן וּמִלִּין חַדְתִּין בְּפוּמֵיהּ וְאִינוּן מִלִּין דְּאוֹרַיְיתָא. אָמַר רִבִּי אַבָּא הָא יְדַעְנָא דְּבְּכָל אֲתַר דְּמַר אָזִיל, קוּדְשָׁא בְּרִיךְ הוּא מְשַׁדֵּר לֵיהּ מַלְאָכִין טָסִין בְּגַדְפִין לְאִשְׁתַּעְשְׁעָא בֵּיהּ.","עַד דְּהֲווּ אָזְלֵי, סָלִיק רִבִּי שִׁמְעוֹן עֵינוֹי, וְחָמָא בַּר נָשׁ דְּהֲוָה רָהִיט וְאָזִיל. יָתְבוּ רִבִּי שִׁמְעוֹן וְרִבִּי אַבָּא. כַּד מָטָא גַּבַּיְיהוּ, אָמַר לֵיהּ רִבִּי שִׁמְעוֹן מַאן אַנְתְּ. אָמַר לֵיהּ יוּדָאי אֲנָא וּמִקַּפּוֹטְקִיָּא קָאֲתִינָא וְאֲנָא אָזִילְנָא אַטִיטְרֵיהּ דְּבַר יוֹחָאי דְּאִתְמַנּוּן חַבְרַיָא בְּמִלִּין יְדִיעָן וְשַׁדְּרוּנִי גַּבֵּיהּ. אָמַר לֵיהּ אֵימָא בְּרִי. אָמַר לֵיהּ אַנְתְּ בַּר יוֹחָאי. אָמַר לֵיהּ אֲנָא בַּר יוֹחָאי.","אָמַר לֵיהּ הָא אוֹקִימְנָא דְּלָא יַפְסִיק בַּר נָשׁ בִּצְלוֹתֵיהּ בֵּינֵיהּ לְבֵין כּוֹתְלָא כְּמָה דִכְתִיב, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וְגו'. וּמַאן דְּצַלֵּי אָסִיר לְמֶעֱבַר אַרְבַּע אַמּוֹת סָמִיךְ לֵיהּ, וְאוּקְמוּהָ לְהַנֵּי אַרְבַּע אַמּוֹת לְכָל סְטַר בַּר לְקַמֵּיהּ. וְאוּקְמוּהָ דְּלָא יִצְלֵי בַּר נָשׁ אֲחוֹרֵי רַבֵּיהּ וְכוּ' וְאִתְמַנּוּן בְּכָל הַנֵּי מִילֵי.","פָּתַח וְאָמַר, (תהילים ל״ט:י״ג) שִׁמְעָה תְּפִלָּתִי יְיָ וְשַׁוְעָתִי הַאֲזִינָה אֶל דִּמְעָתִי אַל תֶּחרָשׁ. מַאי טַעְמָא שִׁמְעָה וְלָא שְׁמַע, בְּאֲתַר חַד כְּתִיב שְׁמַע יְיָ וְחָנִנִי וְגו', וּבְאֲתַר אָחֳרָא שִׁמְעָה. אֶלָּא בְּכָל אֲתַר לְזִמְנִין שְׁמַע לִדְכוּרָא וּלְזִמְנִין שִׁמְעָה לְנוּקְבָא. שִׁמְעָה כְּמָה דְאַתְּ אָמֵר, (תהילים י״ז:א׳) שִׁמְעָה יְיָ צֶדֶק וְגו'. שְׁמַע כְּמָא דְאַתְּ אָמֵר, (תהילים ל׳:י״א) שְׁמַע יְיָ וְחָנֵנִי. (משלי א) שְׁמַע בְּנִי. (דברים כ״ז:ט׳) הַסְכֵּת וּשְׁמַע.","וְהָכָא שִׁמְעָה תְּפִלָּתִי יְיָ, בְּגִין דְּהַאי (דאיהו) דַרְגָּא דִּמְקַבְּלָא כָּל צְלוֹתִין דְּעַלְמָא. וְהָא תָּנִינָן דְּעַבְדָא מִנַּיְיהוּ עֲטָרָה וְשַׁוֵּי לָהּ בְּרֵישָׁא דְּצַדִּיק חַי עוֹלָמִים דִּכְתִיב, (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק. וְעַל דָּא שִׁמְעָה תְּפִלָּתִי יְיָ.","שִׁמְעָה תְּפִלָּתִי יְיָ דָּא צְלוֹתָא דִי בְלַחַשׁ. וְשַׁוְעָתִי הַאֲזִינָה דָּא צְלוֹתָא דְּאָרִים בַּר נָשׁ קָלֵיהּ בְּעַקְתֵיהּ כְּמָא דְאַתְּ אָמֵר, (שמות ב׳:כ״ג) וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים. וּמַהוּ שַׁוְעָתָם, אֶלָּא דְּבִצְלוֹתֵיהּ אָרִים קָלֵיהּ וְזָקִיף עֵינוֹי לְעֵילָא כְּמָא דְאַתְּ אָמֵר, (ישעיהו כ״ב:ה׳) וְשׁוֹעַ אֶל הָהָר. וּצְלוֹתָא דָא מְתַבַּר תַּרְעִין וְדָפִיק (ס\"אודחיק) לוֹן לְאֲעָלָא צְלוֹתֵיהּ. אֶל דִּמְעָתִי אַל תֶּחרָשׁ דָּא, אָעִיל קַמֵּי מַלְכָּא וְלֵית תַּרְעָא דְּקָאִים קַמֵּיהּ, וּלְעוֹלָם לָא אַהֲדָרוּ דִּמְעִין בְּרֵיקַנְיָא."],[[0,"והאי חי אקרי וכו':","וכזה, נקרא חי, כמו שבארנו, במה שכתוב. ובניהו בן יהוידע בן איש חי וגו'. דהיינו כמ\"ש להלן (בפרשת ויגש דף ט\"ז אות נ\"ב) \u0003ומאן דאתקריב לגביה איהו חי,\u0004 ומי שנתקרב לה' נקרא חי ע\"ש. ועל כן כל מי שעוסק בתורה יש לו חירות מכל, חירות בעולם הזה משעבוד אומות העולם עעכו\"ם, וחירות בעולם הבא, כי לא ידרשו ממנו דין וחשבון כלל בעולם ההוא."],[1,"ת\"ח באורייתא וכו':","בוא וראה, כמה סודות עליונים סתומים יש בהתורה, משום זה כתוב, יקרה היא מפנינים. כמה אוצרות נסתרים יש בה, ועל כן, כשנסתכל דוד בהתורה ברוח החכמה. וידע כמה פליאות יוצאות מהתורה, פתח ואמר, גל עיני ואביטה נפלאות מתורתך."],[2,"ת\"ח ויהי הוא וגו' יוצאת:","ושואל כתוב, \u0003יוצאת,\u0004 היה צריך לומר \u0003באה,\u0004 כמ\"ש והנה רחל בתו באה וגו' למה כתוב \u0003יוצאת,\u0004 ואומר שזה יורה, שהקב\"ה הוציאה מכל אנשי העיר, שכולם היו רשעים \u0003ורבקה יוצאת\u0004 ונפרדת מכלל בני העיר, שהיתה צדיקת. \u0003ותרד העינה,\u0004 כתוב עם \u0003ה'\u0004 והוא סוד, כי נקרה לה שמה, בארה של מרים, שה\"ס הנוקבא דז\"א בעת שמאירה בהארת חכמה, ומשום זה כתוב \u0003העינה\u0004 עם \u0003ה'\u0004 הרומזת על הנוקבא שה\"ס \u0003ה'\u0004 תתאה של הוי\"ה. גם העינה הוא מלשון עינים, שהוא שם החכמה. והמים היו עולים לקראת רבקה."],[3,"דבר אחר והנה רבקה יוצאת:","שהיא כמו שכתוב, והנה בנות העיר יוצאות לשאוב מים. ולמה כתוב \u0003יוצאות,\u0004 ולא כתוב הולכות ולא באות. אלא הוא, משום, שהיו נסתרות כל היום, ובשעה ההיא, לעת ערב, יצאו לשאוב מים, והעבד עשה לו זה לסימן."],[3,"","פירוש. כי אין הארת החכמה של הנוקבא, מתגלית אלא בלילה, בסו\"ה ותקם בעוד לילה וגו', וע\"כ היא נבחנת מבחינת הארה הזאת שהיא מסתתרת ביום ונגלית בלילה. (כמ\"ש בזהר משפטים. אות ט\"ו פנחס אות תרצ\"ב ע\"ש) והטעם הוא, כי יום ה\"ס ז\"א, המאיר בחסדים מכוסים מחכמה, כמו או\"א עלאין, והארת החכמה מתגלית רק בהנוקבא לבדה בלי ז\"א (כנ\"ל ב\"א דף קי\"ז ד\"ה מאור) וכשהנוקבא היא לבדה בלי ז\"א, הוא חשך ולא אור, דהיינו לילה, ועל כן הנוקבא מגלית הארתה רק בלילה ולא ביום. וזסו\"ה \u0003לעת ערב לעת צאת השואבות.\u0004 כי \u0003העינה\u0004 כתוב עם \u0003ה'\u0004 שהוא שם הנוקבא בעת שמאירה בהארת חכמה כנ\"ל, וע\"כ אין השואבות יוצאות לשאוב ממנה מימי החכמה, אלא \u0003לעת ערב,\u0004 בשעה שפנה היום. כי מקודם לכן, היא מסתתרת ואינה מאירה כמבואר. וז\"ש הזהר כאן, \u0003דטמירין הוו כל יומא ובההיא שעתא נפקין,\u0004 כי להיות השואבות דבוקות במדרגת הנוקבא, הן מסתתרות גם כן ביום כמוה, ואינן נגלות לשאוב ממנה מימי החכמה אלא בלילה. וז\"ש, \u0003וסימנא נקיט בידיה,\u0004 שהעבד עשה לו זה לסימן, שאמר, הנה אנכי וגו' ובנות העיר יוצאות לשאוב מים, דהיינו, שאינן יוצאות ומתגלות רק לעת ערב, כמו הנוקבא העליונה, שאז ידע שכשרות הן, וימצא ביניהן בת זוגו של יצחק."],[4,"ת\"ח כד מטא עבדא וכו':","בוא וראה, כשהגיע העבד לחרן, ומצא את רבקה לעת ערב, היה אז זמן תפלת המנחה, באותה שעה, שבא יצחק להתפלל תפלת המנחה באותה שעה הגיע העבד אל רבקה. וכן באותה שעה ששוב הגיע יצחק לתפלת המנחה כמקודם לכן, הגיעה רבקה אליו. דהיינו כמ\"ש, ויצא יצחק לשוח בשדה לפנות ערב וגו'. והיה זה כדי שימצא הכל במקום הצריך לו, כראוי להיות, שהכל נמשך בסוד החכמה. וע\"כ בא העבד לבאר המים, שהסו\"ה מעין גנים וגו' ובארנוה, והכל הוא סוד, פירוש, כי יצחק הוא סוד קו שמאל דז\"א, שאין תיקונו מתחיל אלא לעת ערב בזמן תפלת המנחה כמ\"ש לפנינו ולפיכך הן מציאת רבקה והן ביאת רבקה אליו, היה באותו הזמן שמתחיל שליטתו, לעת תפלת המנחה. וגם מטעם זה בא אז העבד אל באר המים, שה\"ס הנוקבא בעת שמאירה מקו שמאל דז\"א."],[5,"ר' שמעון הוה אתי לטבריה וכו':","ר\"ש היה הולך לעיר טבריה, והיה עמו ר' אבא. אמר ר\"ש לר' אבא, נלך, כי אנו רואים שאדם אחד יגיע עתה אלינו, ודברים חדשים בפיו שהם דברי תורה, אמר ר' אבא, כבר יודע אני, שבכל מקום שאדוני הולך, הקב\"ה שולח לו מלאכים עפים בכנפים שישתעשע עמהם."],[6,"עד דהוו אזלי וכו':","בעוד שהיו הולכים, נשא ר\"ש את עיניו, וראה איש שהיה הולך ורץ. ישבו ר\"ש ור\"א, וחכו עליו. כשהגיע אליהם, אמר לו ר\"ש מי אתה, אמר לו יהודי אני, ומעיר קפוטקיא באתי, ואני הולך לסתרו של בן יוחאי, דהיינו לשמוע ממנו נסתרות, כי החברים נמנו וביארו דברים ידועים, ושלחוני אליו, לשמוע אם יסכים עמהם, אמר לו ר\"ש אמור בני. אמר לו, אתה הוא בן יוחאי. אמר לו אני בן יוחאי."],[7,"א\"ל הא אוקימנא וכו':","אמר לו, הרי אמרו, כשמתפלל, לא יהיה דבר מבדיל בינו לבין הקיר. כמו שכתוב, ויסב חזקיה פניו אל הקיר. ומי שמתפלל, אסור לאדם שיעבור ארבע אמות סמוך לו. ואמרו, שאלו ארבע אמות הן לכל צד חוץ מלפניו שהרי אסור להבדיל בינו לבין הקיר. ואמרו שלא יתפלל אדם אחורי רבו. ונמנו בכל דברים אלו דהיינו שהסכימו, לשלוח אותי לשמוע דבריך בזה."],[8,"פתח ואמר שמעה ה' תפלתי וגו':","פתח היהודי ואמר שמעה וכו', ושואל מה הטעם שכתוב \u0003שמעה,\u0004 ולא שמע. ולמה במקום אחד כתוב \u0003שמע\u0004 ה' וחנני וגו', ובמקום אחר \u0003שמעה\u0004 ואומר. אלא בכל מקום שכתוב פעם שמע הוא לזכר, דהיינו לז\"א, וכשכתוב פעם שמעה הוא לנקבה, דהיינו לנוקבא דז\"א, \u0003שמעה,\u0004 הוא כמו שאתה אומר, שמעה ה' צדק וגו' וצדק ה\"ס הנוקבא דז\"א, \u0003שמע\u0004 הוא כמו שאתה אומר שמע הויה וחנני, שהוי\"ה הוא שם ז\"א. וכן שמע בני וכן הסכת ושמע שכל אלו הם לזכר."],[9,"והכא שמעה וכו':","וכאן אומר שמעה תפלתי ה'. שהוא נאמר על הנוקבא. משום שהיא מדרגה, המקבלת כל התפלות, שבעולם, ולמדנו, שהנוקבא עושה עטרה מן התפלות ומשימה אותה בראש הצדיק חי העולמים, שהוא יסוד, וזהו שכתוב ברכות לראש צדיק. ועל זה אומר הכתוב, שמעה תפלתי ה'. ביאור הדברים להלן בדיבור הסמוך."],[10,"שמעה תפלתי ה':","זה הוא תפלה בלחש. דהיינו תפלת שמונה עשרה שאנו מתפללים בלחש. \u0003ושועתי האזינה,\u0004 זהו תפלה בהרמת קול, שאדם מרים קולו, וצועק אל ה' בצרתו כמש\"א, ותעל שועתם אל האלקים, ומהו שועתם שאומר הכתוב, היינו שמרים קולו בתפלתו ונושא עיניו למעלה, כמש\"א ושוע אל ההר. ותפלה זו שוברת שערים, שדופק עליהם להכניס תפלתו לפני ה'. \u0003אל דמעתי אל תחרש,\u0004 זו היא הנכנסת לפני המלך, ואין שער עומד לפניה, שלא יפתח, ולעולם אין תפלה בדמעות חוזרות ריקם."],[10,"","פירוש. כי ג' שורשים הם שמהם נמשכים כל מיני הדינים והיסורים שבעולם: א) דינים הבאים משליטת השמאל בעת שאינו נכלל מימין, שהארתו הוא חכמה בלי חסדים ונקראים דינים דדכורא. ב) דינים הבאים ממלכות דמדת הדין הבלתי נמתקת. ג) דינים הבאים ממלכות הנמתקת במדת הרחמים, שהיא בינה, בסוד עלית המלכות בנקבי עינים. (כנ\"ל ב\"א דף רס\"ג ד\"ה בקולפי) וב' מיני דינים אלו ה\"ס דינין דנוקבא. כמ\"ש לעיל (וירא דף י\"ט ד\"ה והוא) והתפלות שמתפללים על ג' מיני דינים הללו נקראים, תפלה, שועה, דמעה. \u0003תפלה.\u0004 היינו על הדינים דמין הא', ונקראת משום זה \u0003תפלה בלחש,\u0004 כי ז\"א ה\"ס \u0003קול,\u0004 שה\"ס קומת החסדים היוצא על מסך דחירק המכריע בין ב' הקוין ימין ושמאל (כנ\"ל, פרשת לך דף ד' ד\"ה בשעתא) והנוקבא מבחינת ג\"ר שבה היא נקראת \u0003דבור,\u0004 ובעת שהחכמה שבה היא בלי חסדים, נבחנת כדבור בלי \u0003קול,\u0004 דהיינו תפלה בלחש. ועל ידי התפלה אנו מיחדים אותה עם ז\"א שה\"ס חסדים ונקרא קול, ואז נעשה הזווג \u0003דקול ודבור,\u0004 והחכמה שבה מתלבשת בחסדים, שאז מאירה לתחתונים."],[10,"שועה,","היא על הדינים דמין הב', וז\"ש \u0003ומהו שועתם,\u0004 כלומר, מאין באים דינים אלו שהתפלה עליהם נקראת שועה, אלא \u0003דבצלותיה ארים קליה, וזקיף עינוי לעילא.\u0004 היינו משום שהרים קולו בתפלתו, מסבה, שנשא עיניו למעלה. כי אמרו המתפלל ישים עיניו למטה ולבו למעלה, דהיינו כמ\"ש העין רואה והלב חומד, שהעינים ה\"ס חכמה, והלב ה\"ס חסדים, והמתפלל צריך להזהר שלא ימשיך החכמה ממעלה למטה, שזה נבחן שהוא משים עיניו למעלה, וזה היה החטא דעצה\"ד, (כנ\"ל ב\"ב דף ק\"ע ד\"ה ועל) וכן משום זה נקראת הנוקבא עץ הדעת טו\"ר, כי יש בבנינה ב' נקודות דהיינו ב' מלכיות, א) נקודה דמדת הדין, ב) נקודה הממותקת במדת הרחמים. אם \u0003זכי הא טוב,\u0004 שנקודה דמדת הדין נגנזה בה ורק הנקודה הממותקת במדת הרחמים שולטת בה. ואז מקבלת המוחין דבינה בשביל התחתונים שהם \u0003טוב.\u0004 ואם \u0003לא זכי\u0004, דהיינו שממשיך החכמה ממעלה למטה, \u0003הא רע,\u0004 כי תכף נגלה עליו נקודה דמדת הדין שבה, שממנה נמשכים כל הדינים הקשים. (כמ\"ש לעיל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' עש\"ה) ולפיכך מחויב המתפלל לשום עיניו למטה, שלא ימשוך החכמה מלמעלה למטה, כדי שלא תגלה עליו הנקודה דמדת הדין, וז\"ש \u0003וזקיף עינוי לעילא,\u0004 שבתפלתו נשא עיניו למעלה וע\"כ נמשכו עליו הדינים דמין הב', ממלכות דמדת הדין, הנקראים \u0003שועה.\u0004 וז\"ש \u0003וצלותא דא מתבר תרעין.\u0004 כי על ידי תפלתו הוא זוכה להמשיך מסך על המלכות הזו, ואז הוא מעלה מ\"ן, לז\"א הנקרא קול, שנעשה מזה מסך דחירק לז\"א, ובכחו מכריע בין ב' הקוין ימין ושמאל, (ב\"א דף רפ\"ה ד\"ה בין) ואז נשברו השערים הסתומים, כי היו סתומים מכח הארת השמאל, שלא רצה להכלל בימין, ועתה בכח עלית המסך דחירק נכלל השמאל בימין ונפתחו השערים. כלומר שהוסרו הסתימות, אבל עוד אינם ראוים לקבלת התפלה, דהיינו להשפעת מוחין דג\"ר, בסוד קול ודבור, כי אין המוחין מתגלים רק על מסך דמלכות הממותקת במדת הרחמים כנ\"ל וכמ\"ש להלן."],[10,"דמעה,","היא על הדינים דמין הג' הנ\"ל, דהיינו הנמשכים ממסך שעל מלכות הנמתקת בבינה, בסוד עלית ה\"ת לנקבי עינים. המולידה שם דמעות. והוא מלשון המדמע והמנסך (גיטין נב:) כי הבינה ומלכות נתערבו על ידי עליה הזו. וז\"ש \u0003דא אעיל קמי מלכא,\u0004 כי על ידי הדמעות היא מעלה מ\"ן וממשיך מסך על מלכות הממותקת במדת הרחמים, שאז נעשית מוכשרת לקבל כל המוחין דבינה. שה\"ס קבלת התפלה. וז\"ש, \u0003ולעולם לא אהדרו דמעין בריקניא.\u0004"],[10,"","וז\"ש \u0003בגין דהאי דרגא דמקבלא כל צלותין דעלמא,\u0004 כי הנוקבא מקבלת, כל צלותין דעלמא הנכללות באלו הג', הנק' תפלה שועה דמעה. והיא נבנית על ידיהם, שתהיה ראויה להזדווג עם ז\"א, לקבל ממנו המוחין ולהשפיע אל התחתונים. כי ע\"י קבלת ה \u0003שועה,\u0004 נבנה המסך דחירק ליחוד ב' הקוין, ועל ידי קבלת ה \u0003דמעה\u0004 נעשית ראויה לקבלת המוחין, דהיינו שאח\"כ יורדת ה\"ת מעינים לפה, ומתגלית הג\"ר, (כנ\"ל ב\"א דף ז' ד\"ה וכבד ע\"ש) ומקבלת תחילה המיחין דחכמה בלי חסדים, שה\"ס \u0003תפלה בלחש,\u0004 ובזה באה לזווג עם ז\"א, לקבלת חסדים ונעשה היחוד דקול ודבור ומשפעת כל טוב אל התחתונים שגרמו לה כל זה. וז\"ש, \u0003דעבדא מנייהו עטרה ושוי לה ברישא דצדיק חי עולמים.\u0004 שמתפלות הללו היא מקבלת המוחין דחכמה הנקראים עטרה, בסו\"ה צאנה וראנה במלך שלמה בעטרה וגו', והיא מעטרת את ראש הצדיק חי עולמים, שהוא יסוד דז\"א שמזדווגת עמו. כלומר כי אין לז\"א אלא חסדים מכוסים מחכמה, ורק בעת הזווג עם הנוקבא, הוא מקבל על ידיה הארת החכמה, (כנ\"ל ב\"א דף רפ\"ב ד\"ה אלא) ונמצא שהנוקבא מעטרת את ז\"א בעלה. שזסו\"ה אשת חיל עטרת בעלה. וז\"ס בעלה מתעטר בה ואיהי אינה מתעטרת בבעלה."]],[[0,"","וְזְהִ נִקְרָא חַי, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב (שמואל ב כג) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי וְגוֹ'. וְעַל כֵּן, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, יֵשׁ לוֹ חֵרוּת מִן הַכֹּל בָּעוֹלָם הַזֶּה מִשִּׁעְבּוּד שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. חֵרוּת בָּעוֹלָם הַבָּא, מִשּׁוּם שֶׁלֹּא יִתְבְּעוּ מִמֶּנּוּ דִּין בָּעוֹלָם הַהוּא כְּלָל."],[1,"","בֹּא רְאֵה כַּמָּה סוֹדוֹת עֶלְיוֹנִים יֵשׁ בַּתּוֹרָה, מִשּׁוּם כָּךְ כָּתוּב (משלי ג) יְקָרָה הִיא מִפְּנִינִים. כַּמָּה גְנָזִים טְמוּנִים יֵשׁ בָּהּ. וְעַל כֵּן, כְּשֶׁהִסְתַּכֵּל דָּוִד בָּרוּחַ שֶׁל הַחָכְמָה וְיָדַע כַּמָּה נִפְלָאוֹת יוֹצְאִים מִן הַתּוֹרָה. פָּתַח וְאָמַר (תהלים קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ."],[2,"","בֹּא רְאֵה, וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יֹצֵאת. יֹצֵאת? בָּאָה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה יצֵאת? שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אוֹתָהּ מִכָּל אוֹתָם בְּנֵי הָעִיר, שֶׁכֻּלָּם רְשָׁעִים, וְהִיא יוֹצֵאת מֵהַכְּלָל שֶׁלָּהֶם. וַתֵּרֶד הָעַיְנָה כָּתוּב בְּהֵ\"א, סוֹד הוּא שֶׁפָּגְשָׁה שָׁם אֶת בְּאֵר מִרְיָם, וּמִשּׁוּם כָּךְ כָּתוּב הָעַיְנָה בְּהֵ\"א, וְעָלוּ לָהּ הַמַּיִם."],[3,"","דָּבָר אַחֵר וְהִנֵּה רִבְקָה יֹצֵאת, כַּכָּתוּב יֹצְאֹת לִשְׁאֹב מָיִם. לָמָּה יוֹצְאוֹת וְלֹא הוֹלְכוֹת וְלֹא בָאוֹת? אֶלָּא מִשּׁוּם שֶׁטְּמוּנוֹת הָיוּ כָּל הַיּוֹם, וּבְאוֹתָהּ שָׁעָה יוֹצְאוֹת לִשְׁאֹב מַיִם. וְסִימָן לָקַח בְּיָדוֹ."],[4,"","בֹּא רְאֵה, כְּשֶׁהִגִּיעַ הָעֶבֶד לְחָרָן וּמָצָא אֶת רִבְקָה לְעֵת עֶרֶב, הָיָה זְמַן תְּפִלַּת הַמִּנְחָה. בְּאוֹתָהּ שָׁעָה שֶׁהִגִּיעַ יִצְחָק לְהִתְפַּלֵּל תְּפִלַּת מִנְחָה, בְּאוֹתָהּ שָׁעָה הִגִּיעַ הָעֶבֶד אֶל רִבְקָה. וּבַשָּׁעָה הַהִיא שֶׁהִגִּיעַ יִצְחָק לִתְפִלַּת מִנְחָה כְּבַתְּחִלָּה, הִגִּיעָה רִבְקָה אֵלָיו, שֶׁהַכֹּל יִמָּצֵא בִּמְקוֹמוֹ שֶׁצָּרִיךְ כָּרָאוּי, וְהַכֹּל הִגִּיעַ בְּסוֹד הַחָכְמָה, וְעַל כֵּן בָּא הָעֶבֶד לִבְאֵר הַמַּיִם, סוֹד הַכָּתוּב (שיר ד) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנוֹזְלִים מִן לְבָנוֹן. וּבֵאַרְנוּהוּ, וְהַכֹּל הוּא סוֹד."],[5,"","רַבִּי שִׁמְעוֹן בָּא לִטְבֶרְיָה וְהָיָה עִמּוֹ רַבִּי אַבָּא. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אַבָּא, נֵלֵךְ, שֶׁהֲרֵי אָנוּ רָאִינוּ שֶׁאִישׁ אֶחָד יַגִּיעַ כָּעֵת אֵלֵינוּ וּדְבָרִים חֲדָשִׁים בְּפִיו, וְהֵם דִּבְרֵי תוֹרָה. אָמַר רַבִּי אַבָּא, הִנֵּה יָדַעְתִּי שֶׁבְּכָל מָקוֹם שֶׁמַּר הוֹלֵךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ לוֹ מַלְאָכִים טָסִים בִּכְנָפַיִם לְהִשְׁתַּעֲשֵׁעַ בּוֹ."],[6,"","בְּעוֹדָם הוֹלְכִים, הֵרִים רַבִּי שִׁמְעוֹן אֶת עֵינָיו, וְרָאָה אִישׁ שֶׁהָיָה רָץ וְהוֹלֵךְ. יָשְׁבוּ רַבִּי שִׁמְעוֹן וְרַבִּי אַבָּא. כְּשֶׁהִגִּיעַ אֲלֵיהֶם, אָמַר לוֹ רַבִּי שִׁמְעוֹן, מִי אַתָּה? אָמַר לוֹ, אֲנִי יְהוּדִי, וּבָאתִי מִקַּפּוֹטְקִיָּא, וַאֲנִי הָלַכְתִּי לְסִתְרוֹ (לאהל) שֶׁל בַּר יוֹחַאי, שֶׁנִּמְנוּ הַחֲבֵרִים בִּדְבָרִים יְדוּעִים וּשְׁלָחוּנִי אֵלָיו. אָמַר לוֹ, אֱמֹר בְּנִי. אָמַר לוֹ, אַתָּה בַּר יוֹחַאי? אָמַר לוֹ, אֲנִי בַּר יוֹחַאי."],[7,"","אָמַר לוֹ, הֲרֵי אָמַרְנוּ שֶׁלֹּא יַפְסִיק אָדָם בִּתְפִלָּתוֹ בֵּינוֹ לְבֵין הַכֹּתֶל, כַּכָּתוּב (ישעיה לח) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וְגוֹ'. וּמִי שֶׁמִּתְפַּלֵּל, אָסוּר לַעֲבֹר אַרְבַּע אַמּוֹת סָמוּךְ לוֹ, וּבֵאֲרוּ לְאַרְבַּע הָאַמּוֹת הַלָּלוּ לְכָל צַד, פְּרָט לְפָנָיו. וְאָמְרוּ שֶׁלֹּא יִתְפַּלֵּל אָדָם מֵאֲחוֹרֵי רַבּוֹ וְכוּ', וְנִמְנוּ בְּכָל הַדְּבָרִים הַלָּלוּ."],[8,"","פָּתַח וְאָמַר, (תהלים לט) שִׁמְעָה תְפִלָּתִי ה' וְשַׁוְעָתִי הַאֲזִינָה אֶל דִּמְעָתִי אַל תֶּחֱרַשׁ. מָה הַטַּעַם שִׁמְעָה וְלֹא שְׁמַע? בְּמָקוֹם אֶחָד כָּתוּב שְׁמַע ה' וְחָנֵּנִי וְגוֹ', וּבְמָקוֹם אַחֵר שִׁמְעָה. אֶלָּא בְּכָל מָקוֹם לִפְעָמִים שְׁמַע לְזָכָר, וְלִפְעָמִים שִׁמְעָה לִנְקֵבָה. שִׁמְעָה - כְּמוֹ שֶׁנֶּאֱמַר (שם יז) שִׁמְעָה ה' צֶדֶק וְגוֹ'. שְׁמַע - כְּמוֹ שֶׁנֶּאֱמַר (שם ל) שְׁמַע ה' וְחָנֵּנִי, (משלי א) שְׁמַע בְּנִי, (דברים כז) הַסְכֵּת וּשְׁמַע."],[9,"","וְכָאן שִׁמְעָה תְפִלָּתִי ה', מִשּׁוּם שֶׁזֶּה (שהיא) הַדַּרְגָּה שֶׁמְּקַבֶּלֶת כָּל הַתְּפִלּוֹת שֶׁל הָעוֹלָם. וַהֲרֵי שָׁנִינוּ שֶׁעוֹשֶׂה מֵהֶם עֲטָרָה וְשָׂם אוֹתָהּ בְּרֹאשׁ שֶׁל צַדִּיק חַי הָעוֹלָמִים, שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק, וְעַל כֵּן שִׁמְעָה תְפִלָּתִי ה'."],[10,"","שִׁמְעָה תְפִלָּתִי ה' - זוֹ תְפִלָּה שֶׁבְּלַחַשׁ. וְשַׁוְעָתִי הַאֲזִינָה - זוֹ תְפִלָּה שֶׁאָדָם מֵרִים קוֹלוֹ בְּצָרָתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמות ב) וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים. וּמַה זֶּה שַׁוְעָתָם? אֶלָּא שֶׁבִּתְפִלָּתוֹ מֵרִים קוֹלוֹ וְזוֹקֵף עֵינָיו לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כב) וְשׁוֹעַ אֶל הָהָר. וְהַתְּפִלָּה הַזּוֹ מְשַׁבֶּרֶת שְׁעָרִים וְדוֹפֶקֶת (ס\"א ודוחקת) אוֹתָם לְהַכְנִיס אֶת תְּפִלָּתוֹ. אֶל דִּמְעָתִי אַל תֶּחֱרַשׁ - זֹאת נִכְנֶסֶת לִפְנֵי הַמֶּלֶךְ וְאֵין שַׁעַר שֶׁעוֹמֵד לְפָנֶיהָ, וּלְעוֹלָם לֹא חָזְרוּ דְמָעוֹת רֵיקָם."]]],[["תוּ הָא כְּתִיב הָכָא תְּלַת דַּרְגִּין, תְפִלָּה. שַׁוְעָה. דִּמְעָה. לָקֳבֵיל אִלֵּין תְּלַת אָחֳרָנִין. כִּי גֵּר אָנֹכִי עִמָּךְ. לְבָתַר תּוֹשָׁב. לְבָתַר כְּכָל אֲבוֹתָי עִקְרָא דְעַלְמָא.","תָּא חֲזֵי, צְלוֹתָא דְבַר נָשׁ מְעוֹמֶד, בְּגִין דִּתְרֵי צְלוֹתָא נִינְהוּ חַד מִיוֹשֶּׁב וְחַד מְעוֹמֶד, וְאִינוּן חַד לָקֳבֵיל תְּרֵין דַּרְגִּין תְּפִלָּה שֶׁל יַד וּתְפִלָּה שֶׁל רֹאשׁ. לְגַבֵּי יוֹם וָלַיְלָה וְכֹלָּא חַד. אוּף הָכָא תְּפִלָּה מִיוֹשֶּׁב לְגַבֵּי תְּפִלָּה שֶׁל יַד, לְאַתְקִין לָהּ כְּמָה (ד\"א כמאן) דְאַתְקִין לְכַלָּה וְקָשִׁיט לָהּ לְאֲעָלָא לְחוּפָּה, הָכִי נָמֵי מְקַשְׁטִין לָהּ בְּרָזָא דִּרְתִיכָאָה וּמַשִּׁירְיָיהָא, יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ וְכוּ'.","וְעַל דָּא צְלוֹתָא מְיוּשָּׁב, כֵּיוָן דְעָאֳלַת לְגַבֵּי מַלְכָּא עִלָּאָה וְאִיהוּ אָתֵי לְקַבְּלָא לָהּ, כְּדֵין אֲנַן קָיְימִין קַמֵּי מַלְכָּא עִלָּאָה, דְּהָא כְּדֵין (דרגא) דְּכוּרָא אִתְחַבַּר בְּנוּקְבָא, וּבְגִין כָּךְ לָא יַפְסִיק בֵּין גְּאוּלָּה לִתְפִלָּה (וגאולה (שמות קנז א), ותפלה תרין דרגין אינון, רזא דצדיק וצדק יוס\"ף ורח\"ל).","וּבְגִין דְּבַר נָשׁ קָאִים קַמֵּי מַלְכָּא עִלָּאָה נָטַל אַרְבַּע אַמּוֹת לִצְלוֹתֵיהּ וְאוּקְמוּהָ דִּבְשִׁיעוּרָא (ד\"א בשיעורא) דְסוּרְטָא דְּיוֹצֵר כֹּלָּא. וְכָל מַה דְּאָתֵי בְּסִטְרָא דִדְכוּרָא בָּעֵי לֵיהּ לְאִינִישׁ לְמֵיקַם בְקִיּוּמֵיהּ וְאִזְדַּקַּף (ס\"א ויזדקף). כְּגַוְונָא דָא כַּד אִיהוּ כֹּרֵעַ, כֹּרֵעַ בְּבָרוּךְ, וְכַד אִיהוּ זָקִיף, זָקִיף בַּשֵּׁם, בְּגִין לְאַחֲזָאָה שְׁבָחָא דִדְכוּרָא עַל נוּקְבָא.","וְתָא חֲזֵי דְּהָא אוּקְמוּהָ לָא יִצְלֵי בַּר נָשׁ אֲחוֹרֵי רַבֵּיהּ וְאִתְּמָר כְּמָה דִכְתִיב, (דברים י׳:כ׳) אֶת יְיָ אֱלקֶיךָ תִּירָא. אֶת לְאַכְלָלָא דְּבָעֵי לְמִדְחַל מֵרַבֵּיהּ כְּמוֹרָא דִשְׁכִינְתָּא, וּדְחִילוּ דְתַלְמִיד, רַבֵּיהּ אִיהוּ. בְּגִין כָּךְ בְּשַׁעְתָּא דִצְלוֹתָא לָא יַשְׁוֵי הַהוּא מוֹרָא לְקַמֵּיהּ, (ד\"א ל\"ג לצלותא) אֶלָּא מוֹרָא דְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי וְלָא מוֹרָא אָחֳרָא.","וְתָא חֲזֵי צְלוֹתָא דְמִנְחָה אַתְקִין לֵיהּ יִצְחָק. וַדַּאי כְּמָה דְאַתְקִין אַבְרָהָם צְלוֹתָא דְצַפְרָא לָקֳבֵל הַהוּא דַרְגָא דְּאִתְדָּבַּק בֵּיהּ. וְכֵן (ד\"א כך) יִצְחָק אַתְקִין צְלוֹתָא דְמִנְחָה לָקֳבֵל הַהוּא דַרְגָּא דְאִתְדָּבַּק בֵּיהּ. וְעַל דָּא צְלוֹתָא דְמִנְחָה מְכִי נָטֵי שִׁמְשָׁא לְנַחֲתָא בְּדַרְגוֹי לִסְטַר מַעֲרָב.","דְּהָא עַד לָא נָטָה שִׁמְשָׁא לְצַד מַעֲרָב אִקְרֵי יוֹם מִצַּפְרָא עַד הַהוּא זִמְנָא דִּכְתִיב, (תהלים כב) חֶסֶד אֵל כָּל הַיּוֹם. וְאִי תֵימָא עַד חֲשֵׁכָה, תָּא חֲזֵי, דִּכְתִיב (ירמיהו ו׳:ד׳) אוֹי נָא לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. כִּי פָנָה הַיּוֹם לָקֳבֵל צְלוֹתָא דְצַפְרָא דִּכְתִיב חֶסֶד אֵל כָּל הַיּוֹם, דְּהָא כְּדֵין שִׁמְשָׁא אִיהוּ לִסְטַר מִזְרָח, כֵּיוָן דְּנָטָה שִׁמְשָׁא וְנָחֲתָא לִסְטַר מַעֲרָב, הָא כְּדֵין אִיהוּ זְמַן צְלוֹתָא דְמִנְחָה וּכְבָר פָּנָה הַיּוֹם וְאָתוּ צִלְלֵי עָרֶב וְאִתְעַר דִּינָא קַשְׁיָא בְּעָלְמָא.","וּפָנָה הַיּוֹם דְּאִיהוּ דַרְגָּא דְּחֶסֶ\"ד, וְנָטוּ צִלְלֵי עָרֶב דְּאִינוּן דַּרְגָּא דְּדִינָא קַשְׁיָא, וּכְדֵין אִתְחָרַב בֵּי מַקְדְּשָׁא וְאִתּוֹקַד הֵיכָלָא. וְעַל דָּא תָּנִינָן דִּיהֵא בַר נָשׁ זָהִיר בִּצְלוֹתָא דְמִנְחָה דְּאִיהוּ זִמְנָא דְדִינָא קַשְׁיָא שַׁרְיָיא בְּעָלְמָא.","יַעֲקֹב אַתְקִין צְלוֹתָא דְעַרְבִית דְּהָא אִיהוּ אַתְקִין לָהּ וְזָן לָהּ בְּכָל מַה דְּאִצְטְרִיךְ, וַדַּאי וא\"ו אַתְקִין לְה\"א, וְה\"א אִתְּזָנַת מִן וא\"ו דְּלֵית לָהּ נְהוֹרָא מִגַּרְמָהּ כְּלָל.","וּבְגִין כָּךְ תְּפִלַּת עַרְבִית רְשׁוּת דְּהָא אִתְכְּלִילַת בִּצְלוֹתָא דְיוֹמָא בְּגִין לְאִתְנַהֲרָא, וְהַשְׁתָּא לָאו זִמְנָא אִיהוּ. וְאוֹקִימְנָא לָהּ דְּהָא לָא אִתְגַּלְיָא נְהוֹרָא דִּימָמָא דְּיַנְהִיר לָהּ, וְאִיהִי שָׁלְטָא בַּחֲשׁוֹכָא עַד זִמְנָא דְּפַלְגוּת לֵילְיָא דְּאִשְׁתַּעְשַׁע קוּדְשָׁא בְּרִיךְ הוּא עִם צַדִּיקַיָא בְּגִנְתָא דְעֵדֶן, וּכְדֵין אִיהוּ זִמְנָא לְאִשְׁתַּעְשְׁעָא בַּר נָשׁ (ס\"א ולמלעי) בְּאוֹרַיְיתָא כְּמָה דְאִתְּמָר.","תָּא חֲזֵי, דָּוִד אֲתָא וְאָמַר אִלֵּין תְּלַת זִמְנִין דִּצְלוֹתֵי דִּכְתִיב, (תהילים נ״ה:י״ח) עֶרֶב וָבֹקֶר וְצָהֳרָיִם הָא תְּלָתָא, וְאִיהוּ לָא צַלֵּי אֶלָּא תְּרֵי מִנַּיְיהוּ, דִּכְתִיב אָשִׂיחָה וְאֶהֱמֶה, וְלָא יַתִּיר. דָּא לִצְלוֹתָא דְצַפְרָא וְדָא לִצְלוֹתָא דְמִנְחָה, בְּגִין כָּךְ אָשִׂיחָה וְאֶהמֶה דַיְיקָא. בְּצַפְרָא דְּאִיהוּ שַׁעְתָּא דְּחֶסֶד סַגֵּי לֵיהּ בְּחֶסֶד בְּאָשִׂיחָה, וּבְמִנְחָה דְּהוּא שַׁעְתָּא דְדִינָא קַשְׁיָא בָּעֵי הֲמָיָיה וּבְגִין כָּךְ וְאֶהמֶה. וּלְבָתַר כַּד אִתְפְּלִיג לֵילְיָא הֲוָה קָם בְּשִׁירִין וְתוּשְׁבְּחָן כְּדְקָא יָאוֹת דִּכְתִיב, (תהלים ס\"ב) וּבַלַּיְלָה שִׁירֹה עִמִּי וְהָא אִתְּמָר."],[[0,"תו, הא כתיב הכא וכו':","עוד, כי כתוב כאן ג' מדרגות שהם: תפלה, שועה, דמעה, דהיינו שכתוב, שמעה \u0003תפלתי\u0004 ה', \u0003ושועתי\u0004 האזינה אל \u0003דמעתי\u0004 אל תחרש. וכנגד אלו, מסיים הכתוב, ג' מדרגות אחרות, כי \u0003גר\u0004 אנכי עמך, ואחר כך אומר, \u0003תושב\u0004 ואח\"כ אומר, \u0003ככל אבותי,\u0004 שהם עיקר העולם. \u0003וגר,\u0004 הוא כנגד \u0003תפלה. ותושב,\u0004 הוא כנגד \u0003שועה. וככל אבותי,\u0004 הוא כנגד \u0003דמעה.\u0004 פירוש, כי תפלה באה על דינים דמין הא' הנ\"ל, שה\"ס חכמה בלי חסדים, וכיון שהתחתונים עיקר בנינם הוא מחסדים (כנ\"ל ב\"א דף מ\"ה ד\"ה כד) לפיכך בעת שמאירה החכמה בלי חסדים, הם נמצאים כמו גר בארץ נכריה, כי להיות עיקר בנינם מחסדים, מרגישים את חסרון החסדים כמו שהיו אז בארץ נכריה. ועל כן נאמר, כי גר, אנכי עמך, כנגד מדרגת תפלה."],[0,"ושועה,","באה על דינים דמין הב', שעל ידם מתתקן המסך דחירק ונמשכת קומת חסדים כנ\"ל, ואז נפסק הגירות, ומרגישים עצמם כמו \u0003תושב\u0004 בארצו מחמת שהשיגו החסדים. ועל כן \u0003תושב\u0004 הוא כנגד \u0003שועה ודמעה\u0004 באה על דינים דמין הג', שעל ידה מתתקן על בחינת מלכות ממותקת ברחמים ונעשית המלכות מוכשרה לקבל ולהשפיע המוחין דחב\"ד אל התחתונים, מסוד החג\"ת שנעשו לחב\"ד, הנקראים \u0003אבות\u0004 העולם, ועל כן \u0003ככל אבותי\u0004 הוא כנגד \u0003דמעה.\u0004"],[1,"תא חזי צלותא וכו':","בוא וראה, תפלתו של האדם הוא מעומד, כי שני מיני תפלות הן, אחת היא מיושב ואחת היא מעומד, והם אחד, להיותם כנגד שתי מדרגות שהן תפלה של יד ותפלה של ראש, או יום ולילה, והם אחד. היינו כנגד מדרגת ז\"א המכונה תפלה של ראש או יום, וכנגד מדרגת הנוקבא המכונה תפלה של יד או לילה, והם אחד בזווג, אף כאן, תפלה מיושב דהיינו התפלה דיוצר שלפני השמנה עשרה, הוא אל התפלה של יד, דהיינו אל הנוקבא, לתקן אותה, כמו שמתקנים את הכלה ומקשטים אותה להכניסה לחופה, כן מקשטים את הנוקבא, בסוד המרכבות והמחנות המרומזים בהמלות יוצר משרתים ואשר משרתיו עומדים וכו', והאופנים וחיות הקדש וכו' ששבחים אלו, הם לקשט את הנוקבא, דהיינו להמשיך לה ג\"ר משמאל ולהביאה לזווג בשמנה עשרה."],[2,"ועל דא צלותא וכו':","ועל כן תפלה דמיושב, שהיא הנוקבא בקישוטיה, כנ\"ל, כיון שנכנסה אל מלך העליון, שהוא ז\"א, דהיינו בתפלת שמנה עשרה, והוא בא לקבל אותה, אז אנחנו עומדים לפני מלך העליון, כי אז ז\"א מתחבר בהנוקבא. ומשום זה לא יפסיק בין גאולה ותפלה. כי תפלה דמיושב ותפלה דמעומד צריכים להיות מחוברות, כמבואר. ובזה ביאר המימרא, \u0003דלא יפסיק בר נש בצלותיה ביניה לבין כותלא,\u0004 כי תפלה דמיושב, ה\"ס השכינה, הנקראת כותלא או קיר בעת שמאירה בג\"ר דשמאל, מטעם שמחסרון חסדים היא נקפאת אז (כנ\"ל ב\"א דף רמ\"ז ד\"ה פירוש) ונעשית ככותל. וע\"כ אסור להפסיק, אלא לחברה עם החסדים של ז\"א."],[3,"ובגין דבר נש וכו':","ומשום, שהאדם עומד לפני מלך העליון הוא לוקח ארבע אמות לתפלתו ובארוה, שהוא בשיעור חבל של יוצר כל. סורטא, פירושו חבל, כמו לא יקשור סרט של צמר בשל פשתן (כלאים ט') וז\"א, מכונה יוצר כל, להיותו בחינת יצירה דאצילות. ושיעור חבל שלו דהיינו ושיעור מדתו, הוא ארבע אמות הרומזים על ד' המוחין חו\"ב תו\"מ, ואדם המתפלל תפלת שמונה עשרה, צריך שיהיה אז מרכבה ליוצר כל, וימשיך סוד ד' אמות חו\"ב תו\"מ ולהשפיע אל השכינה. וז\"ש \u0003ובגין דבר נש קאים קמי מלכא עלאה,\u0004 היינו שנעשה מרכבה אליו, \u0003נטל ארבע אמות,\u0004 דהיינו ד' המוחין חו\"ב תו\"מ, \u0003לצלותיה,\u0004 שהיא הנוקבא הנקראת צלותא."],[3,"","ומ\"ש לעיל (באות רכ\"ט) \u0003ואוקמוה להני ארבע אמות לכל סטר בר לקמיה,\u0004 רמז בזה, כי אלו ד' המוחין חו\"ב תו\"מ נכללים זה בזה, ויש בכל אחד מהם חו\"ב תו\"מ, ועם זה, אינם אז ט\"ז מוחין, אלא רק י\"ב מוחין, דהיינו ג' מכל צד, חוץ מלפניו, והוא משום חסרון המלכות דמלכות, שהוא עצמות המלכות וע\"כ חסרים ד' המוחין שמלפניו. (כנ\"ל ב\"א דף פ\"ה ד\"ה ויש ע\"ש) ואין לשאול שלפי זה היו צריכים להיות חסרים ד' המוחין שמלאחריו, שהם בחינת מלכות, כי יש ערך הפכי בין האורות והכלים (כנ\"ל בהקדמת הזהר דף כ\"א ד\"ה ואין)."],[3,"וכל מה דאתי בסטרא וכו':","וכל שהוא מצד הזכר, צריך אדם לעמוד על עמדו בקומה זקופה. כעין זה אמרו, כל הכורע כורע בברוך, שה\"ס הנוקבא, וכל הזוקף זוקף בשם, שה\"ס דכר. כדי להראות שבחו של הדכר על הנוקבא. פירוש קומה זקופה יורה ג\"ר המאירים ממעלה למטה. וזהו רק בדכר שה\"ס חסדים מכוסים, אבל בהנוקבא שה\"ס חסדים מגולים, הנה החכמה שלה אינה מאירה רק ממטה למעלה שה\"ס ו\"ק דג\"ר, וע\"כ אינה בבחינת קומה זקופה אלא בכריעה. וז\"ש שע\"כ צריכים לכרוע בברוך ולזקוף בשם, כדי להראות שבחו של הדכר על הנוקבא, אשר המוחין דדכר מאירים מלמעלה למטה."],[4,"ות\"ח, דהא אוקמוה וכו':","ובוא וראה כי ביארו, שלא יתפלל אדם אחורי רבו. ואמרו, שכתוב את ה' אלקיך תירא, \u0003את,\u0004 הוא לרבות ולכלול שצריך לירא מרבו כמורא השכינה, ויראת התלמיד הוא רבו. ולפיכך בעת התפלה לא ישום לפניו אותה המורא, אלא מורא מהקב\"ה בלבדו, ולא מורא מדבר אחר. פירוש. כי המלכות, נקראת מורא שמים, דהיינו מלכות של הקב\"ה שנקרא שמים, שה\"ס מלכות הממותקת במדת הבינה שה\"ס רחמים. ואם יש לאדם מורא מפני דבר אחר חוץ מהקב\"ה, הוא מעורר עליו מלכות דמדת הדין הבלתי ממותקת בבינה. וז\"ס שאסור להתפלל אחורי רבו, כי להיות מורא רבו כמורא שמים, לא יוכל להזהר שיהיה בבחינת מורא שמים בלבד, ויש חשש שלא יתעורר עליו המלכות דמדת הדין. ואז יהיה דבר מפסיק בינו לבין הקיר, אשר הקיר, שה\"ס המלכות לא תהיה ראויה לקבל המוחין."],[5,"ות\"ח, צלותא דמנחה וכו':","ובוא וראה, תפלת המנחה תקן יצחק. כמו שתקן אברהם תפלת שחרית כלפי אותה המדרגה שהיה דבוק בה, דהיינו מדרגת החסד וקו ימין, כך יצחק תקן תפלת המנחה כלפי אותה המדרגה שנתדבק בה, שהיא מדרגת הגבורה וקו שמאל. ועל כן, תפלת המנחה, זמנה הוא, כשנוטה השמש לירד במדרגותיה לצד מערב, דהיינו תכף אחר חצות היום."],[6,"דהא עד דא נטה וכו'.","כי כל עוד שהשמש אינה נוטה לצד מערב, הוא יום, דהיינו מבקר עד הצהרים, שכתוב עליו חסד אל כל היום. ואם תאמר שעד חשכה נקרא יום. בא וראה כי כתוב, אוי נא לנו כי פנה היום כי ינטו צללי ערב. כי פנה היום הוא כנגד תפלת שחרית, שכתוב עליו חסד אל כל היום, כי אז השמש היא לצד מזרח. כיון שהשמש נוטה ויורדת לצד מערב, הרי אז זמן תפלת המנחה, כי כבר פנה היום, וינטו צללי ערב, ונתעורר דין קשה בעולם."],[7,"ופנה היום:","שהוא מדרגת החסד, \u0003ונטו צללי ערב,\u0004 שהם מדרגות הדין הקשה. ואז נחרב בית המקדש, ונשרף ההיכל. ועל כן למדנו, שהאדם יהיה נזהר בתפלת המנחה, כי הוא זמן שדין קשה שורה בעולם."],[8,"יעקב אתקין וכו':","יעקב תקן תפלת ערבית, כי הוא מתקן אותה, דהיינו הנוקבא, וזן אותה בכל מה שהיא צריכה, כי הו' דהויה שהוא ת\"ת והוא יעקב, מתקן את הה' דהויה, שהיא הנוקבא, וה \u0003ה'\u0004 נזונת מן ה \u0003ו'\u0004 כי אין לה לנוקבא מעצמה כלום, אלא שמקבלת הכל מת\"ת, שהיא \u0003ו'\u0004 מהויה, ומכונה יעקב. פירוש. כי יעקב ה\"ס קו אמצעי הממשיך קומת החסדים על המסך דחירק ומכריע ומיחד ב' הקוין ימין ושמאל, שהם אברהם ויצחק, זה בזה, (כנ\"ל ב\"א דף קל\"א ד\"ה תליתאה ע\"ש) ואחר דין הקשה שבא בהארת שמאל דיצחק, בא יעקב ומתקן את המסך דחירק, שתיקון זה ה\"ס \u0003תפלת ערבית.\u0004 וכבר נתבאר (לעיל דף ע\"ב ד\"ה וז\"ש) שתיקון הראשון ה\"ס המסך על המלכות מטרם שנמתקת ברחמים, בסוד התפלה הנקראת \u0003שועה,\u0004 וה\"ס התיקון דתפלת ערבית (ועי' לעיל ב\"א דף קס\"ח ד\"ה מאן. בביאור תפלת ערבית רשות) ואחר זה בא תקון ב' בסוד \u0003דמעה,\u0004 שה\"ס המסך על המלכות הממותקת במדת הרחמים, וה\"ס חצות לילה כמ\"ש לפנינו."],[9,"ובגין כך וכו':","ומשום זה תפלת ערבית רשות. כי היא נכללת בתפלת היום, כדי שתהיה מאירה, כלומר, שאז נעשה זווג על המסך הזה המוציא קומת החסדים שה\"ס יום, ועתה בלילה אין הזמן לזה, וביארנו זה, אשר אין אור היום, שה\"ס חסדים, נגלה עתה להאיר אל הנוקבא, והיא שולטת בחשכה עד הזמן דחצות לילה, שאז הקב\"ה משתעשע עם הצדיקים בגן עדן, ואז הוא הזמן, שאדם ישתעשע בתורה כמו שאמרו."],[10,"תא חזי דוד וכו':","בוא וראה דוד בא ואמר, אלו ג' זמני תפלה, שכתוב ערב ובקר וצהרים, אשיחה ואהמה וישמע קולי, הרי שלשה, והוא לא התפלל אלא שנים מהם, שכתוב אשיחה ואהמה ולא יותר. זה לתפלת הבוקר וזה לתפלת המנחה. וע\"כ אמר אשיחה ואהמה, כי דוקא בבוקר. שהוא זמן החסד, מספיק \u0003אשיחה\u0004 שהוא חסד. ובמנחה שהוא זמן של דין קשה צריכים המיה, ומשום זה אמר ואהמה. אבל תפלת ערבית לא התפלל."],[10,"ולבתר כד אתפליג וכו':","ואחרי כן כשנתחלק הלילה, היה קם ואמר שירות ותשבחות, שכתוב ובלילה שירה עמי, והוא נתבאר. פירוש, כי דוד ה\"ס המלכות, וסוד חצות לילה הוא, אחר שנתמתקה המלכות בבינה, שאז ה\"ס \u0003דמעה\u0004 כמ\"ש לעיל, שאז נעשתה המלכות בית קבול לאורות העליונים כולם, וע\"כ קם אז בשירות ותשבחות. באופן, שתפלת שחרית היא כנגד \u0003תפלה,\u0004 לתקון קו ימין שבנוקבא. וה\"ס \u0003ובגין דבר נש קאים קמי מלכא עלאה נטל ד' אמות לצלותיה.\u0004 שהם מקובלים בתפלת שחרית. ותפלת המנחה הוא ג\"כ כנגד \u0003תפלה\u0004 אלא לתקון קו שמאל שבה שנקראת מבחינה זו כותל או קיר כנ\"ל. ואז צריך האדם להמשיך השלמות של הקיר, דהיינו \u0003דלא יפסיק בר נש בצלותיה ביניה לבין כותלא,\u0004 כלומר שלא יהיה ביניהם חציצה ופגם. ותפלת ערבית ה\"ס \u0003שועה,\u0004 וע\"כ הוא רשות כנ\"ל. וחצות לילה ה\"ס \u0003דמעה.\u0004 דהיינו התקונים של מלכות הממותקת שתהיה בית קבול לאורות העליונים ומשום תקון זה שיהיה בשלמות \u0003לא יצלי בר נש אחורי רביה,\u0004 כדי שלא יחזור ויעורר את המלכות הבלתי ממותקת כנ\"ל. ויקלקל ח\"ו התקון דחצות לילה."]],[[0,"","עוֹד, הִנֵּה כָּתוּב כָּאן שָׁלֹשׁ דְּרָגוֹת: תְּפִלָּה, שַׁוְעָה, דִּמְעָה. כְּנֶגֶד אֵלּוּ שָׁלֹשׁ אֲחֵרִים: כִּי גֵר אָנֹכִי עִמָּךְ, אַחַר כָּךְ תּוֹשָׁב, אַחַר כָּךְ כְּכָל אֲבוֹתָי, עִקַּר הָעוֹלָם."],[1,"","בֹּא רְאֵה, תְּפִלָּה שֶׁל אָדָם מֵעֹמֶד, מִשּׁוּם שֶׁשְּׁתֵּי תְפִלּוֹת הֵן - אַחַת מִיֹּשֶׁב וְאַחַת מֵעֹמֶד, וְהֵן אַחַת כְּנֶגֶד שְׁתֵּי דְרָגוֹת - תְּפִלָּה שֶׁל יָד וּתְפִלָּה שֶׁל רֹאשׁ. כְּלַפֵּי יוֹם וָלַיְלָה, וְהַכֹּל אֶחָד. אַף כָּאן תְּפִלָּה מִיֹּשֶׁב כְּלַפֵּי תְפִלָּה שֶׁל יָד, לְתַקֵּן אוֹתָהּ כְּמוֹ (כמי) שֶׁמְּתַקֵּן אֶת הַכַּלָּה וּמְקַשֵּׁט אוֹתָהּ לְהַכְנִיסָהּ לַחֻפָּה, כָּךְ גַּם מְקַשְּׁטִים אוֹתָהּ בְּסוֹד הַמֶּרְכָּבָה וּמַחֲנוֹתֶיהָ, יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ וְכוּ'."],[2,"","וְעַל זֶה תְּפִלָּה מִיֹּשֶׁב. כֵּיוָן שֶׁנִּכְנֶסֶת לַמֶּלֶךְ הָעֶלְיוֹן וְהוּא בָּא לְקַבֵּל אוֹתָהּ, אָז אָנוּ עוֹמְדִים לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁהֲרֵי אָז (הדרגה) הַזָּכָר מִתְחַבֵּר עִם הַנְּקֵבָה, וּמִשּׁוּם כָּךְ לֹא יַפְסִיק בֵּין גְּאֻלָּה לִתְפִלָּה (וגאלה ותפלה הן שתי דרגות, הסוד של צדיק וצדק, יוסף ורחל)."],[3,"","וּמִשּׁוּם שֶׁאָדָם עוֹמֵד לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, נוֹטֵל אַרְבַּע אַמּוֹת לִתְפִלָּתוֹ, וֶהֱקִימוּהַ שֶׁבְּשִׁעוּר (ד\"א בשעור) הַסֶּרֶט חֶבֶל שֶׁל יוֹצֵר כֹּל. וְכָל מַה שֶּׁבָּא בְּצַד הַזָּכָר, צָרִיךְ לְאָדָם לַעֲמֹד בְּקִיּוּמוֹ וּמִזְדַּקֵּף (ס\"א ויזדקף). כְּמוֹ כֵן כְּשֶׁהוּא כּוֹרֵעַ, כּוֹרֵעַ בְּבָרוּךְ. וּכְשֶׁהוּא זוֹקֵף, זוֹקֵף בַּשֵּׁם, כְּדֵי לְהַרְאוֹת אֶת שֶׁבַח הַזָּכָר עַל הַנְּקֵבָה."],[4,"","וּבֹא וּרְאֵה, שֶׁהֲרֵי אָמַרְנוּ אַל יִתְפַּלֵּל אָדָם אֲחוֹרֵי רַבּוֹ, וְנִתְבָּאֵר, כַּכָּתוּב (דברים י) אֶת ה' אֱלֹהֶיךְ תִּירָא. אֶת - לִכְלֹל שֶׁצָּרִיךְ לִירָא מֵרַבּוֹ כְּמוֹרָא הַשְּׁכִינָה, וְיִרְאַת תַּלְמִיד הוּא רַבּוֹ. מִשּׁוּם כָּךְ בִּשְׁעַת הַתְּפִלָּה לֹא יָשִׂים אוֹתוֹ הַמּוֹרָא לְפָנָיו (ד\"א לתפלה), אֶלָּא אֶת מוֹרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְלֹא מוֹרָא אַחֵר."],[5,"","וּבֹא וּרְאֵה, אֶת תְּפִלַּת מִנְחָה תִּקֵּן יִצְחָק, וַדַּאי כְּמוֹ שֶׁתִּקֵּן אַבְרָהָם תְּפִלַּת הַבֹּקֶר כְּנֶגֶד אוֹתָהּ הַדַּרְגָּה שֶׁנִּדְבַּק בָּהּ. וְכֵן (כך) יִצְחָק תִּקֵּן תְּפִלַּת מִנְחָה כְּנֶגֶד אוֹתָהּ דַּרְגָּה שֶׁנִּדְבַּק בָּהּ. וְעַל כֵּן תְּפִלַּת מִנְחָה מִכַּאֲשֶׁר נוֹטָה הַשֶּׁמֶשׁ לָרֶדֶת בְּדַרְגָּתוֹ לְצַד מַעֲרָב."],[6,"","שֶׁהֲרֵי בְּטֶרֶם נָטָה הַשֶּׁמֶשׁ לְצַד מַעֲרָב, נִקְרָא יוֹם מִן הַבֹּקֶר עַד הַזְּמַן הַהוּא, שֶׁכָּתוּב (תהלים כב) חֶסֶד אֵל כָּל הַיּוֹם. וְאִם תֹּאמַר עַד חֲשֵׁכָה - בֹּא רְאֵה, שֶׁכָּתוּב (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. כִּי פָנָה הַיּוֹם - כְּנֶגֶד תְּפִלַּת הַבֹּקֶר, שֶׁכָּתוּב חֶסֶד אֵל כָּל הַיּוֹם, שֶׁהֲרֵי אָז הַשֶּׁמֶשׁ הִיא לְצַד מִזְרָח. כֵּיוָן שֶׁנָּטָה הַשֶּׁמֶשׁ וְיָרַד לְצַד מַעֲרָב, הֲרֵי אָז הוּא זְמַן תְּפִלַּת הַמִּנְחָה, וּכְבָר פָּנָה הַיּוֹם וּבָאוּ צִלְלֵי עֶרֶב וְהִתְעוֹרֵר הַדִּין הַקָּשֶׁה בָּעוֹלָם."],[7,"","וּפָנָה הַיּוֹם שֶׁהִיא הַדַּרְגָּה שֶׁל חֶסֶד, וְנָטוּ צִלְלֵי עֶרֶב שֶׁהֵם הַדַּרְגָּה שֶׁל הַדִּין הַקָּשֶׁה, וְאָז נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְנִשְׂרַף הַהֵיכָל. וְעַל כֵּן שָׁנִינוּ שֶׁיִּהְיֶה אָדָם זָהִיר בִּתְפִלַּת הַמִּנְחָה, שֶׁהוּא הַזְּמַן שֶׁשָּׁרוּי הַדִּין הַקָּשֶׁה בָּעוֹלָם."],[8,"","יַעֲקֹב תִּקֵּן תְּפִלַּת עַרְבִית, שֶׁהֲרֵי הוּא תִּקֵּן אוֹתָהּ וְזָן אוֹתָהּ בְּכָל מַה שֶּׁצָּרִיךְ, וַדַּאי שֶׁוָּא\"ו תִּקֵּן אֶת הֵ\"א, וְהֵ\"א נִזּוֹנֵית מִוָּא\"ו, שֶׁאֵין לָהּ אוֹר מִשֶּׁל עַצְמָהּ כְּלָל."],[9,"","וּמִשּׁוּם כָּךְ תְּפִלַּת עַרְבִית רְשׁוּת, שֶׁהֲרֵי נִכְלֶלֶת בִּתְפִלַּת הַיּוֹם כְּדֵי שֶׁתִּהְיֶה מְאִירָה, וְכָעֵת לֹא זֶה הַזְּמַן. וּבֵאַרְנוּ אוֹתָהּ, שֶׁהֲרֵי לֹא הִתְגַּלָּה אוֹר הַיּוֹם שֶׁיָּאִיר לָהּ, וְהִיא שׁוֹלֶטֶת בַּחֲשֵׁכָה עַד זְמַן חֲצוֹת הַלַּיְלָה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן הָעֵדֶן, וְאָז הַזְּמַן שֶׁהָאָדָם יִשְׁתַּעֲשַׁע (וללמד) בַּתּוֹרָה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[10,"","בֹּא רְאֵה, דָּוִד בָּא וְאָמַר שְׁלֹשֶׁת זְמַנֵּי הַתְּפִלּוֹת הַלָּלוּ, שֶׁכָּתוּב (תהלים נה) עֶרֶב וָבקֶר וְצָהֳרַיִם, הִנֵּה שְׁלֹשָׁה. וְהוּא לֹא הִתְפַּלֵּל אֶלָּא שְׁנַיִם מֵהֶם, שֶׁכָּתוּב אָשִׂיחָה וְאֶהֱמֶה, וְלֹא יוֹתֵר. זֶה לִתְפִלַּת הַבֹּקֶר - וְזֶה לִתְפִלַּת הַמִּנְחָה. מִשּׁוּם כָּךְ דִּיֵּק אָשִׂיחָה וְאֶהֱמֶה. בַּבֹּקֶר, שֶׁהִיא שְׁעַת הַחֶסֶד, מַסְפִּיק לוֹ בְּחֶסֶד בְּאָשִׂיחָה. וּבְמִנְחָה, שֶׁהִיא שְׁעַת הַדִּין הַקָּשֶׁה, צָרִיךְ הֶמְיָה, וּמִשּׁוּם כָּךְ וְאֶהֱמֶה. אַחַר כָּךְ כְּשֶׁנֶּחְלָק הַלַּיְלָה, הָיָה קָם לְשִׁירוֹת וְתִשְׁבָּחוֹת כָּרָאוּי, שֶׁכָּתוּב (תהלים סב) וּבַלַּיְלָה שִׁירֹה עִמִּי, וַהֲרֵי נִתְבָּאֵר."]]],[["קָם רַבִּי שִׁמְעוֹן וְאֲזְלוּ. אֲזַל הַהוּא בַר נָשׁ בַּהֲדֵיהּ עַד טְבֶרְיָה. עַד דְּהֲווּ אָזְלוּ, אָמַר רִבִּי שִׁמְעוֹן תָּא חֲזֵי, תְּפִלּוֹת כְּנֶגֶד תְּמִידִין תִּקְנוּם רַבָּנָן דְּאַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, בְּגִין דְּאַשְׁכְּחָן תְּרֵי דִּכְתִיב, (במדבר כ״ח:ד׳) אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַּבֹּקֶר וְאֶת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם. וְאִינוּן מִתְקָרְבִין בְּהַנֵּי תְּרֵי זִמְנֵי דְיוֹמָא דְּאִינוּן זִמְנִין לִצְלוֹתָא.","אָמַר הַהוּא גַבְרָא הָא בְּקַדְמִיתָא אָבוֹת תִּקְנוּם לְהַנִּי צְלוֹתֵי, וּמַה דְּאַתְקִינוּ אַבְרָהָם וְיִצְחָק הוּא עִקְרָא, וּמַה דְּאַתְקִין יַעֲקֹב דְּאִיהוּ שְׁבָחָא דְּאֲבָהָן אַמַּאי אִיהוּ רְשׁוּת וְלָא עִקְּרָא כְּהַנֵּי.","אָמַר רִבִּי שִׁמְעוֹן הָא (רכט ב) אִתְּמָר. אֲבָל תָּא חֲזֵי, הַנִּי תְּרֵי זִמְנֵי דִּתְרֵי צְלוֹתֵי לָאו אִינוּן אֶלָּא לְחַבְּרָא לְיַעֲקֹב בְּעַדְבֵיהּ, כֵּיוָן דְּאִתְחַבָּרוּ דָּא בְּדָא אֲנַן לָא צְרִיכִין יַתִּיר, דְּכֵיוָן דְּאִתְיְהִיבַת אִתְּתָא בֵּין תְּרֵין דְּרוֹעִין וְאִתְחַבָּרַת בְּגוּפָא לָא אִצְטְרִיךְ יַתִּיר, וְעַל דָּא אֲנַן בָּעִינָן לְאִתְעָרָא תְּרֵין דְּרוֹעִין בְּגִין דְּאִתְיְהִיבַת בֵּינַיְיהוּ, כֵּיוָן דְּאִיהִי בֵּינַיְיהוּ, גּוּפָא וְאִתְּתָא מִלַּיְיהוּ בִּלְחִישׁוּ דְּלָא לְאַדְכָּרָא.","וּבְגִין כָּךְ יַעֲקֹב מְשַׁמֵּשׁ בַּמָּרוֹם תָּנִינָן. מַאי בַּמָּרוֹם כְּמָה דְאַתְּ אָמֵר, (תהילים צ״ב:ט׳) וְאַתָּה מָרוֹם לְעוֹלָם יְיָ. וְכֹלָּא אִיהוּ רָזָא לְיָדְעֵי מִדִּין. אָתוּ רִבִּי אַבָּא וְהַהוּא יוּדָאי וּנְשָׁקוּ יְדוֹי. אָמַר רִבִּי אַבָּא עַד יוֹמָא דֵין לָא קָאִימְנָא בְּמִלָּה דָא בַּר הַשְׁתָּא. זַכָּאָה חוּלָקִי דְּזָכִינָא לְמִשְׁמַע לֵיהּ:","וַיְבִיאֶהָ יִצְחָק הָאֹהלָה שָׂרָה אִמּוֹ. אָמַר רַבִּי יוֹסֵי הַאי קְרָא קַשְׁיָא. הָאֹהלָה. לְאֹהֶל שָׂרָה אִמּוֹ מִבָּעֵי לֵיהּ, מַאי הָאֹהֱלָה. דַּאֲהַדְּרַת תַּמָּן שְׁכִינְתָּא, בְּגִין דְּכָל זִמְנָא דְשָׂרָה קָיְימָא בְּעָלְמָא שְׁכִינְתָּא לָא אַעֲדֵי מִינָהּ, וּשְׁרַגָּא הֲוָה דְלִיקַת מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת וְהֲוָה נָהִיר כָּל אִינוּן יוֹמֵי דְשַׁבַּתָּא, בָּתַר דְּמִיתַת, כָּבְתָה הַהִיא שְׁרַגָּא. כֵּיוָן דְּאָתַת רִבְקָה אֲהַדָּרַת שְׁכִינְתָּא וּשְׁרַגָּא אַדְלִיקַת. שָׂרָה אִמּוֹ, דְּדַמְיָא לְשָׂרָה בְּכָל עוֹבָדָהָא.","רִבִּי יְהוּדָה אָמַר כְּמָה דְּדִיוּקְנֵיהּ דְּיִצְחָק הֲוָה כְּדִיוּקְנִיהּ דְּאַבְרָהָם, וְכָל מַאן דְּחָמֵי לְיִצְחָק אָמַר דָּא אַבְרָהָם, וַודַּאי אַבְרָהָם הוֹלִיד אֶת יִצְחָק, הָכִי נָמֵי רִבְקָה דִּיוּקְּנָהּ מַמָּשׁ הֲוַת דִּיוּקְנָא דְשָׂרָה, וּבְגִין כָּךְ שָׂרָה אִמּוֹ וַדַּאי.","אָמַר רִבִּי אֶלְעָזָר בְּכֹלָּא הָכִי הוּא, אֲבָל תָּא חֲזֵי, רָזָא אִיהוּ דְּאַף עַל גַּב דְּשָׂרָה מִיתַת, דְּיוּקְנָה לָא אַעֲדֵי מִן בֵּיתָא, וְלָא אִתְחֲזֵי תַּמָּן מִיּוֹמָא דְמִיתַת עַד דְּאֲתַת רִבְקָה, כֵּיוָן דְּעָאֳלַת רִבְקָה אִתְחֲזִיאַת דִּיוּקְנָא דְשָׂרָה, דִּכְתִיב וַיְבִיאֶהָ יִצְחָק הָאֹהלָה וְגו' מִיָּד שָׂרָה אִמּוֹ אִתְחֲזִיאַת תַּמָּן, וְלָא הֲוָה חָמֵי לָהּ בַּר יִצְחָק בִּלְחוֹדוֹי כַּד אָעִיל תַּמָּן, וְעַל דָּא וַיִּנָּחֶם יִצְחָק אַחֲרֵי אִמּוֹ (ס\"א מאי אחרי אמו, אחרי) דְּאִמּוֹ אִתְחֲזִיאַת וְאִזְדַּמְּנָא בְּבֵיתָא, וְעַל דָּא לָא כְּתִיב אַחֲרֵי מִיתַת אִמּוֹ, אֶלָּא אַחֲרֵי אִמּוֹ.","רִבִּי שִׁמְעוֹן אָמַר מַאי שְׁנָא דִכְתִיב בֵּיהּ בְּיִצְחָק וַיִּקַּח אֶת רִבְקָה וַתְּהִי לוֹ לְאִשָּׁה וַיֶּאֱהָבֶהָ. כֵּיוָן דְּאָמַר וַתְּהִי לוֹ לְאִשָּׁה לָא יְדַעְנָא דְּהוּא רָחִים לָהּ, דְּהָא כָּל בְּנִי עַלְמָא רַחֲמֵי לִנְשַׁיְיהוּ. מַאי שְׁנָא בְּיִצְחָק דִּכְתִיב בֵּיהּ וַיֶּאֱהָבֶהָ.","אֶלָּא וַדַּאי אִתְעֲרוּתָא דִרְחִימוּ דִדְכוּרָא לְגַבֵּי אִתְּתָא לָאו אִיהוּ אֶלָּא שְׂמָאלָא דִּכְתִיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְחשֶׁךְ וְלַיְלָה כְּחַד אִינוּן, וּשְׂמָאלָא אִתְעַר רְחִימוּ תָּדִיר לְגַבֵּי נוּקְבָא וְאָחִיד בָּהּ, וְעַל דָּא אַף עַל גַּב דְּאַבְרָהָם (ס\"א הוה) רָחִים לָהּ לְשָׂרָה לָא כְּתִיב בֵּיהּ וַיֶּאֱהָבֶהָ אֶלָּא בְּיִצְחָק. וְאִי תֵימָא וַיֶּאֱהַב יַעֲקֹב אֶת רָחֵל, סִטְרָא דְיִצְחָק דְּהֲוָה בֵּיהּ קָעֳבִיד לֵיהּ.","תָּא חֲזֵי, אַבְרָהָם כַּד חָמָא לְשָׂרָה (ס\"א לרבקה) הֲוָה מְחַבֵּק לָהּ וְלָא יַתִּיר, אֲבָל יִצְחָק דְּאִיהוּ בַּעֲלָהּ אָחִיד בָּהּ וְשַׁוֵּי דְּרוֹעֵיהּ תְּחוֹת רֵישָׁהּ דִּכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. לְבָתַר אֲתָא יַעֲקֹב וְשִׁמֵּשׁ עַרְסָא וְאוֹלִיד תְּרֵיסַר שְׁבָטִין כֹּלָּא כְּדְקָא יְאוּת."],[[0,"קם ר\"ש ואזלו וכו':","קם ר\"ש, והלכו, ואותו האדם הלך עמו עד טבריה. בעוד שהיו הולכים, אמר ר\"ש, בוא וראה, תפלות כנגד תמידים, תקנו רבנן מאנשי כנסת הגדולה, ומשום שמצאו שני תמידים, שכתוב, את הכבש אחד וגו', והם מתקרבים באותם ב' הזמנים שביום, שהם זמני תפלה, על כן תקנו בעיקר ב' תפלות, שהם שחרית ומנחה, אבל תפלת ערבית הוא רשות."],[1,"אמר ההוא גברא וכו':","אמר אותו האדם, הרי האבות תקנו אלו התפלות מקודם שתקנו אנשי כנסת הגדולה, ולא תקנו אותם כנגד התמידים, ולמה מה שתקנו אברהם ויצחק הוא עיקר, ומה שתיקן יעקב, שהוא בחיר האבות, הוא רשות ולא עיקר כמו אלו."],[2,"אמר רבי שמעון וכו':","אמר רבי שמעון, הוא נתבאר, אבל בוא וראה, אלו שני זמנים של שני התפלות שחרית וערבית, אינן, אלא לחבר את יעקב, שהיא זעיר אנפין, בגורלו, שהיא הנוקבא כיון שנתחברו זה בזה, אין אנו צריכים יותר, כי כיון שניתנה הנוקבא בין שני זרועות, שהם אברהם ויצחק, דהיינו קו ימין וקו שמאל, כבר נתחברה בגוף, כי הגוף אינו אלא כלל של ב' הזרועות ואין צריך לתקן יותר. ועל כן אנו צריכים לעורר את תקון שתי הזרועות, על ידי ב' התפלות שחרית וערבית, משום שהנוקבא ניתנה ביניהם, כלומר שצריכים להמשיך הארתם לתוך הנוקבא, ואחר שכבר ניתנה ביניהם, הנה הגוף, שהוא קו אמצעי, הנקרא יעקב, והנוקבא, דבריהם בלחש, שלא להזכיר מדה\"ד שבה."],[2,"","פירוש. אף על פי שיעקב, הוא בחיר שבאבות, כי העיקר הוא קו האמצעי המיחד ב' הקוין זב\"ז, וזולת הכרעת קו האמצעי אינם יכולים להאיר, עם כל זה אין בקו אמצעי תוספת אור על ב' הקוים, כי שורשם של ב' הקוין הם מ\"י אל\"ה אשר בבינה, שהם כוללים כל המוחין שבה, (כנ\"ל ב\"א דף רס\"ד ד\"ה באצבען) אלא משום שקו האמצעי עולה ומכריע ב' הקוין שבבינה ומשלימם, זוכה גם הוא בהם, בסוד תלת נפקי מחד, חד בתלת קיימא (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת ע\"ש) הרי שכל המוחין דבינה הם בב' הקוין ימין ושמאל שהם אברהם ויצחק אשר יעקב משלימם להיותו סוד קו אמצעי, וע\"כ זוכה גם הוא בב' הקוין, ומשפיע אותם לנוקבא. וז\"ש \u0003ועל דא אנן בעינן לאתערא תרין דרועין, בגין דאתיהיבת בינייהו,\u0004 כי הם כללות כל המוחין כולם, \u0003גופא ואתתא מלייהו בלחישו,\u0004 ואלו תקונים הנוספים השייכים לזווג קו אמצעי עם הנוקבא, צריך להיות בלחש, בסו\"ה \u0003וקולה לא ישמע\u0004 כמ\"ש לעיל (וירא קי\"ב ד\"ה וזה אמרו וישראל) שיש בדרך כלל ב' מיני קולות א) קול הבינה, דהיינו ממלכות הממותקת בבינה. ב) קול המלכות עצמה, הבלתי נמתקת בבינה. ואין זווג זו\"ן אלא בסוד קול הבינה וקול המלכות עצמה לא ישמע. וז\"ש \u0003גופא ואתתא מלייהו בלחישו.\u0004 כי אם היה נשמע קולה, דהיינו ממדת הדין הבלתי נמתק, לא היתה ראויה להזדווג עם ז\"א, ולקבל מוחין עליונים (כנ\"ל ב\"א דף ז' ד\"ה וכבר)."],[3,"ובגין כך וכו':","ומשום זה דמילייהו בלחישו ולא נשמע קולה כנ\"ל בסמוך, יעקב משמש במרום. ולמדנו מהו במרום, הוא כמו שאתה אומר, ואתה מרום לעולם ה', דהיינו בינה הנקראת מרום. ומלכות הממותקת, בבינה נקראת גם כן מרום. וכיון שיעקב משמש במרום, במלכות הממותקת, צריך להיות שקולה לא ישמע, כי אז יפרד ח\"ו הזווג. כנ\"ל בדיבור הסמוך."],[3,"וכלא איהו רזא וכו':","והכל הוא סוד ליודעי דין ומשפט. כלומר ליודעי סודות התורה באו ר' אבא ואותו יהודי ונשקו ידיו של ר\"ש. אמר ר' אבא, עד יום הזה לא הבנתי דבר זה, ורק עתה עמדתי על בוריו. אשרי חלקי שזכיתי לשמעו."],[4,"ויביאה יצחק האהלה שרה אמו:","אמר ר' יוסי. מקרא זה קשה, כתוב \u0003האהלה,\u0004 לאהל שרה אמו היה צריך לכתוב, מהו שכתוב האהלה. ואומר, כי חזרה שם השכינה הנקראת \u0003אהל,\u0004 וע\"כ כתוב האהלה, שהיא השכינה. משום כי כל זמן ששרה היתה נמצאת בעולם, לא נסתלקה ממנה השכינה, ונר היה דולק מערב שבת לערב שבת, והיה מאיר כל ימות השבוע. ואחרי שמתה, כבה הנר, וכיון שבאה רבקה, חזרה שם השכינה, והנר חזר ונדלק. \u0003שרה אמו,\u0004 פירושו, שדמתה לשרה בכל מעשיה."],[5,"רבי יהודה אמר וכו':","רי\"א שרה אמו. פירושו. כי כמו שצורתו של יצחק היתה כצורתו של אברהם, וכל מי שראה את יצחק, אמר שזה אברהם. וידעו בודאי שאברהם הוליד את יצחק, כן רבקה היתה צורתה ממש כמו צורתה של שרה, ומשום זה כתוב, \u0003שרה אמו,\u0004 כי אמרו ששרה, היא אמה של רבקה בודאי, באופן, שיצחק ורבקה, היו צורתם כמו אברהם ושרה. והיה ניכר, שאברהם הוליד את יצחק ושרה את רבקה."],[6,"אמר ר' אלעזר וכו':","אר\"א, לגמרי כן הוא הפירוש. אבל בוא וראה, כי סוד הוא, כי אף על פי ששרה מתה, צורתה לא נסתלקה מן הבית, אבל לא נראתה שם מיום שמתה עד שבאה רבקה, כיון שבאה רבקה נראתה צורת שרה, שכתוב ויביאה יצחק האהלה וגו', מיד נראה שם שרה אמו. ולא היה רואה אותה רק יצחק בלבדו בעת שנכנס שמה. ועל כן וינחם יצחק אחר אמו, כי אמו נראית ומזדמנת לו בבית. ועל כן לא כתוב אחרי מיתת אמו, אלא אחרי אמו. כי לא מתה כלל בעד יצחק."],[7,"ר' שמעון אמר מאי שנא וכו':","רש\"א, מהו השינוי, שכתוב בו ביצחק, ויקח את רבקה ותהי לו לאשה ויאהבה, כיון שאמר ותהי לו לאשה, איני יודע שאהב אותה, הרי כל בני העולם אוהבים את נשותיהם, מהו השינוי, שדוקא ביצחק כתוב בו ויאהבה."],[8,"אלא ודאי אתערותא וכו':","ומשיב, אלא ודאי, התעוררות האהבה של הזכר אל הנוקבא, אינה אלא מקו השמאל, שכתוב, שמאלו תחת לראשי. וחשך, שהוא קו השמאל. ולילה, שהיא הנוקבא כאחד הם, כי השמאל מעורר תמיד האהבה אל הנוקבא ואוחז בה, ועל כן אע\"פ שאברהם אהב את שרה, לא כתוב בו \u0003ויאהבה,\u0004 אלא ביצחק בלבד, להיותו קו השמאל דז\"א. ואם תאמר, הרי כתוב ויאהב יעקב את רחל, אע\"פ שאינו קו שמאל. הוא, משום שצד יצחק שהיה כלול בו עשה את זה. פירוש, כי יעקב הוא קו אמצעי דז\"א, הכולל בתוכו ב' הקוין ימין ושמאל, שהם אברהם ויצחק. ומשום התכללותו של יצחק שהיה בו, יתכן לומר עליו \u0003ויאהב,\u0004 כמו ביצחק."],[9,"ת\"ח אברהם וכו':","בוא וראה, אברהם שה\"ס קו ימין דז\"א, כשראה את שרה, שה\"ס הנוקבא דז\"א, היה מחבק אותה ולא יותר שהסו\"ה וימינו תחבקני, אבל יצחק שהוא קו שמאל דז\"א, שהוא בעלה, כנ\"ל בדיבור הסמוך, אחז בה ושם זרועו תחת ראשה, שכתוב, שמאלו תחת לראשי וגו'. ואחר כך, בא יעקב, שהוא קו אמצעי דז\"א, ושמש מטתו והוליד י\"ב שבטים. הכל כראוי להיות. פירוש: ר\"ש מפרש, שאברהם יצחק ויעקב רומזים לז\"א, דהיינו לג' קוין שלו. וכן שרה רבקה לאה ורחל רומזות להנוקבא דז\"א, דהיינו לד' בחינות חו\"ב תו\"מ שבה. ולפיכך אומר אשר ז\"א מסוד קו ימין שלו הוא מחבק להנוקבא בסוד וימינו תחבקני שה\"ס השפעת החסדים. ומסוד קו שמאל שלו, ממשיך לה הג\"ר, בסוד שמאלו תחת לראשי, כלומר שהנוקבא אומרת שמשמאלו של ז\"א נמשך לה בחינת הראש, שהם הג\"ר, ומשום זה נחשב לה השמאל דז\"א לעיקר המשפיע שלה, וע\"כ אומר, \u0003יצחק דאיהו בעלה,\u0004 משום שממנו מקבלת הג\"ר. ועם כל זה, אין הולדה אלא מבחינת קו אמצעי בלבדו, שה\"ס יעקב, וע\"כ אמר, \u0003לבתר אתא יעקב וכו',\u0004 ורק ממנו הולדת נשמות השבטים."]],[[0,"","קָם רַבִּי שִׁמְעוֹן וְהָלְכוּ. הָלַךְ אוֹתוֹ הָאִישׁ עִמּוֹ עַד טְבֶרְיָה. בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, תְּפִלּוֹת כְּנֶגֶד תְּמִידִין תִּקְּנוּם הַחֲכָמִים שֶׁל אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, מִשּׁוּם שֶׁנִּמְצָאוֹת שְׁתַּיִם, שֶׁכָּתוּב (במדבר כח) אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַּבֹּקֶר וְאֶת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם, וְהֵם נִקְרָבִים בִּשְׁנֵי הַזְּמַנִּים הַלָּלוּ שֶׁל הַיּוֹם, שֶׁהֵם זְמַנֵּי הַתְּפִלָּה."],[1,"","אָמַר אוֹתוֹ הָאִישׁ, הֲרֵי בַּתְּחִלָּה הָאָבוֹת תִּקְּנוּ אֶת הַתְּפִלּוֹת הַלָּלוּ, וּמַה שֶּׁתִּקְּנוּ אַבְרָהָם וְיִצְחָק הוּא הָעִקָּר. וּמַה שֶּׁתִּקֵּן יַעֲקֹב שֶׁהוּא הַמְשֻׁבָּח שֶׁל הָאָבוֹת, לָמָּה הִיא רְשׁוּת וְלֹא עִקָּר כְּמוֹ אֵלּוּ?"],[2,"","אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי נִתְבָּאֵר, אֲבָל בֹּא רְאֵה, שְׁנֵי הַזְּמַנִּים הַלָּלוּ שֶׁל שְׁתֵּי הַתְּפִלּוֹת אֵינָם אֶלָּא לְחַבֵּר אֶת יַעֲקֹב לְגוֹרָלוֹ. כֵּיוָן שֶׁהִתְחַבְּרוּ זֶה עִם זֶה, אֵינֶנוּ צְרִיכִים יוֹתֵר. שֶׁכֵּיוָן שֶׁנִּתְּנָה הָאִשָּׁה בֵּין שְׁתֵּי הַזְּרוֹעוֹת וּמִתְחַבֶּרֶת בַּגּוּף, לֹא צָרִיךְ יוֹתֵר, וְעַל כֵּן אָנוּ צְרִיכִים לְעוֹרֵר שְׁתֵּי הַזְּרוֹעוֹת בִּגְלַל שֶׁנִּתְּנָה בֵינֵיהֶם. כֵּיוָן שֶׁהִיא בֵּינֵיהֶם, הַגּוּף וְהָאִשָּׁה, אָז דִּבְרֵיהֶם בְּלַחַשׁ שֶׁלֹּא לְהַזְכִּיר."],[3,"","וּמִשּׁוּם כָּךְ, יַעֲקֹב מְשַׁמֵּשׁ בַּמָּרוֹם שָׁנִינוּ. מַה זֶּה בַּמָּרוֹם? כְּמוֹ שֶׁנֶּאֱמַר (תהלים צב) וְאַתָּה מָרוֹם לְעוֹלָם ה'. וְהַכֹּל הוּא סוֹד לְיוֹדְעֵי הַדִּין. בָּאוּ רַבִּי אַבָּא וְהַיְּהוּדִי הַהוּא וְנָשְׁקוּ אֶת יָדוֹ. אָמַר רַבִּי אַבָּא, עַד הַיּוֹם הַזֶּה לֹא לָמַדְתִּי בַּדָּבָר הַזֶּה, רַק עַכְשָׁו. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לִשְׁמֹעַ אוֹתוֹ."],[4,"","וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה שָׂרָה אִמּוֹ. אָמַר רַבִּי יוֹסֵי, הַפָּסוּק הַזֶּה קָשֶׁה. הָאֹהֱלָה? הָיָה צָרִיךְ לִהְיוֹת לְאֹהֶל שָׂרָה אִמּוֹ! מַה זֶּה הָאֹהֱלָה? שֶׁחָזְרָה לְשָׁם הַשְּׁכִינָה. מִשּׁוּם שֶׁכָּל זְמַן שֶׁשָּׂרָה הָיְתָה קַיֶּמֶת בָּעוֹלָם, לֹא זָזָה מִמֶּנָּה הַשְּׁכִינָה, וְנֵר הָיָה דוֹלֵק מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת וְהָיָה מֵאִיר אֶת כָּל אוֹתָם יְמוֹת הַשָּׁבוּעַ. אַחַר שֶׁמֵּתָה, כָּבָה אוֹתוֹ הַנֵּר. כֵּיוָן שֶׁבָּאָה רִבְקָה, חָזְרָה הַשְּׁכִינָה וְהִדְלִיקָה אֶת הַנֵּר. שָׂרָה אִמּוֹ - שֶׁדָּמְתָה לְשָׂרָה בְּכָל מַעֲשֶׂיהָ."],[5,"","רַבִּי יְהוּדָה אָמַר, כְּמוֹ שֶׁדְּמוּתוֹ שֶׁל יִצְחָק הָיְתָה כִּדְמוּתוֹ שֶׁל אַבְרָהָם, וְכָל מִי שֶׁרָאָה אֶת יִצְחָק אָמַר זֶה וַדַּאי אַבְרָהָם שֶׁהוֹלִיד אֶת יִצְחָק - כָּךְ גַּם דְּמוּתָהּ שֶׁל רִבְקָה מַמָּשׁ הָיְתָה כִּדְמוּתָהּ שֶׁל שָׂרָה, וּמִשּׁוּם כָּךְ שָׂרָה אִמּוֹ וַדַּאי."],[6,"","אָמַר רַבִּי אֶלְעָזָר, בַּכֹּל כָּךְ זֶה, אֲבָל בּא רְאֵה, זֶהוּ סוֹד. שֶׁאַף עַל גַּב שֶׁשָּׂרָה מֵתָה, דְּמוּתָהּ לֹא זָזָה מִן הַבַּיִת, וְלֹא נִרְאֲתָה שָׁם מִיּוֹם שֶׁמֵּתָה עַד שֶׁבָּאָה רִבְקָה. כֵּיוָן שֶׁנִּכְנְסָה רִבְקָה, נִרְאֲתָה דְמוּתָהּ שֶׁל שָׂרָה, שֶׁכָּתוּב וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה וְגוֹ'. מִיָּד שָׂרָה אִמּוֹ נִרְאֲתָה שָׁם. וְלֹא הָיָה רוֹאֶה, רַק יִצְחָק לְבַדּוֹ כְּשֶׁנִּכְנַס לְשָׁם, וְעַל כֵּן וַיִּנָּחֵם יִצְחָק אַחֲרֵי אִמּוֹ. (ס\"א מה זה אחרי אמו? אחרי) שֶׁאִמּוֹ נִרְאֲתָה וְהִזְדַּמְּנָה בַּבַּיִת, וְעַל כֵּן לֹא כָתוּב אַחֲרֵי מִיתַת אִמּוֹ, אֶלָּא אַחֲרֵי אִמּוֹ."],[7,"","רַבִּי שִׁמְעוֹן אָמַר, מַה שּׁוֹנֶה שֶׁכָּתוּב בְּיִצְחָק, וַיִּקַּח אֶת רִבְקָה וַתְּהִי לוֹ לְאִשָּׁה וַיֶּאֱהָבֶהָ? כֵּיוָן שֶׁאָמַר וַתְּהִי לוֹ לְאִשָּׁה, לֹא יָדַעְנוּ שֶׁהוּא אָהַב אוֹתָהּ? שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם אוֹהֲבִים אֶת נְשׁוֹתֵיהֶם. מַה שּׁוֹנֶה בְּיִצְחָק שֶׁכָּתוּב בּוֹ וַיֶּאֱהָבֶהָ?"],[8,"","אֶלָּא וַדַּאי הִתְעוֹרְרוּת שֶׁל הָאַהֲבָה שֶׁל הַזָּכָר לָאִשָּׁה אֵינָהּ אֶלָּא בִּשְׂמֹאל, שֶׁכָּתוּב (שיר א) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְחֹשֶׁךְ וְלַיְלָה הֵם יַחַד, וְהַשְּׂמֹאל מְעוֹרֵר תָּמִיד אַהֲבָה לַנְּקֵבָה וְאוֹחֵז בָּהּ. וְעַל כֵּן, אַף עַל גַּב שֶׁאַבְרָהָם (ס\"א היה) אוֹהֵב אֶת שָׂרָה, לֹא כָתוּב בּוֹ וַיֶּאֱהָבֶהָ, אֶלָּא בְּיִצְחָק. וְאִם תֹּאמַר וַיֶּאֱהַב יַעֲקֹב אֶת רָחֵל - הַצַּד שֶׁל יִצְחָק שֶׁהָיָה בּוֹ עָשָׂה לוֹ."],[9,"","בֹּא רְאֵה, כְּשֶׁאַבְרָהָם רָאָה אֶת שָׂרָה (ס\"א את רבקה), הָיָה מְחַבֵּק אוֹתָהּ וְלֹא יוֹתֵר. אֲבָל יִצְחָק שֶׁהוּא בַּעְלָהּ, אָחַז בָּהּ וְשָׂם אֶת זְרוֹעוֹ תַּחַת רֹאשָׁהּ, שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. אַחַר כָּךְ בָּא יַעֲקֹב וְשִׁמֵּשׁ מִטָּתוֹ, וְהוֹלִיד שְׁנֵים עָשָׂר שְׁבָטִים, כֻּלָּם כָּרָאוּי."]]],[["וְתָא חֲזֵי אֲבָהָן כֻּלְּהוּ בְּרָזָא חָדָא אֲזְלוּ. וְכֻלְּהוּ שִׁמְשׁוּ בְּאַרְבַּע נָשִׁין כָּל חַד מִנַּיְיהוּ, אַבְרָהָם בְּאַרְבַּע שָׂרָה וְהָגָר וּתְרֵי פִּלַּגְשִׁים. דִּכְתִיב וְלִבְנִי הַפִּלַּגְשִׁים אֲשֶׁר לְאַבְרָהָם, פִּלַּגְשִׁים תְּרֵי הָא אַרְבַּע.","יִצְחָק בְּרָזָא דְאַרְבַּע דִּסְטִירוּ דְרִבְקָה, דִּכְתִיב וַיִּקַּח אֶת רִבְקָה חַד. וַתְּהִי לוֹ לְאִשָּׁה תְּרֵי. וַיֶּאֱהָבֶהָ תְּלַת. וַיִּנָּחֶם יִצְחָק אַחֲרֵי אִמּוֹ הָא אַרְבַּע. לָקֳבֵל דָּא הֲווּ לְיַעֲקֹב אַרְבַּע נָשִׁין. וְכֹלָּא בְּרָזָא חָדָא.","רִבִּי חִיָיא אָמַר אַבְרָהָם וְיִצְחָק שִׁמְּשׁוּ כָּל חַד בְּאִתְּתָא חָדָא בְּרָזָא דְּקוּדְשָׁא. אַבְרָהָם בְּשָׂרָה, יִצְחָק בְּרִבְקָה, וְלָקֳבֵל תַּרְוַויְיהוּ הֲוֵי אַרְבַּע נָשִׁין לְיַעֲקֹב בִּתְרֵין חוּלָקִין. רִבִּי שִׁמְעוֹן אָמַר סְלִיקוּ מִלִּין לְאַתְרַיְיהוּ. דְּהָא כֹּלָּא בְּרָזָא קַדִּישָׁא אִתְעֲבַד וְכֹלָּא בְּרָזָא חָדָא:","וַיּוֹסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. קְטוּרָה דָא הִיא הָגָר. דְּהָא תָּנִינָן בָּתַר דְּאִתְפְּרָשָׁא הָגָר מִנֵּיהּ דְּאַבְרָהָם וְטָעַת בָּתַר גִּלּוּלֵי דְּאֲבוּהָ, לְבָתַר אִתְקַּשְׁרָא בְּעוֹבָדִין דְכַשְׁרָן, וּבְגִין כָּךְ אִשְׁתַּנֵּי שְׁמָהּ וְאִקְרֵי קְטוּרָה בְּעוֹבָדִין דְּכָשְׁרָן, וְשָׁדַר אַבְרָהָם וּנְסָבָהּ לֵיהּ לְאִנְתּוּ. מִכָּאן דְּשִׁנּוּי שְׁמָא מְכַפֵּר חוֹבִין, וְעַל דָּא אִשְׁתַּנֵּי שְׁמָהּ.","וַיּוֹסֶף אַבְרָהָם, מַאי וַיּוֹסֶף, אִי תֵימָא דְּעַל שָׂרָה אִיהוּ דְּאוֹסִיף, לָאו הָכִי. אֶלָּא בְּיוֹמָהָא דְשָׂרָה אִזְדַּוַּוג בַּהֲדָהּ זִמְנָא חָדָא, וּלְבָתַר תָּרִיךְ לָהּ עַל עִסְקֵי דְיִשְׁמָעֵאל, וּלְבָתַר וַיּוֹסֶף כְּמִלְקַדְמִין זִמְנָא אָחֳרָא עַל מַה דְּנָסִיב לָהּ בְּקַדְמִיתָא. וּכְפוּם דְשָׁנֵי עוֹבָדָהָא הָכִי נָמֵי שָׁנֵי שְׁמָהּ.","תָּא חֲזֵי, דְּאָמַר רַבִּי אֶלְעָזָר וַיְבִיאֶהָ יִצְחָק הָאֹהלָה שָׂרָה אִמּוֹ. דְּאִתְגַּלְיָא דִּיוּקְנָא דְשָׂרָה וְיִצְחָק אִתְנְחָם אַחֲרֵי דְּאִתְגַּלְיָא אִמּוֹ, וְדִיוּקְנָהָא הֲוָה חָמֵי כָּל יוֹמָא. וְאַבְרָהָם אַף עַל גַּב דְּאִינְסִיב לָא עָאל בְּהַהוּא בֵּיתָא וְלָא אָעִיל לָהּ לְהַאי אִתְּתָא תַּמָּן, בְּגִין דְּשִׁפְחָה לֹא תִירַשׁ גְּבִירְתָּה. וּבְאֹהֶל דְּשָׂרָה לָא אִתְחֲזֵי אִתְּתָא אָחֳרָא אֶלָּא רִבְקָה.","וְאַבְרָהָם אַף עַל גַּב דְּהֲוָה יָדַע דְּדִיוּקְנָא דְשָׂרָה אִתְגַלְּיָיא תַּמָּן, שַׁבְקֵיהּ לְיִצְחָק הַהוּא אֹהֶל לְמֶחמֵי דִּיוּקְנָא דְאִמֵּיהּ כָּל יוֹמָא. יִצְחָק וְלָא אַבְרָהָם, הֲדָא הוּא דִכְתִיב וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. אֶת כָּל אֲשֶׁר לוֹ דַיְיקָא, דָּא הַהוּא דִּיוּקְנָא דְשָׂרָה בְּהַהוּא מַשְׁכְּנָא.","דָּבָר אַחֵר וַיִתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, רָזָא דִמְהֵימְנוּתָא עִלָּאָה לְאִתְדַּבְּקָא יִצְחָק בְּדַרְגָּא דְחוּלָקֵיהּ כְּדְקָא יְאוּת. תָּא חֲזֵי, הָכָא אִתְכְּלִיל (ס\"אמיא באשא) אֶשָׁא בְּמַיָא, וַדַּאי אֶשָׁא נָטִיל מַיָא, מַשְׁמַע וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק דָּא מַיָא דְּאִתְכְּלִיל בְּאֶשָׁא. וּבְקַדְמִיתָא אִתְכְּלִיל כְּחֲדָא אֶשָׁא בְּמַיָא. אֵימָתַי, בְּשַׁעְתָּא דְּעָקַד לֵיהּ לְיִצְחָק לְמֶעְבַּד בֵּיהּ דִּינָא כְּדֵין אִתְכְּלִיל אֶשָׁא בְּמַיָא. וְהַשְׁתָּא אִתְכְּלִילוּ מַיָא בְּאֶשָׁא, לְמֶהוֵי כֹּלָּא רָזָא דִּמְהֵימְנוּתָא עִלָּאָה:","וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנוֹת. מַאי מַתָּנוֹת. אִלֵּין סִטְרֵי דַרְגִּין תַּתָּאִין דְּאִינוּן שְׁמָהָן דְּסִטְרֵי רוּחַ מְסָאֲבָא בְּגִין לְאַשְׁלָמָא דַּרְגִּין, וְאִסְתַּלַּק יִצְחָק עַל כֹּלָּא בִּמְהֵימְנוּתָא עִלָּאָה כְּדְקָא חָזֵי.","בְּנֵי הַפִּילַגְשִׁים, אִלֵּין הֲווּ בְּנֵי קְטוּרָה פִּלֶּגֶשׁ בְּקַדְמִיתָא וּפִלֶּגֶשׁ הַשְׁתָּא. רַבִּי חִיָּיא אָמַר פִּלַגְשִׁים מַמָּשׁ. וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְנוֹ, דְּלָא לְשַׁלְּטָאָה לְגַבֵּיהּ דְּיִצְחָק. בְּעוֹדֶנוּ חַי, בְּעוֹד דְּהֲוָה אַבְרָהָם חַי וְקַיָּים בְּעַלְמָא דְּלָא יְקַטְרְגוּן לֵיהּ לְבָתַר, וּבְגִין דְּיִתְתַּקַּן יִצְחָק בִּסְטַר דִּינָא קַשְׁיָא עִלָּאָה לְאִתְתַּקְּפָא עַל כֻּלְּהוּ, וְכֻלְּהוּ אִתְכַּפְיָין קַמֵּיהּ. קֵדְמָה אֶל אֶרֶץ קֶדֶם, בְּגִין דְּתַמָּן אִינוּן סִטְרֵי חֳרָשֵׁי מְסָאֲבֵי.","תָּא חֲזֵי, כְּתִיב (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמָת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם. אִלֵּין אִינוּן דְּהֲווּ מִבְּנֵי (אינון) בְּנֵי פִּילַגְשִׁים דְּאַבְרָהָם, וְהָא אוֹקִימְנָא דְּהָא בְּאִינוּן הַרְרֵי קֶדֶם אִינוּן דְּאוֹלְפִין חֳרָשִׁין לִבְנֵי נָשָׁא, וּמֵהַהִיא אֶרֶץ קֶדֶם נָפְקוּ לָבָן וּבְעוֹר וּבִלְעָם בְּנוֹ וְכֻלְּהוּ חֳרָשֵׁי וְהָא אוּקְמוּהָ."],[[0,"ות\"ח אבהן כלהו וכו':","בוא וראה, האבות הם כולם בסוד אחד הולכים, דהיינו רק סוד ז\"א בלבדו כנ\"ל בסמוך, וע\"כ כולם שמשו בארבע נשים שכל אחד מהם, היה לו ארבע נשים, שהם שרה רבקה לאה ורחל. כי גם הן סוד אחד, שהוא חו\"ב תו\"מ של הנוקבא דז\"א, כנ\"ל בסמוך. אברהם בארבע נשים, שהם שרה והגר וב' פלגשים, שכתוב ולבני הפלגשים אשר לאברהם, וכתוב \u0003פלגשים,\u0004 שפירושו שתים, ועם שרה והגר הרי הן ארבע."],[1,"יצחק ברזא דארבע וכו':","יצחק היה בסוד ארבע נשים מצד רבקה, כלומר שהיו כלולות ברבקה, שכתוב, \u0003ויקח את רבקה\u0004 היא אחת, \u0003ותהי לו לאשה,\u0004 הרי שתים, \u0003ויאהבה\u0004 הרי שלש. \u0003וינחם יצחק אחר אמו,\u0004 הרי ארבע. כנגד זה היה ליעקב ד' נשים. וכולם, דהיינו כל הי\"ב נשים, הם בסוד אחד, דהיינו הנוקבא דז\"א בלבדה, שיש בה אלו י\"ב בחינות."],[2,"ר' חייא אמר וכו':","רח\"א, אברהם ויצחק, שמשו כל אחד מהם באשה אחת בסוד הקדושה, כי הגר והפלגשים לא היו מקדושה, אברהם בשרה, יצחק ברבקה. וכנגד שניהם, היו ד' נשים ליעקב, בשני החלקים, שהם קודש וחול, שלאה ורחל היו בחלק הקדושה, ובלהה וזלפה היו בסוד חלק חול שהחזיר אל הקדושה."],[2,"ר\"ש אמר וכו':","רש\"א, הדברים עלו למקומם לקדושה, דהיינו דלא כרבי חייא, אלא אפילו הגר והפלגשים והשפחות כולן הן בסוד הקדושה, כמו שמפרש ר\"ש לעיל, שכל הי\"ב נשים הן רק י\"ב בחינות של הנוקבא. כי הכל נעשה בסוד הקדושה והכל הוא בסוד אחד, דהיינו שכולן נכללות בסוד הנוקבא דז\"א בלבדה, כנ\"ל בדבור הסמוך."],[3,"ויוסף אברהם ויקח אשה ושמה קטורה:","קטורה זו היא הגר. כי למדנו, אחר שנפרדה הגר מן אברהם, וזנה אחר גילוליו של אביה, אחר כך חזרה בתשובה, ונתקשרה במעשים טובים, ומשום זה נשתנה שמה ונקראה \u0003קטורה,\u0004 שרומז שנעשית קטורה במעשים טובים. כי קטורה פירושו קשורה, ואז שלח אברהם ולקחה לאשה. מכאן נשמע ששינוי השם מכפר על עברות, כי על כן נשתנה שמה לקטורה, כדי לכפר על עונותיה."],[4,"ויוסף אברהם:","ושואל מהו ויוסף. אם תאמר, שהוסיף אשה על שרה, אינו כך. אלא בימיה של שרה, נזדווג עם הגר פעם אחת, ואחר כך גרש אותה מחמת מעשיו של ישמעאל, שצחק על יצחק, ואחר כך נאמר \u0003ויוסף,\u0004 שפירושו, ויוסף לקחתה כבתחילה, כי לקחה פעם שנית על מה שלקחה מתחילה. וכפי מה ששינתה מעשיה כן נשתנה שמה. ונקראת עתה קטורה."],[5,"תא חזי דאמר ר\"א וכו':","בוא וראה, שאמר ר' אלעזר, בהכתוב, ויביאה יצחק האהלה שרה אמו, שנתגלתה צורתה של שרה עם רבקה, ויצחק התנחם אחרי שנתגלתה אמו, והיה רואה צורתה בכל יום. ואברהם, אע\"פ שנשא אשה, לא נכנס בבית ההוא של שרה, ולא הכניס אשה ההיא שם, משום, ששפחה לא תירש גבירתה, ובאהל של שרה לא נראה אשה אחרת אלא רבקה בלבדה."],[6,"ואברהם אע\"נ וכו':","ואברהם, אע\"פ שהיה יודע שצורתה של שרה נתגלתה שם, עזב ליצחק את האהל, לראות צורת אמו שם, בכל יום. יצחק ראה צורתה ולא אברהם. וזהו שכתוב, ויתן אברהם את כל אשר לו ליצחק, \u0003את כל אשר לו,\u0004 הוא בדיוק, כי סובב על צורה ההיא של שרה שהיתה באותו האהל. שנתנה ליצחק להסתכל בה."],[7,"ד\"א ויתן וכו':","פירוש אחר בהכתוב ויתן אברהם את כל אשר לו ליצחק, היינו שנתן לו סוד אמונה העליונה, שהיא בינא, כדי שיצחק יתדבק במדרגות חלקו כראוי. כי לולא נתן לו סוד הבינה, לא היה יכול להתדבק בקו שמאל. (כמ\"ש לעיל לך דף קמ\"ז ד\"ה פנימיות ע\"ש)"],[7,"ת\"ח הכא וכו':","בוא וראה, כאן נכלל אש שהיא שמאל במים שהם ימין ודאי שהאש לקח את המים, שהשמאל כלל בתוכו את הימין, זה משמע, מהכתוב ויתן אברהם את כל אשר לו ליצחק, זהו מים שנכלל באש, שאברהם שה\"ס מים נתן כל בחינתו ליצחק שה\"ס אש. ובתחילה נכללו יחד אש במים, אימתי היה זה, היינו בשעה שאברהם עקד את יצחק לעשות בו דין דהיינו להעלהו לעולה, אז נכללה אש במים, ועתה נכללו מים באש. כדי שיהיה הכל בסוד אמונה העליונה שהיא בינה. כי ב' קוין ימין ושמאל שבבינה נכללו זה בזה, ואז השיגו שלימותם, ולפיכך גם אברהם ויצחק הנמשכים מב' הקוין ההם שבבינה (כנ\"ל בפ' לך דף קמ\"ז ד\"ה פנימיות) צריכים גם כן להכלל זה מזה, ע\"כ תחלה נכלל שמאל בימין, שזה היה בשעת העקדה, ועתה, נתן אברהם את כל אשר לו ליצחק, שבזה נכלל הימין בתוך השמאל. \u0003מהימנותא\u0004 פירושו מלכות. \u0003מהימנותא עלאה\u0004 פירושו בינה."],[8,"ולבני הפלגשים וגו':","ושואל מהו מתנות, ואומר, אלו הן מיני מדרגות תחתונות של הקדושה בלתי מתוקנות, שהן שמות של מיני רוח הטומאה, ונתנם להם כדי להשלים המדרגות, כלומר שיטהרו אותם וישלימו את המדרגות של הקדושה. ויצחק, נתעלה על כולם באמונה העליונה כראוי. שהיא בינה, כנ\"ל בדבור הסמוך."],[9,"בני הפלגשים:","אלו הם בני קטורה, ונקראת פלגשים, על שם, שהיתה פלגש מקודם לכן מטרם שגרשה, ופלגש עתה שחזר ולקחה. רבי חייא אמר פלגשים ממש, ואינו סובב על קטורה. \u0003וישלחם מעל יצחק בנו,\u0004 כדי שלא ישלטו אצל יצחק. \u0003בעודנו חי,\u0004 היינו בעוד שהיה אברהם חי וקיים בעולם, בכדי שלא יריבו עמו אחר כך. ובכדי שיצחק יתתקן בצד דין הקשה העליון, להתגבר על כולם. וכולם נכנעו לפניו. \u0003קדמה אל ארץ קדם,\u0004 כי שם הם מיני כשפים של הטומאה."],[10,"ת\"ח כתיב וכו':","בוא וראה, כתוב, ותרב חכמת שלמה מחכמת כל בני קדם, אלו הם, שהיו מבני הפלגשים של אברהם. ואמרו, כי באלו הררי קדם, נמצאים אותם המלמדים כשוף לבני אדם, ומאותה ארץ קדם, יצאו לבן ובעור ובלעם בנו וכל המכשפים. וכבר בארוה."]],[[0,"","וּבֹא וּרְאֵה, כָּל הָאָבוֹת הָלְכוּ בְּסוֹד אֶחָד, וְכֻלָּם שִׁמְּשׁוּ בְּאַרְבַּע נָשִׁים כָּל אֶחָד מֵהֶם. אַבְרָהָם בְּאַרְבַּע - שָׂרָה וְהָגָר וּשְׁתֵּי פִּילַגְשִׁים, שֶׁכָּתוּב וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם. פִּילַגִשִׁים - שְׁתַּיִם. הִנֵּה אַרְבַּע."],[1,"","יִצְחָקֹ בְּסוֹד שֶׁל אַרְבַּע שֶׁל הַצַּד שֶׁל רִבְקָה, שֶׁכָּתוּב וַיִּקַּח אֶת רִבְקָה - אֶחָד. וַתְּהִי לוֹ לְאִשָּׁה - שְׁתַּיִם. וַיֶּאֱהָבֶהָ - שָׁלֹשׁ. וַיִּנָּחֵם יִצְחָק אַחֲרֵי אִמּוֹ - הִנֵּה אַרְבַּע. כְּנֶגֶד זֶה הָיוּ לְיַעֲקֹב אַרְבַּע נָשִׁים. וְהַכֹּל בְּסוֹד אֶחָד."],[2,"","רַבִּי חִיָּיא אָמַר, אַבְרָהָם וְיִצְחָק שִׁמְּשׁוּ כָּל אֶחָד עִם אִשָּׁה אַחַת בְּסוֹד שֶׁל קֹדֶשׁ. אַבְרָהָם עִם שָׂרָה, יִצְחָק עִם רִבְקָה. דִּכְנֶגֶד שְׁנֵיהֶם הָיוּ אַרְבַּע נָשִׁים לְיַעֲקֹב בִּשְׁנֵי חֲלָקִים. רַבִּי שִׁמְעוֹן אָמַר, עָלוּ הַדְּבָרִים לִמְקוֹמָם, שֶׁהֲרֵי הַכֹּל נַעֲשָׂה בְּסוֹד קָדוֹשׁ, וְהַכֹּל בְּסוֹד אֶחָד."],[3,"","וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. קְטוּרָה זוֹ הִיא הָגָר. שֶׁהֲרֵי שָׁנִינוּ, אַחַר שֶׁנִּפְרְדָה הָגָר מֵאַבְרָהָם וְטָעֲתָה אַחַר גִּלּוּלֵי אָבִיהָ, אַחַר כָּךְ נִקְשְׁרָה לְמַעֲשִׂים כְּשֵׁרִים, וּמִשּׁוּם כָּךְ הִשְׁתַּנָּה שְׁמָהּ וְנִקְרְאָה קְטוּרָה בְּמַעֲשִׂים כְּשֵׁרִים, וְשָׁלַח אַבְרָהָם וְלָקַח אוֹתָהּ לְאִשָּׁה. מִכָּאן שֶׁשִּׁנּוּי שֵׁם מְכַפֵּר עַל חֲטָאִים, וְעַל כֵּן הִשְׁתַּנָּה שְׁמָהּ."],[4,"","וַיֹּסֶף אַבְרָהָם. מַה זֶּה וַיֹּסֶף? אִם תֹּאמַר שֶׁהוּא הוֹסִיף עַל שָׂרָה - לֹא כָּךְ! אֶלָּא בִּימֵי שָׂרָה הִזְדַּוֵּג עִמָּהּ פַּעַם אַחַת, וְאַחַר כָּךְ גֵּרַשׁ אוֹתָהּ עַל עִסְקֵי יִשְׁמָעֵאל, וְאַחַר כָּךְ וַיֹּסֶף, כְּמוֹ מִקֹּדֶם פַּעַם אַחֶרֶת עַל מַה שֶּׁנָּשָׂא אוֹתָהּ בָּרִאשׁוֹנָה. וּלְפִי שֶׁשִּׁנְּתָה מַעֲשֶׂיהָ, כָּךְ גַּם שִׁנָּה שְׁמָהּ."],[5,"","בֹּא רְאֵה, שֶׁאָמַר רַבִּי אֶלְעָזָר, וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה שָׂרָה אִמּוֹ - שֶׁהִתְגַּלְּתָה דְמוּת שָׂרָה, וְיִצְחָק הִתְנַחֵם אַחֲרֵי שֶׁהִתְגַּלְּתָה אִמּוֹ וְאֶת דְּמוּתָהּ הָיָה רוֹאֶה כָּל יוֹם. וְאַבְרָהָם, אַף עַל גַּב שֶׁנָּשָׂא, לֹא נִכְנַס לְאוֹתוֹ הַבַּיִת, וְלֹא הִכְנִיס אֶת אוֹתָהּ הָאִשָּׁה לְשָׁם כְּדֵי שֶׁשִּׁפְחָה לֹא תִירַשׁ גְּבִרְתָּהּ. וּבְאֹהֶל שָׂרָה לֹא נִרְאֲתָה אִשָּׁה אַחֶרֶת, אֶלָּא רִבְקָה."],[6,"","וְאַף עַל גַּב שֶׁאַבְרָהָם הָיָה יוֹדֵעַ שֶׁדְּמוּתָהּ שֶׁל שָׂרָה נִגְלְתָה שָׁם, הִשְׁאִיר לְיִצְחָק אוֹתוֹ הָאֹהֶל, לִרְאוֹת אֶת הַדְּמוּת שֶׁל אִמּוֹ בְּכָל יוֹם. יִצְחָק וְלֹא אַבְרָהָם. זֶהוּ שֶׁכָּתוּב וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. אֶת כָּל אֲשֶׁר לוֹ דַּוְקָא, זוֹ אוֹתָהּ הַדְּמוּת שֶׁל שָׂרָה בְּאוֹתוֹ הַמִּשְׁכָּן."],[7,"","דָּבָר אַחֵר וַיִתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה שֶׁיִּדְבַּק יִצְחָק בְּדַרְגַּת חֶלְקוֹ כָּרָאוּי. בּא רְאֵה, כָּאן נִכְלְלוּ (מים עם אש) אֵשׁ עִם מַיִם. וַדַּאי אֵשׁ נוֹשֵׂא מַיִם. מַשְׁמָע וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, זֶה הַמַּיִם שֶׁנִּכְלָלִים בָּאֵשׁ. וּבָרִאשׁוֹנָה נִכְלְלוּ יַחַד אֵשׁ וּמַיִם. מָתַי? בְּשָׁעָה שֶׁעָקַד אֶת יִצְחָק לַעֲשׂוֹת בּוֹ דִּין, אָז נִכְלְלָה הָאֵשׁ בַּמַּיִם. וְכָאן נִכְלְלוּ מַיִם בְּאֵשׁ, שֶׁהַכֹּל יִהְיֶה בְּסוֹד הָאֱמוּנָה הָעֶלְיוֹנָה."],[8,"","וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנוֹת. מַה זֶּה מַתָּנוֹת? אֵלּוּ הַצְּדָדִים הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁהֵם שֵׁמוֹת שֶׁל צִדְדֵי רוּחַ הַטֻּמְאָה כְּדֵי לְהַשְׁלִים אֶת הַדְּרָגוֹת, וְהִתְעַלָּה יִצְחָק עַל הַכֹּל בָּאֱמוּנָה הָעֶלְיוֹנָה כָּרָאוּי."],[9,"","בְּנֵי הַפִּילַגְשִׁים - אֵלּוּ הָיוּ בְּנֵי קְטוּרָה. פִּילֶגֶשׁ בָּרִאשׁוֹנָה, וּפִילֶגֶשׁ כָּעֵת. רַבִּי חִיָּיא אָמַר, פִּילַגְשִׁים מַמָּשׁ. וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ - שֶׁלֹּא לִשְׁלֹט אֵצֶל יִצְחָק. בְּעוֹדֶנּוּ חַי - בְּעוֹד שֶׁאַבְרָהָם הָיָה חַי וְקַיָּם בָּעוֹלָם, שֶׁלֹּא יִתְגָּרוּ בוֹ אַחַר כָּךְ, וּכְדֵי שֶׁיִּצְחָק יְתֻקַּן בְּצַד הַדִּין הַקָּשֶׁה הָעֶלְיוֹן שֶׁיִּתְגַּבֵּר עַל כֻּלָּם וְכֻלָּם יִכָּנְעוּ לְפָנָיו. קֵדְמָה אֶל אֶרֶץ קֶדֶם - מִשּׁוּם שֶׁשָּׁם הֵם צִדְדֵי הַכְּשָׁפִים הַטְּמֵאִים."],[10,"","בֹּא רְאֵה, כָּתוּב (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם. אֵלּוּ הֵם שֶׁהָיוּ מִבְּנֵי (הם) בְּנֵי פִּילַגְשִׁים שֶׁל אַבְרָהָם. וַהֲרֵי בֵּאַרְנוּ שֶׁהֲרֵי בְּאוֹתָם הַרֲרֵי קֶדֶם הֵם מְלַמְּדִים כְּשָׁפִים לִבְנֵי אָדָם, וּמֵאוֹתָהּ אֶרֶץ קֶדֶם יָצְאוּ לָבָן וּבְעוֹר וּבִלְעָם, וְכֻלָּם מְכַשְּׁפִים, וַהֲרֵי בֵּאֲרוּהוּ."]]],[["רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיהו מ״ב:כ״ד) מִי נָתַן לִמְשִׁיסָה יַעֲקֹב וְיִשְׂרָאֵל לְבוֹזְזִים הֲלא יְיָ וְגו'. תָּא חֲזֵי, מִזִּמְנָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא בִּרְכָאן לָא שַׁרְיָין בְּעַלְמָא וְאִתְמְנָעוּ, כִּבְיָכוֹל אִתְמְנָעוּ מֵעֵילָא וְתַתָּא, וְכָל אִינוּן שְׁאָר דַּרְגִּין תַּתָּאִין מִתְתַּקְפֵי וְאָזְלֵי וְשָׁלְטֵי עֲלַיְיהוּ דְיִשְׂרָאֵל בְּגִין דְּאִינוּן גָּרְמוּ בְּחוֹבַיְיהוּ.","הַאי קְרָא לָא אִתְיַישְׁבָן מִלֵּיהּ דִּכְתִיב מִי נָתַן לִמְשִׁיסָה יַעֲקֹב, כֵּיוָן דְּאָמַר מִי נָתַן לִמְשִׁיסָה יַעֲקֹב וְיִשְׂרָאֵל, מַהוּ חָטָאנוּ לוֹ, חָטְאוּ לוֹ מִבָּעֵי לֵיהּ, וְאִי אָמַר חָטָאנוּ לוֹ, מַאי וְלא אָבוּ, וְלא אָבִינוּ מִבָּעֵי לֵיהּ.","אֶלָּא בְּשַׁעְתָּא דְּאִתְחָרַב מַקְדְּשָׁא וְאִתּוֹקַד הֵיכָלָא וְעַמָּא אִתְגְּלִי, בָּעְיָא שְׁכִינְתָּא לְאִתְעַקְּרָא מִדּוּכְתָּהּ וּלְמֵיהַךְ עִמְּהוֹן בְּגָלוּתָא, אָמְרָה אֵיהַךְ בְּקַדְמִיתָא לְמֶחמֵי בֵּיתָאי וְהֵיכָלָאי וְאֶפְקוֹד עַל דּוּכְתֵּי דְּכַהֲנֵי וְלֵיוָאֵי דְּהֲווּ פָלְחִין בְּבֵיתָאי.","אָמַר רִבִּי אֶלְעָזָר בְּהַהִיא שַׁעְתָּא אִסְתַּכָּלַת כְּנֶסֶת יִשְׂרָאֵל לְעֵילָא וְחָמַאת דְּבַעֲלָהּ אִסְתַּלַּק מִנָּהּ לְעֵילָא לְעֵילָא, נָחֲתַת לְתַתָּא עָאלַת בְּבֵיתָא וְאִסְתַּכָּלַת בְּכָל אִינוּן דּוּכְתֵּי, וְאִשְׁתְּמַע קָלָא לְעֵילָא לְעֵילָא וְאִשְׁתְּמַע קָלָא לְתַתָּא. הֲדָא הוּא דִכְתִיב (ירמיהו ל״א:ט״ו) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנְיהָ וְגו' וְאוּקְמוּהָ.","כֵּיוָן דְּעָאלַת בְּגָלוּתָא אִסְתַּכָּלַת בְּעַמָא וְחָמַאת דְּדָחֲקֵי לוֹן וְרָמְסֵי לוֹן בְּגָלוּתָא בֵּין רַגְלַיְיהוּ דִּשְׁאָר עַמִּין, כְּדֵין אָמְרַת (ישעיהו מ״ב:כ״ד) מִי נָתַן לִמְשִׁיסָּה יַעֲקֹב וְגו'. וְאִינוּן אָמְרִין הֲלֹא יְיָ זוּ חָטָאנוּ לוֹ. וְהִיא אֲמָרַת וְלֹא אָבוּ בִדְרָכָיו הָלוֹךְ וְלא שָׁמְעוּ בְּתוֹרָתוֹ.","וּבְשַׁעְתָּא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִפְקַד עַל עַמֵּיהּ, כְּנֶסֶת יִשְׂרָאֵל תֵּיתוּב מִן גָּלוּתָא בְּקַדְמִיתָא (אמר ליה קודשא בריך הוא) תֵּיהַךְ לְבֵיתָא, בְגִין דְּבֵית הַמִּקְדָּשׁ יִתְבְּנֵי בְּקַדְמִיתָא, וְיֵימָא לָהּ קוּדְשָׁא בְּרִיךְ הוּא קוּמִי מֵעַפְרָא. הִיא תָבַת וְאָמְרָה לְאָן אֲתַר אֵיהַךְ, בֵּיתָאי חָרַב הֵיכָלִי אִתּוֹקַד בְּנוּרָא. עַד דְּקוּדְשָׁא בְּרִיךְ הוּא יִבְנִי בֵּי מַקְדְּשָׁא בְּקַדְמִיתָא וְיַתְקִין הֵיכָלָא וְיִבְנֵי קַרְתָּא דִּיְרוּשָׁלַ ם, וּלְבָתַר יוֹקִים לָהּ מֵעַפְרָא. הֲדָא הוּא דִכְתִיב (תהילים קמ״ז:ב׳) בּוֹנִה יְרוּשָׁלַיִם יְיָ וְגו'. בּוֹנֵה יְרוּשָׁלַיִם בְּקַדְמִיתָא וּלְבָתַר נִדְחֵי יִשְׂרָאֵל יְכַנֵּס, וְיֵימָא לָהּ (ישעיהו נ״ב:ב׳) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלַיִם וְגו'. וְיִתְכַּנֵּישׁ גָּלוּתְהוֹן דְּיִשְׂרָאֵל. הֲדָא הוּא דִכְתִיב בּוֹנֵה יְרוּשָׁלַיִם יְיָ, בְּקַדְמִיתָא, וּלְבָתַר נִדְחֵי יִשְׂרָאֵל יְכַנֵּס. וּכְדֵין הָרוֹפֵא לִשְׁבוּרֵי לֵב וּמְחַבֵּשׁ לְעַצְבוֹתָם דָּא תְּחִיַּית הַמֵּתִים. וּכְתִיב, (יחזקאל ל״ו:כ״ז) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי אֶת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וְגו'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן ואָמֵן: (ע\"כ פרשת חיי שרה)"],[[0,"ר' חזקיה פתח וכו':","ר\"ח פתח ואמר, מי נתן למשיסה יעקב וישראל לבוזזים וגו' בוא וראה מזמן שחרב בית המקדש, אין ברכות שורות בעולם ונעצרו, כביכול שנמנעו מלמעלה מעולמות העליונים, ומלמטה מהתחתונים. וכל אלו מדרגות התחתונות מתגברות והולכות, ושולטות על ישראל, משום שישראל גרמו את זה בעונותיהם. וענין חסרון הברכות בעולמות העליונים, הוא משום שהתחתונים אינם ראוים לקבל מהם, וכל השפע שהם צריכים להשפיע לתחתונים נמנע מהם. כי אין להם למי להשפיע. (ועיין בזה בפתיחה לחכמת הקבלה דף ל\"ד אות קס\"א וקס\"ב ובההמשך, שנתבאר שם על בוריו.)"],[1,"האי קרא וכו':","מקרא זה, דבריו אינם מיושבים. כי כתוב, מי נתן למשיסה יעקב וישראל לבוזזים הלא ה' זו חטאנו לו. כיון שאמר, מי נתן למשיסה יעקב וישראל, מה הוא שאומר \u0003חטאנו לו,\u0004 חטאו לו, היה צריך לומר. דהיינו לשון נסתר ולא כמדברים בעדם. ואם כבר אומר, \u0003חטאנו לו,\u0004 דהיינו מדברים בעדם, מה הוא שאומר שוב \u0003ולא אבו\u0004 דהיינו שוב לשון נסתר, ולא אבינו היה צריך לומר, שהוא כמדברים בעדם."],[2,"אלא בשעתא וכו':","ומשיב, אלא בשעה שנחרב בית המקדש ונשרף ההיכל, והעם הלך לגלות, רצתה השכינה להתעקר ממקומה וללכת לגלות עמהם. אמרה השכינה, אלך תחלה לראות ביתי והיכלי, ואפקוד את המקומות של הכהנים והלוים, שהיו עובדים בביתי."],[3,"אמר ר' אלעזר וכו':","באותה שעה נסתכלה כנסת ישראל, היא השכינה למעלה, וראתה שבעלה, ז\"א, נסתלק ממנה, ועלה למעלה למעלה, ירדה למטה ונכנסה בבית המקדש, והסתכלה בכל המקומות, ובכתה ונשמע הקול למעלה למעלה בשמים, ונשמע הקול למטה בארץ. וזהו שכתוב, קול ברמה נשמע נהי בכי תמרורים רחל מבכה על בניה וגו' ובארוהו."],[4,"כיון דעאלת בגלותא וכו':","כיון שבאה בגלות, הסתכלה בעם, וראתה, איך שדוחקים אותם ורומסים אותם בין רגליהם של שאר העמים, בגלות, אז אמרה, \u0003מי נתן למשיסה יעקב\u0004 וגו'. וישראל אמרו, \u0003הלא ה' זו חטאנו לו,\u0004 ומיושב בזה מש\"כ כמדבר בעדו. והשכינה אמרה \u0003ולא אבו בדרכיו הלוך ולא שמעו בתורתו.\u0004 ומיושב בזה, מה ששוב אומר הכתוב בלשון נסתר."],[5,"ובשעתא דזמין קב\"ה וכו':","ולשעה שעתיד הקב\"ה לפקוד את עמו, להוציאם מגלות, כנסת ישראל, היא השכינה תשוב תחילה מהגלות, ותלך לבית המקדש מטעם שבית המקדש תבנה תחילה לקבוץ גליות, ששם השראת השכינה, וע\"כ גם השכינה מקדמת לצאת מהגלות. ויאמר לה הקב\"ה, קומי מעפר. והשכינה משיבה ואמרה, לאיזה מקום אלך, הרי ביתי חרב, היכלי נשרף באש. עד שהקב\"ה, יבנה בית המקדש מתחילה, ויתקן החיכל, ויבנה עיר ירושלים, ואחר זה יקים את השכינה מעפר, וז\"ש, בונה ירושלים ה' וגו', מתחילה \u0003בונה ירושלים,\u0004 ואחר כך \u0003נדחי ישראל יכנס,\u0004 ויאמר לה התנערי מעפר קומי שבי ירושלים וגו', ואח\"כ יקבץ גליות ישראל. וז\"ש מתחילה, בונה ירושלים ה', ואח\"כ, נדחי ישראל יכנס. ואז, הרופא לשבורי לב ומחבש לעצבותם, שזהו \u0003תחיית המתים.\u0004 וכתוב, ואת רוחי אתן בקרבכם ועשיתי את אשר בחקי תלכו וגו'. בילא\"ו."]],[[0,"","רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיה מב) מִי נָתַן לִמְשִׁסָּה יַעֲקֹב וְיִשְׂרָאֵל לְבזְזִים הֲלֹא ה' וְגוֹ'. בּא רְאֵה, מִזְּמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, הַבְּרָכוֹת לֹא שׁוֹרוֹת בָּעוֹלָם וְנִמְנָעוֹת, כִּבְיָכוֹל נִמְנָעוֹת מִמַּעְלָה וּמַטָּה, וְכָל אוֹתָן שְׁאָר הַדְּרָגוֹת הַתַּחְתּוֹנוֹת מִתְגַּבְּרוֹת וְהוֹלְכוֹת וְשׁוֹלְטוֹת עַל יִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם גָּרְמוּ בַּחֲטָאֵיהֶם."],[1,"","הַפָּסוּק הַזֶּה אֵין מִתְיַשְּׁבִים דְּבָרָיו, שֶׁכָּתוּב מִי נָתַן לִמְשִׁסָּה יַעֲקֹב. כֵּיוָן שֶׁאָמַר מִי נָתַן לִמְשִׁסָּה יַעֲקֹב וְיִשְׂרָאֵל, מַה זֶּה חָטָאנוּ לוֹ? הָיָה צָרִיךְ לִהְיוֹת חָטְאוּ לוֹ! וְאִם אָמַר חָטָאנוּ לוֹ, מַהוּ וְלֹא אָבוּ? וְלֹא אָבִינוּ צָרִיךְ לִהְיוֹת!"],[2,"","אֶלָּא בְּשָׁעָה שֶׁנֶּחֱרַב הַמִּקְדָּשׁ וְנִשְׂרַף הַהֵיכָל וְהָעָם הָגְלָה, רָצְתָה הַשְּׁכִינָה לְהֵעָקֵר מִמְּקוֹמָהּ וְלָלֶכֶת עִמָּהֶם בַּגָּלוּת. אָמְרָה: אֵלֵךְ בָּרִאשׁוֹנָה לִרְאוֹת אֶת בֵּיתִי וְהֵיכָלִי, וְאֶפְקֹד אֶת מְקוֹמוֹת הַכֹּהֲנִים וְהַלְוִיִּם שֶׁהָיוּ עוֹבְדִים בְּבֵיתִי."],[3,"","אָמַר רַבִּי אֶלְעָזָר, בְּאוֹתָהּ שָׁעָה הִסְתַּכְּלָה כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה וְרָאֲתָה אֶת בַּעְלָהּ מִסְתַּלֵּק מִמֶּנָּה לְמַעְלָה לְמַעְלָה. יָרְדָה לְמַטָּה, נִכְנְסָה לַבַּיִת וְהִסְתַּכְּלָה בְּכָל אוֹתָם הַמְּקוֹמוֹת, וְנִשְׁמַע קוֹל לְמַעְלָה לְמַעְלָה, וְנִשְׁמַע קוֹל לְמַטָּה. זֶהוּ שֶׁכָּתוּב (ירמיה לא) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ וְגוֹ', וּבֵאֲרוּהָ."],[4,"","כֵּיוָן שֶׁנִּכְנְסָה לַגָּלוּת, הִסְתַּכְּלָה עַל הָעָם, וְרָאֲתָה שֶׁדּוֹחֲקִים אוֹתָם וְרוֹמְסִים אוֹתָם בַּגָּלוּת בֵּין רַגְלֵי שְׁאָר הָעַמִּים. אָז אָמְרָה: (ישעיה מב) מִי נָתַן לִמְשִׁסָּה יַעֲקֹב וְגוֹ'. וְהֵם אוֹמְרִים: הֲלֹא ה' זוּ חָטָאנוּ לוֹ. וְהִיא אוֹמֶרֶת: וְלֹא אָבוּ בִדְרָכָיו הָלוֹךְ וְלֹא שָׁמְעוּ בְּתוֹרָתוֹ."],[5,"","וּבְשָׁעָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְקֹד אֶת עַמּוֹ, כְּנֶסֶת יִשְׂרָאֵל תָּשׁוּב מִן הַגָּלוּת בָּרִאשׁוֹנָה. (אומר לה הקדוש ברוך הוא): תֵּלְכִי לַבַּיִת כְּדֵי שֶׁבֵּית הַמִּקְדָּשׁ יִבָּנֶה בַּהַתְחָלָה. וְיֹאמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: קוּמִי מִן הֶעָפָר. הִיא שָׁבָה וְאוֹמֶרֶת: לְאֵיזֶה מָקוֹם אֵלֵךְ? בֵּיתִי חָרֵב, וְהֵיכָלִי נִשְׂרַף בָּאֵשׁ. עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִבְנֶה אֶת בֵּית הַמִּקְדָּשׁ בָּרִאשׁוֹנָה וְיַתְקִין אֶת הַהֵיכָל וְיִבְנֶה אֶת קִרְיַת יְרוּשָׁלַיִם, וְאַחַר כָּךְ יָקִים אוֹתָהּ מִן הֶעָפָר. זֶהוּ שֶׁכָּתוּב (תהלים קמז) בּוֹנֵה יְרוּשָׁלַיִם ה' וְגוֹ'. בּוֹנֵה יְרוּשָׁלַיִם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ נִדְחֵי יִשְׂרָאֵל יְכַנֵּס. וְיֹאמַר לָהּ: (ישעיה נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלם וְגוֹ'. וִיכַנֵּס אֶת גָּלֻיּוֹת יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב בּוֹנֵה יְרוּשָׁלַיִם ה' - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - נִדְחֵי יִשְׂרָאֵל יְכַנֵּס. וְאָז הָרוֹפֵא לִשְׁבוּרֵי לֵב וּמְחַבֵּשׁ לְעַצְּבוֹתָם, זוֹ תְחִיַּת הַמֵּתִים, וְכָתוּב (יחזקאל לו) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי אֵת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
